/// Cross-company view of the latest point-in-time first-principles states.
///
/// This is deliberately a hypothesis/evidence map rather than an opportunity
/// score.  Until observations have been reviewed and outcome-tested, coverage
/// cannot be turned into a ranking or an exposure action.
#[derive(Debug, Clone, Serialize, PartialEq)]
pub(crate) struct FirstPrinciplesHypothesisMap {
    pub policy_version: String,
    pub status: String,
    pub latest_decision_at: Option<DateTime<Utc>>,
    pub map_fingerprint_sha256: String,
    pub model_count: usize,
    pub company_count: usize,
    pub source_sample_ids: Vec<String>,
    pub models: Vec<FirstPrinciplesHypothesisModel>,
    pub measurement_backlog: FirstPrinciplesMeasurementBacklog,
    pub opportunity_ranking_enabled: bool,
    pub action_authorized: bool,
    pub scope: String,
}

/// Operational queue for turning traceable evidence into a bounded quantitative
/// observation. The ordering is review readiness, never investment merit.
#[derive(Debug, Clone, Serialize, PartialEq)]
pub(crate) struct FirstPrinciplesMeasurementBacklog {
    pub policy_version: String,
    pub status: String,
    pub total_driver_count: usize,
    pub measured_driver_count: usize,
    pub ready_for_review_count: usize,
    pub rejected_needs_new_evidence_count: usize,
    pub metricization_required_count: usize,
    pub operating_kpi_required_count: usize,
    pub no_traceable_evidence_count: usize,
    pub items: Vec<FirstPrinciplesMeasurementBacklogItem>,
    pub investment_ranking_enabled: bool,
    pub action_authorized: bool,
    pub scope: String,
}

#[derive(Debug, Clone, Serialize, PartialEq)]
pub(crate) struct FirstPrinciplesMeasurementBacklogItem {
    pub symbol: String,
    pub company_name: String,
    pub sample_id: String,
    pub decision_at: DateTime<Utc>,
    pub model_id: String,
    pub driver_family: String,
    pub driver_id: String,
    pub driver_label: String,
    pub status: String,
    pub measurement_status: MeasurementStatus,
    pub traceable_observation_count: usize,
    pub review_candidate_count: usize,
    pub pending_review_candidate_count: usize,
    pub admitted_candidate_count: usize,
    pub rejected_candidate_count: usize,
    pub required_observations: Vec<String>,
    pub target_operating_kpi_ids: Vec<String>,
    pub next_check: String,
}

#[derive(Debug, Clone, Serialize, PartialEq)]
pub(crate) struct FirstPrinciplesHypothesisModel {
    pub model_id: String,
    pub model_version: String,
    pub state: String,
    pub latest_decision_at: DateTime<Utc>,
    pub company_count: usize,
    pub symbols: Vec<String>,
    pub demand_traceable_company_count: usize,
    pub supply_traceable_company_count: usize,
    pub value_capture_traceable_company_count: usize,
    pub fully_traceable_company_count: usize,
    pub demand_measured_company_count: usize,
    pub supply_measured_company_count: usize,
    pub value_capture_measured_company_count: usize,
    pub fully_measured_company_count: usize,
    pub evidence_pathway: FirstPrinciplesEvidencePathwayCounts,
    pub promoted_driver_count: usize,
    pub blocked_conflict_driver_count: usize,
    pub blocked_rejection_driver_count: usize,
    pub blocked_falsification_driver_count: usize,
    pub missing_checks: Vec<String>,
    pub interpretation: String,
}

/// Counts unique point-in-time observations by their evidence pathway.
///
/// One observation may be attached to more than one driver family, so the map
/// deduplicates it by company and observation id before incrementing these
/// counters.  The pathway is diagnostic only: a traceable source claim is not
/// silently promoted into a measured or human-confirmed causal driver.
#[derive(Debug, Clone, Default, Serialize, PartialEq, Eq)]
pub(crate) struct FirstPrinciplesEvidencePathwayCounts {
    pub unique_observation_count: usize,
    pub direct_metric_count: usize,
    pub proxy_count: usize,
    pub confirmed_context_count: usize,
    pub structured_source_claim_count: usize,
    pub computed_comparison_count: usize,
    pub computed_ratio_count: usize,
    pub computed_ratio_trend_count: usize,
    pub operating_kpi_claim_count: usize,
}

