pub(crate) async fn handle_get_evidence_review_queue(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<ReviewQueueQuery>,
) -> Response {
    let admin = match crate::routes::public_admin::require_public_admin_for_read(&state, &headers) {
        Ok(admin) => admin,
        Err(response) => return response,
    };
    let symbol_filter = query
        .symbol
        .map(|symbol| symbol.trim().to_ascii_uppercase())
        .filter(|symbol| !symbol.is_empty());
    if symbol_filter
        .as_deref()
        .is_some_and(|symbol| !valid_symbol(symbol))
    {
        return (StatusCode::BAD_REQUEST, "invalid symbol").into_response();
    }
    let status_filter = query
        .status
        .as_deref()
        .unwrap_or("pending")
        .trim()
        .to_ascii_lowercase();
    if !matches!(
        status_filter.as_str(),
        "all" | "pending" | "accepted" | "rejected"
    ) {
        return (StatusCode::BAD_REQUEST, "invalid review queue status").into_response();
    }
    let kind_filter = query
        .kind
        .as_deref()
        .unwrap_or("all")
        .trim()
        .to_ascii_lowercase();
    if !matches!(
        kind_filter.as_str(),
        "all" | "source_claim" | "operating_kpi" | "computed_comparison" | "computed_ratio"
    ) {
        return (StatusCode::BAD_REQUEST, "invalid review queue kind").into_response();
    }
    let selection_mode = query
        .selection
        .as_deref()
        .unwrap_or("full_queue")
        .trim()
        .to_ascii_lowercase();
    if !matches!(
        selection_mode.as_str(),
        "full_queue" | "active_batch" | "source_batch" | "old_wang_batch"
    ) {
        return (StatusCode::BAD_REQUEST, "invalid review queue selection").into_response();
    }
    if selection_mode != "full_queue" && status_filter != "pending" {
        return (
            StatusCode::BAD_REQUEST,
            "review batches only support pending evidence",
        )
            .into_response();
    }
    let limit = if selection_mode != "full_queue" {
        query
            .limit
            .unwrap_or(DEFAULT_ACTIVE_REVIEW_BATCH_SIZE)
            .clamp(1, MAX_ACTIVE_REVIEW_BATCH_SIZE)
    } else {
        query
            .limit
            .unwrap_or(DEFAULT_REVIEW_QUEUE_LIMIT)
            .clamp(1, MAX_REVIEW_QUEUE_LIMIT)
    };
    match read_all_training_samples(&state, symbol_filter.as_deref()).await {
        Ok(samples) => {
            let mut queue = build_evidence_review_queue_with_selection(
                &samples,
                symbol_filter,
                &status_filter,
                &kind_filter,
                limit,
                &selection_mode,
            );
            queue.old_wang_reviewer_configured =
                state.core.config.admins.has_old_wang_web_user_id();
            queue.old_wang_submission_authorized = state
                .core
                .config
                .admins
                .is_old_wang_web_user_id(&admin.user_id);
            Json(queue).into_response()
        }
        Err(error) => {
            warn!(%error, "investment evidence review queue read failed");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                "investment evidence review queue unavailable",
            )
                .into_response()
        }
    }
}

pub(crate) async fn handle_get_reward_governance(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> Response {
    if let Err(response) =
        crate::routes::public_admin::require_public_admin_for_read(&state, &headers)
    {
        return response;
    }
    match reward_governance_context(&state).await {
        Ok((evidence_gate, proposal, latest_review)) => Json(reward_governance_response(
            &evidence_gate,
            &proposal,
            latest_review,
        ))
        .into_response(),
        Err(error) => {
            warn!(%error, "reward governance read failed");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                "reward governance unavailable",
            )
                .into_response()
        }
    }
}

pub(crate) async fn handle_review_reward_governance(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<RewardGovernanceRequest>,
) -> Response {
    let admin =
        match crate::routes::public_admin::require_public_admin_for_mutation(&state, &headers) {
            Ok(admin) => admin,
            Err(response) => return response,
        };
    let _lock = match acquire_reward_governance_lock(&state).await {
        Ok(lock) => lock,
        Err(error) if error == "reward governance review is already in progress" => {
            return (StatusCode::CONFLICT, error).into_response();
        }
        Err(error) => {
            warn!(%error, "reward governance lock failed");
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                "reward governance unavailable",
            )
                .into_response();
        }
    };
    let (evidence_gate, proposal, latest_review) = match reward_governance_context(&state).await {
        Ok(context) => context,
        Err(error) => {
            warn!(%error, "reward governance context failed");
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                "reward governance unavailable",
            )
                .into_response();
        }
    };
    if request.expected_review_id.as_deref()
        != latest_review
            .as_ref()
            .map(|record| record.review_id.as_str())
    {
        return (
            StatusCode::CONFLICT,
            "reward governance changed; reload before submitting",
        )
            .into_response();
    }
    let normalized = match validate_reward_governance_submission(request, &proposal, &evidence_gate)
    {
        Ok(normalized) => normalized,
        Err(error) => return (StatusCode::BAD_REQUEST, error).into_response(),
    };
    let submitted_at = Utc::now();
    let review_id = format!(
        "reward-{}-{}",
        submitted_at.timestamp_millis(),
        Uuid::new_v4()
    );
    let record = RewardGovernanceRecord {
        schema_version: REWARD_GOVERNANCE_SCHEMA_VERSION.to_string(),
        review_id: review_id.clone(),
        previous_review_id: latest_review.map(|record| record.review_id),
        design_version: REWARD_DESIGN_VERSION.to_string(),
        proposal_sha256: reward_objective_sha256(&proposal),
        submitted_at,
        reviewer_id: admin.user_id,
        verdict: normalized.verdict,
        rationale: normalized.rationale,
        component_weights: normalized.component_weights,
        confirmed_hard_gate_ids: normalized.confirmed_hard_gate_ids,
        counterfactual_protocol_confirmed: normalized.counterfactual_protocol_confirmed,
    };
    if let Err(error) = validate_reward_governance_record(&record, &proposal) {
        warn!(%error, "reward governance record validation failed");
        return (StatusCode::BAD_REQUEST, error).into_response();
    }
    let path = reward_governance_directory(&state).join(format!("{review_id}.json"));
    if let Err(error) = write_immutable_json(&path, &record).await {
        warn!(%error, "reward governance audit write failed");
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            "reward governance unavailable",
        )
            .into_response();
    }
    Json(reward_governance_response(
        &evidence_gate,
        &proposal,
        Some(record),
    ))
    .into_response()
}

