pub(crate) async fn handle_register_shadow_implementation(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<ShadowImplementationRegistrationRequest>,
) -> Response {
    let admin =
        match crate::routes::public_admin::require_public_admin_for_mutation(&state, &headers) {
            Ok(admin) => admin,
            Err(response) => return response,
        };
    let _lock = match acquire_shadow_implementation_registry_lock(&state).await {
        Ok(lock) => lock,
        Err(error) if error == "shadow implementation registration is already in progress" => {
            return (StatusCode::CONFLICT, error).into_response();
        }
        Err(error) => {
            warn!(%error, "shadow implementation registry lock failed");
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                "shadow implementation registry unavailable",
            )
                .into_response();
        }
    };
    let (evidence_gate, policy, proposal, reward_review, shadow_review, mut implementations) =
        match shadow_implementation_registry_context(&state).await {
            Ok(context) => context,
            Err(error) => {
                warn!(%error, "shadow implementation registry context failed");
                return (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "shadow implementation registry unavailable",
                )
                    .into_response();
            }
        };
    let normalized = match validate_shadow_implementation_registration_request(
        request,
        &evidence_gate,
        &policy,
        &proposal,
        reward_review.as_ref(),
        shadow_review.as_ref(),
    ) {
        Ok(normalized) => normalized,
        Err(error) => return (StatusCode::BAD_REQUEST, error).into_response(),
    };
    let registered_at = Utc::now();
    let implementation_id = format!(
        "shadow-implementation-{}-{}",
        registered_at.timestamp_millis(),
        Uuid::new_v4()
    );
    let mut record = ShadowImplementationRecord {
        schema_version: SHADOW_IMPLEMENTATION_REGISTRY_SCHEMA_VERSION.to_string(),
        implementation_id: implementation_id.clone(),
        implementation_spec_sha256: String::new(),
        registered_at,
        registered_by: admin.user_id,
        shadow_review_id: normalized.shadow_review_id,
        reward_review_id: normalized.reward_review_id,
        policy_version: policy.policy_version.clone(),
        protocol_sha256: shadow_protocol_sha256(&policy),
        implementation_name: normalized.implementation_name,
        implementation_kind: normalized.implementation_kind,
        code_revision: normalized.code_revision,
        status: "registered_not_started".to_string(),
        input_contract: SHADOW_IMPLEMENTATION_INPUT_CONTRACT.to_string(),
        accounting_contract: SHADOW_IMPLEMENTATION_ACCOUNTING_CONTRACT.to_string(),
        benchmark_symbol: policy.benchmark_symbol.clone(),
        execution_assumption: policy.constraints.execution_assumption.clone(),
        deterministic_replay_required: true,
        outbound_network_allowed: false,
        external_tools_allowed: false,
        production_writes_allowed: false,
        ledger_creation_allowed: false,
        order_generation_allowed: false,
        broker_access_allowed: false,
        run_authorized: false,
        shadow_portfolio_authorized: false,
        trading_authorized: false,
    };
    record.implementation_spec_sha256 = shadow_implementation_spec_sha256(&record);
    if implementations
        .iter()
        .any(|current| current.implementation_spec_sha256 == record.implementation_spec_sha256)
    {
        return (
            StatusCode::CONFLICT,
            "this exact shadow implementation specification is already registered",
        )
            .into_response();
    }
    if let Err(error) = validate_shadow_implementation_record(&record, &policy) {
        warn!(%error, "shadow implementation record validation failed");
        return (StatusCode::BAD_REQUEST, error).into_response();
    }
    let path = shadow_implementation_directory(&state).join(format!("{implementation_id}.json"));
    if let Err(error) = write_immutable_json(&path, &record).await {
        warn!(%error, "shadow implementation registry write failed");
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            "shadow implementation registry unavailable",
        )
            .into_response();
    }
    implementations.push(record);
    Json(shadow_implementation_registry_response(
        &evidence_gate,
        &policy,
        &proposal,
        reward_review.as_ref(),
        shadow_review.as_ref(),
        implementations,
    ))
    .into_response()
}

