pub(crate) async fn refresh_from_company_ratings(
    state: &AppState,
    ratings: &CompanyRatingSnapshot,
) {
    let key_events = super::key_event_chain::current_snapshot(state).await;
    let source_claims = load_source_claims(state, Utc::now()).await;
    let operating_kpi_claims = load_operating_kpi_claims(state, Utc::now()).await;
    let promotion_reviews = load_promotion_review_indexes(state, None).await;
    let macro_report = super::daily_signals::current_macro_report(state).await;
    let snapshots = build_decisions_with_claims(
        ratings,
        Some(&key_events),
        &source_claims,
        &operating_kpi_claims,
        &promotion_reviews,
        Some(&macro_report),
    );
    let mut written = 0usize;
    for snapshot in &snapshots {
        match write_decision(state, snapshot).await {
            Ok(()) => written += 1,
            Err(error) => warn!(
                symbol = %snapshot.symbol,
                %error,
                "investment decision snapshot write failed"
            ),
        }
    }
    info!(
        written,
        total = snapshots.len(),
        "investment decision snapshots refreshed"
    );
    // Historical outcomes must now pass the separately reviewed
    // reconstruction -> protocol -> implementation -> sealed-price -> dry-run
    // authorization chain.  Daily rating refreshes are not an authorized
    // labeler trigger and must never fetch future prices or rewrite samples.
}

/// Re-projects decisions only when the confirmed causal input set changed.
/// This lets the 19:55 key-event worker publish a new point-in-time training
/// state without manufacturing a duplicate revision on no-change days.
pub(crate) async fn refresh_from_key_events(state: &AppState, key_events: &KeyEventChainSnapshot) {
    let ratings = super::company_ratings::current_snapshot(state).await;
    let source_claims = load_source_claims(state, Utc::now()).await;
    let operating_kpi_claims = load_operating_kpi_claims(state, Utc::now()).await;
    let promotion_reviews = load_promotion_review_indexes(state, None).await;
    let macro_report = super::daily_signals::current_macro_report(state).await;
    let candidates = build_decisions_with_claims(
        &ratings,
        Some(key_events),
        &source_claims,
        &operating_kpi_claims,
        &promotion_reviews,
        Some(&macro_report),
    );
    let mut written = Vec::new();
    for snapshot in candidates {
        let unchanged = tokio::fs::read(current_path(state, &snapshot.symbol))
            .await
            .ok()
            .and_then(|bytes| serde_json::from_slice::<InvestmentDecisionSnapshot>(&bytes).ok())
            .filter(|current| validate_point_in_time(current).is_ok())
            .is_some_and(|current| causal_models_equal(&current, &snapshot));
        if unchanged {
            continue;
        }
        match write_decision(state, &snapshot).await {
            Ok(()) => written.push(snapshot),
            Err(error) => warn!(
                symbol = %snapshot.symbol,
                %error,
                "key-event decision projection failed"
            ),
        }
    }
    if !written.is_empty() {
        info!(
            written = written.len(),
            "confirmed key events changed decision causal states"
        );
        // A key-event refresh only freezes a new point-in-time state.  Future
        // outcomes are isolated behind the historical dry-run governance path.
    }
}

/// Freezes the newly published macro state into a separate decision revision.
/// This is still a research trajectory: it does not recalculate an order or
/// mutate the deterministic company action.
pub(crate) async fn refresh_from_macro_signal(state: &AppState, macro_report: &DailySignalReport) {
    if !macro_report_is_eligible(macro_report) {
        return;
    }
    let ratings = super::company_ratings::current_snapshot(state).await;
    let key_events = super::key_event_chain::current_snapshot(state).await;
    let source_claims = load_source_claims(state, macro_report.generated_at).await;
    let operating_kpi_claims = load_operating_kpi_claims(state, macro_report.generated_at).await;
    let promotion_reviews = load_promotion_review_indexes(state, None).await;
    let candidates = build_decisions_with_claims(
        &ratings,
        Some(&key_events),
        &source_claims,
        &operating_kpi_claims,
        &promotion_reviews,
        Some(macro_report),
    );
    let mut written = 0usize;
    for snapshot in candidates {
        let unchanged = tokio::fs::read(current_path(state, &snapshot.symbol))
            .await
            .ok()
            .and_then(|bytes| serde_json::from_slice::<InvestmentDecisionSnapshot>(&bytes).ok())
            .filter(|current| validate_point_in_time(current).is_ok())
            .is_some_and(|current| {
                serde_json::to_value(&current.market_regime).ok()
                    == serde_json::to_value(&snapshot.market_regime).ok()
            });
        if unchanged {
            continue;
        }
        match write_decision(state, &snapshot).await {
            Ok(()) => written += 1,
            Err(error) => {
                warn!(symbol = %snapshot.symbol, %error, "macro-regime decision projection failed")
            }
        }
    }
    if written > 0 {
        info!(
            written,
            "point-in-time macro regime frozen into decision samples"
        );
    }
}

fn causal_models_equal(
    left: &InvestmentDecisionSnapshot,
    right: &InvestmentDecisionSnapshot,
) -> bool {
    match (
        serde_json::to_value(&left.first_principles),
        serde_json::to_value(&right.first_principles),
    ) {
        (Ok(left), Ok(right)) => left == right,
        _ => false,
    }
}

pub(crate) async fn current_decision(
    state: &AppState,
    symbol: &str,
) -> Option<InvestmentDecisionSnapshot> {
    let path = current_path(state, symbol);
    if let Ok(bytes) = tokio::fs::read(&path).await
        && let Ok(snapshot) = serde_json::from_slice::<InvestmentDecisionSnapshot>(&bytes)
        && snapshot.schema_version == SCHEMA_VERSION
        && validate_point_in_time(&snapshot).is_ok()
    {
        if let Err(error) = write_decision_chat_context(state, &snapshot).await {
            warn!(%symbol, %error, "investment decision chat context refresh failed");
        }
        return Some(snapshot);
    }

    let ratings = super::company_ratings::current_snapshot(state).await;
    let key_events = super::key_event_chain::current_snapshot(state).await;
    let source_claims = load_source_claims(state, Utc::now()).await;
    let operating_kpi_claims = load_operating_kpi_claims(state, Utc::now()).await;
    let promotion_reviews = load_promotion_review_indexes(state, Some(symbol)).await;
    let macro_report = super::daily_signals::current_macro_report(state).await;
    let snapshot = build_decisions_with_claims(
        &ratings,
        Some(&key_events),
        &source_claims,
        &operating_kpi_claims,
        &promotion_reviews,
        Some(&macro_report),
    )
    .into_iter()
    .find(|item| item.symbol == symbol)?;
    if let Err(error) = write_decision(state, &snapshot).await {
        warn!(%symbol, %error, "on-demand investment decision write failed");
    }
    Some(snapshot)
}

async fn load_source_claims(state: &AppState, until: DateTime<Utc>) -> Vec<EarningsSourceClaim> {
    let path = state.core.configured_event_store_path();
    tokio::task::spawn_blocking(move || {
        let store = EventStore::open(path)?;
        // SEC point-in-time backfill spans multiple years. Current projections still cap
        // attached observations per driver, while evaluation needs the longer sequence.
        let events =
            store.list_earnings_source_claim_events(until - Duration::days(4_000), until)?;
        Ok::<_, anyhow::Error>(
            events
                .iter()
                .flat_map(source_claims_from_event)
                .filter(|claim| claim.published_at <= until)
                .collect::<Vec<_>>(),
        )
    })
    .await
    .map_err(|error| anyhow::anyhow!(error))
    .and_then(|result| result)
    .unwrap_or_else(|error| {
        warn!(%error, "investment source-claim load failed");
        Vec::new()
    })
}

async fn load_operating_kpi_claims(
    state: &AppState,
    until: DateTime<Utc>,
) -> Vec<OperatingKpiSourceClaim> {
    let path = state.core.configured_event_store_path();
    tokio::task::spawn_blocking(move || {
        let store = EventStore::open(path)?;
        let events =
            store.list_earnings_source_claim_events(until - Duration::days(4_000), until)?;
        Ok::<_, anyhow::Error>(
            events
                .iter()
                .flat_map(operating_kpi_claims_from_event)
                .filter(|claim| claim.published_at <= until)
                .collect::<Vec<_>>(),
        )
    })
    .await
    .map_err(|error| anyhow::anyhow!(error))
    .and_then(|result| result)
    .unwrap_or_else(|error| {
        warn!(%error, "investment operating-KPI claim load failed");
        Vec::new()
    })
}

async fn load_promotion_review_indexes(
    state: &AppState,
    symbol_filter: Option<&str>,
) -> BTreeMap<String, CausalPromotionReviewIndex> {
    let samples = match read_all_training_samples(state, symbol_filter).await {
        Ok(samples) => samples,
        Err(error) => {
            warn!(%error, "causal promotion reviews unavailable");
            return BTreeMap::new();
        }
    };
    causal_promotion_review_indexes(&samples)
}

fn causal_promotion_review_indexes(
    samples: &[DecisionTrainingSample],
) -> BTreeMap<String, CausalPromotionReviewIndex> {
    let mut indexes = BTreeMap::<String, CausalPromotionReviewIndex>::new();
    let mut ordered = samples.iter().collect::<Vec<_>>();
    ordered.sort_by_key(|sample| latest_causal_review_timestamp(sample));
    for sample in ordered {
        let index = indexes.entry(sample.state.symbol.clone()).or_default();
        for review in &sample.human_review.causal_link_reviews {
            let Some(reviewed_at) = causal_review_timestamp(sample, review) else {
                continue;
            };
            index.reviewed_through = Some(
                index
                    .reviewed_through
                    .map(|current| current.max(reviewed_at))
                    .unwrap_or(reviewed_at),
            );
            index.verdicts.insert(
                (review.driver_id.clone(), review.observation_id.clone()),
                CausalReviewVerdictAt {
                    verdict: review.verdict.clone(),
                    effect: review.effect.clone(),
                    speaker_confirmation: review.speaker_confirmation.clone(),
                    old_wang_reviewer_identity_verified: review.old_wang_reviewer_identity_verified,
                    reviewed_at,
                },
            );
        }
    }
    indexes
}

fn build_decisions_with_claims(
    ratings: &CompanyRatingSnapshot,
    key_events: Option<&KeyEventChainSnapshot>,
    source_claims: &[EarningsSourceClaim],
    operating_kpi_claims: &[OperatingKpiSourceClaim],
    promotion_reviews: &BTreeMap<String, CausalPromotionReviewIndex>,
    macro_report: Option<&DailySignalReport>,
) -> Vec<InvestmentDecisionSnapshot> {
    ratings
        .items
        .iter()
        .map(|rating| {
            build_decision_with_context_and_macro(
                ratings,
                rating,
                key_events,
                source_claims,
                operating_kpi_claims,
                promotion_reviews.get(&rating.symbol),
                macro_report,
            )
        })
        .collect()
}

