fn build_decision_with_context_and_macro(
    ratings: &CompanyRatingSnapshot,
    rating: &CompanyRating,
    key_events: Option<&KeyEventChainSnapshot>,
    source_claims: &[EarningsSourceClaim],
    operating_kpi_claims: &[OperatingKpiSourceClaim],
    promotion_reviews: Option<&CausalPromotionReviewIndex>,
    macro_report: Option<&DailySignalReport>,
) -> InvestmentDecisionSnapshot {
    let latest_claim_at = source_claims
        .iter()
        .filter(|claim| claim.symbol.eq_ignore_ascii_case(&rating.symbol))
        .map(|claim| claim.published_at)
        .max();
    let latest_operating_kpi_at = operating_kpi_claims
        .iter()
        .filter(|claim| claim.symbol.eq_ignore_ascii_case(&rating.symbol))
        .map(|claim| claim.published_at)
        .max();
    let decision_at = key_events
        .map(|snapshot| snapshot.generated_at)
        .into_iter()
        .chain(latest_claim_at)
        .chain(latest_operating_kpi_at)
        .chain(
            promotion_reviews
                .and_then(|reviews| reviews.reviewed_through)
                .into_iter(),
        )
        .chain(
            macro_report
                .filter(|report| macro_report_is_eligible(report))
                .map(|report| report.generated_at),
        )
        .filter(|generated_at| *generated_at > ratings.generated_at)
        .max()
        .unwrap_or(ratings.generated_at);
    let decision_date_beijing = decision_at.with_timezone(&Shanghai).date_naive();
    let evidence = build_evidence(rating, decision_date_beijing);
    let mut first_principles = first_principles_model(
        rating,
        decision_date_beijing,
        decision_at,
        key_events,
        source_claims,
        operating_kpi_claims,
    );
    if let Some(model) = &mut first_principles {
        apply_measurement_admissions(model, promotion_reviews);
        apply_causal_promotions(model, promotion_reviews, decision_at);
    }
    let company_quality = company_quality_state(rating, decision_date_beijing);
    let financial_verification =
        financial_state(rating, decision_date_beijing, decision_at, source_claims);
    let valuation = rating
        .valuation
        .as_ref()
        .filter(|value| {
            parse_as_of_date(&value.as_of).is_some_and(|as_of| as_of <= decision_date_beijing)
        })
        .cloned();
    let crowding = crowding_state(rating, valuation.as_ref(), decision_date_beijing);
    let market_regime = market_regime_state(macro_report, decision_at);
    let decision = decision_policy(
        rating,
        valuation.as_ref(),
        &company_quality,
        &financial_verification,
        &crowding,
        first_principles.as_ref(),
        &market_regime,
    );
    let decision_completeness = decision_completeness_state(
        decision_date_beijing,
        first_principles.as_ref(),
        &company_quality,
        &financial_verification,
        valuation.as_ref(),
        &crowding,
        &market_regime,
        &decision,
    );
    InvestmentDecisionSnapshot {
        schema_version: SCHEMA_VERSION.to_string(),
        revision_id: format!(
            "{}-{}-{}",
            rating.symbol,
            decision_at.timestamp_millis(),
            ratings.methodology_version
        ),
        symbol: rating.symbol.clone(),
        company_name: rating.name.clone(),
        theme: rating.theme.clone(),
        decision_at,
        decision_date_beijing,
        source_rating_methodology: ratings.methodology_version.clone(),
        source_rating_score: rating.score,
        source_rating_light: rating.light.clone(),
        data_status: rating.data_status.clone(),
        evidence_coverage: evidence.len(),
        first_principles,
        company_quality,
        financial_verification,
        valuation,
        valuation_missing_reason: rating.valuation_unavailable_reason.clone(),
        crowding,
        market_regime,
        decision_completeness,
        decision,
        evidence,
    }
}

fn company_quality_state(rating: &CompanyRating, decision_date: NaiveDate) -> CompanyQualityState {
    let research_as_of =
        parse_as_of_date(&rating.research_updated_at).filter(|as_of| *as_of <= decision_date);
    if research_as_of.is_none() {
        return CompanyQualityState {
            status: MeasurementStatus::Unmeasured,
            research_as_of: None,
            business_model: "该时间点无可用研究基线".to_string(),
            value_chain: String::new(),
            moat_hypothesis: String::new(),
            thesis: String::new(),
            moat_score: 0.0,
            scarcity_score: 0.0,
            fundamentals_score: 0.0,
            visibility_score: 0.0,
        };
    }
    CompanyQualityState {
        status: MeasurementStatus::PartiallyMeasured,
        research_as_of,
        business_model: rating.business_model.clone(),
        value_chain: rating.value_chain.clone(),
        moat_hypothesis: rating.moat.clone(),
        thesis: rating.thesis_summary.clone(),
        moat_score: rating.dimensions.moat,
        scarcity_score: rating.dimensions.scarcity,
        fundamentals_score: rating.dimensions.fundamentals,
        visibility_score: rating.dimensions.visibility,
    }
}

fn first_principles_model(
    rating: &CompanyRating,
    decision_date: NaiveDate,
    decision_at: DateTime<Utc>,
    key_events: Option<&KeyEventChainSnapshot>,
    source_claims: &[EarningsSourceClaim],
    operating_kpi_claims: &[OperatingKpiSourceClaim],
) -> Option<FirstPrinciplesModel> {
    let financial_current = rating
        .financial_as_of
        .as_deref()
        .and_then(parse_as_of_date)
        .is_some_and(|as_of| as_of <= decision_date);
    let forward_current = rating
        .metrics
        .forward_metric_as_of
        .as_deref()
        .and_then(parse_as_of_date)
        .is_some_and(|as_of| as_of <= decision_date)
        && rating.metrics.forward_metric_growth_percent.is_some();
    let measurements = ModelMeasurements {
        forward_operating: forward_current,
        margin: financial_current
            && (rating.metrics.gross_margin_percent.is_some()
                || rating.metrics.gross_margin_change_pp.is_some()),
        cash_conversion: financial_current
            && (rating.metrics.operating_cash_flow_growth_percent.is_some()
                || rating.metrics.free_cash_flow_growth_percent.is_some()
                || rating.metrics.fcf_margin_percent.is_some()),
        capital_expenditure: financial_current
            && (rating.metrics.capital_expenditure_growth_percent.is_some()
                || rating
                    .metrics
                    .property_plant_equipment_growth_percent
                    .is_some()),
    };

    let mut model = if rating.theme.contains("存储")
        || matches!(
            rating.symbol.as_str(),
            "SNDK" | "MU" | "SKHY" | "STX" | "WDC"
        ) {
        storage_first_principles(rating, measurements)
    } else if rating.theme.contains("光通信/网络") {
        optical_interconnect_model(rating, measurements)
    } else if rating.theme.contains("电力/液冷") {
        data_center_power_model(rating, measurements)
    } else if rating.theme.contains("算力芯片/制造") || rating.theme.contains("半导体设备")
    {
        ai_compute_model(rating, measurements)
    } else if rating.theme.contains("AI平台/软件")
        || rating.theme.contains("New Cloud")
        || rating.theme.contains("AI服务器/OEM")
    {
        ai_platform_model(rating, measurements)
    } else if rating.theme.contains("AI医疗") {
        ai_application_model(rating, measurements)
    } else {
        return None;
    };
    if let Some(catalog_model_id) = operating_kpi_model_id_for_symbol(&rating.symbol)
        && catalog_model_id != model.model_id
    {
        warn!(
            symbol = %rating.symbol,
            rating_model_id = %model.model_id,
            catalog_model_id,
            "first-principles model disagrees with the shared operating-KPI catalog"
        );
        return None;
    }
    attach_causal_observations(
        &mut model,
        rating,
        decision_date,
        decision_at,
        key_events,
        source_claims,
        operating_kpi_claims,
    );
    Some(model)
}

