fn inventory_proxy_driver(model_id: &str) -> Option<&'static str> {
    match model_id {
        "ai-storage-demand-supply" => Some("inventory_price"),
        "ai-compute-effective-capacity" => Some("yield_lead_time"),
        "ai-optical-interconnect-bandwidth" => Some("deployment_inventory"),
        _ => None,
    }
}

fn confirmed_event_driver(model_id: &str, topic_id: &str) -> Option<&'static str> {
    match (model_id, topic_id) {
        ("ai-storage-demand-supply", "hbm" | "hbf" | "nand_ssd") => Some("inventory_price"),
        ("ai-storage-demand-supply", "models" | "applications") => Some("enterprise_adoption"),
        ("ai-compute-effective-capacity", "asic" | "rubin") => Some("architecture_content"),
        ("ai-compute-effective-capacity", "models") => Some("inference_tokens"),
        ("ai-compute-effective-capacity", "data_center") => Some("power_deployment"),
        ("ai-optical-interconnect-bandwidth", "optical_800g_16t" | "cpo" | "npo") => {
            Some("bandwidth_generation")
        }
        ("ai-optical-interconnect-bandwidth", "data_center") => Some("accelerator_ports"),
        ("ai-data-center-power-delivery", "sofc") => Some("generation_equipment"),
        ("ai-data-center-power-delivery", "data_center") => Some("deployed_compute_mw"),
        ("ai-platform-token-economics", "models") => Some("usage_intensity"),
        ("ai-platform-token-economics", "applications") => Some("paid_workloads"),
        ("ai-platform-token-economics", "data_center" | "asic" | "rubin") => {
            Some("capacity_deployment")
        }
        ("ai-application-workflow-value", "applications") => Some("adoption_usage"),
        ("ai-application-workflow-value", "models") => Some("outcome_quality"),
        _ => None,
    }
}

fn truncate_causal_text(value: &str, max: usize) -> String {
    let mut output = value.chars().take(max).collect::<String>();
    if value.chars().count() > max {
        output.push('…');
    }
    output
}

fn model_driver(
    driver_id: &str,
    label: &str,
    mechanism: &str,
    required_observations: Vec<&str>,
    partially_measured: bool,
) -> ModelDriver {
    ModelDriver {
        driver_id: driver_id.to_string(),
        label: label.to_string(),
        mechanism: mechanism.to_string(),
        required_observations: required_observations
            .into_iter()
            .map(str::to_string)
            .collect(),
        measurement_status: if partially_measured {
            MeasurementStatus::PartiallyMeasured
        } else {
            MeasurementStatus::Unmeasured
        },
        observations: Vec::new(),
        promotion: CausalPromotionState::default(),
    }
}

fn financial_state(
    rating: &CompanyRating,
    decision_date: NaiveDate,
    decision_at: DateTime<Utc>,
    source_claims: &[EarningsSourceClaim],
) -> FinancialVerificationState {
    financial_state_from_inputs(
        &rating.symbol,
        rating.financial_as_of.as_deref(),
        &rating.metrics,
        decision_date,
        decision_at,
        source_claims,
    )
}

/// Projects the same point-in-time SEC claim ledger used by the decision
/// engine into rating-facing financial evidence. The projection deliberately
/// carries the claim policy and quality warnings; callers must not treat the
/// result as rating-eligible merely because a regulatory source exists.
pub(crate) async fn current_sec_financial_states(
    state: &AppState,
    symbols: &[String],
    decision_at: DateTime<Utc>,
) -> HashMap<String, FinancialVerificationState> {
    let claims = load_source_claims(state, decision_at).await;
    let decision_date = decision_at.with_timezone(&Shanghai).date_naive();
    symbols
        .iter()
        .filter_map(|symbol| {
            let projected = financial_state_from_inputs(
                symbol,
                None,
                &RatingMetrics::default(),
                decision_date,
                decision_at,
                &claims,
            );
            (!projected.source_claim_ids.is_empty()).then(|| (symbol.clone(), projected))
        })
        .collect()
}

fn financial_state_from_inputs(
    symbol: &str,
    financial_as_of: Option<&str>,
    metrics: &RatingMetrics,
    decision_date: NaiveDate,
    decision_at: DateTime<Utc>,
    source_claims: &[EarningsSourceClaim],
) -> FinancialVerificationState {
    let matching = source_claims
        .iter()
        .filter(|claim| claim.symbol.eq_ignore_ascii_case(symbol))
        .filter(|claim| claim.published_at <= decision_at)
        .collect::<Vec<_>>();
    let resolutions = resolve_claim_lifecycles(&matching);
    let comparisons = computed_claim_comparisons(&matching, &resolutions);
    let ratios = computed_claim_ratios(&matching, &resolutions);
    let ratio_trends = computed_claim_ratio_trends(&ratios);
    let latest_yoy = |metric_id: &str| {
        comparisons
            .iter()
            .filter(|comparison| comparison.kind == CausalComparisonKind::YearOverYear)
            .filter(|comparison| comparison.current.metric_id == metric_id)
            .max_by_key(|comparison| comparison.current.published_at)
    };
    let latest_ratio = |metric_id: &str| {
        ratios
            .iter()
            .filter(|ratio| ratio.metric_id == metric_id)
            .max_by_key(|ratio| ratio.numerator.published_at)
    };
    let latest_ratio_yoy = |metric_id: &str| {
        ratio_trends
            .iter()
            .filter(|trend| trend.comparison_kind == CausalComparisonKind::YearOverYear)
            .filter(|trend| trend.current.metric_id == metric_id)
            .max_by_key(|trend| trend.current.numerator.published_at)
    };
    let latest_active_claim = |metric_id: &str| {
        matching
            .iter()
            .copied()
            .filter(|claim| claim.metric_id == metric_id)
            .filter(|claim| {
                resolutions.get(&claim.claim_id).is_some_and(|resolution| {
                    resolution.status == CausalClaimLifecycleStatus::Active
                })
            })
            .filter(|claim| claim.numeric_value.is_some())
            .max_by_key(|claim| claim.published_at)
    };
    let sec_revenue_growth = latest_yoy("revenue");
    let sec_gross_margin = latest_ratio("gross_margin");
    let sec_gross_margin_change = latest_ratio_yoy("gross_margin");
    let sec_operating_margin = latest_ratio("operating_margin");
    let sec_accounts_receivable_growth = latest_yoy("accounts_receivable");
    let sec_accounts_payable_growth = latest_yoy("accounts_payable");
    let sec_inventory_growth = latest_yoy("inventory");
    let sec_property_plant_equipment_growth = latest_yoy("property_plant_equipment");
    let sec_operating_cash_flow_growth = latest_yoy("operating_cash_flow");
    let sec_capital_expenditure_growth = latest_yoy("capital_expenditure");
    let sec_cash_and_equivalents = latest_active_claim("cash_and_equivalents");
    let sec_long_term_debt = latest_active_claim("long_term_debt");
    let comparable_fcf_pair = sec_operating_cash_flow_growth
        .zip(sec_capital_expenditure_growth)
        .filter(|(cashflow, capex)| {
            cashflow.current.period == capex.current.period
                && cashflow.prior.period == capex.prior.period
                && cashflow.current.unit == capex.current.unit
                && cashflow.prior.unit == capex.prior.unit
                && cashflow.current.unit == cashflow.prior.unit
        })
        .and_then(|(cashflow, capex)| {
            Some((
                cashflow.current.numeric_value? - capex.current.numeric_value?,
                cashflow.prior.numeric_value? - capex.prior.numeric_value?,
                cashflow.current.unit.clone(),
            ))
        });
    let mut selected_claims = Vec::<&EarningsSourceClaim>::new();
    for comparison in [
        sec_revenue_growth,
        sec_accounts_receivable_growth,
        sec_accounts_payable_growth,
        sec_inventory_growth,
        sec_property_plant_equipment_growth,
        sec_operating_cash_flow_growth,
        sec_capital_expenditure_growth,
    ]
    .into_iter()
    .flatten()
    {
        selected_claims.push(&comparison.current);
        selected_claims.push(&comparison.prior);
    }
    for ratio in [sec_gross_margin, sec_operating_margin]
        .into_iter()
        .flatten()
    {
        selected_claims.push(&ratio.numerator);
        selected_claims.push(&ratio.denominator);
    }
    if let Some(trend) = sec_gross_margin_change {
        selected_claims.push(&trend.current.numerator);
        selected_claims.push(&trend.current.denominator);
        selected_claims.push(&trend.prior.numerator);
        selected_claims.push(&trend.prior.denominator);
    }
    selected_claims.extend(sec_cash_and_equivalents);
    selected_claims.extend(sec_long_term_debt);
    let source_claim_ids = unique_strings(
        selected_claims
            .iter()
            .map(|claim| claim.claim_id.clone())
            .collect(),
    );
    let source_urls = unique_strings(
        selected_claims
            .iter()
            .map(|claim| claim.source_url.clone())
            .collect(),
    );
    let source_calculations = unique_strings(
        [
            sec_revenue_growth.map(|value| financial_comparison_trace("收入同比", value)),
            sec_accounts_receivable_growth
                .map(|value| financial_comparison_trace("应收账款同比", value)),
            sec_accounts_payable_growth
                .map(|value| financial_comparison_trace("应付账款同比", value)),
            sec_inventory_growth.map(|value| financial_comparison_trace("库存同比", value)),
            sec_property_plant_equipment_growth
                .map(|value| financial_comparison_trace("PPE同比", value)),
            sec_operating_cash_flow_growth
                .map(|value| financial_comparison_trace("经营现金流同比", value)),
            sec_capital_expenditure_growth
                .map(|value| financial_comparison_trace("资本开支同比", value)),
            sec_gross_margin.map(|value| financial_ratio_trace("毛利率", value)),
            sec_operating_margin.map(|value| financial_ratio_trace("营业利润率", value)),
            sec_gross_margin_change.map(|value| {
                format!(
                    "毛利率同比：{} {:.1}% → {} {:.1}%，变化 {:+.1} 个百分点",
                    value.prior.numerator.period,
                    value.prior.result_percent,
                    value.current.numerator.period,
                    value.current.result_percent,
                    value.change_percentage_points
                )
            }),
            comparable_fcf_pair.as_ref().map(|(current, prior, unit)| {
                format!(
                    "自由现金流：经营现金流 − 资本开支；上期 {} {}，本期 {} {}",
                    format_compact_number(*prior),
                    unit,
                    format_compact_number(*current),
                    unit
                )
            }),
        ]
        .into_iter()
        .flatten()
        .collect(),
    );
    let source_claims = selected_claims
        .iter()
        .filter_map(|claim| {
            Some(FinancialSourceClaimTrace {
                claim_id: claim.claim_id.clone(),
                metric_id: claim.metric_id.clone(),
                metric_basis: claim.metric_basis.clone(),
                period: claim.period.clone(),
                numeric_value: claim.numeric_value?,
                unit: claim.unit.clone(),
                source_url: claim.source_url.clone(),
                published_at: claim.published_at,
            })
        })
        .map(|trace| (trace.claim_id.clone(), trace))
        .collect::<BTreeMap<_, _>>()
        .into_values()
        .collect::<Vec<_>>();
    let mut quality_warnings = Vec::new();
    for (label, comparison) in [
        ("收入同比", sec_revenue_growth),
        ("应收账款同比", sec_accounts_receivable_growth),
        ("应付账款同比", sec_accounts_payable_growth),
        ("库存同比", sec_inventory_growth),
        ("PPE同比", sec_property_plant_equipment_growth),
        ("经营现金流同比", sec_operating_cash_flow_growth),
        ("资本开支同比", sec_capital_expenditure_growth),
    ] {
        if comparison.is_some_and(|value| value.change_percent.abs() >= 200.0) {
            quality_warnings.push(format!(
                "{label}绝对变化达到 200% 以上：数学结果保留，但需回看原表、低基数和特殊事项后才能用于判断"
            ));
        }
    }
    if sec_gross_margin_change.is_some_and(|value| value.change_percentage_points.abs() >= 40.0) {
        quality_warnings.push(
            "毛利率同比变化达到 40 个百分点以上：需核对产品结构、价格周期、会计口径和一次性事项"
                .to_string(),
        );
    }
    if [sec_gross_margin, sec_operating_margin]
        .into_iter()
        .flatten()
        .any(|ratio| !(-100.0..=100.0).contains(&ratio.result_percent))
    {
        quality_warnings.push(
            "利润率落在常规百分比边界之外：进入人工数据质量复核，不参与完整性通过".to_string(),
        );
    }
    if comparable_fcf_pair
        .as_ref()
        .is_some_and(|(current, prior, _)| *current <= 0.0 || *prior <= 0.0)
    {
        quality_warnings.push(
            "自由现金流至少一期为非正值：保留绝对额，但百分比增长没有经济意义，不予计算"
                .to_string(),
        );
    }
    let quality_warnings = unique_strings(quality_warnings);
    let sec_financial_as_of = selected_claims
        .iter()
        .map(|claim| claim.published_at)
        .max()
        .map(|published_at| {
            published_at
                .with_timezone(&Shanghai)
                .date_naive()
                .to_string()
        });
    let valid_financial = financial_as_of
        .and_then(parse_as_of_date)
        .is_some_and(|as_of| as_of <= decision_date);
    let valid_forward = metrics
        .forward_metric_as_of
        .as_deref()
        .and_then(parse_as_of_date)
        .is_some_and(|as_of| as_of <= decision_date);
    let revenue_growth_percent = sec_revenue_growth
        .map(|comparison| comparison.change_percent)
        .or_else(|| {
            valid_financial
                .then_some(metrics.revenue_growth_percent)
                .flatten()
        });
    let gross_margin_percent = sec_gross_margin
        .map(|ratio| ratio.result_percent)
        .or_else(|| {
            valid_financial
                .then_some(metrics.gross_margin_percent)
                .flatten()
        });
    let gross_margin_change_pp = sec_gross_margin_change
        .map(|trend| trend.change_percentage_points)
        .or_else(|| {
            valid_financial
                .then_some(metrics.gross_margin_change_pp)
                .flatten()
        });
    let ebit_margin_percent = sec_operating_margin
        .map(|ratio| ratio.result_percent)
        .or_else(|| {
            valid_financial
                .then_some(metrics.ebit_margin_percent)
                .flatten()
        });
    let fcf_margin_percent = valid_financial
        .then_some(metrics.fcf_margin_percent)
        .flatten();
    let accounts_receivable_growth_percent = sec_accounts_receivable_growth
        .map(|comparison| comparison.change_percent)
        .or_else(|| {
            valid_financial
                .then_some(metrics.accounts_receivable_growth_percent)
                .flatten()
        });
    let accounts_payable_growth_percent = sec_accounts_payable_growth
        .map(|comparison| comparison.change_percent)
        .or_else(|| {
            valid_financial
                .then_some(metrics.accounts_payable_growth_percent)
                .flatten()
        });
    let inventory_growth_percent = sec_inventory_growth
        .map(|comparison| comparison.change_percent)
        .or_else(|| {
            valid_financial
                .then_some(metrics.inventory_growth_percent)
                .flatten()
        });
    let property_plant_equipment_growth_percent = sec_property_plant_equipment_growth
        .map(|comparison| comparison.change_percent)
        .or_else(|| {
            valid_financial
                .then_some(metrics.property_plant_equipment_growth_percent)
                .flatten()
        });
    let operating_cash_flow_growth_percent = sec_operating_cash_flow_growth
        .map(|comparison| comparison.change_percent)
        .or_else(|| {
            valid_financial
                .then_some(metrics.operating_cash_flow_growth_percent)
                .flatten()
        });
    let capital_expenditure_growth_percent = sec_capital_expenditure_growth
        .map(|comparison| comparison.change_percent)
        .or_else(|| {
            valid_financial
                .then_some(metrics.capital_expenditure_growth_percent)
                .flatten()
        });
    let free_cash_flow_growth_percent = match comparable_fcf_pair.as_ref() {
        Some((current, prior, _)) if *current > 0.0 && *prior > 0.0 => {
            Some((current / prior - 1.0) * 100.0)
        }
        // Once current SEC cash-flow facts exist, an economically meaningless
        // percentage must not be backfilled from an older rating snapshot.
        Some(_) => None,
        None => valid_financial
            .then_some(metrics.free_cash_flow_growth_percent)
            .flatten(),
    };
    let cash_and_equivalents = sec_cash_and_equivalents.and_then(|claim| claim.numeric_value);
    let long_term_debt = sec_long_term_debt.and_then(|claim| claim.numeric_value);
    let net_cash = cash_and_equivalents
        .zip(long_term_debt)
        .and_then(|(cash, debt)| {
            (sec_cash_and_equivalents?.unit == sec_long_term_debt?.unit).then_some(cash - debt)
        });
    let current_free_cash_flow = comparable_fcf_pair.as_ref().map(|(current, _, _)| *current);
    let prior_free_cash_flow = comparable_fcf_pair.as_ref().map(|(_, prior, _)| *prior);
    let financial_value_unit = comparable_fcf_pair
        .as_ref()
        .map(|(_, _, unit)| unit.clone())
        .or_else(|| sec_cash_and_equivalents.map(|claim| claim.unit.clone()));
    let forward_metric_growth_percent = valid_forward
        .then_some(metrics.forward_metric_growth_percent)
        .flatten();
    let observed = [
        revenue_growth_percent,
        gross_margin_percent,
        gross_margin_change_pp,
        ebit_margin_percent,
        fcf_margin_percent,
        forward_metric_growth_percent,
        accounts_receivable_growth_percent,
        accounts_payable_growth_percent,
        inventory_growth_percent,
        property_plant_equipment_growth_percent,
        operating_cash_flow_growth_percent,
        capital_expenditure_growth_percent,
        free_cash_flow_growth_percent,
    ]
    .into_iter()
    .flatten()
    .count();
    let status = if observed == 0 {
        MeasurementStatus::Unmeasured
    } else if observed < 13 {
        MeasurementStatus::PartiallyMeasured
    } else {
        MeasurementStatus::Measured
    };
    let mut missing_checks = Vec::new();
    if revenue_growth_percent.is_none() {
        missing_checks.push("收入增长".to_string());
    }
    if gross_margin_percent.is_none() {
        missing_checks.push("毛利率".to_string());
    }
    if gross_margin_change_pp.is_none() {
        missing_checks.push("毛利率同比变化".to_string());
    }
    if fcf_margin_percent.is_none() || free_cash_flow_growth_percent.is_none() {
        missing_checks.push("自由现金流率".to_string());
    }
    if forward_metric_growth_percent.is_none() {
        missing_checks.push("积压订单/RPO/ARR/订单或指引增长".to_string());
    }
    // These working-capital and capacity fields do not yet exist in the
    // rating feed.  Keep them visible as training/evidence gaps.
    if accounts_receivable_growth_percent.is_none() {
        missing_checks.push("应收账款与收入增速对比".to_string());
    }
    if accounts_payable_growth_percent.is_none() {
        missing_checks.push("应付账款与采购/产能变化".to_string());
    }
    if inventory_growth_percent.is_none() {
        missing_checks.push("库存数量、结构与周转".to_string());
    }
    if property_plant_equipment_growth_percent.is_none()
        || capital_expenditure_growth_percent.is_none()
    {
        missing_checks.push("资本开支与PPE变化".to_string());
    }
    missing_checks.push("真实产能、利用率与扩产时间（需公司或产业证据）".to_string());
    FinancialVerificationState {
        policy_version: FINANCIAL_VERIFICATION_POLICY_VERSION.to_string(),
        status,
        financial_as_of: sec_financial_as_of.or_else(|| {
            valid_financial
                .then(|| financial_as_of.map(str::to_string))
                .flatten()
        }),
        revenue_growth_percent,
        gross_margin_percent,
        gross_margin_change_pp,
        ebit_margin_percent,
        fcf_margin_percent,
        accounts_receivable_growth_percent,
        accounts_payable_growth_percent,
        inventory_growth_percent,
        property_plant_equipment_growth_percent,
        operating_cash_flow_growth_percent,
        capital_expenditure_growth_percent,
        free_cash_flow_growth_percent,
        cash_and_equivalents,
        long_term_debt,
        net_cash,
        current_free_cash_flow,
        prior_free_cash_flow,
        financial_value_unit,
        forward_metric_label: valid_forward
            .then_some(metrics.forward_metric_label.clone())
            .flatten(),
        forward_metric_value: valid_forward
            .then_some(metrics.forward_metric_value.clone())
            .flatten(),
        forward_metric_growth_percent,
        forward_metric_as_of: valid_forward
            .then_some(metrics.forward_metric_as_of.clone())
            .flatten(),
        source_claim_ids,
        source_urls,
        source_calculations,
        source_claims,
        quality_warnings,
        missing_checks,
    }
}

fn financial_comparison_trace(label: &str, value: &ComputedClaimComparison) -> String {
    format!(
        "{label}：{} {} {} → {} {} {}，变化 {:+.1}%",
        value.prior.period,
        format_compact_number(value.prior.numeric_value.unwrap_or_default()),
        value.prior.unit,
        value.current.period,
        format_compact_number(value.current.numeric_value.unwrap_or_default()),
        value.current.unit,
        value.change_percent
    )
}

fn financial_ratio_trace(label: &str, value: &ComputedClaimRatio) -> String {
    format!(
        "{label}：{} / {} = {:.1}%（{}；{}）",
        format_compact_number(value.numerator.numeric_value.unwrap_or_default()),
        format_compact_number(value.denominator.numeric_value.unwrap_or_default()),
        value.result_percent,
        value.numerator.period,
        value.numerator.unit
    )
}

fn macro_report_is_eligible(report: &DailySignalReport) -> bool {
    report.kind == "macro"
        && report.status != "framework_only"
        && report.status != "stale"
        && !report.stale
        && report
            .score
            .is_some_and(|score| score.is_finite() && (0.0..=100.0).contains(&score))
}

fn market_regime_label(score: f64) -> &'static str {
    if score >= 70.0 {
        "supportive"
    } else if score >= 55.0 {
        "balanced"
    } else if score >= 40.0 {
        "defensive"
    } else {
        "stress"
    }
}

fn unavailable_market_regime(reason: impl Into<String>) -> MarketRegimeState {
    MarketRegimeState {
        taxonomy_version: MARKET_REGIME_TAXONOMY_VERSION.to_string(),
        missing_reason: reason.into(),
        ..Default::default()
    }
}

fn market_regime_state(
    report: Option<&DailySignalReport>,
    decision_at: DateTime<Utc>,
) -> MarketRegimeState {
    let Some(report) = report else {
        return unavailable_market_regime("该决策时间点没有宏观快照");
    };
    if !macro_report_is_eligible(report)
        || report.generated_at > decision_at
        || decision_at - report.generated_at > Duration::hours(MARKET_REGIME_MAX_AGE_HOURS)
        || report
            .data_cutoff
            .as_deref()
            .and_then(parse_as_of_date)
            .is_some_and(|cutoff| cutoff > decision_at.with_timezone(&Shanghai).date_naive())
    {
        return unavailable_market_regime("宏观快照缺失、过期或晚于该决策时间点");
    }
    let Some(score) = report
        .score
        .filter(|score| score.is_finite() && (0.0..=100.0).contains(score))
    else {
        return unavailable_market_regime("宏观快照没有可核验评分");
    };
    let source_urls = report
        .evidence
        .iter()
        .map(|item| item.source_url.trim())
        .chain(report.sources.iter().map(|item| item.url.trim()))
        .filter(|url| url.starts_with("https://"))
        .map(str::to_string)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .take(24)
        .collect::<Vec<_>>();
    if source_urls.is_empty() {
        return unavailable_market_regime("宏观快照缺少可追溯来源");
    }
    MarketRegimeState {
        taxonomy_version: MARKET_REGIME_TAXONOMY_VERSION.to_string(),
        status: MarketRegimeStatus::Observed,
        label: market_regime_label(score).to_string(),
        macro_score: Some(score),
        macro_signal: report.signal.clone(),
        macro_phase: report.phase.clone(),
        report_generated_at: Some(report.generated_at),
        data_cutoff: report.data_cutoff.clone(),
        source_model_version: report.model_version.clone(),
        source_urls,
        missing_reason: String::new(),
    }
}

fn crowding_state(
    rating: &CompanyRating,
    valuation: Option<&DailyValuation>,
    decision_date: NaiveDate,
) -> CrowdingState {
    let market_as_of = rating
        .market_as_of
        .clone()
        .unwrap_or_else(|| decision_date.to_string());
    let market_source = rating
        .data_sources
        .iter()
        .find(|source| source.contains("FMP") || source.contains("Nasdaq"))
        .cloned()
        .unwrap_or_else(|| "公司评级行情快照".to_string());
    let usable_history = rating.market_history.as_ref().filter(|history| {
        history.policy_version == "hone-market-history-v1-nasdaq-daily-close"
            && history.quality_status == "usable"
            && history.quality_warnings.is_empty()
            && history.source_url.starts_with("https://")
            && parse_as_of_date(&history.as_of).is_some_and(|as_of| {
                as_of <= decision_date && decision_date.signed_duration_since(as_of).num_days() <= 7
            })
    });
    let usable_short_interest = rating.short_interest.as_ref().filter(|summary| {
        summary.policy_version == SHORT_INTEREST_POLICY_VERSION
            && summary.quality_status == "usable"
            && summary.quality_warnings.is_empty()
            && summary.source_url.starts_with("https://")
            && parse_as_of_date(&summary.as_of).is_some_and(|as_of| {
                as_of <= decision_date
                    && decision_date.signed_duration_since(as_of).num_days() <= 45
            })
    });
    let usable_options_positioning = rating.options_positioning.as_ref().filter(|summary| {
        summary.policy_version == OPTIONS_POSITIONING_POLICY_VERSION
            && summary.quality_status == "usable"
            && summary.quality_warnings.is_empty()
            && summary.source_url.starts_with("https://")
            && parse_as_of_date(&summary.as_of).is_some_and(|as_of| {
                as_of <= decision_date && decision_date.signed_duration_since(as_of).num_days() <= 5
            })
    });
    let usable_news_attention = rating.news_attention.as_ref().filter(|summary| {
        summary.policy_version == NEWS_ATTENTION_POLICY_VERSION
            && summary.quality_status == "usable"
            && summary.quality_warnings.is_empty()
            && summary.source_url.starts_with("https://")
            && parse_as_of_date(&summary.as_of).is_some_and(|as_of| {
                as_of <= decision_date && decision_date.signed_duration_since(as_of).num_days() <= 1
            })
    });
    let usable_institutional_holdings = rating.institutional_holdings.as_ref().filter(|summary| {
        summary.policy_version == INSTITUTIONAL_HOLDINGS_POLICY_VERSION
            && summary.quality_status == "usable"
            && summary.quality_warnings.is_empty()
            && summary.source_url.starts_with("https://")
            && parse_as_of_date(&summary.observed_on).is_some_and(|observed_on| {
                observed_on <= decision_date
                    && decision_date.signed_duration_since(observed_on).num_days()
                        <= INSTITUTIONAL_HOLDINGS_MAX_OBSERVATION_AGE_DAYS
            })
    });
    let usable_analyst_consensus = rating.analyst_consensus.as_ref().filter(|summary| {
        summary.policy_version == ANALYST_CONSENSUS_POLICY_VERSION
            && summary.quality_status == "usable"
            && summary.quality_warnings.is_empty()
            && summary.source_url.starts_with("https://")
            && parse_as_of_date(&summary.observed_on).is_some_and(|observed_on| {
                observed_on <= decision_date
                    && decision_date.signed_duration_since(observed_on).num_days()
                        <= ANALYST_CONSENSUS_MAX_OBSERVATION_AGE_DAYS
            })
    });
    let trend_as_of = usable_history
        .map(|history| history.as_of.clone())
        .unwrap_or_else(|| market_as_of.clone());
    let trend_source = usable_history
        .map(|history| history.source_url.clone())
        .unwrap_or_else(|| market_source.clone());
    let mut components = Vec::new();
    if let (Some(price), Some(low), Some(high)) = (rating.price, rating.year_low, rating.year_high)
        && price.is_finite()
        && low.is_finite()
        && high.is_finite()
        && price > 0.0
        && low > 0.0
        && high > low
    {
        let position = ((price - low) / (high - low) * 100.0).clamp(0.0, 100.0);
        components.push(CrowdingComponent {
            component_id: "price_position_52w".to_string(),
            label: "52周价格位置".to_string(),
            raw_value_percent: position,
            pressure_score: position,
            weight: 0.20,
            as_of: market_as_of.clone(),
            source: market_source.clone(),
        });
    }
    if let (Some(price), Some(avg50)) = (rating.price, rating.price_avg50)
        && price.is_finite()
        && avg50.is_finite()
        && price > 0.0
        && avg50 > 0.0
    {
        let extension = (price / avg50 - 1.0) * 100.0;
        components.push(CrowdingComponent {
            component_id: "price_vs_50d".to_string(),
            label: "现价相对50日均线".to_string(),
            raw_value_percent: extension,
            pressure_score: crowding_anchor(extension),
            weight: 0.15,
            as_of: trend_as_of.clone(),
            source: trend_source.clone(),
        });
    }
    if let (Some(avg50), Some(avg200)) = (rating.price_avg50, rating.price_avg200)
        && avg50.is_finite()
        && avg200.is_finite()
        && avg50 > 0.0
        && avg200 > 0.0
    {
        let trend = (avg50 / avg200 - 1.0) * 100.0;
        components.push(CrowdingComponent {
            component_id: "average_50d_vs_200d".to_string(),
            label: "50日均线相对200日均线".to_string(),
            raw_value_percent: trend,
            pressure_score: crowding_anchor(trend),
            weight: 0.10,
            as_of: trend_as_of,
            source: trend_source,
        });
    }
    if let Some(value) = valuation.filter(|value| {
        parse_as_of_date(&value.as_of).is_some_and(|as_of| {
            as_of <= decision_date && decision_date.signed_duration_since(as_of).num_days() <= 7
        }) && value.current_price.is_finite()
            && value.bear_case.is_finite()
            && value.bull_case.is_finite()
            && value.bull_case > value.bear_case
    }) {
        let position =
            ((value.current_price - value.bear_case) / (value.bull_case - value.bear_case) * 100.0)
                .clamp(0.0, 100.0);
        components.push(CrowdingComponent {
            component_id: "valuation_scenario_position".to_string(),
            label: "现价在悲观—乐观估值区间的位置".to_string(),
            raw_value_percent: position,
            pressure_score: position,
            weight: 0.20,
            as_of: value.as_of.clone(),
            source: format!("多方法三情景估值：{}", value.method),
        });
    }
    let market_history = usable_history;
    if let Some(history) = market_history {
        if let Some(value) = history
            .return_20_sessions_percent
            .filter(|value| value.is_finite())
        {
            components.push(CrowdingComponent {
                component_id: "return_20_sessions".to_string(),
                label: "20交易日价格变化".to_string(),
                raw_value_percent: value,
                pressure_score: short_return_pressure(value),
                weight: 0.10,
                as_of: history.as_of.clone(),
                source: history.source_url.clone(),
            });
        }
        if let Some(value) = history
            .return_60_sessions_percent
            .filter(|value| value.is_finite())
        {
            components.push(CrowdingComponent {
                component_id: "return_60_sessions".to_string(),
                label: "60交易日价格变化".to_string(),
                raw_value_percent: value,
                pressure_score: medium_return_pressure(value),
                weight: 0.10,
                as_of: history.as_of.clone(),
                source: history.source_url.clone(),
            });
        }
        if let Some(value) = history
            .drawdown_from_60_session_high_percent
            .filter(|value| value.is_finite() && *value <= 0.0)
        {
            components.push(CrowdingComponent {
                component_id: "drawdown_from_60_session_high".to_string(),
                label: "距60交易日收盘高点".to_string(),
                raw_value_percent: value,
                pressure_score: drawdown_pressure(value),
                weight: 0.10,
                as_of: history.as_of.clone(),
                source: history.source_url.clone(),
            });
        }
        if let (Some(return_20), Some(volume_ratio)) = (
            history.return_20_sessions_percent,
            history.recent_5_session_volume_vs_prior_55_percent,
        ) && return_20.is_finite()
            && volume_ratio.is_finite()
            && volume_ratio >= 0.0
        {
            let signed_excess = signed_volume_excess(return_20, volume_ratio);
            components.push(CrowdingComponent {
                component_id: "volume_direction_confirmation".to_string(),
                label: "近期异常成交量与20日方向共振".to_string(),
                raw_value_percent: signed_excess,
                pressure_score: volume_direction_pressure(signed_excess),
                weight: 0.05,
                as_of: history.as_of.clone(),
                source: history.source_url.clone(),
            });
        }
    }
    let weight_sum = components.iter().map(|item| item.weight).sum::<f64>();
    let score = (weight_sum > 0.0).then(|| {
        components
            .iter()
            .map(|item| item.pressure_score * item.weight)
            .sum::<f64>()
            / weight_sum
    });
    let mut observations = components
        .iter()
        .map(|item| {
            format!(
                "{} {:+.1}% → 压力分 {:.1}（{}）",
                item.label, item.raw_value_percent, item.pressure_score, item.as_of
            )
        })
        .collect::<Vec<_>>();
    if let Some(history) = usable_history
        && let Some(volume_ratio) = history.recent_5_session_volume_vs_prior_55_percent
    {
        observations.push(format!(
            "近5日均量为之前55日均量的 {volume_ratio:.1}%（原始量能事实；方向共振项只计超过100%的部分）"
        ));
    }
    if let Some(change) = rating.change_percent {
        observations.push(format!("单日涨跌 {change:.2}%（展示但不计入拥挤分）"));
    }
    if let Some(summary) = usable_short_interest {
        observations.push(format!(
            "空头股数较上期 {:+.1}%，回补天数 {:.1}（{}；背景证据，不计入拥挤分）",
            summary.change_percent, summary.days_to_cover, summary.as_of
        ));
    }
    if let Some(summary) = usable_options_positioning {
        observations.push(format!(
            "{} 到期月看跌/看涨未平仓量比 {}，成交量比 {}（{}；仓位背景，不计入拥挤分）",
            summary.expiration_date,
            summary
                .put_call_open_interest_ratio
                .map(|value| format!("{value:.2}"))
                .unwrap_or_else(|| "—".to_string()),
            summary
                .put_call_volume_ratio
                .map(|value| format!("{value:.2}"))
                .unwrap_or_else(|| "—".to_string()),
            summary.as_of,
        ));
    }
    if let Some(summary) = usable_news_attention {
        observations.push(format!(
            "近{}日媒体聚合发布 {} 篇，之前{}日 {} 篇，发布速率比 {}（{}；注意力背景，不计入拥挤分）",
            summary.recent_window_days,
            summary.recent_article_count,
            summary.window_days - summary.recent_window_days,
            summary.prior_article_count,
            summary
                .activity_ratio
                .map(|value| format!("{value:.2}"))
                .unwrap_or_else(|| "—".to_string()),
            summary.as_of,
        ));
    }
    if let Some(summary) = usable_institutional_holdings {
        observations.push(format!(
            "机构持股 {:.1}%（{} 位13F持有人）；增持/减持分类股数 {:.0}/{:.0}，前{}大记录跨{}个报告期（观察日 {}；背景证据，不计入拥挤分）",
            summary.institutional_ownership_percent,
            summary.institutional_holders,
            summary.increased_positions_shares,
            summary.decreased_positions_shares,
            summary.top_sample_rows,
            summary.report_period_count,
            summary.observed_on,
        ));
    }
    if let Some(summary) = usable_analyst_consensus {
        observations.push(format!(
            "分析师建议买入/持有/卖出 {}/{}/{}，最大类别“{}”占 {:.1}%；目标价低/共识/高 {:.2}/{:.2}/{:.2}（观察日 {}；背景证据，不计入拥挤分）",
            summary.buy_count,
            summary.hold_count,
            summary.sell_count,
            summary.dominant_rating,
            summary.dominant_share_percent,
            summary.low_target_price,
            summary.consensus_target_price,
            summary.high_target_price,
            summary.observed_on,
        ));
    }
    let mut missing_checks = Vec::new();
    if !components
        .iter()
        .any(|item| item.component_id == "price_position_52w")
    {
        missing_checks.push("52周价格位置".to_string());
    }
    if !components
        .iter()
        .any(|item| item.component_id == "price_vs_50d")
        || !components
            .iter()
            .any(|item| item.component_id == "average_50d_vs_200d")
    {
        missing_checks.push("50/200日趋势与价格延伸".to_string());
    }
    if !components
        .iter()
        .any(|item| item.component_id == "valuation_scenario_position")
    {
        missing_checks.push("七日内多方法估值位置".to_string());
    }
    let history_component_ids = [
        "return_20_sessions",
        "return_60_sessions",
        "drawdown_from_60_session_high",
        "volume_direction_confirmation",
    ];
    if !history_component_ids.iter().all(|id| {
        components
            .iter()
            .any(|component| component.component_id == *id)
    }) {
        missing_checks.push("20/60交易日收益、60日回撤与近期成交量路径".to_string());
    }
    missing_checks.extend([
        "相对自身历史与同业的估值分位".to_string(),
        "252交易日收益、回撤与波动路径".to_string(),
    ]);
    if usable_short_interest.is_none() {
        missing_checks.push("空头仓位变化与回补压力".to_string());
    }
    if usable_institutional_holdings.is_some() {
        missing_checks
            .push("机构持仓报告期一致性、持仓类型与对冲/衍生品暴露（13F聚合仅作背景）".to_string());
    } else {
        missing_checks.push("机构持仓集中度".to_string());
    }
    if usable_analyst_consensus.is_some() {
        missing_checks.push(
            "目标价贡献者数量、逐笔更新时间与分析师样本独立性（聚合共识仅作背景）".to_string(),
        );
    } else {
        missing_checks.push("分析师建议与目标价样本集中度".to_string());
    }
    if usable_news_attention.is_some() {
        missing_checks.push("社交讨论、情绪与独立新闻事件去重（媒体发布量仅作背景）".to_string());
    } else {
        missing_checks.push("社交讨论与新闻注意力集中度".to_string());
    }
    if usable_options_positioning.is_some() {
        missing_checks
            .push("期权隐含波动、偏斜、杠杆与资金流（指定月未平仓量仅作背景）".to_string());
    } else {
        missing_checks.push("期权隐含波动、偏斜、未平仓量、杠杆与资金流".to_string());
    }
    CrowdingState {
        policy_version: CROWDING_POLICY_VERSION.to_string(),
        status: if score.is_some() {
            MeasurementStatus::PartiallyMeasured
        } else {
            MeasurementStatus::Unmeasured
        },
        score,
        label: score
            .map(crowding_label)
            .unwrap_or("暂无可核验位置")
            .to_string(),
        components,
        short_interest: usable_short_interest.cloned(),
        options_positioning: usable_options_positioning.cloned(),
        news_attention: usable_news_attention.cloned(),
        institutional_holdings: usable_institutional_holdings.cloned(),
        analyst_consensus: usable_analyst_consensus.cloned(),
        observations,
        missing_checks,
        scope:
            "只测量点时价格、估值、收益、回撤和成交量共振的拥挤压力；空头、指定月期权仓位、媒体发布活跃度、机构13F聚合及分析师建议/目标价聚合仅作背景且不计分；不把上涨等同贪婪、不把下跌等同恐惧，也不直接改变动作。"
                .to_string(),
    }
}

fn crowding_anchor(value: f64) -> f64 {
    let points = [
        (-20.0, 10.0),
        (-10.0, 25.0),
        (0.0, 50.0),
        (10.0, 75.0),
        (20.0, 90.0),
        (40.0, 100.0),
    ];
    if value <= points[0].0 {
        return points[0].1;
    }
    for pair in points.windows(2) {
        let (x0, y0) = pair[0];
        let (x1, y1) = pair[1];
        if value <= x1 {
            return y0 + (value - x0) / (x1 - x0) * (y1 - y0);
        }
    }
    points.last().map(|(_, score)| *score).unwrap_or(50.0)
}

fn interpolate_pressure(value: f64, points: &[(f64, f64)]) -> f64 {
    if value <= points[0].0 {
        return points[0].1;
    }
    for pair in points.windows(2) {
        let (x0, y0) = pair[0];
        let (x1, y1) = pair[1];
        if value <= x1 {
            return y0 + (value - x0) / (x1 - x0) * (y1 - y0);
        }
    }
    points.last().map(|(_, score)| *score).unwrap_or(50.0)
}

fn short_return_pressure(value: f64) -> f64 {
    interpolate_pressure(
        value,
        &[
            (-30.0, 5.0),
            (-15.0, 20.0),
            (0.0, 50.0),
            (15.0, 80.0),
            (30.0, 95.0),
        ],
    )
}

fn medium_return_pressure(value: f64) -> f64 {
    interpolate_pressure(
        value,
        &[
            (-45.0, 5.0),
            (-25.0, 20.0),
            (0.0, 50.0),
            (30.0, 80.0),
            (60.0, 95.0),
        ],
    )
}

fn drawdown_pressure(value: f64) -> f64 {
    interpolate_pressure(
        value,
        &[
            (-50.0, 5.0),
            (-30.0, 20.0),
            (-15.0, 45.0),
            (-5.0, 75.0),
            (0.0, 95.0),
        ],
    )
}

fn signed_volume_excess(return_20: f64, volume_ratio_percent: f64) -> f64 {
    let excess = (volume_ratio_percent - 100.0).clamp(0.0, 100.0);
    if return_20 > 0.0 {
        excess
    } else if return_20 < 0.0 {
        -excess
    } else {
        0.0
    }
}

fn volume_direction_pressure(signed_excess_percent: f64) -> f64 {
    (50.0 + signed_excess_percent.clamp(-100.0, 100.0) * 0.4).clamp(10.0, 90.0)
}

fn crowding_label(score: f64) -> &'static str {
    if score >= 80.0 {
        "价格/估值位置拥挤风险偏高"
    } else if score >= 60.0 {
        "价格/估值位置偏高"
    } else if score >= 40.0 {
        "价格/估值位置中性"
    } else if score >= 20.0 {
        "价格/估值位置偏低"
    } else {
        "价格/估值位置显著偏低"
    }
}

fn decision_completeness_state(
    decision_date: NaiveDate,
    first_principles: Option<&FirstPrinciplesModel>,
    company_quality: &CompanyQualityState,
    financial: &FinancialVerificationState,
    valuation: Option<&DailyValuation>,
    crowding: &CrowdingState,
    market_regime: &MarketRegimeState,
    decision: &DecisionPolicyState,
) -> DecisionCompletenessState {
    let mut checks = Vec::new();

    let (first_principles_status, first_principles_evidence, first_principles_gaps) =
        if let Some(model) = first_principles {
            let observed_family = |drivers: &[ModelDriver]| {
                drivers.iter().any(|driver| {
                    driver.measurement_status != MeasurementStatus::Unmeasured
                        && !driver.observations.is_empty()
                })
            };
            let observed_families = [
                observed_family(&model.demand_drivers),
                observed_family(&model.supply_drivers),
                observed_family(&model.value_capture_drivers),
            ];
            let observed_count = observed_families.iter().filter(|value| **value).count();
            let structure_complete = !model.demand_equation.trim().is_empty()
                && !model.effective_supply_equation.trim().is_empty()
                && !model.scarcity_equation.trim().is_empty()
                && !model.value_capture_equation.trim().is_empty()
                && !model.invalidation_conditions.is_empty();
            let status = if structure_complete && observed_count == 3 {
                DecisionCompletenessCheckStatus::Pass
            } else if structure_complete {
                DecisionCompletenessCheckStatus::Partial
            } else {
                DecisionCompletenessCheckStatus::Missing
            };
            let mut gaps = Vec::new();
            if !observed_families[0] {
                gaps.push("需求驱动缺少点时现实证据".to_string());
            }
            if !observed_families[1] {
                gaps.push("供给驱动缺少点时现实证据".to_string());
            }
            if !observed_families[2] {
                gaps.push("价值捕获缺少点时现实证据".to_string());
            }
            (
                status,
                vec![format!(
                    "模型 {}@{}；需求/供给/价值捕获已观察 {observed_count}/3",
                    model.model_id, model.version
                )],
                gaps,
            )
        } else {
            (
                DecisionCompletenessCheckStatus::Missing,
                Vec::new(),
                vec!["没有适用的第一性原理产业模型".to_string()],
            )
        };
    checks.push(DecisionCompletenessCheck {
        check_id: "first_principles_reality_validation".to_string(),
        label: "第一性原理与现实验证".to_string(),
        status: first_principles_status,
        required_for_directional_research: true,
        required_for_portfolio_decision: true,
        evidence: first_principles_evidence,
        gaps: first_principles_gaps,
    });

    let quality_scores = [
        company_quality.moat_score,
        company_quality.scarcity_score,
        company_quality.fundamentals_score,
        company_quality.visibility_score,
    ];
    let quality_complete = company_quality.research_as_of.is_some()
        && !company_quality.business_model.trim().is_empty()
        && !company_quality.value_chain.trim().is_empty()
        && !company_quality.moat_hypothesis.trim().is_empty()
        && !company_quality.thesis.trim().is_empty()
        && quality_scores
            .iter()
            .all(|score| score.is_finite() && (0.0..=100.0).contains(score));
    checks.push(DecisionCompletenessCheck {
        check_id: "company_value_capture".to_string(),
        label: "商业模式、护城河与公司价值捕获".to_string(),
        status: if quality_complete {
            DecisionCompletenessCheckStatus::Pass
        } else if company_quality.research_as_of.is_some() {
            DecisionCompletenessCheckStatus::Partial
        } else {
            DecisionCompletenessCheckStatus::Missing
        },
        required_for_directional_research: true,
        required_for_portfolio_decision: true,
        evidence: company_quality
            .research_as_of
            .map(|as_of| vec![format!("公司研究基线日期 {as_of}")])
            .unwrap_or_default(),
        gaps: (!quality_complete)
            .then(|| vec!["商业模式、价值链、护城河、核心论点或评分口径不完整".to_string()])
            .unwrap_or_default(),
    });

    let revenue_present = financial.revenue_growth_percent.is_some();
    let margin_present = financial.gross_margin_percent.is_some()
        && (financial.gross_margin_change_pp.is_some() || financial.ebit_margin_percent.is_some());
    let cash_present = financial.fcf_margin_percent.is_some()
        || financial.operating_cash_flow_growth_percent.is_some()
        || financial.free_cash_flow_growth_percent.is_some();
    let working_capital_present = financial.accounts_receivable_growth_percent.is_some()
        && financial.accounts_payable_growth_percent.is_some()
        && financial.inventory_growth_percent.is_some();
    let financial_categories = [
        revenue_present,
        margin_present,
        cash_present,
        working_capital_present,
    ];
    let financial_count = financial_categories.iter().filter(|value| **value).count();
    let financial_status = if financial.financial_as_of.is_some()
        && financial_count == 4
        && financial.quality_warnings.is_empty()
    {
        DecisionCompletenessCheckStatus::Pass
    } else if financial.financial_as_of.is_some() && financial_count > 0 {
        DecisionCompletenessCheckStatus::Partial
    } else {
        DecisionCompletenessCheckStatus::Missing
    };
    let mut financial_gaps = Vec::new();
    if !revenue_present {
        financial_gaps.push("缺少收入增长".to_string());
    }
    if !margin_present {
        financial_gaps.push("缺少毛利率及其变化或营业利润率".to_string());
    }
    if !cash_present {
        financial_gaps.push("缺少经营现金流或自由现金流验证".to_string());
    }
    if !working_capital_present {
        financial_gaps.push("应收、应付与库存三项尚未全部完成验证".to_string());
    }
    financial_gaps.extend(financial.quality_warnings.iter().cloned());
    let mut financial_evidence = financial
        .financial_as_of
        .as_ref()
        .map(|as_of| {
            vec![format!(
                "财务日期 {as_of}；核心类别覆盖 {financial_count}/4"
            )]
        })
        .unwrap_or_default();
    let mut financial_values = Vec::new();
    if let Some(value) = financial.revenue_growth_percent {
        financial_values.push(format!("收入同比 {value:.1}%"));
    }
    if let Some(value) = financial.gross_margin_percent {
        financial_values.push(format!("毛利率 {value:.1}%"));
    }
    if let Some(value) = financial.gross_margin_change_pp {
        financial_values.push(format!("毛利率同比 {value:+.1} 个百分点"));
    }
    if let Some(value) = financial.operating_cash_flow_growth_percent {
        financial_values.push(format!("经营现金流同比 {value:.1}%"));
    }
    if !financial_values.is_empty() {
        financial_evidence.push(financial_values.join("；"));
    }
    if !financial.source_urls.is_empty() {
        financial_evidence.push(format!(
            "SEC 一手来源 {} 个、原始事实 {} 条",
            financial.source_urls.len(),
            financial.source_claim_ids.len()
        ));
    }
    financial_evidence.extend(financial.source_calculations.iter().take(4).cloned());
    checks.push(DecisionCompletenessCheck {
        check_id: "financial_transmission".to_string(),
        label: "财务传导与质量".to_string(),
        status: financial_status,
        required_for_directional_research: true,
        required_for_portfolio_decision: true,
        evidence: financial_evidence,
        gaps: financial_gaps,
    });

    let valuation_valid = valuation.is_some_and(|value| {
        parse_as_of_date(&value.as_of).is_some_and(|as_of| {
            as_of <= decision_date && decision_date.signed_duration_since(as_of).num_days() <= 7
        }) && value.current_price.is_finite()
            && value.current_price > 0.0
            && value.bear_case.is_finite()
            && value.base_case.is_finite()
            && value.bull_case.is_finite()
            && value.bear_case <= value.base_case
            && value.base_case <= value.bull_case
            && value.method_count >= 2
            && !value.method.trim().is_empty()
            && !value.assumptions.is_empty()
            && !value.sources.is_empty()
    });
    checks.push(DecisionCompletenessCheck {
        check_id: "multi_method_valuation".to_string(),
        label: "多方法三情景估值".to_string(),
        status: if valuation_valid {
            DecisionCompletenessCheckStatus::Pass
        } else if valuation.is_some() {
            DecisionCompletenessCheckStatus::Partial
        } else {
            DecisionCompletenessCheckStatus::Missing
        },
        required_for_directional_research: true,
        required_for_portfolio_decision: true,
        evidence: valuation
            .map(|value| {
                vec![format!(
                    "估值日期 {}；方法 {} 种；悲观/基准/乐观 {:.2}/{:.2}/{:.2}",
                    value.as_of,
                    value.method_count,
                    value.bear_case,
                    value.base_case,
                    value.bull_case
                )]
            })
            .unwrap_or_default(),
        gaps: (!valuation_valid)
            .then(|| {
                vec!["需要七日内、至少两种方法、完整假设与来源的悲观/基准/乐观估值".to_string()]
            })
            .unwrap_or_default(),
    });

    let falsifiability_complete =
        !decision.falsifiers.is_empty() && !decision.next_checks.is_empty();
    checks.push(DecisionCompletenessCheck {
        check_id: "falsifiability".to_string(),
        label: "反方、证伪与下一步验证".to_string(),
        status: if falsifiability_complete {
            DecisionCompletenessCheckStatus::Pass
        } else {
            DecisionCompletenessCheckStatus::Missing
        },
        required_for_directional_research: true,
        required_for_portfolio_decision: true,
        evidence: falsifiability_complete
            .then(|| {
                vec![format!(
                    "证伪条件 {} 条；下一步验证 {} 条",
                    decision.falsifiers.len(),
                    decision.next_checks.len()
                )]
            })
            .unwrap_or_default(),
        gaps: (!falsifiability_complete)
            .then(|| vec!["缺少可执行的证伪条件或后续验证项".to_string()])
            .unwrap_or_default(),
    });

    let crowding_valid = crowding.status == MeasurementStatus::Measured
        && crowding
            .score
            .is_some_and(|score| score.is_finite() && (0.0..=100.0).contains(&score));
    checks.push(DecisionCompletenessCheck {
        check_id: "timing_and_crowding".to_string(),
        label: "价格位置、趋势与拥挤度".to_string(),
        status: if crowding_valid {
            DecisionCompletenessCheckStatus::Pass
        } else if crowding.score.is_some() || !crowding.observations.is_empty() {
            DecisionCompletenessCheckStatus::Partial
        } else {
            DecisionCompletenessCheckStatus::Missing
        },
        required_for_directional_research: false,
        required_for_portfolio_decision: true,
        evidence: crowding.observations.clone(),
        gaps: crowding.missing_checks.clone(),
    });

    let macro_valid = market_regime.status == MarketRegimeStatus::Observed;
    checks.push(DecisionCompletenessCheck {
        check_id: "market_regime".to_string(),
        label: "宏观与市场状态".to_string(),
        status: if macro_valid {
            DecisionCompletenessCheckStatus::Pass
        } else {
            DecisionCompletenessCheckStatus::Missing
        },
        required_for_directional_research: false,
        required_for_portfolio_decision: true,
        evidence: macro_valid
            .then(|| vec![format!("宏观状态 {}", market_regime.label)])
            .unwrap_or_default(),
        gaps: (!macro_valid)
            .then(|| vec![market_regime.missing_reason.clone()])
            .unwrap_or_default(),
    });

    checks.push(DecisionCompletenessCheck {
        check_id: "portfolio_context".to_string(),
        label: "用户组合、相关性与风险预算".to_string(),
        status: DecisionCompletenessCheckStatus::Missing,
        required_for_directional_research: false,
        required_for_portfolio_decision: true,
        evidence: Vec::new(),
        gaps: vec![
            "公司点时快照不包含用户持仓、相关性、现金和风险预算；必须在组合层另行合并".to_string(),
        ],
    });

    let passed_checks = checks
        .iter()
        .filter(|check| check.status == DecisionCompletenessCheckStatus::Pass)
        .count();
    let total_checks = checks.len();
    let directional_research_ready = checks.iter().all(|check| {
        !check.required_for_directional_research
            || check.status == DecisionCompletenessCheckStatus::Pass
    });
    let portfolio_decision_ready = checks.iter().all(|check| {
        !check.required_for_portfolio_decision
            || check.status == DecisionCompletenessCheckStatus::Pass
    });
    DecisionCompletenessState {
        policy_version: DECISION_COMPLETENESS_POLICY_VERSION.to_string(),
        status: if portfolio_decision_ready {
            "portfolio_ready"
        } else if directional_research_ready {
            "directional_research_ready"
        } else {
            "research_incomplete"
        }
        .to_string(),
        passed_checks,
        total_checks,
        completeness_percent: if total_checks == 0 {
            0.0
        } else {
            passed_checks as f64 / total_checks as f64 * 100.0
        },
        directional_research_ready,
        portfolio_decision_ready,
        checks,
        scope: "只判断决策链证据是否齐全，不评价证据方向或自动产生买卖、仓位、奖励和交易授权。"
            .to_string(),
    }
}

fn decision_policy(
    rating: &CompanyRating,
    valuation: Option<&DailyValuation>,
    company_quality: &CompanyQualityState,
    financial: &FinancialVerificationState,
    crowding: &CrowdingState,
    first_principles: Option<&FirstPrinciplesModel>,
    market_regime: &MarketRegimeState,
) -> DecisionPolicyState {
    let valuation_supports_opportunity = valuation.is_some_and(|valuation| {
        valuation.current_price <= valuation.base_case && valuation.expected_upside_percent > 0.0
    });
    let valuation_signals_risk = valuation.is_some_and(|valuation| {
        valuation.current_price > valuation.bull_case || valuation.expected_upside_percent <= -20.0
    });
    let current_evidence_ready = matches!(rating.data_status.as_str(), "live" | "partial")
        && rating.factor_coverage >= 6
        && financial.status != MeasurementStatus::Unmeasured;
    let (base_zone, base_action) = if !current_evidence_ready {
        (ResearchZone::InsufficientData, ExposureAction::ResearchOnly)
    } else if rating.light == "red" || valuation_signals_risk {
        (ResearchZone::Risk, ExposureAction::ReduceCandidate)
    } else if rating.light == "green" && valuation_supports_opportunity {
        (ResearchZone::Opportunity, ExposureAction::IncreaseCandidate)
    } else {
        (ResearchZone::Hold, ExposureAction::Maintain)
    };

    let mut methodology = hari_methodology_state(
        &base_zone,
        &base_action,
        company_quality,
        first_principles,
        market_regime,
    );
    let (zone, action) = if base_action == ExposureAction::IncreaseCandidate
        && !methodology.increase_candidate_authorized
    {
        (ResearchZone::InsufficientData, ExposureAction::ResearchOnly)
    } else {
        (base_zone.clone(), base_action.clone())
    };

    let mut rationale = vec![format!(
        "公司研究综合分 {:.1}，当前灯号 {}，有效因子覆盖 {}/10。",
        rating.score, rating.light, rating.factor_coverage
    )];
    if let Some(valuation) = valuation {
        rationale.push(format!(
            "当前价格位于{}，概率加权价值相对现价空间 {:.1}%。",
            valuation.current_position, valuation.expected_upside_percent
        ));
    } else {
        rationale.push(format!(
            "估值尚未进入决策：{}",
            rating.valuation_unavailable_reason
        ));
    }
    if crowding.status == MeasurementStatus::Unmeasured {
        rationale.push("拥挤度尚未形成可核验输入，因此本版本不会把情绪猜测计入动作。".to_string());
    } else {
        let mut context = Vec::new();
        if crowding.short_interest.is_some() {
            context.push("空头仓位");
        }
        if crowding.options_positioning.is_some() {
            context.push("指定月期权仓位");
        }
        if crowding.news_attention.is_some() {
            context.push("媒体发布活跃度");
        }
        if crowding.institutional_holdings.is_some() {
            context.push("机构13F聚合");
        }
        rationale.push(if context.is_empty() {
            format!(
                "拥挤度仅完成价格/估值路径的部分测量：{}；机构、空头、期权、资金与注意力证据仍不完整，不计入动作。",
                crowding.label
            )
        } else {
            format!(
                "拥挤度仅完成价格/估值路径的部分测量：{}；{}已有点时背景但不计分，机构报告期一致性、分析师、隐含波动/偏斜、资金、社交情绪与事件去重仍不完整，不计入动作。",
                crowding.label,
                context.join("、")
            )
        });
    }
    let causal_confidence = causal_confidence_state(&rating.confidence, first_principles);
    if causal_confidence.adjustment != "unchanged" {
        rationale.extend(causal_confidence.reasons.iter().cloned());
        rationale
            .push("因果证据晋级只调整置信度；研究区间与动作仍由原确定性策略计算。".to_string());
    }
    if base_action == ExposureAction::IncreaseCandidate && action == ExposureAction::ResearchOnly {
        rationale.push(format!(
            "基础评分曾形成机会候选，但 Hari 已确认逻辑门禁未通过：{}；当前只保留研究，不生成增加暴露候选。",
            methodology.blocking_reasons.join("；")
        ));
    }
    methodology.portfolio_action_authorized = false;

    DecisionPolicyState {
        zone,
        action,
        confidence: causal_confidence.effective_confidence.clone(),
        causal_confidence,
        rationale,
        falsifiers: rating.falsifiers.clone(),
        next_checks: unique_strings(
            rating
                .watch_items
                .iter()
                .cloned()
                .chain(rating.risks.iter().map(|risk| format!("风险复核：{risk}")))
                .collect(),
        ),
        methodology,
    }
}

fn hari_methodology_state(
    base_zone: &ResearchZone,
    base_action: &ExposureAction,
    company_quality: &CompanyQualityState,
    first_principles: Option<&FirstPrinciplesModel>,
    market_regime: &MarketRegimeState,
) -> DecisionMethodologyState {
    let drivers = first_principles
        .into_iter()
        .flat_map(|model| {
            model
                .demand_drivers
                .iter()
                .chain(model.supply_drivers.iter())
                .chain(model.value_capture_drivers.iter())
        })
        .collect::<Vec<_>>();
    let observation_count = drivers
        .iter()
        .flat_map(|driver| driver.observations.iter())
        .filter(|observation| {
            observation.relationship != CausalObservationRelationship::ConfirmedContext
        })
        .count();
    let demand_measured = first_principles.is_some_and(|model| {
        model
            .demand_drivers
            .iter()
            .any(|driver| driver.measurement_status != MeasurementStatus::Unmeasured)
    });
    let supply_measured = first_principles.is_some_and(|model| {
        model
            .supply_drivers
            .iter()
            .any(|driver| driver.measurement_status != MeasurementStatus::Unmeasured)
    });
    let value_capture_measured = first_principles.is_some_and(|model| {
        model
            .value_capture_drivers
            .iter()
            .any(|driver| driver.measurement_status != MeasurementStatus::Unmeasured)
    });
    let quality_baseline_present = company_quality.status != MeasurementStatus::Unmeasured
        && !company_quality.moat_hypothesis.trim().is_empty()
        && !company_quality.thesis.trim().is_empty();

    let gate = evaluate_hari_company_gate(HariCompanyGateInputs {
        increase_candidate_requested: *base_action == ExposureAction::IncreaseCandidate,
        first_principles_observed: first_principles.is_some() && observation_count > 0,
        quality_baseline_present,
        demand_measured,
        supply_measured,
        value_capture_measured,
    });
    let first_principles_passed = gate.first_principles_passed;
    let scarcity_differentiation_passed = gate.scarcity_differentiation_passed;
    let future_space_passed = gate.future_space_passed;
    let blocking_reasons = hari_company_gate_blocking_reasons(&gate);
    let increase_candidate_authorized = gate.increase_candidate_authorized;
    let rule = |logic_id: &str,
                label: &str,
                passed: bool,
                decision_effect: &str,
                evidence: Vec<String>,
                gaps: Vec<String>| MethodologyRuleApplication {
        logic_id: logic_id.to_string(),
        logic_version: "0.1".to_string(),
        label: label.to_string(),
        status: if passed { "passed" } else { "blocked" }.to_string(),
        decision_effect: decision_effect.to_string(),
        evidence,
        gaps,
    };
    let mut rules = vec![
        rule(
            "LOG-V0001",
            "第一性原理与现实验证",
            first_principles_passed,
            "increase_gate",
            first_principles
                .map(|model| {
                    vec![
                        format!("公式模型 {}@{}", model.model_id, model.version),
                        format!("当前非背景观察 {} 条", observation_count),
                    ]
                })
                .unwrap_or_default(),
            (!first_principles_passed)
                .then(|| vec!["缺公式或缺少可观察现实证据".to_string()])
                .unwrap_or_default(),
        ),
        rule(
            "LOG-V0002",
            "稀缺与差异化公司选择",
            scarcity_differentiation_passed,
            "increase_gate",
            [
                quality_baseline_present.then(|| "历史研究基线包含护城河与长期主线".to_string()),
                supply_measured.then(|| "有效供给侧已有当前测量".to_string()),
                value_capture_measured.then(|| "公司价值捕获已有当前测量".to_string()),
            ]
            .into_iter()
            .flatten()
            .collect(),
            [
                (!quality_baseline_present).then(|| "缺少可追溯公司质量基线".to_string()),
                (!supply_measured).then(|| "供给约束尚未测量".to_string()),
                (!value_capture_measured)
                    .then(|| "产业需求向公司份额、利润与现金流的传导尚未测量".to_string()),
            ]
            .into_iter()
            .flatten()
            .collect(),
        ),
        rule(
            "LOG-V0006",
            "未来空间决定低买或离场",
            future_space_passed,
            "increase_gate",
            [
                demand_measured.then(|| "需求侧至少一个驱动已有当前测量".to_string()),
                supply_measured.then(|| "供给侧至少一个驱动已有当前测量".to_string()),
            ]
            .into_iter()
            .flatten()
            .collect(),
            [
                (!demand_measured).then(|| "未来需求驱动尚未测量".to_string()),
                (!supply_measured).then(|| "未来供给释放尚未测量".to_string()),
            ]
            .into_iter()
            .flatten()
            .collect(),
        ),
    ];
    rules.extend([
        MethodologyRuleApplication {
            logic_id: "LOG-V0003".to_string(),
            logic_version: "0.1".to_string(),
            label: "牛熊识别与组合总仓位控制".to_string(),
            status: "delegated_to_portfolio".to_string(),
            decision_effect: "portfolio_gate".to_string(),
            evidence: (market_regime.status == MarketRegimeStatus::Observed)
                .then(|| vec![format!("点时宏观环境 {}", market_regime.label)])
                .unwrap_or_default(),
            gaps: (market_regime.status != MarketRegimeStatus::Observed)
                .then(|| vec!["公司快照缺少可用宏观环境".to_string()])
                .unwrap_or_default(),
        },
        MethodologyRuleApplication {
            logic_id: "LOG-V0004".to_string(),
            logic_version: "0.1".to_string(),
            label: "随市场状态切换的杠铃组合".to_string(),
            status: "delegated_to_portfolio".to_string(),
            decision_effect: "portfolio_gate".to_string(),
            evidence: Vec::new(),
            gaps: vec!["公司点时快照不包含压舱石、高 Beta、现金和相关性结构".to_string()],
        },
        MethodologyRuleApplication {
            logic_id: "LOG-V0005".to_string(),
            logic_version: "0.1".to_string(),
            label: "板块优先的仓位分配".to_string(),
            status: "delegated_to_portfolio".to_string(),
            decision_effect: "portfolio_gate".to_string(),
            evidence: Vec::new(),
            gaps: vec!["公司点时快照不包含板块预算、组合相关性和风险预算".to_string()],
        },
    ]);
    DecisionMethodologyState {
        policy_version: HARI_POLICY_VERSION.to_string(),
        skill_id: HARI_SKILL_ID.to_string(),
        skill_version: HARI_SKILL_VERSION.to_string(),
        confirmed_logic_ids: HARI_CONFIRMED_LOGIC_IDS
            .iter()
            .map(|value| (*value).to_string())
            .collect(),
        candidate_logic_used: false,
        pre_methodology_zone: research_zone_id(base_zone).to_string(),
        pre_methodology_action: exposure_action_id(base_action).to_string(),
        increase_candidate_authorized,
        portfolio_action_authorized: false,
        rules,
        blocking_reasons,
        scope: "只把已确认的 Hari 逻辑作为确定性准入门禁；当前映射和缺口判断属于 HONE 工程实现，不冒充老王确认的数值阈值。组合动作必须在 actor 组合层另行审查，本层不授权交易。".to_string(),
    }
}

#[derive(Debug, Clone, Copy)]
struct HariCompanyGateInputs {
    increase_candidate_requested: bool,
    first_principles_observed: bool,
    quality_baseline_present: bool,
    demand_measured: bool,
    supply_measured: bool,
    value_capture_measured: bool,
}

#[derive(Debug, Clone, PartialEq)]
struct HariCompanyGateOutcome {
    first_principles_passed: bool,
    scarcity_differentiation_passed: bool,
    future_space_passed: bool,
    blocking_logic_ids: Vec<&'static str>,
    increase_candidate_authorized: bool,
}

fn evaluate_hari_company_gate(inputs: HariCompanyGateInputs) -> HariCompanyGateOutcome {
    let first_principles_passed = inputs.first_principles_observed;
    let scarcity_differentiation_passed =
        inputs.quality_baseline_present && inputs.supply_measured && inputs.value_capture_measured;
    let future_space_passed = inputs.demand_measured && inputs.supply_measured;
    let mut blocking_logic_ids = Vec::new();
    if inputs.increase_candidate_requested {
        if !first_principles_passed {
            blocking_logic_ids.push("LOG-V0001");
        }
        if !scarcity_differentiation_passed {
            blocking_logic_ids.push("LOG-V0002");
        }
        if !future_space_passed {
            blocking_logic_ids.push("LOG-V0006");
        }
    }
    HariCompanyGateOutcome {
        first_principles_passed,
        scarcity_differentiation_passed,
        future_space_passed,
        increase_candidate_authorized: inputs.increase_candidate_requested
            && blocking_logic_ids.is_empty(),
        blocking_logic_ids,
    }
}

fn hari_company_gate_blocking_reasons(gate: &HariCompanyGateOutcome) -> Vec<String> {
    gate.blocking_logic_ids
        .iter()
        .map(|logic_id| match *logic_id {
            "LOG-V0001" => "LOG-V0001：缺少第一性原理公式对应的当前现实验证",
            "LOG-V0002" => "LOG-V0002：稀缺性与公司价值捕获尚未同时获得当前证据",
            "LOG-V0006" => "LOG-V0006：未来需求与供给释放尚未形成双边可观察证据",
            _ => "未知 Hari 公司准入门禁",
        })
        .map(str::to_string)
        .collect()
}

fn hari_logic_scenario_benchmark() -> HariLogicScenarioBenchmark {
    struct Scenario {
        case_id: &'static str,
        label: &'static str,
        covered_logic_ids: &'static [&'static str],
        inputs: HariCompanyGateInputs,
        expected_authorized: bool,
        expected_blocking_logic_ids: &'static [&'static str],
    }

    let complete = HariCompanyGateInputs {
        increase_candidate_requested: true,
        first_principles_observed: true,
        quality_baseline_present: true,
        demand_measured: true,
        supply_measured: true,
        value_capture_measured: true,
    };
    let scenarios = [
        Scenario {
            case_id: "first_principles_without_reality",
            label: "第一性原理没有现实观察时阻断增加候选",
            covered_logic_ids: &["LOG-V0001"],
            inputs: HariCompanyGateInputs {
                first_principles_observed: false,
                ..complete
            },
            expected_authorized: false,
            expected_blocking_logic_ids: &["LOG-V0001"],
        },
        Scenario {
            case_id: "scarcity_without_value_capture",
            label: "只有稀缺、没有公司价值捕获时阻断增加候选",
            covered_logic_ids: &["LOG-V0002"],
            inputs: HariCompanyGateInputs {
                value_capture_measured: false,
                ..complete
            },
            expected_authorized: false,
            expected_blocking_logic_ids: &["LOG-V0002"],
        },
        Scenario {
            case_id: "future_demand_unmeasured",
            label: "未来需求没有测量时不能把回调升级为机会",
            covered_logic_ids: &["LOG-V0006"],
            inputs: HariCompanyGateInputs {
                demand_measured: false,
                ..complete
            },
            expected_authorized: false,
            expected_blocking_logic_ids: &["LOG-V0006"],
        },
        Scenario {
            case_id: "future_supply_unmeasured",
            label: "供给释放没有测量时同时阻断稀缺与未来空间",
            covered_logic_ids: &["LOG-V0002", "LOG-V0006"],
            inputs: HariCompanyGateInputs {
                supply_measured: false,
                ..complete
            },
            expected_authorized: false,
            expected_blocking_logic_ids: &["LOG-V0002", "LOG-V0006"],
        },
        Scenario {
            case_id: "complete_company_gate",
            label: "公司层三道门齐全时只形成增加候选",
            covered_logic_ids: &["LOG-V0001", "LOG-V0002", "LOG-V0006"],
            inputs: complete,
            expected_authorized: true,
            expected_blocking_logic_ids: &[],
        },
        Scenario {
            case_id: "portfolio_authority_stays_delegated",
            label: "非增加动作和组合三逻辑都不能在公司层产生仓位授权",
            covered_logic_ids: &["LOG-V0003", "LOG-V0004", "LOG-V0005"],
            inputs: HariCompanyGateInputs {
                increase_candidate_requested: false,
                ..complete
            },
            expected_authorized: false,
            expected_blocking_logic_ids: &[],
        },
    ];
    let actual_portfolio_delegated = HARI_PORTFOLIO_DELEGATED_LOGIC_IDS
        == ["LOG-V0003", "LOG-V0004", "LOG-V0005"]
        && HARI_PORTFOLIO_DELEGATED_LOGIC_IDS
            .iter()
            .all(|logic_id| HARI_CONFIRMED_LOGIC_IDS.contains(logic_id));
    let cases = scenarios
        .into_iter()
        .map(|scenario| {
            let outcome = evaluate_hari_company_gate(scenario.inputs);
            let actual_blocking_logic_ids = outcome
                .blocking_logic_ids
                .iter()
                .map(|value| (*value).to_string())
                .collect::<Vec<_>>();
            let expected_blocking_logic_ids = scenario
                .expected_blocking_logic_ids
                .iter()
                .map(|value| (*value).to_string())
                .collect::<Vec<_>>();
            let mut failure_reasons = Vec::new();
            if outcome.increase_candidate_authorized != scenario.expected_authorized {
                failure_reasons.push("公司层增加候选授权与预期不一致".to_string());
            }
            if actual_blocking_logic_ids != expected_blocking_logic_ids {
                failure_reasons.push("阻断逻辑集合或顺序与预期不一致".to_string());
            }
            if !actual_portfolio_delegated {
                failure_reasons.push("LOG-V0003/4/5 未保持在组合层".to_string());
            }
            HariLogicScenarioCase {
                case_id: scenario.case_id.to_string(),
                label: scenario.label.to_string(),
                covered_logic_ids: scenario
                    .covered_logic_ids
                    .iter()
                    .map(|value| (*value).to_string())
                    .collect(),
                expected_company_increase_authorized: scenario.expected_authorized,
                actual_company_increase_authorized: outcome.increase_candidate_authorized,
                expected_blocking_logic_ids,
                actual_blocking_logic_ids,
                expected_portfolio_delegated: true,
                actual_portfolio_delegated,
                passed: failure_reasons.is_empty(),
                failure_reasons,
            }
        })
        .collect::<Vec<_>>();
    let passed_scenario_count = cases.iter().filter(|case| case.passed).count();
    HariLogicScenarioBenchmark {
        policy_version: HARI_SCENARIO_BENCHMARK_POLICY_VERSION.to_string(),
        skill_id: HARI_SKILL_ID.to_string(),
        skill_version: HARI_SKILL_VERSION.to_string(),
        confirmed_logic_ids: HARI_CONFIRMED_LOGIC_IDS
            .iter()
            .map(|value| (*value).to_string())
            .collect(),
        scenario_count: cases.len(),
        passed_scenario_count,
        failed_scenario_count: cases.len() - passed_scenario_count,
        all_passed: passed_scenario_count == cases.len(),
        cases,
        synthetic_scenarios_only: true,
        training_label_created: false,
        decision_authorized: false,
        portfolio_action_authorized: false,
        shadow_portfolio_authorized: false,
        trading_authorized: false,
        scope: "固定合成情景只验证已确认逻辑在代码中的门禁一致性，不评价投资收益，不生成训练标签，也不授权公司、组合、影子或真实交易动作。".to_string(),
    }
}

