fn apply_opening_portfolio_source_artifact_receipt_execution_readiness(
    readiness: &mut EmpiricalValidationReadiness,
    summary: Option<super::controlled_shadow_opening_portfolio_source_artifact_receipt_execution_attempts::OpeningPortfolioSourceArtifactReceiptExecutionReadinessSummary>,
) {
    match summary {
        Some(summary) => {
            readiness.historical_outcome_opening_portfolio_source_artifact_receipt_execution_pending_claim_count = summary.pending_claim_count;
            readiness.historical_outcome_opening_portfolio_source_artifact_receipt_execution_terminal_result_count = summary.terminal_result_count;
            readiness.historical_outcome_opening_portfolio_source_artifact_receipt_execution_successful_untrusted_receipt_count = summary.successful_untrusted_receipt_count;
            readiness.historical_outcome_opening_portfolio_source_artifact_receipt_execution_failed_consumed_claim_count = summary.failed_consumed_claim_count;
            readiness.historical_outcome_opening_portfolio_source_artifact_receipt_execution_encryption_key_configured = summary.encryption_key_configured;
            readiness
                .historical_outcome_opening_portfolio_source_artifact_receipt_execution_status =
                if summary.successful_untrusted_receipt_count > 0 {
                    "untrusted_source_artifact_receipt_waiting_for_stage_133_independent_validation"
                } else if summary.failed_consumed_claim_count > 0 {
                    "one_shot_source_artifact_receipt_failed_claim_consumed"
                } else if summary.pending_claim_count > 0 && !summary.encryption_key_configured {
                    "pending_stage_131_claim_waiting_for_receipt_encryption_key"
                } else if summary.pending_claim_count > 0 {
                    "ready_for_stage_132_one_shot_encrypted_source_artifact_receipt"
                } else {
                    "waiting_for_unstarted_stage_131_claim"
                }
                .to_string();
            if summary.pending_claim_count > 0 && !summary.encryption_key_configured {
                readiness.blocking_reasons.push("Stage 132 有待接收 claim，但未配置独立的来源工件 AES-256 加密密钥；尚未读取来源字节".to_string());
            }
            if summary.successful_untrusted_receipt_count > 0 {
                readiness.blocking_reasons.push("Stage 132 已生成未受信来源工件 receipt；必须先通过 Stage 133 链外独立校验，不能直接成为期初持仓或账本".to_string());
            }
            if summary.failed_consumed_claim_count > 0 {
                readiness.blocking_reasons.push(
                    "Stage 132 存在已终止且不可重试的来源工件接收 claim；必须重新走上游授权链"
                        .to_string(),
                );
            }
        }
        None => {
            readiness
                .blocking_reasons
                .push("Stage 132 来源工件单次加密接收表不可用，准备度失败关闭".to_string());
        }
    }
    readiness.blocking_reasons = unique_strings(std::mem::take(&mut readiness.blocking_reasons));
    if !readiness.blocking_reasons.is_empty() {
        readiness.empirical_validation_ready = false;
        readiness.status = "blocked".to_string();
    }
}

fn apply_opening_portfolio_source_artifact_receipt_validation_readiness(
    readiness: &mut EmpiricalValidationReadiness,
    summary: Option<super::controlled_shadow_opening_portfolio_source_artifact_receipt_validations::OpeningPortfolioSourceArtifactReceiptValidationReadinessSummary>,
) {
    match summary {
        Some(summary) => {
            readiness.historical_outcome_opening_portfolio_source_artifact_receipt_validation_completed_untrusted_receipt_count = summary.completed_untrusted_receipt_count;
            readiness.historical_outcome_opening_portfolio_source_artifact_receipt_validation_pending_independent_validation_count = summary.pending_independent_validation_count;
            readiness.historical_outcome_opening_portfolio_source_artifact_receipt_validation_independently_validated_receipt_count = summary.independently_validated_receipt_count;
            readiness.historical_outcome_opening_portfolio_source_artifact_receipt_validation_failed_independent_validation_count = summary.failed_independent_validation_count;
            readiness.historical_outcome_opening_portfolio_source_artifact_receipt_validation_future_stage_134_eligible_count = summary.future_stage_134_eligible_count;
            readiness.historical_outcome_opening_portfolio_source_artifact_receipt_validation_encryption_key_configured = summary.encryption_key_configured;
            readiness
                .historical_outcome_opening_portfolio_source_artifact_receipt_validation_status =
                summary.validation_status;

            if summary.independently_validated_receipt_count > 0 {
                readiness.blocking_reasons.retain(|reason| {
                    reason != "Stage 132 已生成未受信来源工件 receipt；必须先通过 Stage 133 链外独立校验，不能直接成为期初持仓或账本"
                });
                readiness.blocking_reasons.push("Stage 133 已独立验证加密来源工件 receipt，但只开放 Stage 134 零能力期初快照物化实现登记；仍未解析财务行或形成真实持仓".to_string());
            } else if summary.failed_independent_validation_count > 0 {
                readiness.blocking_reasons.push(
                    "Stage 133 存在终态失败的来源工件独立验证；该 receipt 不得进入期初快照物化链"
                        .to_string(),
                );
            } else if summary.pending_independent_validation_count > 0
                && !summary.encryption_key_configured
            {
                readiness.blocking_reasons.push("Stage 133 有待验证的加密 receipt，但独立验证环境缺少同一 AES-256 密钥；尚未创建验证终态".to_string());
            } else if summary.pending_independent_validation_count > 0 {
                readiness.blocking_reasons.push("Stage 133 等待责任链外管理员独立重开 result、receipt、密文与认证解密后的明文证据".to_string());
            }
        }
        None => {
            readiness
                .blocking_reasons
                .push("Stage 133 来源工件 receipt 独立验证表不可用，准备度失败关闭".to_string());
        }
    }
    readiness.blocking_reasons = unique_strings(std::mem::take(&mut readiness.blocking_reasons));
    if !readiness.blocking_reasons.is_empty() {
        readiness.empirical_validation_ready = false;
        readiness.status = "blocked".to_string();
    }
}

