fn research_zone_id(zone: &ResearchZone) -> &'static str {
    match zone {
        ResearchZone::Opportunity => "opportunity",
        ResearchZone::Hold => "hold",
        ResearchZone::Risk => "risk",
        ResearchZone::InsufficientData => "insufficient_data",
    }
}

fn exposure_action_id(action: &ExposureAction) -> &'static str {
    match action {
        ExposureAction::IncreaseCandidate => "increase_candidate",
        ExposureAction::Maintain => "maintain",
        ExposureAction::ReduceCandidate => "reduce_candidate",
        ExposureAction::ResearchOnly => "research_only",
    }
}

fn parse_research_zone_id(value: &str) -> Option<ResearchZone> {
    match value {
        "opportunity" => Some(ResearchZone::Opportunity),
        "hold" => Some(ResearchZone::Hold),
        "risk" => Some(ResearchZone::Risk),
        "insufficient_data" => Some(ResearchZone::InsufficientData),
        _ => None,
    }
}

fn parse_exposure_action_id(value: &str) -> Option<ExposureAction> {
    match value {
        "increase_candidate" => Some(ExposureAction::IncreaseCandidate),
        "maintain" => Some(ExposureAction::Maintain),
        "reduce_candidate" => Some(ExposureAction::ReduceCandidate),
        "research_only" => Some(ExposureAction::ResearchOnly),
        _ => None,
    }
}

fn causal_confidence_state(
    base_confidence: &str,
    first_principles: Option<&FirstPrinciplesModel>,
) -> CausalConfidenceState {
    let base = normalize_confidence(base_confidence);
    let drivers = first_principles
        .into_iter()
        .flat_map(|model| {
            model
                .demand_drivers
                .iter()
                .chain(model.supply_drivers.iter())
                .chain(model.value_capture_drivers.iter())
        })
        .collect::<Vec<_>>();
    let promoted_driver_count = drivers
        .iter()
        .filter(|driver| driver.promotion.status == CausalPromotionStatus::PromotedConfidenceOnly)
        .count();
    let blocked_conflict_count = drivers
        .iter()
        .filter(|driver| driver.promotion.status == CausalPromotionStatus::BlockedConflict)
        .count();
    let blocked_human_rejection_count = drivers
        .iter()
        .filter(|driver| driver.promotion.status == CausalPromotionStatus::BlockedHumanRejection)
        .count();
    let blocked_falsification_count = drivers
        .iter()
        .filter(|driver| driver.promotion.status == CausalPromotionStatus::BlockedFalsification)
        .count();
    let mut reasons = Vec::new();
    let (effective, adjustment) = if blocked_conflict_count > 0
        || blocked_human_rejection_count > 0
        || blocked_falsification_count > 0
    {
        reasons.push(format!(
            "{} 个驱动存在未解决冲突，{} 个驱动被人工拒绝，{} 个驱动出现人工确认的证伪证据，因果置信度下调一级。",
            blocked_conflict_count, blocked_human_rejection_count, blocked_falsification_count
        ));
        (decrease_confidence(&base), "downgraded")
    } else if promoted_driver_count >= 2 {
        reasons.push(format!(
            "{} 个驱动已满足跨期独立证据和逐条人工复核门槛，因果置信度上调一级。",
            promoted_driver_count
        ));
        (increase_confidence(&base), "upgraded")
    } else {
        (base.clone(), "unchanged")
    };
    CausalConfidenceState {
        policy_version: CAUSAL_PROMOTION_POLICY_VERSION.to_string(),
        base_confidence: base,
        effective_confidence: effective,
        promoted_driver_count,
        blocked_conflict_count,
        blocked_human_rejection_count,
        blocked_falsification_count,
        adjustment: adjustment.to_string(),
        reasons,
    }
}

fn normalize_confidence(value: &str) -> String {
    match value.trim().to_ascii_lowercase().as_str() {
        "high" => "high".to_string(),
        "medium" => "medium".to_string(),
        _ => "low".to_string(),
    }
}

fn increase_confidence(value: &str) -> String {
    match value {
        "low" => "medium".to_string(),
        "medium" | "high" => "high".to_string(),
        _ => "low".to_string(),
    }
}

fn decrease_confidence(value: &str) -> String {
    match value {
        "high" => "medium".to_string(),
        "medium" | "low" => "low".to_string(),
        _ => "low".to_string(),
    }
}

fn build_evidence(rating: &CompanyRating, decision_date: NaiveDate) -> Vec<DecisionEvidence> {
    let mut evidence = Vec::new();
    if let Some(as_of) = parse_as_of_date(&rating.research_updated_at)
        && as_of <= decision_date
    {
        evidence.push(DecisionEvidence {
            evidence_id: format!("{}-research-{}", rating.symbol, as_of),
            kind: EvidenceKind::HistoricalResearch,
            status: EvidenceStatus::HistoricalBaseline,
            label: "历史公司研究基线".to_string(),
            value: rating.thesis_summary.clone(),
            as_of,
            source: "公司研究卡".to_string(),
        });
    }
    if let (Some(price), Some(as_of)) = (
        rating.price,
        rating.market_as_of.as_deref().and_then(parse_as_of_date),
    ) && as_of <= decision_date
    {
        evidence.push(DecisionEvidence {
            evidence_id: format!("{}-market-{}", rating.symbol, as_of),
            kind: EvidenceKind::Market,
            status: EvidenceStatus::CurrentVerified,
            label: "市场价格".to_string(),
            value: format!("{price:.2}"),
            as_of,
            source: rating
                .data_sources
                .iter()
                .find(|source| source.contains("Nasdaq") || source.contains("FMP"))
                .cloned()
                .unwrap_or_else(|| "当前行情源".to_string()),
        });
    }
    if let Some(as_of) = rating.financial_as_of.as_deref().and_then(parse_as_of_date)
        && as_of <= decision_date
    {
        evidence.push(DecisionEvidence {
            evidence_id: format!("{}-financial-{}", rating.symbol, as_of),
            kind: EvidenceKind::Financial,
            status: EvidenceStatus::CurrentVerified,
            label: "财务验证".to_string(),
            value: financial_value_summary(rating),
            as_of,
            source: "最近季度财务输入".to_string(),
        });
    }
    if let (Some(label), Some(as_of), Some(source)) = (
        rating.metrics.forward_metric_label.as_ref(),
        rating
            .metrics
            .forward_metric_as_of
            .as_deref()
            .and_then(parse_as_of_date),
        rating.metrics.forward_metric_source_url.as_ref(),
    ) && as_of <= decision_date
    {
        evidence.push(DecisionEvidence {
            evidence_id: format!("{}-forward-{}", rating.symbol, as_of),
            kind: EvidenceKind::ForwardOperating,
            status: EvidenceStatus::CurrentVerified,
            label: label.clone(),
            value: rating
                .metrics
                .forward_metric_value
                .clone()
                .unwrap_or_else(|| "已核验但无可展示值".to_string()),
            as_of,
            source: source.clone(),
        });
    }
    if let Some(valuation) = &rating.valuation
        && let Some(as_of) = parse_as_of_date(&valuation.as_of)
        && as_of <= decision_date
    {
        evidence.push(DecisionEvidence {
            evidence_id: format!("{}-valuation-{}", rating.symbol, as_of),
            kind: EvidenceKind::Valuation,
            status: EvidenceStatus::Computed,
            label: "多方法三情景估值".to_string(),
            value: format!(
                "悲观 {:.2} / 基准 {:.2} / 乐观 {:.2}",
                valuation.bear_case, valuation.base_case, valuation.bull_case
            ),
            as_of,
            source: valuation.sources.join("；"),
        });
    }
    evidence
}

fn financial_value_summary(rating: &CompanyRating) -> String {
    let mut values = Vec::new();
    if let Some(value) = rating.metrics.revenue_growth_percent {
        values.push(format!("收入同比 {value:.1}%"));
    }
    if let Some(value) = rating.metrics.gross_margin_percent {
        values.push(format!("毛利率 {value:.1}%"));
    }
    if let Some(value) = rating.metrics.fcf_margin_percent {
        values.push(format!("FCF率 {value:.1}%"));
    }
    if values.is_empty() {
        "财务日期已核验，核心字段仍缺失".to_string()
    } else {
        values.join("；")
    }
}

fn parse_as_of_date(raw: &str) -> Option<NaiveDate> {
    let prefix = raw.trim().get(..10)?;
    NaiveDate::parse_from_str(prefix, "%Y-%m-%d").ok()
}

fn causal_numeric_matches(value: f64, text: &str) -> bool {
    let normalized = text.replace([',', '，', ' '], "");
    let exact = value.to_string();
    let rounded_integer = (value.fract().abs() < f64::EPSILON).then(|| format!("{value:.0}"));
    let integer_word = rounded_integer
        .as_deref()
        .and_then(english_integer_word)
        .is_some_and(|word| {
            text.split(|character: char| !character.is_ascii_alphabetic())
                .any(|token| token.eq_ignore_ascii_case(word))
        });
    normalized.contains(&exact)
        || rounded_integer
            .as_deref()
            .is_some_and(|candidate| normalized.contains(candidate))
        || integer_word
}

fn english_integer_word(value: &str) -> Option<&'static str> {
    match value {
        "0" => Some("zero"),
        "1" => Some("one"),
        "2" => Some("two"),
        "3" => Some("three"),
        "4" => Some("four"),
        "5" => Some("five"),
        "6" => Some("six"),
        "7" => Some("seven"),
        "8" => Some("eight"),
        "9" => Some("nine"),
        "10" => Some("ten"),
        "11" => Some("eleven"),
        "12" => Some("twelve"),
        "13" => Some("thirteen"),
        "14" => Some("fourteen"),
        "15" => Some("fifteen"),
        "16" => Some("sixteen"),
        "17" => Some("seventeen"),
        "18" => Some("eighteen"),
        "19" => Some("nineteen"),
        "20" => Some("twenty"),
        _ => None,
    }
}

fn causal_operating_kpi_is_valid(
    provenance: &CausalOperatingKpiProvenance,
    observation: &CausalObservation,
    driver: &ModelDriver,
    registry: &OperatingKpiRegistry,
) -> bool {
    let definition = normalize_claim_key(&provenance.issuer_definition);
    let source_text = normalize_claim_key(&format!(
        "{} {}",
        provenance.value_text, provenance.evidence_quote
    ));
    let lifecycle_valid = match provenance.lifecycle_status {
        CausalClaimLifecycleStatus::Active => {
            provenance.disposition != EarningsClaimDisposition::Withdrawn
                && provenance.superseded_by.is_none()
                && provenance.conflicting_claim_ids.is_empty()
        }
        CausalClaimLifecycleStatus::Superseded => {
            provenance
                .superseded_by
                .as_deref()
                .is_some_and(|id| !id.is_empty() && id != observation.observation_id)
                && provenance.conflicting_claim_ids.is_empty()
        }
        CausalClaimLifecycleStatus::Conflicted => {
            provenance.superseded_by.is_none()
                && !provenance.conflicting_claim_ids.is_empty()
                && provenance
                    .conflicting_claim_ids
                    .iter()
                    .all(|id| !id.is_empty() && id != &observation.observation_id)
        }
        CausalClaimLifecycleStatus::Withdrawn => {
            provenance.disposition == EarningsClaimDisposition::Withdrawn
                && provenance.superseded_by.is_none()
                && provenance.conflicting_claim_ids.is_empty()
        }
    };
    provenance.schema_version == OPERATING_KPI_CLAIM_SCHEMA_VERSION
        && registry
            .entries
            .iter()
            .any(|entry| entry.kpi_id == provenance.kpi_id && entry.driver_id == driver.driver_id)
        && !provenance.issuer_metric_name.trim().is_empty()
        && !provenance.issuer_definition.trim().is_empty()
        && !provenance.definition_key.trim().is_empty()
        && source_text.contains(&definition)
        && !provenance.period.trim().is_empty()
        && !provenance.value_text.trim().is_empty()
        && !provenance.measurement_scope.trim().is_empty()
        && !provenance.source_event_id.trim().is_empty()
        && !provenance.source_locator.trim().is_empty()
        && !provenance.evidence_quote.trim().is_empty()
        && provenance.numeric_value.is_none_or(f64::is_finite)
        && provenance.numeric_value.is_none_or(|value| {
            causal_numeric_matches(value, &provenance.value_text)
                || causal_numeric_matches(value, &provenance.evidence_quote)
        })
        && provenance
            .numeric_value
            .is_none_or(|_| !provenance.unit.trim().is_empty())
        && provenance.source_artifact.as_ref().is_none_or(|artifact| {
            operating_kpi_source_artifact_is_valid(artifact)
                && matches!(
                    provenance.source_time_precision.as_deref(),
                    Some("exact" | "date_only_conservative_end_of_day")
                )
        })
        && (!matches!(
            provenance.claim_kind,
            OperatingKpiClaimKind::ManagementGuidance | OperatingKpiClaimKind::ContractMilestone
        ) || provenance
            .speaker
            .as_deref()
            .is_some_and(|value| !value.trim().is_empty()))
        && matches!(
            provenance.source_document.as_str(),
            "earnings_call_transcript"
                | "earnings_release"
                | "sec_filing"
                | "investor_presentation"
                | "official_customer_disclosure"
                | "regulator_disclosure"
        )
        && observation
            .source_url
            .as_deref()
            .is_some_and(|url| url.starts_with("https://"))
        && lifecycle_valid
}

fn validate_causal_promotion(
    driver: &ModelDriver,
    decision_at: DateTime<Utc>,
) -> Result<(), String> {
    let promotion = &driver.promotion;
    if promotion.policy_version.is_empty() {
        return Ok(());
    }
    if promotion.policy_version != CAUSAL_PROMOTION_POLICY_VERSION
        || promotion
            .reviewed_through
            .is_some_and(|reviewed_at| reviewed_at > decision_at)
    {
        return Err("causal promotion policy or review time is invalid".to_string());
    }
    let structured = driver
        .observations
        .iter()
        .filter(|observation| {
            observation.relationship == CausalObservationRelationship::StructuredSourceClaim
        })
        .collect::<Vec<_>>();
    let active = structured
        .iter()
        .copied()
        .filter(|observation| {
            observation.claim.as_ref().is_some_and(|claim| {
                claim_is_promotion_eligible(claim)
                    && claim.lifecycle_status == CausalClaimLifecycleStatus::Active
            })
        })
        .collect::<Vec<_>>();
    let active_ids = active
        .iter()
        .map(|observation| observation.observation_id.as_str())
        .collect::<BTreeSet<_>>();
    let accepted_ids = promotion
        .accepted_observation_ids
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    let rejected_ids = promotion
        .rejected_observation_ids
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    let falsifying_ids = promotion
        .falsifying_observation_ids
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    if accepted_ids.len() != promotion.accepted_observation_ids.len()
        || rejected_ids.len() != promotion.rejected_observation_ids.len()
        || falsifying_ids.len() != promotion.falsifying_observation_ids.len()
        || !accepted_ids.is_disjoint(&rejected_ids)
        || !accepted_ids.is_disjoint(&falsifying_ids)
        || !rejected_ids.is_disjoint(&falsifying_ids)
        || !accepted_ids.is_subset(&active_ids)
        || !rejected_ids.is_subset(&active_ids)
        || !falsifying_ids.is_subset(&active_ids)
        || promotion.active_claim_count != active.len()
        || promotion.accepted_claim_count != accepted_ids.len()
    {
        return Err("causal promotion review projection is invalid".to_string());
    }
    let source_events = active
        .iter()
        .filter_map(|observation| observation.claim.as_ref())
        .map(|claim| claim.source_event_id.as_str())
        .filter(|event_id| !event_id.trim().is_empty())
        .collect::<BTreeSet<_>>();
    let source_urls = active
        .iter()
        .filter_map(|observation| observation.source_url.as_deref())
        .collect::<BTreeSet<_>>();
    let periods = active
        .iter()
        .filter_map(|observation| observation.claim.as_ref())
        .map(|claim| normalize_claim_key(&claim.period))
        .collect::<BTreeSet<_>>();
    let dates = active
        .iter()
        .map(|observation| observation.as_of)
        .collect::<Vec<_>>();
    let span = dates
        .iter()
        .min()
        .zip(dates.iter().max())
        .map(|(first, last)| (*last - *first).num_days())
        .unwrap_or_default();
    if promotion.distinct_source_events != source_events.len().min(source_urls.len())
        || promotion.distinct_periods != periods.len()
        || promotion.evidence_span_days != span
    {
        return Err("causal promotion evidence counts are invalid".to_string());
    }
    let has_conflict = structured.iter().any(|observation| {
        observation.claim.as_ref().is_some_and(|claim| {
            claim_is_promotion_eligible(claim)
                && claim.lifecycle_status == CausalClaimLifecycleStatus::Conflicted
        })
    });
    let repeat_evidence_ready = active.len() >= MIN_PROMOTION_ACCEPTED_CLAIMS
        && source_events.len() >= MIN_PROMOTION_SOURCE_EVENTS
        && source_urls.len() >= MIN_PROMOTION_SOURCE_EVENTS
        && periods.len() >= MIN_PROMOTION_PERIODS
        && span >= MIN_PROMOTION_SPAN_DAYS;
    let expected = if structured.is_empty() {
        CausalPromotionStatus::TrainingOnly
    } else if has_conflict {
        CausalPromotionStatus::BlockedConflict
    } else if !falsifying_ids.is_empty() {
        CausalPromotionStatus::BlockedFalsification
    } else if !rejected_ids.is_empty() {
        CausalPromotionStatus::BlockedHumanRejection
    } else if !repeat_evidence_ready {
        CausalPromotionStatus::PendingRepeatEvidence
    } else if accepted_ids.len() < active.len()
        || accepted_ids.len() < MIN_PROMOTION_ACCEPTED_CLAIMS
    {
        CausalPromotionStatus::PendingHumanReview
    } else {
        CausalPromotionStatus::PromotedConfidenceOnly
    };
    if promotion.status != expected {
        return Err("causal promotion status is inconsistent with its evidence".to_string());
    }
    Ok(())
}

fn causal_ratio_provenance_is_valid(
    ratio: &CausalRatioProvenance,
    decision_at: DateTime<Utc>,
) -> bool {
    let expected_result = ratio.numerator_numeric_value / ratio.denominator_numeric_value * 100.0;
    let expected_pair = match ratio.ratio_kind {
        CausalRatioKind::GrossMargin => {
            ratio.metric_id == "gross_margin" && ratio.numerator_metric_id == "gross_profit"
        }
        CausalRatioKind::OperatingMargin => {
            ratio.metric_id == "operating_margin" && ratio.numerator_metric_id == "operating_income"
        }
    };
    ratio.formula_version == COMPUTED_RATIO_FORMULA_VERSION
        && expected_pair
        && ratio.denominator_metric_id == "revenue"
        && !ratio.numerator_metric_basis.trim().is_empty()
        && !ratio.denominator_metric_basis.trim().is_empty()
        && !ratio.numerator_claim_id.trim().is_empty()
        && !ratio.denominator_claim_id.trim().is_empty()
        && ratio.numerator_claim_id != ratio.denominator_claim_id
        && !ratio.period.trim().is_empty()
        && ratio.numerator_numeric_value.is_finite()
        && ratio.denominator_numeric_value.is_finite()
        && ratio.denominator_numeric_value.abs() > f64::EPSILON
        && ratio.result_percent.is_finite()
        && (ratio.result_percent - expected_result).abs() <= 0.000_001
        && ratio.published_at <= decision_at
        && ratio.source_url.starts_with("https://")
}

fn causal_ratio_trend_is_valid(
    trend: &CausalRatioTrendProvenance,
    decision_at: DateTime<Utc>,
) -> bool {
    let Some(current_period) = parse_fiscal_period_key(&trend.current.period) else {
        return false;
    };
    let Some(prior_period) = parse_fiscal_period_key(&trend.prior.period) else {
        return false;
    };
    let period_pair_valid = match trend.comparison_kind {
        CausalComparisonKind::YearOverYear => {
            prior_period.fiscal_year == current_period.fiscal_year - 1
                && prior_period.slot == current_period.slot
        }
        CausalComparisonKind::SequentialQuarter => {
            matches!(current_period.slot, FiscalSlot::Q2 | FiscalSlot::Q3)
                && previous_fiscal_period(current_period) == Some(prior_period)
        }
    };
    causal_ratio_provenance_is_valid(&trend.current, decision_at)
        && causal_ratio_provenance_is_valid(&trend.prior, decision_at)
        && trend.formula_version == COMPUTED_RATIO_TREND_FORMULA_VERSION
        && trend.metric_id == trend.current.metric_id
        && trend.metric_id == trend.prior.metric_id
        && trend.current.ratio_kind == trend.prior.ratio_kind
        && normalize_claim_key(&trend.current.numerator_metric_basis)
            == normalize_claim_key(&trend.prior.numerator_metric_basis)
        && normalize_claim_key(&trend.current.denominator_metric_basis)
            == normalize_claim_key(&trend.prior.denominator_metric_basis)
        && trend.current.source_url != trend.prior.source_url
        && trend.prior.published_at < trend.current.published_at
        && period_pair_valid
        && trend.change_percentage_points.is_finite()
        && (trend.change_percentage_points
            - (trend.current.result_percent - trend.prior.result_percent))
            .abs()
            <= 0.000_001
}

fn operating_kpi_registry_is_valid(model: &FirstPrinciplesModel) -> bool {
    let driver_ids = model
        .demand_drivers
        .iter()
        .chain(model.supply_drivers.iter())
        .chain(model.value_capture_drivers.iter())
        .map(|driver| driver.driver_id.as_str())
        .collect::<BTreeSet<_>>();
    let mut kpi_ids = BTreeSet::new();
    let registry = &model.operating_kpi_registry;
    let Some(shared_catalog) = operating_kpi_catalog_for_model(&model.model_id) else {
        return false;
    };
    let shared_entries = shared_catalog
        .iter()
        .map(|entry| (entry.kpi_id, entry.driver_id))
        .collect::<BTreeSet<_>>();
    let registry_entries = registry
        .entries
        .iter()
        .map(|entry| (entry.kpi_id.as_str(), entry.driver_id.as_str()))
        .collect::<BTreeSet<_>>();
    let legacy_storage_v3_entries = shared_entries
        .iter()
        .copied()
        .filter(|(kpi_id, _)| *kpi_id != "storage_nbm_remaining_performance_obligations")
        .collect::<BTreeSet<_>>();
    let legacy_storage_v2_entries = legacy_storage_v3_entries
        .iter()
        .copied()
        .filter(|(kpi_id, _)| {
            !matches!(
                *kpi_id,
                "data_center_revenue_growth" | "signed_storage_supply_agreements"
            )
        })
        .collect::<BTreeSet<_>>();
    let registry_matches_shared_catalog = if model.model_id == "ai-storage-demand-supply"
        && registry.version == LEGACY_OPERATING_KPI_REGISTRY_VERSION
    {
        let registry_ids = registry_entries
            .iter()
            .map(|(kpi_id, _)| *kpi_id)
            .collect::<BTreeSet<_>>();
        let current_ids = shared_entries
            .iter()
            .map(|(kpi_id, _)| *kpi_id)
            .collect::<BTreeSet<_>>();
        let legacy_v3_ids = legacy_storage_v3_entries
            .iter()
            .map(|(kpi_id, _)| *kpi_id)
            .collect::<BTreeSet<_>>();
        let legacy_v2_ids = legacy_storage_v2_entries
            .iter()
            .map(|(kpi_id, _)| *kpi_id)
            .collect::<BTreeSet<_>>();
        registry_ids == current_ids
            || registry_ids == legacy_v3_ids
            || registry_ids == legacy_v2_ids
    } else if model.model_id == "ai-storage-demand-supply"
        && registry.version == LEGACY_STORAGE_OPERATING_KPI_REGISTRY_VERSION
    {
        registry_entries == legacy_storage_v2_entries
    } else if model.model_id == "ai-storage-demand-supply"
        && registry.version == LEGACY_STORAGE_OPERATING_KPI_REGISTRY_V3_VERSION
    {
        registry_entries == legacy_storage_v3_entries
    } else if model.model_id == "ai-data-center-power-delivery"
        && registry.version == LEGACY_OPERATING_KPI_REGISTRY_VERSION
    {
        registry_entries
            .iter()
            .map(|(kpi_id, driver_id)| {
                (
                    if *kpi_id == "power_backlog_mw" {
                        "generation_equipment_backlog"
                    } else {
                        *kpi_id
                    },
                    *driver_id,
                )
            })
            .collect::<BTreeSet<_>>()
            == shared_entries
    } else {
        registry_entries == shared_entries
    };
    let registry_version_valid = if model.model_id == "ai-storage-demand-supply" {
        matches!(
            registry.version.as_str(),
            LEGACY_OPERATING_KPI_REGISTRY_VERSION
                | LEGACY_STORAGE_OPERATING_KPI_REGISTRY_VERSION
                | LEGACY_STORAGE_OPERATING_KPI_REGISTRY_V3_VERSION
                | STORAGE_OPERATING_KPI_REGISTRY_VERSION
        )
    } else {
        matches!(
            registry.version.as_str(),
            LEGACY_OPERATING_KPI_REGISTRY_VERSION | OPERATING_KPI_REGISTRY_VERSION
        )
    };
    let storage_semantics_valid = if model.model_id != "ai-storage-demand-supply" {
        true
    } else {
        registry
            .entries
            .iter()
            .find(|entry| entry.kpi_id == "nand_bit_shipments_growth")
            .is_some_and(|entry| match registry.version.as_str() {
                LEGACY_OPERATING_KPI_REGISTRY_VERSION => entry.driver_id == "wafer_bits",
                LEGACY_STORAGE_OPERATING_KPI_REGISTRY_VERSION
                | LEGACY_STORAGE_OPERATING_KPI_REGISTRY_V3_VERSION
                | STORAGE_OPERATING_KPI_REGISTRY_VERSION => {
                    entry.driver_id == "realized_bit_demand"
                        && entry.definition.contains("不得解释为晶圆产能增长")
                        && entry
                            .acceptance_requirements
                            .iter()
                            .any(|requirement| requirement.contains("不得替代晶圆产能"))
                }
                _ => false,
            })
    };
    registry_version_valid
        && storage_semantics_valid
        && registry_matches_shared_catalog
        && registry.model_id == model.model_id
        && !registry.entries.is_empty()
        && registry.entries.iter().all(|entry| {
            let policy_is_coherent = match entry.comparability_policy {
                OperatingKpiComparabilityPolicy::StandardizedMetric => {
                    !entry.issuer_definition_required && entry.cross_company_comparable
                }
                OperatingKpiComparabilityPolicy::WithinIssuerOnly
                | OperatingKpiComparabilityPolicy::ContractMilestone => {
                    entry.issuer_definition_required && !entry.cross_company_comparable
                }
            };
            !entry.kpi_id.trim().is_empty()
                && kpi_ids.insert(entry.kpi_id.as_str())
                && !entry.label.trim().is_empty()
                && driver_ids.contains(entry.driver_id.as_str())
                && !entry.definition.trim().is_empty()
                && !entry.unit.trim().is_empty()
                && !entry.period_policy.trim().is_empty()
                && !entry.source_priority.is_empty()
                && entry
                    .source_priority
                    .iter()
                    .all(|source| !source.trim().is_empty())
                && entry.acceptance_requirements.len() >= 4
                && entry
                    .acceptance_requirements
                    .iter()
                    .all(|requirement| !requirement.trim().is_empty())
                && !entry.forbidden_inference.trim().is_empty()
                && policy_is_coherent
        })
}

fn validate_crowding_state(state: &CrowdingState) -> Result<(), String> {
    if state.policy_version.is_empty() {
        if state
            .score
            .is_some_and(|score| !score.is_finite() || !(0.0..=100.0).contains(&score))
        {
            return Err("legacy crowding score is invalid".to_string());
        }
        return Ok(());
    }
    let legacy_v1 = state.policy_version == LEGACY_CROWDING_POLICY_VERSION;
    let legacy_v2 = state.policy_version == LEGACY_CROWDING_PRICE_PATH_POLICY_VERSION;
    if (!legacy_v1 && !legacy_v2 && state.policy_version != CROWDING_POLICY_VERSION)
        || state.scope.trim().is_empty()
        || state
            .observations
            .iter()
            .chain(state.missing_checks.iter())
            .any(|value| value.trim().is_empty())
    {
        return Err("crowding contract is invalid".to_string());
    }
    if legacy_v1
        && (state.short_interest.is_some()
            || state.options_positioning.is_some()
            || state.news_attention.is_some()
            || state.institutional_holdings.is_some()
            || state.analyst_consensus.is_some())
    {
        return Err("legacy crowding state carries unsupported background context".to_string());
    }
    if legacy_v2 && state.analyst_consensus.is_some() {
        return Err("v2 crowding state carries unsupported analyst context".to_string());
    }
    if let Some(summary) = &state.short_interest {
        let expected_change =
            (summary.current_shares_short / summary.previous_shares_short - 1.0) * 100.0;
        if summary.policy_version != SHORT_INTEREST_POLICY_VERSION
            || parse_as_of_date(&summary.as_of).is_none()
            || summary.source.trim().is_empty()
            || !summary.source_url.starts_with("https://")
            || !summary.current_shares_short.is_finite()
            || summary.current_shares_short <= 0.0
            || !summary.previous_shares_short.is_finite()
            || summary.previous_shares_short <= 0.0
            || !summary.change_percent.is_finite()
            || (summary.change_percent - expected_change).abs() > 1e-3
            || !summary.average_daily_share_volume.is_finite()
            || summary.average_daily_share_volume <= 0.0
            || !summary.days_to_cover.is_finite()
            || summary.days_to_cover < 0.0
            || summary.observation_count < 2
            || summary.quality_status != "usable"
            || !summary.quality_warnings.is_empty()
            || summary.interpretation.trim().is_empty()
        {
            return Err("short-interest context is invalid".to_string());
        }
    }
    if let Some(summary) = &state.options_positioning {
        let Some(as_of) = parse_as_of_date(&summary.as_of) else {
            return Err("options-positioning context is invalid".to_string());
        };
        let Some(expiration) = parse_as_of_date(&summary.expiration_date) else {
            return Err("options-positioning context is invalid".to_string());
        };
        let expected_days = expiration.signed_duration_since(as_of).num_days();
        if summary.policy_version != OPTIONS_POSITIONING_POLICY_VERSION
            || summary.source.trim().is_empty()
            || !summary.source_url.starts_with("https://")
            || expiration <= as_of
            || summary.days_to_expiration != expected_days
            || !(20..=90).contains(&summary.days_to_expiration)
            || !summary.spot_price.is_finite()
            || summary.spot_price <= 0.0
            || !summary.call_open_interest.is_finite()
            || summary.call_open_interest <= 0.0
            || !summary.put_open_interest.is_finite()
            || summary.put_open_interest <= 0.0
            || !optional_ratio_matches(
                summary.put_call_open_interest_ratio,
                summary.put_open_interest,
                summary.call_open_interest,
            )
            || !summary.call_volume.is_finite()
            || summary.call_volume < 0.0
            || !summary.put_volume.is_finite()
            || summary.put_volume < 0.0
            || !optional_ratio_matches(
                summary.put_call_volume_ratio,
                summary.put_volume,
                summary.call_volume,
            )
            || summary.contract_rows == 0
            || summary.quality_status != "usable"
            || !summary.quality_warnings.is_empty()
            || summary.interpretation.trim().is_empty()
        {
            return Err("options-positioning context is invalid".to_string());
        }
    }
    if let Some(summary) = &state.news_attention {
        let Some(as_of) = parse_as_of_date(&summary.as_of) else {
            return Err("news-attention context is invalid".to_string());
        };
        let prior_days = summary.window_days - summary.recent_window_days;
        let expected_recent_rate =
            summary.recent_article_count as f64 / summary.recent_window_days.max(1) as f64;
        let expected_prior_rate = summary.prior_article_count as f64 / prior_days.max(1) as f64;
        let oldest_is_valid = if summary.observed_article_count == 0 {
            summary.oldest_observed_date.is_empty()
        } else {
            parse_as_of_date(&summary.oldest_observed_date).is_some_and(|oldest| oldest <= as_of)
        };
        if summary.policy_version != NEWS_ATTENTION_POLICY_VERSION
            || summary.source.trim().is_empty()
            || !summary.source_url.starts_with("https://")
            || summary.window_days != 14
            || summary.recent_window_days != 3
            || prior_days != 11
            || summary.result_limit != 100
            || summary.truncated_window
            || summary.quality_status != "usable"
            || !summary.quality_warnings.is_empty()
            || summary.interpretation.trim().is_empty()
            || summary.recent_article_count + summary.prior_article_count
                > summary.observed_article_count
            || summary.unique_publishers > summary.observed_article_count
            || !summary.recent_daily_rate.is_finite()
            || (summary.recent_daily_rate - expected_recent_rate).abs() > 1e-3
            || !summary.prior_daily_rate.is_finite()
            || (summary.prior_daily_rate - expected_prior_rate).abs() > 1e-3
            || !optional_ratio_matches(
                summary.activity_ratio,
                expected_recent_rate,
                expected_prior_rate,
            )
            || !oldest_is_valid
        {
            return Err("news-attention context is invalid".to_string());
        }
    }
    if let Some(summary) = &state.institutional_holdings {
        let Some(observed_on) = parse_as_of_date(&summary.observed_on) else {
            return Err("institutional-holdings context is invalid".to_string());
        };
        let Some(earliest_period) = parse_as_of_date(&summary.earliest_report_period) else {
            return Err("institutional-holdings context is invalid".to_string());
        };
        let Some(latest_period) = parse_as_of_date(&summary.latest_report_period) else {
            return Err("institutional-holdings context is invalid".to_string());
        };
        let active_holders = summary.increased_positions_holders
            + summary.decreased_positions_holders
            + summary.held_positions_holders;
        let active_shares = summary.increased_positions_shares
            + summary.decreased_positions_shares
            + summary.held_positions_shares;
        let truncation_is_consistent = if summary.holder_table_truncated {
            summary.total_reported_records > summary.top_sample_rows
        } else {
            summary.total_reported_records == summary.top_sample_rows
        };
        if summary.policy_version != INSTITUTIONAL_HOLDINGS_POLICY_VERSION
            || summary.source.trim().is_empty()
            || !summary.source_url.starts_with("https://")
            || !summary.institutional_ownership_percent.is_finite()
            || !(0.0..=300.0).contains(&summary.institutional_ownership_percent)
            || summary.institutional_holders == 0
            || !summary.total_shares_held.is_finite()
            || summary.total_shares_held <= 0.0
            || summary.total_reported_records == 0
            || summary.top_sample_rows == 0
            || summary.top_sample_rows > 50
            || !truncation_is_consistent
            || earliest_period > latest_period
            || latest_period > observed_on
            || summary.report_period_count == 0
            || summary.report_period_count > summary.top_sample_rows
            || summary.latest_period_rows_in_sample == 0
            || summary.latest_period_rows_in_sample > summary.top_sample_rows
            || active_holders != summary.institutional_holders
            || !active_shares.is_finite()
            || (active_shares - summary.total_shares_held).abs() > 1.0
            || !summary.increased_positions_shares.is_finite()
            || summary.increased_positions_shares < 0.0
            || !summary.decreased_positions_shares.is_finite()
            || summary.decreased_positions_shares < 0.0
            || !summary.held_positions_shares.is_finite()
            || summary.held_positions_shares < 0.0
            || !summary.new_positions_shares.is_finite()
            || summary.new_positions_shares < 0.0
            || !summary.sold_out_positions_shares.is_finite()
            || summary.sold_out_positions_shares < 0.0
            || summary.quality_status != "usable"
            || !summary.quality_warnings.is_empty()
            || summary.interpretation.trim().is_empty()
        {
            return Err("institutional-holdings context is invalid".to_string());
        }
    }
    if let Some(summary) = &state.analyst_consensus {
        let Some(_observed_on) = parse_as_of_date(&summary.observed_on) else {
            return Err("analyst-consensus context is invalid".to_string());
        };
        let expected_total = summary.buy_count + summary.hold_count + summary.sell_count;
        let counts = [
            ("买入", summary.buy_count),
            ("持有", summary.hold_count),
            ("卖出", summary.sell_count),
        ];
        let expected_dominant_count = counts
            .iter()
            .map(|(_, count)| *count)
            .max()
            .unwrap_or_default();
        let dominant_labels = counts
            .iter()
            .filter(|(_, count)| *count == expected_dominant_count)
            .map(|(label, _)| *label)
            .collect::<Vec<_>>();
        let expected_dominant_rating = if dominant_labels.len() == 1 {
            dominant_labels[0]
        } else {
            "并列"
        };
        let total = expected_total as f64;
        let expected_buy_share = summary.buy_count as f64 / total * 100.0;
        let expected_hold_share = summary.hold_count as f64 / total * 100.0;
        let expected_sell_share = summary.sell_count as f64 / total * 100.0;
        let expected_dominant_share = expected_dominant_count as f64 / total * 100.0;
        let expected_range_width = (summary.high_target_price - summary.low_target_price)
            / summary.consensus_target_price
            * 100.0;
        if summary.policy_version != ANALYST_CONSENSUS_POLICY_VERSION
            || summary.source.trim().is_empty()
            || !summary.source_url.starts_with("https://")
            || expected_total < 3
            || summary.recommendation_count != expected_total
            || summary.dominant_rating != expected_dominant_rating
            || summary.dominant_count != expected_dominant_count
            || !summary.buy_share_percent.is_finite()
            || (summary.buy_share_percent - expected_buy_share).abs() > 1e-3
            || !summary.hold_share_percent.is_finite()
            || (summary.hold_share_percent - expected_hold_share).abs() > 1e-3
            || !summary.sell_share_percent.is_finite()
            || (summary.sell_share_percent - expected_sell_share).abs() > 1e-3
            || !summary.dominant_share_percent.is_finite()
            || (summary.dominant_share_percent - expected_dominant_share).abs() > 1e-3
            || !summary.consensus_target_price.is_finite()
            || summary.consensus_target_price <= 0.0
            || !summary.low_target_price.is_finite()
            || summary.low_target_price <= 0.0
            || !summary.high_target_price.is_finite()
            || summary.high_target_price <= 0.0
            || summary.low_target_price > summary.consensus_target_price
            || summary.consensus_target_price > summary.high_target_price
            || !summary.target_range_width_percent.is_finite()
            || (summary.target_range_width_percent - expected_range_width).abs() > 1e-3
            || summary.historical_month_count == 0
            || summary.quality_status != "usable"
            || !summary.quality_warnings.is_empty()
            || summary.interpretation.trim().is_empty()
        {
            return Err("analyst-consensus context is invalid".to_string());
        }
    }
    let mut ids = BTreeSet::new();
    let mut weighted_score = 0.0;
    let mut weight_sum = 0.0;
    for component in &state.components {
        let (expected_weight, expected_score) = match component.component_id.as_str() {
            "price_position_52w" => (
                if legacy_v1 { 0.35 } else { 0.20 },
                component.raw_value_percent,
            ),
            "price_vs_50d" => (
                if legacy_v1 { 0.25 } else { 0.15 },
                crowding_anchor(component.raw_value_percent),
            ),
            "average_50d_vs_200d" => (
                if legacy_v1 { 0.15 } else { 0.10 },
                crowding_anchor(component.raw_value_percent),
            ),
            "valuation_scenario_position" => (
                if legacy_v1 { 0.25 } else { 0.20 },
                component.raw_value_percent,
            ),
            "return_20_sessions" if !legacy_v1 => {
                (0.10, short_return_pressure(component.raw_value_percent))
            }
            "return_60_sessions" if !legacy_v1 => {
                (0.10, medium_return_pressure(component.raw_value_percent))
            }
            "drawdown_from_60_session_high" if !legacy_v1 => {
                (0.10, drawdown_pressure(component.raw_value_percent))
            }
            "volume_direction_confirmation" if !legacy_v1 => {
                (0.05, volume_direction_pressure(component.raw_value_percent))
            }
            _ => return Err("crowding component identity is invalid".to_string()),
        };
        if !ids.insert(component.component_id.as_str())
            || component.label.trim().is_empty()
            || component.as_of.trim().is_empty()
            || component.source.trim().is_empty()
            || !component.raw_value_percent.is_finite()
            || !component.pressure_score.is_finite()
            || !(0.0..=100.0).contains(&component.pressure_score)
            || (matches!(
                component.component_id.as_str(),
                "price_position_52w" | "valuation_scenario_position"
            ) && !(0.0..=100.0).contains(&component.raw_value_percent))
            || (component.component_id == "drawdown_from_60_session_high"
                && component.raw_value_percent > 0.0)
            || (component.component_id == "volume_direction_confirmation"
                && !(-100.0..=100.0).contains(&component.raw_value_percent))
            || (component.weight - expected_weight).abs() > 1e-9
            || (component.pressure_score - expected_score).abs() > 1e-6
        {
            return Err("crowding component is invalid".to_string());
        }
        weighted_score += component.pressure_score * component.weight;
        weight_sum += component.weight;
    }
    if state.components.is_empty() {
        if state.status != MeasurementStatus::Unmeasured
            || state.score.is_some()
            || state.label != "暂无可核验位置"
        {
            return Err("empty crowding state carries a measurement".to_string());
        }
    } else {
        let expected = weighted_score / weight_sum;
        if state.status != MeasurementStatus::PartiallyMeasured
            || state
                .score
                .is_none_or(|score| !score.is_finite() || (score - expected).abs() > 1e-6)
            || state.label != crowding_label(expected)
            || state.observations.len() < state.components.len()
            || state.missing_checks.len() < 5
        {
            return Err("crowding projection is invalid".to_string());
        }
    }
    Ok(())
}

fn optional_ratio_matches(actual: Option<f64>, numerator: f64, denominator: f64) -> bool {
    let expected = (denominator > 0.0).then_some(numerator / denominator);
    match (actual, expected) {
        (Some(actual), Some(expected)) => actual.is_finite() && (actual - expected).abs() <= 1e-3,
        (None, None) => true,
        _ => false,
    }
}

fn financial_scalar_matches(actual: Option<f64>, expected: Option<f64>) -> bool {
    match (actual, expected) {
        (Some(actual), Some(expected)) => {
            actual.is_finite()
                && expected.is_finite()
                && (actual - expected).abs() <= 1e-6 * expected.abs().max(1.0)
        }
        (None, None) => true,
        _ => false,
    }
}

/// Replays the small set of valuation-preparation facts projected from the
/// point-in-time SEC ledger. These values remain observation-only, but they
/// still need the same tamper resistance as ratios used by the decision layer.
fn financial_prepared_values_are_valid(financial: &FinancialVerificationState) -> bool {
    let latest_claim = |metric_id: &str| {
        financial
            .source_claims
            .iter()
            .filter(|claim| claim.metric_id == metric_id)
            .max_by_key(|claim| claim.published_at)
    };
    let cash_claim = latest_claim("cash_and_equivalents");
    let debt_claim = latest_claim("long_term_debt");
    let expected_cash = cash_claim.map(|claim| claim.numeric_value);
    let expected_debt = debt_claim.map(|claim| claim.numeric_value);
    if !financial_scalar_matches(financial.cash_and_equivalents, expected_cash)
        || !financial_scalar_matches(financial.long_term_debt, expected_debt)
    {
        return false;
    }

    let expected_net_cash = cash_claim.zip(debt_claim).and_then(|(cash, debt)| {
        (cash.unit == debt.unit).then_some(cash.numeric_value - debt.numeric_value)
    });
    if !financial_scalar_matches(financial.net_cash, expected_net_cash) {
        return false;
    }

    let latest_by_period = |metric_id: &str| {
        let mut values = BTreeMap::<(FiscalPeriodKey, String), &FinancialSourceClaimTrace>::new();
        for claim in financial
            .source_claims
            .iter()
            .filter(|claim| claim.metric_id == metric_id)
        {
            let Some(period) = parse_fiscal_period_key(&claim.period) else {
                continue;
            };
            let key = (period, claim.unit.clone());
            if values
                .get(&key)
                .is_none_or(|previous| previous.published_at <= claim.published_at)
            {
                values.insert(key, claim);
            }
        }
        values
    };
    let operating_cash_flow = latest_by_period("operating_cash_flow");
    let capital_expenditure = latest_by_period("capital_expenditure");
    let mut fcf_candidates = Vec::<(DateTime<Utc>, f64, f64, String)>::new();
    for ((current_period, unit), current_ocf) in &operating_cash_flow {
        let prior_period = FiscalPeriodKey {
            fiscal_year: current_period.fiscal_year - 1,
            slot: current_period.slot,
        };
        let current_key = (*current_period, unit.clone());
        let prior_key = (prior_period, unit.clone());
        let Some(current_capex) = capital_expenditure.get(&current_key).copied() else {
            continue;
        };
        let Some(prior_ocf) = operating_cash_flow.get(&prior_key).copied() else {
            continue;
        };
        let Some(prior_capex) = capital_expenditure.get(&prior_key).copied() else {
            continue;
        };
        if prior_ocf.numeric_value.abs() <= f64::EPSILON
            || prior_capex.numeric_value.abs() <= f64::EPSILON
            || prior_ocf.published_at >= current_ocf.published_at
            || prior_capex.published_at >= current_capex.published_at
            || !period_durations_are_comparable(&prior_ocf.period, &current_ocf.period)
            || !period_durations_are_comparable(&prior_capex.period, &current_capex.period)
        {
            continue;
        }
        fcf_candidates.push((
            current_ocf.published_at.max(current_capex.published_at),
            current_ocf.numeric_value - current_capex.numeric_value,
            prior_ocf.numeric_value - prior_capex.numeric_value,
            unit.clone(),
        ));
    }
    let expected_fcf = fcf_candidates
        .into_iter()
        .max_by_key(|(published_at, _, _, _)| *published_at);
    let expected_current_fcf = expected_fcf.as_ref().map(|(_, current, _, _)| *current);
    let expected_prior_fcf = expected_fcf.as_ref().map(|(_, _, prior, _)| *prior);
    if !financial_scalar_matches(financial.current_free_cash_flow, expected_current_fcf)
        || !financial_scalar_matches(financial.prior_free_cash_flow, expected_prior_fcf)
    {
        return false;
    }

    let expected_fcf_growth = expected_current_fcf
        .zip(expected_prior_fcf)
        .filter(|(current, prior)| *current > 0.0 && *prior > 0.0)
        .map(|(current, prior)| (current / prior - 1.0) * 100.0);
    if expected_fcf.is_some()
        && !financial_scalar_matches(financial.free_cash_flow_growth_percent, expected_fcf_growth)
    {
        return false;
    }

    let expected_unit = expected_fcf
        .as_ref()
        .map(|(_, _, _, unit)| unit.as_str())
        .or_else(|| cash_claim.map(|claim| claim.unit.as_str()));
    financial.financial_value_unit.as_deref() == expected_unit
}

fn validate_point_in_time(snapshot: &InvestmentDecisionSnapshot) -> Result<(), String> {
    if snapshot.schema_version != SCHEMA_VERSION {
        return Err("unsupported decision schema".to_string());
    }
    if snapshot.symbol.trim().is_empty() {
        return Err("decision symbol is empty".to_string());
    }
    match snapshot.market_regime.status {
        MarketRegimeStatus::Unavailable => {
            if (!snapshot.market_regime.taxonomy_version.is_empty()
                && snapshot.market_regime.taxonomy_version != MARKET_REGIME_TAXONOMY_VERSION)
                || !snapshot.market_regime.label.is_empty()
                || snapshot.market_regime.macro_score.is_some()
                || snapshot.market_regime.report_generated_at.is_some()
                || !snapshot.market_regime.source_urls.is_empty()
            {
                return Err("unavailable market regime carries observed data".to_string());
            }
        }
        MarketRegimeStatus::Observed => {
            let Some(score) = snapshot.market_regime.macro_score else {
                return Err("observed market regime is missing its score".to_string());
            };
            let Some(generated_at) = snapshot.market_regime.report_generated_at else {
                return Err("observed market regime is missing its timestamp".to_string());
            };
            if snapshot.market_regime.taxonomy_version != MARKET_REGIME_TAXONOMY_VERSION
                || !score.is_finite()
                || !(0.0..=100.0).contains(&score)
                || snapshot.market_regime.label != market_regime_label(score)
                || generated_at > snapshot.decision_at
                || snapshot.decision_at - generated_at
                    > Duration::hours(MARKET_REGIME_MAX_AGE_HOURS)
                || snapshot
                    .market_regime
                    .source_model_version
                    .trim()
                    .is_empty()
                || snapshot.market_regime.source_urls.is_empty()
                || snapshot
                    .market_regime
                    .source_urls
                    .iter()
                    .any(|url| !url.starts_with("https://"))
                || snapshot
                    .market_regime
                    .data_cutoff
                    .as_deref()
                    .and_then(parse_as_of_date)
                    .is_some_and(|cutoff| cutoff > snapshot.decision_date_beijing)
                || !snapshot.market_regime.missing_reason.is_empty()
            {
                return Err("market regime point-in-time provenance is invalid".to_string());
            }
        }
    }
    validate_crowding_state(&snapshot.crowding)?;
    if snapshot
        .crowding
        .short_interest
        .as_ref()
        .and_then(|summary| parse_as_of_date(&summary.as_of))
        .is_some_and(|as_of| as_of > snapshot.decision_date_beijing)
    {
        return Err("future short-interest context is not allowed".to_string());
    }
    if snapshot
        .crowding
        .options_positioning
        .as_ref()
        .and_then(|summary| parse_as_of_date(&summary.as_of))
        .is_some_and(|as_of| as_of > snapshot.decision_date_beijing)
    {
        return Err("future options-positioning context is not allowed".to_string());
    }
    if snapshot
        .crowding
        .news_attention
        .as_ref()
        .and_then(|summary| parse_as_of_date(&summary.as_of))
        .is_some_and(|as_of| as_of > snapshot.decision_date_beijing)
    {
        return Err("future news-attention context is not allowed".to_string());
    }
    if let Some(observed_on) = snapshot
        .crowding
        .institutional_holdings
        .as_ref()
        .and_then(|summary| parse_as_of_date(&summary.observed_on))
    {
        if observed_on > snapshot.decision_date_beijing {
            return Err("future institutional-holdings context is not allowed".to_string());
        }
        if snapshot
            .decision_date_beijing
            .signed_duration_since(observed_on)
            .num_days()
            > INSTITUTIONAL_HOLDINGS_MAX_OBSERVATION_AGE_DAYS
        {
            return Err("stale institutional-holdings context is not allowed".to_string());
        }
    }
    if let Some(observed_on) = snapshot
        .crowding
        .analyst_consensus
        .as_ref()
        .and_then(|summary| parse_as_of_date(&summary.observed_on))
    {
        if observed_on > snapshot.decision_date_beijing {
            return Err("future analyst-consensus context is not allowed".to_string());
        }
        if snapshot
            .decision_date_beijing
            .signed_duration_since(observed_on)
            .num_days()
            > ANALYST_CONSENSUS_MAX_OBSERVATION_AGE_DAYS
        {
            return Err("stale analyst-consensus context is not allowed".to_string());
        }
    }
    if snapshot
        .evidence
        .iter()
        .any(|item| item.as_of > snapshot.decision_date_beijing)
    {
        return Err("future evidence is not allowed in a point-in-time decision".to_string());
    }
    if let Some(model) = &snapshot.first_principles {
        if !operating_kpi_registry_is_valid(model) {
            return Err("operating KPI registry is invalid".to_string());
        }
        for driver in model
            .demand_drivers
            .iter()
            .chain(model.supply_drivers.iter())
            .chain(model.value_capture_drivers.iter())
        {
            let legacy_driver = driver.promotion.policy_version.is_empty();
            let mut observation_ids = Vec::new();
            for observation in &driver.observations {
                if observation.as_of > snapshot.decision_date_beijing {
                    return Err("future causal observation is not allowed".to_string());
                }
                if observation.observation_id.trim().is_empty()
                    || observation.label.trim().is_empty()
                    || observation.value.trim().is_empty()
                    || observation.source.trim().is_empty()
                    || observation.source_tier.trim().is_empty()
                    || observation.policy_status != "training_only_pending_human_review"
                    || observation_ids.contains(&observation.observation_id)
                {
                    return Err("causal observation provenance is invalid".to_string());
                }
                match (
                    &observation.relationship,
                    &observation.claim,
                    &observation.computed,
                    &observation.ratio,
                    &observation.ratio_trend,
                    &observation.operating_kpi,
                ) {
                    (
                        CausalObservationRelationship::StructuredSourceClaim,
                        Some(claim),
                        None,
                        None,
                        None,
                        None,
                    ) => {
                        if claim.metric_id.trim().is_empty()
                            || (!legacy_driver && claim.metric_basis.trim().is_empty())
                            || (!legacy_driver && claim.source_event_id.trim().is_empty())
                            || claim.period.trim().is_empty()
                            || claim.source_document.trim().is_empty()
                            || claim.source_locator.trim().is_empty()
                            || claim.quote_excerpt.trim().is_empty()
                            || claim.numeric_value.is_some_and(|value| !value.is_finite())
                            || claim.numeric_value.is_some_and(|value| {
                                !causal_numeric_matches(value, &observation.value)
                                    && !causal_numeric_matches(value, &claim.quote_excerpt)
                            })
                            || !matches!(
                                claim.source_document.as_str(),
                                "earnings_call_transcript" | "earnings_release" | "sec_filing"
                            )
                            || observation
                                .source_url
                                .as_deref()
                                .is_none_or(|url| !url.starts_with("https://"))
                            || (claim.numeric_value.is_some() && claim.unit.trim().is_empty())
                            || (!matches!(claim.claim_kind, EarningsClaimKind::ReportedFact)
                                && claim.speaker.as_deref().unwrap_or("").trim().is_empty())
                        {
                            return Err("structured source claim is invalid".to_string());
                        }
                        match claim.lifecycle_status {
                            CausalClaimLifecycleStatus::Active => {
                                if claim.disposition == EarningsClaimDisposition::Withdrawn
                                    || claim.superseded_by.is_some()
                                    || !claim.conflicting_claim_ids.is_empty()
                                {
                                    return Err(
                                        "active source claim lifecycle is invalid".to_string()
                                    );
                                }
                            }
                            CausalClaimLifecycleStatus::Superseded => {
                                if claim.superseded_by.as_deref().is_none_or(str::is_empty)
                                    || claim.superseded_by.as_deref()
                                        == Some(observation.observation_id.as_str())
                                    || !claim.conflicting_claim_ids.is_empty()
                                {
                                    return Err(
                                        "superseded source claim lifecycle is invalid".to_string()
                                    );
                                }
                            }
                            CausalClaimLifecycleStatus::Conflicted => {
                                if claim.conflicting_claim_ids.is_empty()
                                    || claim.conflicting_claim_ids.iter().any(|claim_id| {
                                        claim_id.is_empty()
                                            || claim_id == &observation.observation_id
                                    })
                                    || claim.superseded_by.is_some()
                                {
                                    return Err(
                                        "conflicted source claim lifecycle is invalid".to_string()
                                    );
                                }
                            }
                            CausalClaimLifecycleStatus::Withdrawn => {
                                if claim.disposition != EarningsClaimDisposition::Withdrawn
                                    || claim.superseded_by.is_some()
                                    || !claim.conflicting_claim_ids.is_empty()
                                {
                                    return Err(
                                        "withdrawn source claim lifecycle is invalid".to_string()
                                    );
                                }
                            }
                        }
                    }
                    (CausalObservationRelationship::StructuredSourceClaim, None, _, _, _, _) => {
                        return Err("structured source claim is missing provenance".to_string());
                    }
                    (CausalObservationRelationship::StructuredSourceClaim, Some(_), _, _, _, _) => {
                        return Err(
                            "structured source claim carries computed provenance".to_string()
                        );
                    }
                    (
                        CausalObservationRelationship::ComputedComparison,
                        None,
                        Some(computed),
                        None,
                        None,
                        None,
                    ) => {
                        let expected_change = (computed.current_numeric_value
                            - computed.prior_numeric_value)
                            / computed.prior_numeric_value.abs()
                            * 100.0;
                        let expected_as_of = computed
                            .current_published_at
                            .with_timezone(&Shanghai)
                            .date_naive();
                        if computed.formula_version != COMPUTED_COMPARISON_FORMULA_VERSION
                            || computed.metric_id.trim().is_empty()
                            || computed.metric_basis.trim().is_empty()
                            || computed.current_claim_id.trim().is_empty()
                            || computed.prior_claim_id.trim().is_empty()
                            || computed.current_claim_id == computed.prior_claim_id
                            || computed.current_period.trim().is_empty()
                            || computed.prior_period.trim().is_empty()
                            || computed.unit.trim().is_empty()
                            || !computed.current_numeric_value.is_finite()
                            || !computed.prior_numeric_value.is_finite()
                            || computed.prior_numeric_value.abs() <= f64::EPSILON
                            || !computed.change_percent.is_finite()
                            || (computed.change_percent - expected_change).abs() > 0.000_001
                            || computed.prior_published_at >= computed.current_published_at
                            || computed.current_published_at > snapshot.decision_at
                            || observation.as_of != expected_as_of
                            || observation.source_tier != "deterministic_computation"
                            || observation.source_url.as_deref()
                                != Some(computed.current_source_url.as_str())
                            || !computed.current_source_url.starts_with("https://")
                            || !computed.prior_source_url.starts_with("https://")
                            || !computed_period_pair_is_valid(computed)
                        {
                            return Err("computed comparison provenance is invalid".to_string());
                        }
                    }
                    (CausalObservationRelationship::ComputedComparison, _, None, _, _, _) => {
                        return Err("computed comparison is missing provenance".to_string());
                    }
                    (
                        CausalObservationRelationship::ComputedComparison,
                        Some(_),
                        Some(_),
                        _,
                        _,
                        _,
                    ) => {
                        return Err(
                            "computed comparison carries source claim provenance".to_string()
                        );
                    }
                    (CausalObservationRelationship::ComputedComparison, None, Some(_), _, _, _) => {
                        return Err("computed comparison carries unrelated provenance".to_string());
                    }
                    (
                        CausalObservationRelationship::ComputedRatio,
                        None,
                        None,
                        Some(ratio),
                        None,
                        None,
                    ) => {
                        let expected_as_of =
                            ratio.published_at.with_timezone(&Shanghai).date_naive();
                        if !causal_ratio_provenance_is_valid(ratio, snapshot.decision_at)
                            || observation.as_of != expected_as_of
                            || observation.source_tier != "deterministic_computation"
                            || observation.source_url.as_deref() != Some(ratio.source_url.as_str())
                        {
                            return Err("computed ratio provenance is invalid".to_string());
                        }
                    }
                    (CausalObservationRelationship::ComputedRatio, _, _, None, _, _) => {
                        return Err("computed ratio is missing provenance".to_string());
                    }
                    (CausalObservationRelationship::ComputedRatio, Some(_), _, Some(_), _, _)
                    | (CausalObservationRelationship::ComputedRatio, _, Some(_), Some(_), _, _)
                    | (CausalObservationRelationship::ComputedRatio, _, _, Some(_), Some(_), _)
                    | (CausalObservationRelationship::ComputedRatio, _, _, Some(_), _, Some(_)) => {
                        return Err("computed ratio carries unrelated provenance".to_string());
                    }
                    (
                        CausalObservationRelationship::ComputedRatioTrend,
                        None,
                        None,
                        None,
                        Some(trend),
                        None,
                    ) => {
                        let expected_as_of = trend
                            .current
                            .published_at
                            .with_timezone(&Shanghai)
                            .date_naive();
                        if !causal_ratio_trend_is_valid(trend, snapshot.decision_at)
                            || observation.as_of != expected_as_of
                            || observation.source_tier != "deterministic_computation"
                            || observation.source_url.as_deref()
                                != Some(trend.current.source_url.as_str())
                        {
                            return Err("computed ratio trend provenance is invalid".to_string());
                        }
                    }
                    (CausalObservationRelationship::ComputedRatioTrend, _, _, _, None, _) => {
                        return Err("computed ratio trend is missing provenance".to_string());
                    }
                    (CausalObservationRelationship::ComputedRatioTrend, _, _, _, Some(_), _) => {
                        return Err("computed ratio trend carries unrelated provenance".to_string());
                    }
                    (
                        CausalObservationRelationship::OperatingKpiClaim,
                        None,
                        None,
                        None,
                        None,
                        Some(provenance),
                    ) => {
                        if !causal_operating_kpi_is_valid(
                            provenance,
                            observation,
                            driver,
                            &model.operating_kpi_registry,
                        ) {
                            return Err("operating KPI provenance is invalid".to_string());
                        }
                    }
                    (CausalObservationRelationship::OperatingKpiClaim, _, _, _, _, None) => {
                        return Err("operating KPI claim is missing provenance".to_string());
                    }
                    (CausalObservationRelationship::OperatingKpiClaim, _, _, _, _, Some(_)) => {
                        return Err("operating KPI claim carries unrelated provenance".to_string());
                    }
                    (_, Some(_), _, _, _, _) => {
                        return Err("non-claim observation carries claim provenance".to_string());
                    }
                    (_, None, Some(_), _, _, _) => {
                        return Err(
                            "non-computed observation carries computed provenance".to_string()
                        );
                    }
                    (_, None, None, Some(_), _, _) => {
                        return Err("non-ratio observation carries ratio provenance".to_string());
                    }
                    (_, None, None, None, Some(_), _) => {
                        return Err(
                            "non-ratio-trend observation carries trend provenance".to_string()
                        );
                    }
                    (_, None, None, None, None, Some(_)) => {
                        return Err(
                            "non-operating-KPI observation carries KPI provenance".to_string()
                        );
                    }
                    (_, None, None, None, None, None) => {}
                }
                observation_ids.push(observation.observation_id.clone());
            }
            validate_causal_promotion(driver, snapshot.decision_at)?;
        }
    }
    let financial = &snapshot.financial_verification;
    let financial_values = [
        financial.revenue_growth_percent,
        financial.gross_margin_percent,
        financial.gross_margin_change_pp,
        financial.ebit_margin_percent,
        financial.fcf_margin_percent,
        financial.accounts_receivable_growth_percent,
        financial.accounts_payable_growth_percent,
        financial.inventory_growth_percent,
        financial.property_plant_equipment_growth_percent,
        financial.operating_cash_flow_growth_percent,
        financial.capital_expenditure_growth_percent,
        financial.free_cash_flow_growth_percent,
        financial.forward_metric_growth_percent,
    ];
    let source_ids = financial
        .source_claim_ids
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    let source_urls = financial
        .source_urls
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    let source_calculations = financial
        .source_calculations
        .iter()
        .collect::<BTreeSet<_>>();
    let source_claim_trace_ids = financial
        .source_claims
        .iter()
        .map(|claim| claim.claim_id.as_str())
        .collect::<BTreeSet<_>>();
    let source_claim_trace_urls = financial
        .source_claims
        .iter()
        .map(|claim| claim.source_url.as_str())
        .collect::<BTreeSet<_>>();
    let quality_warnings = financial.quality_warnings.iter().collect::<BTreeSet<_>>();
    let anomaly_review_required = [
        financial.revenue_growth_percent,
        financial.accounts_receivable_growth_percent,
        financial.accounts_payable_growth_percent,
        financial.inventory_growth_percent,
        financial.property_plant_equipment_growth_percent,
        financial.operating_cash_flow_growth_percent,
        financial.capital_expenditure_growth_percent,
    ]
    .into_iter()
    .flatten()
    .any(|value| value.abs() >= 200.0)
        || financial
            .gross_margin_change_pp
            .is_some_and(|value| value.abs() >= 40.0)
        || [
            financial.gross_margin_percent,
            financial.ebit_margin_percent,
        ]
        .into_iter()
        .flatten()
        .any(|value| !(-100.0..=100.0).contains(&value));
    let non_positive_fcf_warning_required = financial
        .current_free_cash_flow
        .zip(financial.prior_free_cash_flow)
        .is_some_and(|(current, prior)| current <= 0.0 || prior <= 0.0);
    let quality_warning_required = anomaly_review_required || non_positive_fcf_warning_required;
    let prepared_financial_values_present = financial.cash_and_equivalents.is_some()
        || financial.long_term_debt.is_some()
        || financial.net_cash.is_some()
        || financial.current_free_cash_flow.is_some()
        || financial.prior_free_cash_flow.is_some()
        || financial.financial_value_unit.is_some();
    if (!financial.policy_version.is_empty()
        && !matches!(
            financial.policy_version.as_str(),
            SEC_PROJECTION_FINANCIAL_VERIFICATION_POLICY_VERSION
                | FINANCIAL_QUALITY_FINANCIAL_VERIFICATION_POLICY_VERSION
                | SOURCE_CLAIM_TRACE_FINANCIAL_VERIFICATION_POLICY_VERSION
                | FINANCIAL_VERIFICATION_POLICY_VERSION
        ))
        || financial_values
            .into_iter()
            .flatten()
            .any(|value| !value.is_finite())
        || source_ids.len() != financial.source_claim_ids.len()
        || source_urls.len() != financial.source_urls.len()
        || source_calculations.len() != financial.source_calculations.len()
        || source_claim_trace_ids.len() != financial.source_claims.len()
        || quality_warnings.len() != financial.quality_warnings.len()
        || financial
            .source_claim_ids
            .iter()
            .any(|id| id.trim().is_empty())
        || financial
            .source_urls
            .iter()
            .any(|url| !url.starts_with("https://"))
        || (financial.source_claim_ids.is_empty() != financial.source_urls.is_empty())
        || financial
            .source_calculations
            .iter()
            .chain(financial.quality_warnings.iter())
            .any(|value| value.trim().is_empty())
        || (!financial.source_calculations.is_empty() && financial.source_urls.is_empty())
        || (matches!(
            financial.policy_version.as_str(),
            SOURCE_CLAIM_TRACE_FINANCIAL_VERIFICATION_POLICY_VERSION
                | FINANCIAL_VERIFICATION_POLICY_VERSION
        ) && (!financial.source_claim_ids.is_empty()
            && (source_claim_trace_ids != source_ids || source_claim_trace_urls != source_urls)))
        || (matches!(
            financial.policy_version.as_str(),
            SOURCE_CLAIM_TRACE_FINANCIAL_VERIFICATION_POLICY_VERSION
                | FINANCIAL_VERIFICATION_POLICY_VERSION
        ) && financial.source_claims.iter().any(|claim| {
            claim.claim_id.trim().is_empty()
                || claim.metric_id.trim().is_empty()
                || claim.metric_basis.trim().is_empty()
                || claim.period.trim().is_empty()
                || !claim.numeric_value.is_finite()
                || !monetary_millions_unit(&claim.unit)
                || !claim.source_url.starts_with("https://")
                || claim.published_at > snapshot.decision_at
        }))
        || ((financial.policy_version == FINANCIAL_VERIFICATION_POLICY_VERSION
            || (financial.policy_version
                == SOURCE_CLAIM_TRACE_FINANCIAL_VERIFICATION_POLICY_VERSION
                && prepared_financial_values_present))
            && !financial_prepared_values_are_valid(financial))
        || (matches!(
            financial.policy_version.as_str(),
            FINANCIAL_QUALITY_FINANCIAL_VERIFICATION_POLICY_VERSION
                | SOURCE_CLAIM_TRACE_FINANCIAL_VERIFICATION_POLICY_VERSION
        ) && !prepared_financial_values_present
            && anomaly_review_required != !financial.quality_warnings.is_empty())
        || ((financial.policy_version == FINANCIAL_VERIFICATION_POLICY_VERSION
            || (financial.policy_version
                == SOURCE_CLAIM_TRACE_FINANCIAL_VERIFICATION_POLICY_VERSION
                && prepared_financial_values_present))
            && quality_warning_required != !financial.quality_warnings.is_empty())
        || (!financial.source_claim_ids.is_empty()
            && financial
                .financial_as_of
                .as_deref()
                .and_then(parse_as_of_date)
                .is_none_or(|as_of| as_of > snapshot.decision_date_beijing))
    {
        return Err("financial verification provenance is invalid".to_string());
    }
    let methodology = &snapshot.decision.methodology;
    if !methodology.policy_version.is_empty() {
        let Some(base_zone) = parse_research_zone_id(&methodology.pre_methodology_zone) else {
            return Err("Hari methodology carries an invalid base zone".to_string());
        };
        let Some(base_action) = parse_exposure_action_id(&methodology.pre_methodology_action)
        else {
            return Err("Hari methodology carries an invalid base action".to_string());
        };
        let mut expected = hari_methodology_state(
            &base_zone,
            &base_action,
            &snapshot.company_quality,
            snapshot.first_principles.as_ref(),
            &snapshot.market_regime,
        );
        match methodology.policy_version.as_str() {
            HARI_POLICY_VERSION => {}
            LEGACY_HARI_POLICY_VERSION => {
                expected.policy_version = LEGACY_HARI_POLICY_VERSION.to_string();
                // V1 used this field as a vacuous truth outside an increase
                // candidate. A short-lived local build also wrote false there.
                // Neither value affected zone/action, so both remain replayable.
                if base_action != ExposureAction::IncreaseCandidate {
                    expected.increase_candidate_authorized =
                        methodology.increase_candidate_authorized;
                }
            }
            _ => return Err("Hari methodology carries an unknown policy version".to_string()),
        }
        let expected_final = if base_action == ExposureAction::IncreaseCandidate
            && !expected.increase_candidate_authorized
        {
            (ResearchZone::InsufficientData, ExposureAction::ResearchOnly)
        } else {
            (base_zone, base_action)
        };
        if methodology != &expected
            || snapshot.decision.zone != expected_final.0
            || snapshot.decision.action != expected_final.1
        {
            return Err("Hari methodology projection is invalid".to_string());
        }
    }
    if !snapshot.decision_completeness.policy_version.is_empty() {
        let completeness = &snapshot.decision_completeness;
        let mut check_ids = BTreeSet::new();
        if !matches!(
            completeness.policy_version.as_str(),
            LEGACY_DECISION_COMPLETENESS_POLICY_VERSION
                | SEC_PROJECTION_DECISION_COMPLETENESS_POLICY_VERSION
                | FINANCIAL_QUALITY_DECISION_COMPLETENESS_POLICY_VERSION
                | PRICE_POSITION_DECISION_COMPLETENESS_POLICY_VERSION
                | DECISION_COMPLETENESS_POLICY_VERSION
        ) || completeness.total_checks != completeness.checks.len()
            || completeness.total_checks == 0
            || completeness.passed_checks > completeness.total_checks
            || !completeness.completeness_percent.is_finite()
            || !(0.0..=100.0).contains(&completeness.completeness_percent)
            || completeness.scope.trim().is_empty()
            || completeness.checks.iter().any(|check| {
                check.check_id.trim().is_empty()
                    || !check_ids.insert(check.check_id.as_str())
                    || check.label.trim().is_empty()
                    || check.gaps.iter().any(|gap| gap.trim().is_empty())
                    || check.evidence.iter().any(|item| item.trim().is_empty())
            })
        {
            return Err("decision completeness contract is invalid".to_string());
        }
        if completeness.policy_version == DECISION_COMPLETENESS_POLICY_VERSION {
            let expected = decision_completeness_state(
                snapshot.decision_date_beijing,
                snapshot.first_principles.as_ref(),
                &snapshot.company_quality,
                &snapshot.financial_verification,
                snapshot.valuation.as_ref(),
                &snapshot.crowding,
                &snapshot.market_regime,
                &snapshot.decision,
            );
            if completeness != &expected {
                return Err("decision completeness projection is invalid".to_string());
            }
        }
    }
    let confidence = &snapshot.decision.causal_confidence;
    if !confidence.policy_version.is_empty() {
        if confidence.policy_version != CAUSAL_PROMOTION_POLICY_VERSION
            || !matches!(
                confidence.base_confidence.as_str(),
                "low" | "medium" | "high"
            )
            || !matches!(
                confidence.effective_confidence.as_str(),
                "low" | "medium" | "high"
            )
            || snapshot.decision.confidence != confidence.effective_confidence
        {
            return Err("causal confidence projection is invalid".to_string());
        }
        let expected = causal_confidence_state(
            &confidence.base_confidence,
            snapshot.first_principles.as_ref(),
        );
        if confidence.effective_confidence != expected.effective_confidence
            || confidence.promoted_driver_count != expected.promoted_driver_count
            || confidence.blocked_conflict_count != expected.blocked_conflict_count
            || confidence.blocked_human_rejection_count != expected.blocked_human_rejection_count
            || confidence.blocked_falsification_count != expected.blocked_falsification_count
            || confidence.adjustment != expected.adjustment
        {
            return Err("causal confidence does not match promoted drivers".to_string());
        }
    }
    if snapshot
        .company_quality
        .research_as_of
        .is_some_and(|as_of| as_of > snapshot.decision_date_beijing)
    {
        return Err("future research baseline is not allowed".to_string());
    }
    if snapshot
        .financial_verification
        .financial_as_of
        .as_deref()
        .and_then(parse_as_of_date)
        .is_some_and(|as_of| as_of > snapshot.decision_date_beijing)
        || snapshot
            .financial_verification
            .forward_metric_as_of
            .as_deref()
            .and_then(parse_as_of_date)
            .is_some_and(|as_of| as_of > snapshot.decision_date_beijing)
    {
        return Err("future financial evidence is not allowed".to_string());
    }
    if snapshot
        .valuation
        .as_ref()
        .and_then(|value| parse_as_of_date(&value.as_of))
        .is_some_and(|as_of| as_of > snapshot.decision_date_beijing)
    {
        return Err("future valuation is not allowed".to_string());
    }
    Ok(())
}

fn unique_strings(items: Vec<String>) -> Vec<String> {
    let mut output = Vec::new();
    for item in items {
        let trimmed = item.trim();
        if !trimmed.is_empty() && !output.iter().any(|existing| existing == trimmed) {
            output.push(trimmed.to_string());
        }
    }
    output
}

fn valid_symbol(symbol: &str) -> bool {
    !symbol.is_empty()
        && symbol.len() <= 16
        && symbol
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'-'))
}

fn valid_sample_id(sample_id: &str) -> bool {
    !sample_id.is_empty()
        && sample_id.len() <= 240
        && !sample_id.contains(['/', '\\'])
        && sample_id != "."
        && sample_id != ".."
        && sample_id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'-' | b'_'))
}

fn normalize_optional_text(value: Option<String>) -> Option<String> {
    value.and_then(|value| {
        let trimmed = value.trim();
        (!trimmed.is_empty()).then(|| trimmed.to_string())
    })
}

fn normalize_error_attributions(
    errors: Vec<DecisionErrorAttribution>,
) -> Vec<DecisionErrorAttribution> {
    errors
        .into_iter()
        .map(|mut error| {
            error.explanation = error.explanation.trim().to_string();
            error.evidence_ids = unique_strings(error.evidence_ids);
            error
        })
        .collect()
}

fn normalize_causal_link_reviews(reviews: Vec<CausalLinkReview>) -> Vec<CausalLinkReview> {
    reviews
        .into_iter()
        .map(|mut review| {
            review.driver_id = review.driver_id.trim().to_string();
            review.observation_id = review.observation_id.trim().to_string();
            review.explanation = review.explanation.trim().to_string();
            review.verbatim_judgment = normalize_optional_text(review.verbatim_judgment);
            review.applicability_boundary = normalize_optional_text(review.applicability_boundary);
            review.falsifier = normalize_optional_text(review.falsifier);
            review.review_id = normalize_optional_text(review.review_id);
            review.reviewer_id = normalize_optional_text(review.reviewer_id);
            review.evidence_identity_sha256 =
                normalize_optional_text(review.evidence_identity_sha256);
            review.source_review_id = normalize_optional_text(review.source_review_id);
            review.source_review_sample_id =
                normalize_optional_text(review.source_review_sample_id);
            review
        })
        .collect()
}

fn upsert_causal_link_review(reviews: &mut Vec<CausalLinkReview>, review: CausalLinkReview) {
    reviews.retain(|current| {
        current.driver_id != review.driver_id || current.observation_id != review.observation_id
    });
    reviews.push(review);
    reviews.sort_by(|left, right| {
        left.driver_id
            .cmp(&right.driver_id)
            .then_with(|| left.observation_id.cmp(&right.observation_id))
    });
}

fn upsert_causal_source_review(
    reviews: &mut Vec<CausalSourceReviewProjection>,
    review: CausalSourceReviewProjection,
) {
    reviews.retain(|current| {
        current.driver_id != review.driver_id || current.observation_id != review.observation_id
    });
    reviews.push(review);
    reviews.sort_by(|left, right| {
        left.driver_id
            .cmp(&right.driver_id)
            .then_with(|| left.observation_id.cmp(&right.observation_id))
    });
}

fn find_causal_observation<'a>(
    sample: &'a DecisionTrainingSample,
    driver_id: &str,
    observation_id: &str,
) -> Option<(&'a ModelDriver, &'a CausalObservation)> {
    sample.state.first_principles.as_ref().and_then(|model| {
        model
            .demand_drivers
            .iter()
            .chain(model.supply_drivers.iter())
            .chain(model.value_capture_drivers.iter())
            .find_map(|driver| {
                (driver.driver_id == driver_id)
                    .then(|| {
                        driver
                            .observations
                            .iter()
                            .find(|observation| observation.observation_id == observation_id)
                            .map(|observation| (driver, observation))
                    })
                    .flatten()
            })
    })
}

fn causal_evidence_fingerprint(
    sample: &DecisionTrainingSample,
    driver_id: &str,
    observation_id: &str,
) -> Result<String, String> {
    let (driver, observation) = find_causal_observation(sample, driver_id, observation_id)
        .ok_or_else(|| "source review observation is not in the frozen sample".to_string())?;
    let bytes = serde_json::to_vec(&(
        CAUSAL_SOURCE_REVIEW_SCHEMA_VERSION,
        &sample.sample_id,
        &sample.state.symbol,
        sample.state.decision_at,
        &driver.driver_id,
        &driver.mechanism,
        observation,
    ))
    .map_err(|error| error.to_string())?;
    Ok(format!("{:x}", Sha256::digest(bytes)))
}

fn causal_evidence_identity(
    sample: &DecisionTrainingSample,
    driver_id: &str,
    observation_id: &str,
) -> Result<String, String> {
    let (driver, observation) = find_causal_observation(sample, driver_id, observation_id)
        .ok_or_else(|| "evidence identity observation is not in the frozen sample".to_string())?;
    let bytes = serde_json::to_vec(&(
        CAUSAL_EVIDENCE_IDENTITY_VERSION,
        &sample.state.symbol,
        &driver.driver_id,
        &driver.mechanism,
        observation,
    ))
    .map_err(|error| error.to_string())?;
    Ok(format!("{:x}", Sha256::digest(bytes)))
}

fn source_review_projection(record: &CausalSourceReviewRecord) -> CausalSourceReviewProjection {
    CausalSourceReviewProjection {
        driver_id: record.driver_id.clone(),
        observation_id: record.observation_id.clone(),
        evidence_fingerprint_sha256: record.evidence_fingerprint_sha256.clone(),
        verdict: record.verdict.clone(),
        note: record.note.clone(),
        review_id: record.review_id.clone(),
        reviewed_at: record.submitted_at,
        reviewer_id: record.reviewer_id.clone(),
    }
}

#[derive(Debug, Clone)]
struct ReusableCausalSourceReview {
    projection: CausalSourceReviewProjection,
    origin_sample_id: String,
    evidence_identity_sha256: String,
}

async fn reusable_causal_source_review(
    state: &AppState,
    target_sample: &DecisionTrainingSample,
    driver_id: &str,
    observation_id: &str,
    expected_review_id: Option<&str>,
) -> Result<ReusableCausalSourceReview, String> {
    let directory = decision_root(state)
        .join("training")
        .join(&target_sample.state.symbol);
    let samples =
        read_replay_directory(&directory, &target_sample.state.symbol, usize::MAX, true).await?;
    reusable_causal_source_review_from_samples(
        &samples,
        target_sample,
        driver_id,
        observation_id,
        expected_review_id,
    )
}

fn reusable_causal_source_review_from_samples(
    samples: &[DecisionTrainingSample],
    target_sample: &DecisionTrainingSample,
    driver_id: &str,
    observation_id: &str,
    expected_review_id: Option<&str>,
) -> Result<ReusableCausalSourceReview, String> {
    let context = causal_source_review_context_from_samples(samples);
    reusable_causal_source_review_from_context(
        &context,
        target_sample,
        driver_id,
        observation_id,
        expected_review_id,
    )
}

fn causal_source_review_context_from_samples(
    samples: &[DecisionTrainingSample],
) -> Vec<ReusableCausalSourceReview> {
    causal_source_review_context_from_iter(samples.iter())
}

fn causal_source_review_context_from_iter<'a>(
    samples: impl IntoIterator<Item = &'a DecisionTrainingSample>,
) -> Vec<ReusableCausalSourceReview> {
    let mut context = Vec::new();
    for sample in samples {
        for review in &sample.human_review.causal_source_reviews {
            let Ok(identity) =
                causal_evidence_identity(sample, &review.driver_id, &review.observation_id)
            else {
                continue;
            };
            context.push(ReusableCausalSourceReview {
                projection: review.clone(),
                origin_sample_id: sample.sample_id.clone(),
                evidence_identity_sha256: identity,
            });
        }
    }
    context
}

fn reusable_causal_source_review_from_context(
    context: &[ReusableCausalSourceReview],
    target_sample: &DecisionTrainingSample,
    driver_id: &str,
    observation_id: &str,
    expected_review_id: Option<&str>,
) -> Result<ReusableCausalSourceReview, String> {
    let expected_review_id = expected_review_id
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| "source review id is required".to_string())?;
    let target_identity = causal_evidence_identity(target_sample, driver_id, observation_id)?;
    let mut matching = context
        .iter()
        .filter(|review| {
            review.projection.driver_id == driver_id
                && review.projection.observation_id == observation_id
                && review.evidence_identity_sha256 == target_identity
        })
        .cloned()
        .collect::<Vec<_>>();
    if matching.is_empty() {
        return Err(
            "verify the exact frozen evidence before submitting Old Wang's causal judgment"
                .to_string(),
        );
    }
    let first_verdict = matching[0].projection.verdict.clone();
    if matching
        .iter()
        .any(|review| review.projection.verdict != first_verdict)
    {
        return Err(
            "the same frozen evidence has conflicting source reviews across decision snapshots"
                .to_string(),
        );
    }
    matching.sort_by(|left, right| {
        left.projection
            .reviewed_at
            .cmp(&right.projection.reviewed_at)
            .then_with(|| left.projection.review_id.cmp(&right.projection.review_id))
    });
    let latest = matching.pop().expect("matching source review is not empty");
    if latest.projection.review_id != expected_review_id {
        return Err("source review changed; reload before submitting".to_string());
    }
    Ok(latest)
}

fn causal_review_timestamp(
    sample: &DecisionTrainingSample,
    review: &CausalLinkReview,
) -> Option<DateTime<Utc>> {
    review.reviewed_at.or(sample.human_review.reviewed_at)
}

fn latest_causal_review_timestamp(sample: &DecisionTrainingSample) -> Option<DateTime<Utc>> {
    sample
        .human_review
        .causal_link_reviews
        .iter()
        .filter_map(|review| causal_review_timestamp(sample, review))
        .max()
}

