async fn acquire_causal_training_experiment_lock(
    state: &AppState,
) -> Result<DecisionReviewLock, String> {
    let directory = decision_root(state).join("governance-locks");
    tokio::fs::create_dir_all(&directory)
        .await
        .map_err(|error| error.to_string())?;
    let path = directory.join("causal-training-experiment-registry.lock");
    for attempt in 0..2 {
        match tokio::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&path)
            .await
        {
            Ok(_) => return Ok(DecisionReviewLock { path }),
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists && attempt == 0 => {
                let stale = tokio::fs::metadata(&path)
                    .await
                    .ok()
                    .and_then(|metadata| metadata.modified().ok())
                    .and_then(|modified| SystemTime::now().duration_since(modified).ok())
                    .is_some_and(|age| age >= StdDuration::from_secs(600));
                if stale {
                    let _ = tokio::fs::remove_file(&path).await;
                    continue;
                }
                return Err(
                    "causal training experiment registration is already in progress".to_string(),
                );
            }
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
                return Err(
                    "causal training experiment registration is already in progress".to_string(),
                );
            }
            Err(error) => return Err(error.to_string()),
        }
    }
    Err("causal training experiment lock unavailable".to_string())
}

