fn build_training_sample(snapshot: &InvestmentDecisionSnapshot) -> DecisionTrainingSample {
    DecisionTrainingSample {
        schema_version: TRAINING_SCHEMA_VERSION.to_string(),
        sample_id: snapshot.revision_id.clone(),
        observed_at: snapshot.decision_at,
        state: snapshot.clone(),
        selected_action: snapshot.decision.action.clone(),
        human_review: HumanReviewState {
            status: HumanReviewStatus::Pending,
            review_id: None,
            reviewed_at: None,
            reviewer_id: None,
            correction_note: None,
            thesis_verdict: ThesisReviewVerdict::Pending,
            corrected_zone: None,
            corrected_action: None,
            error_attributions: Vec::new(),
            causal_link_reviews: Vec::new(),
            causal_source_reviews: Vec::new(),
        },
        outcomes: [20_u16, 60, 250]
            .into_iter()
            .map(|horizon_market_sessions| ForwardOutcomeLabel {
                horizon_market_sessions,
                status: OutcomeStatus::PendingMarketSessions,
                period_start: None,
                period_end: None,
                market_sessions_observed: None,
                labelled_at: None,
                asset_start_price: None,
                asset_end_price: None,
                asset_return_percent: None,
                benchmark_symbol: None,
                benchmark_start_price: None,
                benchmark_end_price: None,
                benchmark_return_percent: None,
                excess_return_percent: None,
                max_drawdown_percent: None,
                market_data_source: None,
                invalid_reason: None,
            })
            .collect(),
        reward: RewardState {
            status: RewardStatus::Unconfigured,
            objective_version: None,
            value: None,
            note: "奖励函数尚未获批；不得把短期涨跌自动当作投资质量。".to_string(),
        },
    }
}

fn validate_training_sample(sample: &DecisionTrainingSample) -> Result<(), String> {
    if sample.schema_version != TRAINING_SCHEMA_VERSION {
        return Err("unsupported training sample schema".to_string());
    }
    validate_point_in_time(&sample.state)?;
    if sample.sample_id != sample.state.revision_id
        || sample.observed_at != sample.state.decision_at
        || sample.selected_action != sample.state.decision.action
    {
        return Err("training sample does not match its decision state".to_string());
    }
    let review = &sample.human_review;
    if review
        .reviewed_at
        .is_some_and(|reviewed_at| reviewed_at < sample.observed_at)
        || review
            .reviewer_id
            .as_deref()
            .is_some_and(|reviewer| reviewer.trim().is_empty() || reviewer.len() > 128)
        || review.correction_note.as_deref().is_some_and(|note| {
            let note = note.trim();
            note.is_empty() || note.chars().count() > 4_000
        })
    {
        return Err("human review provenance or correction is invalid".to_string());
    }
    if review.review_id.as_deref().is_some_and(|review_id| {
        review_id.trim().is_empty() || review_id.len() > 200 || review_id.contains(['/', '\\'])
    }) {
        return Err("human review id is invalid".to_string());
    }
    let mut error_kinds = Vec::new();
    for error in &review.error_attributions {
        let explanation = error.explanation.trim();
        if explanation.is_empty()
            || explanation.chars().count() > 2_000
            || error_kinds.contains(&error.kind)
            || error.evidence_ids.len() > 20
            || error.evidence_ids.iter().any(|evidence_id| {
                evidence_id.trim().is_empty()
                    || !sample
                        .state
                        .evidence
                        .iter()
                        .any(|evidence| evidence.evidence_id == *evidence_id)
            })
        {
            return Err("human review error attribution is invalid".to_string());
        }
        error_kinds.push(error.kind.clone());
    }
    let mut causal_links = Vec::new();
    let mut source_review_targets = Vec::new();
    for source_review in &review.causal_source_reviews {
        let key = (
            source_review.driver_id.as_str(),
            source_review.observation_id.as_str(),
        );
        let expected_fingerprint = causal_evidence_fingerprint(
            sample,
            &source_review.driver_id,
            &source_review.observation_id,
        );
        if source_review_targets.len() >= 50
            || source_review_targets.contains(&key)
            || source_review.verdict == CausalSourceVerification::Unchecked
            || source_review.note.trim().is_empty()
            || source_review.note.chars().count() > 2_000
            || source_review.review_id.trim().is_empty()
            || source_review.review_id.len() > 240
            || source_review.review_id.contains(['/', '\\'])
            || source_review.reviewed_at < sample.observed_at
            || source_review.reviewer_id.trim().is_empty()
            || source_review.reviewer_id.len() > 128
            || !valid_sha256(&source_review.evidence_fingerprint_sha256)
            || expected_fingerprint.is_err()
            || expected_fingerprint
                .is_ok_and(|fingerprint| fingerprint != source_review.evidence_fingerprint_sha256)
        {
            return Err("human source review is invalid".to_string());
        }
        source_review_targets.push(key);
    }
    for causal_review in &review.causal_link_reviews {
        let key = (
            causal_review.driver_id.as_str(),
            causal_review.observation_id.as_str(),
        );
        let explanation = causal_review.explanation.trim();
        let distilled_fields = [
            causal_review.verbatim_judgment.as_deref(),
            causal_review.applicability_boundary.as_deref(),
            causal_review.falsifier.as_deref(),
        ];
        let source_excluded = matches!(
            causal_review.speaker_confirmation,
            CausalSpeakerConfirmation::EvidenceMismatch
                | CausalSpeakerConfirmation::InsufficientSourceContext
        );
        let has_any_distillation = distilled_fields.iter().any(Option::is_some)
            || causal_review.speaker_confirmation != CausalSpeakerConfirmation::Unconfirmed;
        let has_complete_distillation = if source_excluded {
            distilled_fields.iter().all(|value| value.is_none())
        } else {
            distilled_fields.iter().all(|value| {
                value.is_some_and(|value| {
                    let value = value.trim();
                    !value.is_empty() && value.chars().count() <= 2_000
                })
            }) && causal_review.speaker_confirmation != CausalSpeakerConfirmation::Unconfirmed
        };
        let causal_provenance = (
            causal_review.review_id.as_deref(),
            causal_review.reviewed_at,
            causal_review.reviewer_id.as_deref(),
        );
        let has_complete_causal_provenance = matches!(
            causal_provenance,
            (Some(review_id), Some(reviewed_at), Some(reviewer))
                if !review_id.trim().is_empty()
                    && review_id.len() <= 240
                    && !review_id.contains(['/', '\\'])
                    && reviewed_at >= sample.observed_at
                    && !reviewer.trim().is_empty()
                    && reviewer.len() <= 128
        );
        let has_any_causal_provenance = causal_review.review_id.is_some()
            || causal_review.reviewed_at.is_some()
            || causal_review.reviewer_id.is_some();
        let reviewed_observation = sample.state.first_principles.as_ref().and_then(|model| {
            model
                .demand_drivers
                .iter()
                .chain(model.supply_drivers.iter())
                .chain(model.value_capture_drivers.iter())
                .find_map(|driver| {
                    (driver.driver_id == causal_review.driver_id)
                        .then(|| {
                            driver.observations.iter().find(|observation| {
                                observation.observation_id == causal_review.observation_id
                            })
                        })
                        .flatten()
                })
        });
        let accepts_inactive_claim = causal_review.verdict == CausalLinkVerdict::Accepted
            && reviewed_observation.is_some_and(|observation| {
                observation.claim.as_ref().is_some_and(|claim| {
                    claim.lifecycle_status != CausalClaimLifecycleStatus::Active
                        || !claim_is_promotion_eligible(claim)
                }) || observation.operating_kpi.as_ref().is_some_and(|claim| {
                    claim.lifecycle_status != CausalClaimLifecycleStatus::Active
                        || claim.disposition != EarningsClaimDisposition::Active
                })
            });
        let invalid_effect = causal_review.verdict == CausalLinkVerdict::Rejected
            && causal_review.effect != CausalEvidenceEffect::Unclassified;
        let invalid_source_exclusion = source_excluded
            && (causal_review.verdict != CausalLinkVerdict::Rejected
                || causal_review.effect != CausalEvidenceEffect::Unclassified);
        let invalid_identity_binding = causal_review.old_wang_reviewer_identity_verified
            && causal_review.speaker_confirmation
                != CausalSpeakerConfirmation::OldWangConfirmedAfterSourceCheck;
        let evidence_binding = (
            causal_review.evidence_identity_sha256.as_deref(),
            causal_review.source_review_id.as_deref(),
            causal_review.source_review_sample_id.as_deref(),
        );
        let has_any_evidence_binding = evidence_binding.0.is_some()
            || evidence_binding.1.is_some()
            || evidence_binding.2.is_some();
        let has_complete_evidence_binding = matches!(
            evidence_binding,
            (Some(identity), Some(source_review_id), Some(source_sample_id))
                if valid_sha256(identity)
                    && !source_review_id.trim().is_empty()
                    && source_review_id.len() <= 240
                    && !source_review_id.contains(['/', '\\'])
                    && valid_sample_id(source_sample_id)
                    && causal_evidence_identity(
                        sample,
                        &causal_review.driver_id,
                        &causal_review.observation_id,
                    )
                    .is_ok_and(|expected| expected == identity)
        );
        if causal_links.len() >= 50
            || causal_review.driver_id.trim().is_empty()
            || causal_review.observation_id.trim().is_empty()
            || explanation.is_empty()
            || explanation.chars().count() > 2_000
            || causal_links.contains(&key)
            || reviewed_observation.is_none()
            || accepts_inactive_claim
            || invalid_effect
            || invalid_source_exclusion
            || invalid_identity_binding
            || (has_any_evidence_binding && !has_complete_evidence_binding)
            || (has_any_distillation && !has_complete_distillation)
            || (has_any_causal_provenance && !has_complete_causal_provenance)
            || (!has_any_causal_provenance && review.reviewed_at.is_none())
        {
            return Err("human causal-link review is invalid".to_string());
        }
        causal_links.push(key);
    }
    match review.status {
        HumanReviewStatus::Pending => {
            if review.reviewed_at.is_some()
                || review.review_id.is_some()
                || review.reviewer_id.is_some()
                || review.correction_note.is_some()
                || review.thesis_verdict != ThesisReviewVerdict::Pending
                || review.corrected_zone.is_some()
                || review.corrected_action.is_some()
                || !review.error_attributions.is_empty()
                || review.causal_link_reviews.iter().any(|causal| {
                    causal.review_id.is_none()
                        || causal.reviewed_at.is_none()
                        || causal.reviewer_id.is_none()
                })
            {
                return Err("pending human review contains review output".to_string());
            }
        }
        HumanReviewStatus::Accepted => {
            if review.reviewed_at.is_none()
                || review.review_id.is_none()
                || review.reviewer_id.as_deref().unwrap_or("").is_empty()
                || review.thesis_verdict == ThesisReviewVerdict::Pending
                || review.correction_note.is_some()
                || review.corrected_zone.is_some()
                || review.corrected_action.is_some()
                || !review.error_attributions.is_empty()
            {
                return Err(
                    "accepted human review is incomplete or contains corrections".to_string(),
                );
            }
        }
        HumanReviewStatus::Rejected => {
            if review.reviewed_at.is_none()
                || review.review_id.is_none()
                || review.reviewer_id.as_deref().unwrap_or("").is_empty()
                || review.thesis_verdict != ThesisReviewVerdict::Invalidated
                || review.corrected_zone.is_some()
                || review.corrected_action.is_some()
                || review.error_attributions.is_empty()
            {
                return Err("rejected human review lacks invalidation evidence".to_string());
            }
        }
        HumanReviewStatus::Corrected => {
            if review.reviewed_at.is_none()
                || review.review_id.is_none()
                || review.reviewer_id.as_deref().unwrap_or("").is_empty()
                || review.thesis_verdict == ThesisReviewVerdict::Pending
                || review.correction_note.as_deref().unwrap_or("").is_empty()
                || (review.corrected_zone.is_none()
                    && review.corrected_action.is_none()
                    && review.error_attributions.is_empty())
            {
                return Err("corrected human review lacks provenance or correction".to_string());
            }
        }
    }
    let horizons = sample
        .outcomes
        .iter()
        .map(|outcome| outcome.horizon_market_sessions)
        .collect::<Vec<_>>();
    if horizons != [20, 60, 250] {
        return Err("training sample has an unsupported outcome horizon set".to_string());
    }
    for outcome in &sample.outcomes {
        let values = [
            outcome.asset_start_price,
            outcome.asset_end_price,
            outcome.asset_return_percent,
            outcome.benchmark_start_price,
            outcome.benchmark_end_price,
            outcome.benchmark_return_percent,
            outcome.excess_return_percent,
            outcome.max_drawdown_percent,
        ];
        match outcome.status {
            OutcomeStatus::PendingMarketSessions => {
                if outcome.period_start.is_some()
                    || outcome.period_end.is_some()
                    || outcome.market_sessions_observed.is_some()
                    || outcome.labelled_at.is_some()
                    || outcome.benchmark_symbol.is_some()
                    || outcome.market_data_source.is_some()
                    || outcome.invalid_reason.is_some()
                    || values.into_iter().any(|value| value.is_some())
                {
                    return Err("pending outcome contains future observations".to_string());
                }
            }
            OutcomeStatus::Observed => {
                let period_start = outcome
                    .period_start
                    .ok_or_else(|| "observed outcome is missing its start date".to_string())?;
                let period_end = outcome
                    .period_end
                    .ok_or_else(|| "observed outcome is missing its end date".to_string())?;
                let labelled_at = outcome
                    .labelled_at
                    .ok_or_else(|| "observed outcome is missing label time".to_string())?;
                if period_start < sample.state.decision_date_beijing
                    || period_end <= period_start
                    || outcome.market_sessions_observed != Some(outcome.horizon_market_sessions)
                    || labelled_at.with_timezone(&Shanghai).date_naive() < period_end
                    || outcome.benchmark_symbol.as_deref().unwrap_or("").is_empty()
                    || outcome
                        .market_data_source
                        .as_deref()
                        .unwrap_or("")
                        .is_empty()
                    || outcome.invalid_reason.is_some()
                    || values
                        .into_iter()
                        .any(|value| value.is_none_or(|value| !value.is_finite()))
                    || outcome.asset_start_price.is_some_and(|value| value <= 0.0)
                    || outcome.asset_end_price.is_some_and(|value| value <= 0.0)
                    || outcome
                        .benchmark_start_price
                        .is_some_and(|value| value <= 0.0)
                    || outcome
                        .benchmark_end_price
                        .is_some_and(|value| value <= 0.0)
                {
                    return Err(
                        "observed outcome is incomplete or leaks decision-date data".to_string()
                    );
                }
                let asset_start = outcome.asset_start_price.unwrap();
                let asset_end = outcome.asset_end_price.unwrap();
                let benchmark_start = outcome.benchmark_start_price.unwrap();
                let benchmark_end = outcome.benchmark_end_price.unwrap();
                let asset_return = outcome.asset_return_percent.unwrap();
                let benchmark_return = outcome.benchmark_return_percent.unwrap();
                let excess_return = outcome.excess_return_percent.unwrap();
                if (asset_return - percent_return(asset_start, asset_end)).abs() > 0.02
                    || (benchmark_return - percent_return(benchmark_start, benchmark_end)).abs()
                        > 0.02
                    || (excess_return - (asset_return - benchmark_return)).abs() > 0.02
                    || outcome.max_drawdown_percent.unwrap() > 0.0
                    || !outcome
                        .market_data_source
                        .as_deref()
                        .unwrap_or("")
                        .contains(OUTCOME_BENCHMARK_POLICY)
                {
                    return Err(
                        "observed outcome calculations or provenance are invalid".to_string()
                    );
                }
            }
            OutcomeStatus::Invalid => {
                if values.into_iter().any(|value| value.is_some())
                    || outcome.market_data_source.is_some()
                    || outcome.invalid_reason.as_deref().unwrap_or("").is_empty()
                {
                    return Err("invalid outcome must not carry performance values".to_string());
                }
            }
        }
    }
    match sample.reward.status {
        RewardStatus::Unconfigured => {
            if sample.reward.objective_version.is_some() || sample.reward.value.is_some() {
                return Err("unconfigured reward contains a value".to_string());
            }
        }
        RewardStatus::Computed => {
            if sample
                .reward
                .objective_version
                .as_deref()
                .unwrap_or("")
                .is_empty()
                || sample.reward.value.is_none_or(|value| !value.is_finite())
                || sample
                    .outcomes
                    .iter()
                    .any(|outcome| outcome.status != OutcomeStatus::Observed)
            {
                return Err("computed reward lacks an objective or complete outcomes".to_string());
            }
        }
    }
    Ok(())
}

async fn read_replay_samples(
    state: &AppState,
    symbol: &str,
    limit: usize,
) -> Result<Vec<DecisionTrainingSample>, String> {
    let directory = decision_root(state).join("training").join(symbol);
    read_replay_directory(&directory, symbol, limit, false).await
}

async fn read_all_training_samples(
    state: &AppState,
    symbol_filter: Option<&str>,
) -> Result<Vec<DecisionTrainingSample>, String> {
    if let Some(symbol) = symbol_filter {
        return read_replay_samples(state, symbol, MAX_REPLAY_LIMIT).await;
    }
    let root = decision_root(state).join("training");
    let mut directories = match tokio::fs::read_dir(&root).await {
        Ok(directories) => directories,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(error) => return Err(error.to_string()),
    };
    let mut samples = Vec::new();
    while let Some(entry) = directories
        .next_entry()
        .await
        .map_err(|error| error.to_string())?
    {
        if !entry
            .file_type()
            .await
            .map_err(|error| error.to_string())?
            .is_dir()
        {
            continue;
        }
        let symbol = entry.file_name().to_string_lossy().to_string();
        if !valid_symbol(&symbol) {
            return Err("training storage contains an invalid symbol directory".to_string());
        }
        samples
            .extend(read_replay_directory(&entry.path(), &symbol, MAX_REPLAY_LIMIT, true).await?);
    }
    samples.sort_by(|left, right| {
        left.observed_at
            .cmp(&right.observed_at)
            .then_with(|| left.sample_id.cmp(&right.sample_id))
    });
    Ok(samples)
}

fn build_evaluation_report(
    samples: &[DecisionTrainingSample],
    source_claims: &[EarningsSourceClaim],
    symbol_filter: Option<String>,
) -> DecisionEvaluationReport {
    let hari_logic_scenario_benchmark = hari_logic_scenario_benchmark();
    let first_principles_hypothesis_map = first_principles_hypothesis_map(samples);
    let mut review = ReviewEvaluation {
        pending: 0,
        accepted: 0,
        corrected: 0,
        rejected: 0,
        review_rate_percent: 0.0,
    };
    let mut errors: BTreeMap<DecisionErrorKind, (usize, usize)> = BTreeMap::new();
    let mut causal_review = CausalReviewEvaluation {
        available_links: 0,
        reviewed_links: 0,
        accepted_links: 0,
        rejected_links: 0,
        review_rate_percent: 0.0,
    };
    for sample in samples {
        match sample.human_review.status {
            HumanReviewStatus::Pending => review.pending += 1,
            HumanReviewStatus::Accepted => review.accepted += 1,
            HumanReviewStatus::Corrected => review.corrected += 1,
            HumanReviewStatus::Rejected => review.rejected += 1,
        }
        for error in &sample.human_review.error_attributions {
            let entry = errors.entry(error.kind.clone()).or_default();
            entry.0 += 1;
            if matches!(
                error.severity,
                ErrorSeverity::Material | ErrorSeverity::Critical
            ) {
                entry.1 += 1;
            }
        }
        causal_review.available_links += sample
            .state
            .first_principles
            .as_ref()
            .map(|model| {
                model
                    .demand_drivers
                    .iter()
                    .chain(model.supply_drivers.iter())
                    .chain(model.value_capture_drivers.iter())
                    .map(|driver| driver.observations.len())
                    .sum::<usize>()
            })
            .unwrap_or_default();
        for causal_link in &sample.human_review.causal_link_reviews {
            causal_review.reviewed_links += 1;
            match causal_link.verdict {
                CausalLinkVerdict::Accepted => causal_review.accepted_links += 1,
                CausalLinkVerdict::Rejected => causal_review.rejected_links += 1,
            }
        }
    }
    let reviewed = review.accepted + review.corrected + review.rejected;
    review.review_rate_percent = rate_percent(reviewed, samples.len());
    causal_review.review_rate_percent =
        rate_percent(causal_review.reviewed_links, causal_review.available_links);
    let causal_effects = causal_effect_evaluation(samples);
    let causal_training_dataset = causal_training_dataset_report(samples);
    let operating_kpi_review = operating_kpi_review_evaluation(samples);
    let computed_review = computed_review_evaluation(samples);
    let horizons = [20_u16, 60, 250]
        .into_iter()
        .map(|horizon| horizon_evaluation(samples, horizon))
        .collect::<Vec<_>>();
    let mut action_horizons = Vec::new();
    for action in [
        ExposureAction::IncreaseCandidate,
        ExposureAction::Maintain,
        ExposureAction::ReduceCandidate,
        ExposureAction::ResearchOnly,
    ] {
        for horizon in [20_u16, 60, 250] {
            action_horizons.push(action_horizon_evaluation(samples, action.clone(), horizon));
        }
    }
    let confidences = unique_strings(
        samples
            .iter()
            .map(|sample| sample.state.decision.confidence.clone())
            .collect(),
    );
    let mut confidence_horizons = Vec::new();
    for confidence in confidences {
        for horizon in [20_u16, 60, 250] {
            confidence_horizons.push(confidence_horizon_evaluation(samples, &confidence, horizon));
        }
    }
    let correction_comparisons = [20_u16, 60, 250]
        .into_iter()
        .map(|horizon| correction_comparison(samples, horizon))
        .collect::<Vec<_>>();
    let observed_250 = horizons
        .iter()
        .find(|item| item.horizon_market_sessions == 250)
        .map(|item| item.observed_count)
        .unwrap_or_default();
    let evidence_gate = offline_evidence_gate(samples, observed_250);
    let shadow_policy = shadow_policy_protocol(samples, &evidence_gate);
    let reward_design = reward_design_proposal(&evidence_gate);
    let claim_corpus = claim_corpus_evaluation(samples, source_claims);
    DecisionEvaluationReport {
        schema_version: EVALUATION_SCHEMA_VERSION.to_string(),
        generated_at: Utc::now(),
        symbol_filter,
        reward_status: RewardStatus::Unconfigured,
        sample_count: samples.len(),
        hari_logic_scenario_benchmark,
        empirical_validation_readiness: None,
        first_principles_hypothesis_map,
        review,
        causal_review,
        causal_effects,
        causal_training_dataset,
        operating_kpi_review,
        computed_review,
        claim_corpus,
        errors: errors
            .into_iter()
            .map(
                |(kind, (count, material_or_critical_count))| ErrorEvaluation {
                    kind,
                    count,
                    material_or_critical_count,
                },
            )
            .collect(),
        horizons,
        action_horizons,
        confidence_horizons,
        correction_comparisons,
        evidence_gate,
        shadow_policy,
        reward_design,
    }
}

#[derive(Default)]
struct FirstPrinciplesHypothesisAccumulator {
    latest_decision_at: Option<DateTime<Utc>>,
    symbols: BTreeSet<String>,
    demand_traceable_company_count: usize,
    supply_traceable_company_count: usize,
    value_capture_traceable_company_count: usize,
    fully_traceable_company_count: usize,
    demand_measured_company_count: usize,
    supply_measured_company_count: usize,
    value_capture_measured_company_count: usize,
    fully_measured_company_count: usize,
    evidence_pathway: FirstPrinciplesEvidencePathwayCounts,
    unique_observation_keys: BTreeSet<String>,
    promoted_driver_count: usize,
    blocked_conflict_driver_count: usize,
    blocked_rejection_driver_count: usize,
    blocked_falsification_driver_count: usize,
}

fn first_principles_measurement_backlog(
    samples: &[DecisionTrainingSample],
) -> FirstPrinciplesMeasurementBacklog {
    let review_indexes = causal_promotion_review_indexes(samples);
    let mut latest_by_symbol = BTreeMap::<String, &DecisionTrainingSample>::new();
    for sample in samples {
        let symbol = sample.state.symbol.trim().to_ascii_uppercase();
        if symbol.is_empty() {
            continue;
        }
        let replace = latest_by_symbol.get(&symbol).is_none_or(|current| {
            sample.observed_at > current.observed_at
                || (sample.observed_at == current.observed_at
                    && sample.sample_id > current.sample_id)
        });
        if replace {
            latest_by_symbol.insert(symbol, sample);
        }
    }

    let mut total_driver_count = 0;
    let mut measured_driver_count = 0;
    let mut ready_for_review_count = 0;
    let mut rejected_needs_new_evidence_count = 0;
    let mut metricization_required_count = 0;
    let mut operating_kpi_required_count = 0;
    let mut no_traceable_evidence_count = 0;
    let mut items = Vec::new();

    for (symbol, sample) in latest_by_symbol {
        let Some(model) = &sample.state.first_principles else {
            continue;
        };
        let review_index = review_indexes.get(&symbol);
        for (drivers, family) in [
            (&model.demand_drivers, "demand"),
            (&model.supply_drivers, "supply"),
            (&model.value_capture_drivers, "value_capture"),
        ] {
            for driver in drivers {
                total_driver_count += 1;
                let mut review_candidate_count = 0;
                let mut pending_review_candidate_count = 0;
                let mut admitted_candidate_count = 0;
                let mut rejected_candidate_count = 0;
                let mut structured_claim_count = 0;
                let mut context_count = 0;
                let source_measured = driver
                    .observations
                    .iter()
                    .any(observation_is_source_measurement);
                for observation in &driver.observations {
                    structured_claim_count += usize::from(
                        observation.relationship
                            == CausalObservationRelationship::StructuredSourceClaim,
                    );
                    context_count += usize::from(
                        observation.relationship == CausalObservationRelationship::ConfirmedContext,
                    );
                    if !observation_is_measurement_review_candidate(observation) {
                        continue;
                    }
                    review_candidate_count += 1;
                    let review = review_index.and_then(|index| {
                        index
                            .verdicts
                            .get(&(driver.driver_id.clone(), observation.observation_id.clone()))
                    });
                    match review {
                        Some(review)
                            if review.verdict == CausalLinkVerdict::Accepted
                                && review.speaker_confirmation
                                    == CausalSpeakerConfirmation::OldWangConfirmedAfterSourceCheck
                                && review.old_wang_reviewer_identity_verified
                                && matches!(
                                    review.effect,
                                    CausalEvidenceEffect::Supports
                                        | CausalEvidenceEffect::Falsifies
                                ) =>
                        {
                            admitted_candidate_count += 1;
                        }
                        Some(review)
                            if review.verdict == CausalLinkVerdict::Accepted
                                && matches!(
                                    review.effect,
                                    CausalEvidenceEffect::Supports
                                        | CausalEvidenceEffect::Falsifies
                                ) =>
                        {
                            pending_review_candidate_count += 1;
                        }
                        Some(_) => rejected_candidate_count += 1,
                        None => pending_review_candidate_count += 1,
                    }
                }
                let measured = driver.measurement_status != MeasurementStatus::Unmeasured
                    || source_measured
                    || admitted_candidate_count > 0;
                if measured {
                    measured_driver_count += 1;
                    continue;
                }

                let (status, next_check) = if pending_review_candidate_count > 0 {
                    ready_for_review_count += 1;
                    (
                        "ready_for_measurement_review",
                        "复核已由同口径一手事实确定性计算的同比、环比或利润率；只有老王本人确认关系成立且明确支持或证伪该驱动，才进入部分量化层。".to_string(),
                    )
                } else if review_candidate_count > 0 && rejected_candidate_count > 0 {
                    rejected_needs_new_evidence_count += 1;
                    (
                        "review_rejected_needs_new_evidence",
                        "已有计算证据被拒绝、仅作背景或关系复杂；保留审计记录，并寻找新的同口径指标或公司经营 KPI。".to_string(),
                    )
                } else if structured_claim_count > 0 {
                    metricization_required_count += 1;
                    (
                        "source_claims_need_metricization",
                        "把管理层表述落到同定义、同期间、带数值的一手指标；优先匹配经营 KPI 注册表，不能把文字判断直接当作测量。".to_string(),
                    )
                } else if context_count > 0 {
                    operating_kpi_required_count += 1;
                    (
                        "context_needs_operating_kpi",
                        "补公司原始经营口径或可复算的一手财务指标，明确分母、期间、产品边界和来源定位。".to_string(),
                    )
                } else {
                    no_traceable_evidence_count += 1;
                    (
                        "no_traceable_evidence",
                        "从 SEC、公司 IR、财报电话会或客户一手披露采集该驱动所需观察，缺失保持缺失。".to_string(),
                    )
                };
                items.push(FirstPrinciplesMeasurementBacklogItem {
                    symbol: symbol.clone(),
                    company_name: sample.state.company_name.clone(),
                    sample_id: sample.sample_id.clone(),
                    decision_at: sample.state.decision_at,
                    model_id: model.model_id.clone(),
                    driver_family: family.to_string(),
                    driver_id: driver.driver_id.clone(),
                    driver_label: driver.label.clone(),
                    status: status.to_string(),
                    measurement_status: MeasurementStatus::Unmeasured,
                    traceable_observation_count: driver.observations.len(),
                    review_candidate_count,
                    pending_review_candidate_count,
                    admitted_candidate_count,
                    rejected_candidate_count,
                    required_observations: driver.required_observations.clone(),
                    target_operating_kpi_ids: model
                        .operating_kpi_registry
                        .entries
                        .iter()
                        .filter(|entry| entry.driver_id == driver.driver_id)
                        .map(|entry| entry.kpi_id.clone())
                        .collect(),
                    next_check,
                });
            }
        }
    }
    items.sort_by(|left, right| {
        measurement_backlog_status_rank(&left.status)
            .cmp(&measurement_backlog_status_rank(&right.status))
            .then_with(|| {
                right
                    .pending_review_candidate_count
                    .cmp(&left.pending_review_candidate_count)
            })
            .then_with(|| left.model_id.cmp(&right.model_id))
            .then_with(|| left.symbol.cmp(&right.symbol))
            .then_with(|| left.driver_family.cmp(&right.driver_family))
            .then_with(|| left.driver_id.cmp(&right.driver_id))
    });
    let status = if total_driver_count == 0 {
        "empty"
    } else if items.is_empty() {
        "measured"
    } else if ready_for_review_count > 0 {
        "review_ready"
    } else {
        "evidence_acquisition_required"
    };
    FirstPrinciplesMeasurementBacklog {
        policy_version: FIRST_PRINCIPLES_MEASUREMENT_BACKLOG_POLICY_VERSION.to_string(),
        status: status.to_string(),
        total_driver_count,
        measured_driver_count,
        ready_for_review_count,
        rejected_needs_new_evidence_count,
        metricization_required_count,
        operating_kpi_required_count,
        no_traceable_evidence_count,
        items,
        investment_ranking_enabled: false,
        action_authorized: false,
        scope: "待办只按量化复核准备度和稳定标识排序；接受的确定性计算只把对应驱动标为部分量化，不代表因果成立、投资机会、仓位建议或交易授权。".to_string(),
    }
}

fn measurement_backlog_status_rank(status: &str) -> u8 {
    match status {
        "ready_for_measurement_review" => 0,
        "review_rejected_needs_new_evidence" => 1,
        "source_claims_need_metricization" => 2,
        "context_needs_operating_kpi" => 3,
        _ => 4,
    }
}

fn first_principles_hypothesis_map(
    samples: &[DecisionTrainingSample],
) -> FirstPrinciplesHypothesisMap {
    let measurement_backlog = first_principles_measurement_backlog(samples);
    let mut latest_by_symbol = BTreeMap::<String, &DecisionTrainingSample>::new();
    for sample in samples {
        let symbol = sample.state.symbol.trim().to_ascii_uppercase();
        if symbol.is_empty() {
            continue;
        }
        let replace = latest_by_symbol.get(&symbol).is_none_or(|current| {
            sample.observed_at > current.observed_at
                || (sample.observed_at == current.observed_at
                    && sample.sample_id > current.sample_id)
        });
        if replace {
            latest_by_symbol.insert(symbol, sample);
        }
    }

    let mut grouped = BTreeMap::<(String, String), FirstPrinciplesHypothesisAccumulator>::new();
    let mut source_sample_ids = Vec::new();
    let mut latest_decision_at = None;
    for (symbol, sample) in latest_by_symbol {
        let Some(model) = &sample.state.first_principles else {
            continue;
        };
        source_sample_ids.push(sample.sample_id.clone());
        latest_decision_at = Some(
            latest_decision_at.map_or(sample.observed_at, |current: DateTime<Utc>| {
                current.max(sample.observed_at)
            }),
        );
        let accumulator = grouped
            .entry((model.model_id.clone(), model.version.clone()))
            .or_default();
        accumulator.latest_decision_at = Some(
            accumulator
                .latest_decision_at
                .map_or(sample.observed_at, |current| {
                    current.max(sample.observed_at)
                }),
        );
        accumulator.symbols.insert(symbol.clone());

        let demand_traceable = driver_family_has_traceable_evidence(&model.demand_drivers);
        let supply_traceable = driver_family_has_traceable_evidence(&model.supply_drivers);
        let value_capture_traceable =
            driver_family_has_traceable_evidence(&model.value_capture_drivers);
        let demand_measured = driver_family_has_measurement(&model.demand_drivers);
        let supply_measured = driver_family_has_measurement(&model.supply_drivers);
        let value_capture_measured = driver_family_has_measurement(&model.value_capture_drivers);
        accumulator.demand_traceable_company_count += usize::from(demand_traceable);
        accumulator.supply_traceable_company_count += usize::from(supply_traceable);
        accumulator.value_capture_traceable_company_count += usize::from(value_capture_traceable);
        accumulator.fully_traceable_company_count +=
            usize::from(demand_traceable && supply_traceable && value_capture_traceable);
        accumulator.demand_measured_company_count += usize::from(demand_measured);
        accumulator.supply_measured_company_count += usize::from(supply_measured);
        accumulator.value_capture_measured_company_count += usize::from(value_capture_measured);
        accumulator.fully_measured_company_count +=
            usize::from(demand_measured && supply_measured && value_capture_measured);

        for driver in model
            .demand_drivers
            .iter()
            .chain(model.supply_drivers.iter())
            .chain(model.value_capture_drivers.iter())
        {
            for observation in &driver.observations {
                let observation_key = format!("{symbol}\0{}", observation.observation_id);
                if accumulator.unique_observation_keys.insert(observation_key) {
                    accumulator.evidence_pathway.unique_observation_count += 1;
                    match observation.relationship {
                        CausalObservationRelationship::DirectMetric => {
                            accumulator.evidence_pathway.direct_metric_count += 1;
                        }
                        CausalObservationRelationship::Proxy => {
                            accumulator.evidence_pathway.proxy_count += 1;
                        }
                        CausalObservationRelationship::ConfirmedContext => {
                            accumulator.evidence_pathway.confirmed_context_count += 1;
                        }
                        CausalObservationRelationship::StructuredSourceClaim => {
                            accumulator.evidence_pathway.structured_source_claim_count += 1;
                        }
                        CausalObservationRelationship::ComputedComparison => {
                            accumulator.evidence_pathway.computed_comparison_count += 1;
                        }
                        CausalObservationRelationship::ComputedRatio => {
                            accumulator.evidence_pathway.computed_ratio_count += 1;
                        }
                        CausalObservationRelationship::ComputedRatioTrend => {
                            accumulator.evidence_pathway.computed_ratio_trend_count += 1;
                        }
                        CausalObservationRelationship::OperatingKpiClaim => {
                            accumulator.evidence_pathway.operating_kpi_claim_count += 1;
                        }
                    }
                }
            }
            match driver.promotion.status {
                CausalPromotionStatus::PromotedConfidenceOnly => {
                    accumulator.promoted_driver_count += 1;
                }
                CausalPromotionStatus::BlockedConflict => {
                    accumulator.blocked_conflict_driver_count += 1;
                }
                CausalPromotionStatus::BlockedHumanRejection => {
                    accumulator.blocked_rejection_driver_count += 1;
                }
                CausalPromotionStatus::BlockedFalsification => {
                    accumulator.blocked_falsification_driver_count += 1;
                }
                _ => {}
            }
        }
    }
    source_sample_ids.sort();

    let mut models = grouped
        .into_iter()
        .map(|((model_id, model_version), accumulator)| {
            let symbols = accumulator.symbols.into_iter().collect::<Vec<_>>();
            let company_count = symbols.len();
            let mut missing_checks = Vec::new();
            if accumulator.demand_traceable_company_count < company_count {
                missing_checks.push(format!(
                    "{} 家公司的需求侧尚无可追溯点时证据",
                    company_count - accumulator.demand_traceable_company_count
                ));
            }
            if accumulator.supply_traceable_company_count < company_count {
                missing_checks.push(format!(
                    "{} 家公司的供给侧尚无可追溯点时证据",
                    company_count - accumulator.supply_traceable_company_count
                ));
            }
            if accumulator.value_capture_traceable_company_count < company_count {
                missing_checks.push(format!(
                    "{} 家公司的价值捕获尚无可追溯点时证据",
                    company_count - accumulator.value_capture_traceable_company_count
                ));
            }
            if accumulator.demand_traceable_company_count
                > accumulator.demand_measured_company_count
            {
                missing_checks.push(format!(
                    "{} 家公司的需求证据可追溯但尚未进入严格量化层",
                    accumulator.demand_traceable_company_count
                        - accumulator.demand_measured_company_count
                ));
            }
            if accumulator.supply_traceable_company_count
                > accumulator.supply_measured_company_count
            {
                missing_checks.push(format!(
                    "{} 家公司的供给证据可追溯但尚未进入严格量化层",
                    accumulator.supply_traceable_company_count
                        - accumulator.supply_measured_company_count
                ));
            }
            if accumulator.value_capture_traceable_company_count
                > accumulator.value_capture_measured_company_count
            {
                missing_checks.push(format!(
                    "{} 家公司的价值捕获证据可追溯但尚未进入严格量化层",
                    accumulator.value_capture_traceable_company_count
                        - accumulator.value_capture_measured_company_count
                ));
            }
            if accumulator.promoted_driver_count == 0 {
                missing_checks.push("尚无通过老王确认和跨期重复证据门槛的支持驱动".to_string());
            }
            if accumulator.blocked_conflict_driver_count > 0 {
                missing_checks.push(format!(
                    "{} 个驱动存在未解决的一手证据冲突",
                    accumulator.blocked_conflict_driver_count
                ));
            }
            if accumulator.blocked_rejection_driver_count > 0 {
                missing_checks.push(format!(
                    "{} 个驱动被人工否决",
                    accumulator.blocked_rejection_driver_count
                ));
            }
            if accumulator.blocked_falsification_driver_count > 0 {
                missing_checks.push(format!(
                    "{} 个驱动已有人工确认的证伪证据",
                    accumulator.blocked_falsification_driver_count
                ));
            }
            let state = if accumulator.blocked_falsification_driver_count > 0 {
                "falsification_blocked"
            } else if accumulator.blocked_conflict_driver_count > 0
                || accumulator.blocked_rejection_driver_count > 0
            {
                "contested"
            } else if accumulator.promoted_driver_count > 0 {
                "partially_human_supported"
            } else if accumulator.fully_measured_company_count > 0 {
                "reality_measured_unreviewed"
            } else if accumulator.demand_measured_company_count > 0
                || accumulator.supply_measured_company_count > 0
                || accumulator.value_capture_measured_company_count > 0
            {
                "measurement_partial"
            } else if accumulator.fully_traceable_company_count > 0 {
                "traceable_evidence_unmeasured"
            } else if accumulator.demand_traceable_company_count > 0
                || accumulator.supply_traceable_company_count > 0
                || accumulator.value_capture_traceable_company_count > 0
            {
                "traceable_evidence_partial"
            } else {
                "structure_only"
            };
            FirstPrinciplesHypothesisModel {
                model_id,
                model_version,
                state: state.to_string(),
                latest_decision_at: accumulator
                    .latest_decision_at
                    .expect("hypothesis group has a source sample"),
                company_count,
                symbols,
                demand_traceable_company_count: accumulator.demand_traceable_company_count,
                supply_traceable_company_count: accumulator.supply_traceable_company_count,
                value_capture_traceable_company_count: accumulator
                    .value_capture_traceable_company_count,
                fully_traceable_company_count: accumulator.fully_traceable_company_count,
                demand_measured_company_count: accumulator.demand_measured_company_count,
                supply_measured_company_count: accumulator.supply_measured_company_count,
                value_capture_measured_company_count: accumulator
                    .value_capture_measured_company_count,
                fully_measured_company_count: accumulator.fully_measured_company_count,
                evidence_pathway: accumulator.evidence_pathway,
                promoted_driver_count: accumulator.promoted_driver_count,
                blocked_conflict_driver_count: accumulator.blocked_conflict_driver_count,
                blocked_rejection_driver_count: accumulator.blocked_rejection_driver_count,
                blocked_falsification_driver_count: accumulator
                    .blocked_falsification_driver_count,
                missing_checks,
                interpretation: "可追溯层包含一手上下文、结构化来源和确定性计算；量化层只接纳直接指标、代理指标或有效 KPI。两层都不等于假设已验证。".to_string(),
            }
        })
        .collect::<Vec<_>>();
    models.sort_by(|left, right| {
        left.model_id
            .cmp(&right.model_id)
            .then_with(|| left.model_version.cmp(&right.model_version))
    });

    let status = if models.is_empty() {
        "empty"
    } else if models
        .iter()
        .any(|model| model.blocked_falsification_driver_count > 0)
    {
        "falsification_present"
    } else if models.iter().any(|model| {
        model.blocked_conflict_driver_count > 0 || model.blocked_rejection_driver_count > 0
    }) {
        "contested"
    } else if models.iter().any(|model| model.promoted_driver_count > 0) {
        "human_support_partial"
    } else {
        "awaiting_human_causal_review"
    };
    let company_count = models.iter().map(|model| model.company_count).sum();
    let mut map = FirstPrinciplesHypothesisMap {
        policy_version: FIRST_PRINCIPLES_HYPOTHESIS_MAP_POLICY_VERSION.to_string(),
        status: status.to_string(),
        latest_decision_at,
        map_fingerprint_sha256: String::new(),
        model_count: models.len(),
        company_count,
        source_sample_ids,
        models,
        measurement_backlog,
        opportunity_ranking_enabled: false,
        action_authorized: false,
        scope: "产业假设地图只聚合每家公司最新的点时决策，分开展示可追溯证据与严格量化证据，并保留证伪状态；它不是行业机会排名、收益预测、仓位建议或交易授权。".to_string(),
    };
    map.map_fingerprint_sha256 = first_principles_hypothesis_map_sha256(&map);
    debug_assert!(validate_first_principles_hypothesis_map(&map).is_ok());
    map
}

fn driver_family_has_measurement(drivers: &[ModelDriver]) -> bool {
    drivers.iter().any(|driver| {
        driver.measurement_status != MeasurementStatus::Unmeasured
            && !driver.observations.is_empty()
    })
}

fn driver_family_has_traceable_evidence(drivers: &[ModelDriver]) -> bool {
    drivers.iter().any(|driver| !driver.observations.is_empty())
}

fn first_principles_hypothesis_map_sha256(map: &FirstPrinciplesHypothesisMap) -> String {
    let payload = serde_json::json!({
        "policy_version": map.policy_version,
        "status": map.status,
        "latest_decision_at": map.latest_decision_at,
        "model_count": map.model_count,
        "company_count": map.company_count,
        "source_sample_ids": map.source_sample_ids,
        "models": map.models,
        "measurement_backlog": map.measurement_backlog,
        "opportunity_ranking_enabled": map.opportunity_ranking_enabled,
        "action_authorized": map.action_authorized,
        "scope": map.scope,
    });
    format!(
        "{:x}",
        Sha256::digest(serde_json::to_vec(&payload).expect("hypothesis map serializes"))
    )
}

fn validate_first_principles_hypothesis_map(
    map: &FirstPrinciplesHypothesisMap,
) -> Result<(), String> {
    if map.policy_version != FIRST_PRINCIPLES_HYPOTHESIS_MAP_POLICY_VERSION
        || map.opportunity_ranking_enabled
        || map.action_authorized
        || map.measurement_backlog.investment_ranking_enabled
        || map.measurement_backlog.action_authorized
        || map.measurement_backlog.policy_version
            != FIRST_PRINCIPLES_MEASUREMENT_BACKLOG_POLICY_VERSION
        || map.model_count != map.models.len()
        || map.company_count
            != map
                .models
                .iter()
                .map(|model| model.company_count)
                .sum::<usize>()
        || map.source_sample_ids.len() != map.company_count
        || map.map_fingerprint_sha256.len() != 64
        || map.map_fingerprint_sha256 != first_principles_hypothesis_map_sha256(map)
    {
        return Err("first-principles hypothesis map contract is invalid".to_string());
    }
    let backlog = &map.measurement_backlog;
    let unresolved_count = backlog.ready_for_review_count
        + backlog.rejected_needs_new_evidence_count
        + backlog.metricization_required_count
        + backlog.operating_kpi_required_count
        + backlog.no_traceable_evidence_count;
    if backlog.total_driver_count != backlog.measured_driver_count + unresolved_count
        || unresolved_count != backlog.items.len()
        || backlog.items.iter().any(|item| {
            item.symbol.trim().is_empty()
                || item.model_id.trim().is_empty()
                || item.driver_id.trim().is_empty()
                || item.measurement_status != MeasurementStatus::Unmeasured
                || item.admitted_candidate_count > item.review_candidate_count
                || item.pending_review_candidate_count > item.review_candidate_count
                || item.rejected_candidate_count > item.review_candidate_count
                || item.admitted_candidate_count
                    + item.pending_review_candidate_count
                    + item.rejected_candidate_count
                    != item.review_candidate_count
                || item
                    .target_operating_kpi_ids
                    .iter()
                    .any(|kpi_id| kpi_id.trim().is_empty())
                || item
                    .target_operating_kpi_ids
                    .iter()
                    .collect::<BTreeSet<_>>()
                    .len()
                    != item.target_operating_kpi_ids.len()
        })
    {
        return Err("first-principles measurement backlog contract is invalid".to_string());
    }
    let mut symbols = BTreeSet::new();
    let mut sample_ids = BTreeSet::new();
    for sample_id in &map.source_sample_ids {
        if sample_id.trim().is_empty() || !sample_ids.insert(sample_id) {
            return Err("first-principles hypothesis map sources are invalid".to_string());
        }
    }
    for model in &map.models {
        let pathway_total = model.evidence_pathway.direct_metric_count
            + model.evidence_pathway.proxy_count
            + model.evidence_pathway.confirmed_context_count
            + model.evidence_pathway.structured_source_claim_count
            + model.evidence_pathway.computed_comparison_count
            + model.evidence_pathway.computed_ratio_count
            + model.evidence_pathway.computed_ratio_trend_count
            + model.evidence_pathway.operating_kpi_claim_count;
        if model.company_count != model.symbols.len()
            || model.demand_traceable_company_count > model.company_count
            || model.supply_traceable_company_count > model.company_count
            || model.value_capture_traceable_company_count > model.company_count
            || model.fully_traceable_company_count > model.company_count
            || model.demand_measured_company_count > model.demand_traceable_company_count
            || model.supply_measured_company_count > model.supply_traceable_company_count
            || model.value_capture_measured_company_count
                > model.value_capture_traceable_company_count
            || model.fully_measured_company_count > model.fully_traceable_company_count
            || pathway_total != model.evidence_pathway.unique_observation_count
            || model.model_id.trim().is_empty()
            || model.model_version.trim().is_empty()
            || model.symbols.iter().any(|symbol| !symbols.insert(symbol))
        {
            return Err("first-principles hypothesis model counts are invalid".to_string());
        }
    }
    Ok(())
}

fn operating_kpi_review_evaluation(
    samples: &[DecisionTrainingSample],
) -> OperatingKpiReviewEvaluation {
    type ClaimKey = (String, String);
    let mut available =
        BTreeMap::<ClaimKey, (DateTime<Utc>, String, CausalOperatingKpiProvenance)>::new();
    for sample in samples {
        let Some(model) = &sample.state.first_principles else {
            continue;
        };
        for driver in model
            .demand_drivers
            .iter()
            .chain(model.supply_drivers.iter())
            .chain(model.value_capture_drivers.iter())
        {
            for observation in &driver.observations {
                if observation.relationship != CausalObservationRelationship::OperatingKpiClaim {
                    continue;
                }
                let Some(claim) = &observation.operating_kpi else {
                    continue;
                };
                let key = (
                    sample.state.symbol.clone(),
                    observation.observation_id.clone(),
                );
                if available
                    .get(&key)
                    .is_none_or(|(previous_at, _, _)| *previous_at <= sample.observed_at)
                {
                    available.insert(
                        key,
                        (sample.observed_at, driver.driver_id.clone(), claim.clone()),
                    );
                }
            }
        }
    }

    let mut reviewed = BTreeMap::<ClaimKey, (DateTime<Utc>, CausalLinkVerdict)>::new();
    for sample in samples {
        for review in &sample.human_review.causal_link_reviews {
            let Some(reviewed_at) = causal_review_timestamp(sample, review) else {
                continue;
            };
            if causal_source_verification_from_confirmation(&review.speaker_confirmation)
                != CausalSourceVerification::VerifiedAgainstSource
                || !review.old_wang_reviewer_identity_verified
            {
                continue;
            }
            let key = (sample.state.symbol.clone(), review.observation_id.clone());
            if available
                .get(&key)
                .is_some_and(|(_, current_driver_id, _)| current_driver_id == &review.driver_id)
                && reviewed
                    .get(&key)
                    .is_none_or(|(previous_at, _)| *previous_at <= reviewed_at)
            {
                reviewed.insert(key, (reviewed_at, review.verdict.clone()));
            }
        }
    }

    let claims = available
        .values()
        .map(|(_, _, claim)| claim)
        .collect::<Vec<_>>();
    let lifecycle_count = |status: CausalClaimLifecycleStatus| {
        claims
            .iter()
            .filter(|claim| claim.lifecycle_status == status)
            .count()
    };
    let distinct_symbols = available
        .keys()
        .map(|(symbol, _)| symbol.clone())
        .collect::<BTreeSet<_>>()
        .len();
    let distinct_kpis = claims
        .iter()
        .map(|claim| claim.kpi_id.clone())
        .collect::<BTreeSet<_>>()
        .len();
    let distinct_definitions = claims
        .iter()
        .map(|claim| claim.definition_key.clone())
        .collect::<BTreeSet<_>>()
        .len();
    let accepted_claims = reviewed
        .values()
        .filter(|(_, verdict)| *verdict == CausalLinkVerdict::Accepted)
        .count();
    let rejected_claims = reviewed
        .values()
        .filter(|(_, verdict)| *verdict == CausalLinkVerdict::Rejected)
        .count();

    OperatingKpiReviewEvaluation {
        available_claims: available.len(),
        active_claims: lifecycle_count(CausalClaimLifecycleStatus::Active),
        superseded_claims: lifecycle_count(CausalClaimLifecycleStatus::Superseded),
        conflicted_claims: lifecycle_count(CausalClaimLifecycleStatus::Conflicted),
        withdrawn_claims: lifecycle_count(CausalClaimLifecycleStatus::Withdrawn),
        definition_change_claims: claims
            .iter()
            .filter(|claim| claim.definition_changed)
            .count(),
        distinct_symbols,
        distinct_kpis,
        distinct_definitions,
        reviewed_claims: reviewed.len(),
        accepted_claims,
        rejected_claims,
        review_rate_percent: rate_percent(reviewed.len(), available.len()),
    }
}

#[derive(Debug, Clone)]
struct CausalEffectCandidate {
    driver_id: String,
    driver_label: String,
    metric_id: Option<String>,
    market_regime: Option<String>,
}

#[derive(Debug, Clone)]
struct CausalEffectVerdictAt {
    verdict: CausalLinkVerdict,
    effect: CausalEvidenceEffect,
    reviewed_at: DateTime<Utc>,
}

#[derive(Debug, Default)]
struct CausalEffectCounts {
    available: usize,
    reviewed: usize,
    accepted: usize,
    rejected: usize,
    unclassified_accepted: usize,
    supports: usize,
    falsifies: usize,
    mixed: usize,
    context_only: usize,
}

impl CausalEffectCounts {
    fn record_review(&mut self, review: &CausalEffectVerdictAt) {
        self.reviewed += 1;
        match review.verdict {
            CausalLinkVerdict::Rejected => self.rejected += 1,
            CausalLinkVerdict::Accepted => {
                self.accepted += 1;
                match review.effect {
                    CausalEvidenceEffect::Unclassified => self.unclassified_accepted += 1,
                    CausalEvidenceEffect::Supports => self.supports += 1,
                    CausalEvidenceEffect::Falsifies => self.falsifies += 1,
                    CausalEvidenceEffect::Mixed => self.mixed += 1,
                    CausalEvidenceEffect::ContextOnly => self.context_only += 1,
                }
            }
        }
    }

    fn classified_accepted(&self) -> usize {
        self.supports + self.falsifies + self.mixed + self.context_only
    }
}

fn causal_dataset_component_split(component_symbols: &[String]) -> CausalDatasetSplit {
    let component_key = component_symbols.join("\u{001f}");
    let digest = Sha256::digest(format!(
        "{CAUSAL_TRAINING_DATASET_POLICY_VERSION}:company-source-component:{component_key}"
    ));
    let bucket = u16::from_be_bytes([digest[0], digest[1]]) % 100;
    match bucket {
        0..=69 => CausalDatasetSplit::Train,
        70..=84 => CausalDatasetSplit::Validation,
        _ => CausalDatasetSplit::HoldoutTest,
    }
}

#[derive(Debug, Default, PartialEq, Eq)]
struct CausalDatasetSplitAudit {
    connected_component_count: usize,
    shared_source_group_count: usize,
    largest_component_symbol_count: usize,
    company_split_isolation_verified: bool,
    source_group_split_isolation_verified: bool,
}

fn causal_union_find_root(parents: &mut [usize], mut index: usize) -> usize {
    while parents[index] != index {
        parents[index] = parents[parents[index]];
        index = parents[index];
    }
    index
}

fn causal_union_find_merge(parents: &mut [usize], left: usize, right: usize) {
    let left_root = causal_union_find_root(parents, left);
    let right_root = causal_union_find_root(parents, right);
    if left_root == right_root {
        return;
    }
    let (root, child) = if left_root < right_root {
        (left_root, right_root)
    } else {
        (right_root, left_root)
    };
    parents[child] = root;
}

/// Assigns an indivisible split to every connected component in the bipartite
/// graph of companies and source events. This is deliberately stricter than
/// hashing companies independently: if one SEC filing, transcript, industry
/// milestone or computed claim group is reused by multiple companies, every
/// affected company stays on the same side of the train/holdout boundary.
fn assign_causal_dataset_component_splits(
    examples: &mut [CausalTrainingExample],
) -> CausalDatasetSplitAudit {
    let symbols = examples
        .iter()
        .map(|example| example.symbol.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    if symbols.is_empty() {
        return CausalDatasetSplitAudit {
            company_split_isolation_verified: true,
            source_group_split_isolation_verified: true,
            ..CausalDatasetSplitAudit::default()
        };
    }
    let symbol_indexes = symbols
        .iter()
        .enumerate()
        .map(|(index, symbol)| (symbol.clone(), index))
        .collect::<BTreeMap<_, _>>();
    let mut parents = (0..symbols.len()).collect::<Vec<_>>();
    let mut source_symbols = BTreeMap::<String, BTreeSet<String>>::new();
    for example in examples.iter() {
        for identity in &example.source_identity_keys {
            source_symbols
                .entry(identity.clone())
                .or_default()
                .insert(example.symbol.clone());
        }
    }
    for group_symbols in source_symbols.values() {
        let mut indexes = group_symbols
            .iter()
            .filter_map(|symbol| symbol_indexes.get(symbol).copied());
        let Some(first) = indexes.next() else {
            continue;
        };
        for index in indexes {
            causal_union_find_merge(&mut parents, first, index);
        }
    }
    let mut components = BTreeMap::<usize, Vec<String>>::new();
    for (index, symbol) in symbols.iter().enumerate() {
        let root = causal_union_find_root(&mut parents, index);
        components.entry(root).or_default().push(symbol.clone());
    }
    let mut split_by_symbol = BTreeMap::new();
    for component_symbols in components.values_mut() {
        component_symbols.sort();
        let split = causal_dataset_component_split(component_symbols);
        for symbol in component_symbols.iter() {
            split_by_symbol.insert(symbol.clone(), split.clone());
        }
    }
    for example in examples.iter_mut() {
        example.split = split_by_symbol
            .get(&example.symbol)
            .expect("every causal example symbol belongs to a component")
            .clone();
    }
    let company_splits = examples.iter().fold(
        BTreeMap::<String, BTreeSet<CausalDatasetSplit>>::new(),
        |mut groups, example| {
            groups
                .entry(example.symbol.clone())
                .or_default()
                .insert(example.split.clone());
            groups
        },
    );
    let source_group_splits = examples.iter().fold(
        BTreeMap::<String, BTreeSet<CausalDatasetSplit>>::new(),
        |mut groups, example| {
            for identity in &example.source_identity_keys {
                groups
                    .entry(identity.clone())
                    .or_default()
                    .insert(example.split.clone());
            }
            groups
        },
    );
    CausalDatasetSplitAudit {
        connected_component_count: components.len(),
        shared_source_group_count: source_symbols
            .values()
            .filter(|symbols| symbols.len() > 1)
            .count(),
        largest_component_symbol_count: components.values().map(Vec::len).max().unwrap_or_default(),
        company_split_isolation_verified: company_splits.values().all(|splits| splits.len() == 1),
        source_group_split_isolation_verified: source_group_splits
            .values()
            .all(|splits| splits.len() == 1),
    }
}

fn causal_dataset_normalized_source_url(raw: &str) -> Option<String> {
    let mut parsed = url::Url::parse(raw.trim()).ok()?;
    if !matches!(parsed.scheme(), "http" | "https") {
        return None;
    }
    parsed.set_fragment(None);
    let mut query = parsed
        .query_pairs()
        .filter_map(|(key, value)| {
            let lower = key.to_ascii_lowercase();
            (!lower.starts_with("utm_")
                && !matches!(
                    lower.as_str(),
                    "fbclid" | "gclid" | "dclid" | "mc_cid" | "mc_eid"
                ))
            .then(|| (key.into_owned(), value.into_owned()))
        })
        .collect::<Vec<_>>();
    query.sort();
    parsed.set_query(None);
    if !query.is_empty() {
        parsed
            .query_pairs_mut()
            .extend_pairs(query.iter().map(|(key, value)| (key, value)));
    }
    Some(parsed.to_string())
}

fn causal_dataset_add_source_url(identities: &mut BTreeSet<String>, raw: &str) {
    if let Some(normalized) = causal_dataset_normalized_source_url(raw) {
        identities.insert(format!("url:{normalized}"));
    }
}

fn causal_dataset_source_identities(observation: &CausalObservation) -> Vec<String> {
    let mut identities = BTreeSet::new();
    if let Some(source_url) = observation.source_url.as_deref() {
        causal_dataset_add_source_url(&mut identities, source_url);
    }

    if let Some(claim) = &observation.claim {
        if !claim.source_event_id.trim().is_empty() {
            identities.insert(format!("event:{}", claim.source_event_id.trim()));
        }
        identities.insert(format!("claim:{}", observation.observation_id.trim()));
    }
    if let Some(claim) = &observation.operating_kpi {
        if !claim.source_event_id.trim().is_empty() {
            identities.insert(format!("event:{}", claim.source_event_id.trim()));
        }
        identities.insert(format!("claim:{}", observation.observation_id.trim()));
        if let Some(artifact) = &claim.source_artifact
            && valid_sha256(&artifact.source_sha256)
        {
            identities.insert(format!(
                "artifact-sha256:{}",
                artifact.source_sha256.to_ascii_lowercase()
            ));
        }
    }
    if let Some(computed) = &observation.computed {
        identities.insert(format!("claim:{}", computed.current_claim_id.trim()));
        identities.insert(format!("claim:{}", computed.prior_claim_id.trim()));
        causal_dataset_add_source_url(&mut identities, &computed.current_source_url);
        causal_dataset_add_source_url(&mut identities, &computed.prior_source_url);
    }
    if let Some(ratio) = &observation.ratio {
        identities.insert(format!("claim:{}", ratio.numerator_claim_id.trim()));
        identities.insert(format!("claim:{}", ratio.denominator_claim_id.trim()));
        causal_dataset_add_source_url(&mut identities, &ratio.source_url);
    }
    if let Some(trend) = &observation.ratio_trend {
        for ratio in [&trend.current, &trend.prior] {
            identities.insert(format!("claim:{}", ratio.numerator_claim_id.trim()));
            identities.insert(format!("claim:{}", ratio.denominator_claim_id.trim()));
            causal_dataset_add_source_url(&mut identities, &ratio.source_url);
        }
    }
    identities.retain(|identity| !identity.ends_with(':'));
    if identities.is_empty() {
        identities.insert(format!(
            "observation:{}:{}:{}",
            observation.source.trim(),
            observation.as_of,
            observation.observation_id.trim()
        ));
    }
    identities.into_iter().collect()
}

fn causal_source_verification_from_confirmation(
    confirmation: &CausalSpeakerConfirmation,
) -> CausalSourceVerification {
    match confirmation {
        CausalSpeakerConfirmation::SourceCheckedNotSpeakerConfirmed
        | CausalSpeakerConfirmation::OldWangConfirmedAfterSourceCheck => {
            CausalSourceVerification::VerifiedAgainstSource
        }
        CausalSpeakerConfirmation::EvidenceMismatch => CausalSourceVerification::EvidenceMismatch,
        CausalSpeakerConfirmation::InsufficientSourceContext => {
            CausalSourceVerification::InsufficientSourceContext
        }
        CausalSpeakerConfirmation::Unconfirmed | CausalSpeakerConfirmation::OldWangConfirmed => {
            CausalSourceVerification::Unchecked
        }
    }
}

fn causal_dataset_target(review: &CausalLinkReview) -> Option<&'static str> {
    if review.speaker_confirmation != CausalSpeakerConfirmation::OldWangConfirmedAfterSourceCheck
        || !review.old_wang_reviewer_identity_verified
        || review.verbatim_judgment.is_none()
        || review.applicability_boundary.is_none()
        || review.falsifier.is_none()
    {
        return None;
    }
    match (&review.verdict, &review.effect) {
        (CausalLinkVerdict::Rejected, CausalEvidenceEffect::Unclassified) => {
            Some("relationship_rejected")
        }
        (CausalLinkVerdict::Accepted, CausalEvidenceEffect::Supports) => Some("supports"),
        (CausalLinkVerdict::Accepted, CausalEvidenceEffect::Falsifies) => Some("falsifies"),
        (CausalLinkVerdict::Accepted, CausalEvidenceEffect::Mixed) => Some("mixed"),
        (CausalLinkVerdict::Accepted, CausalEvidenceEffect::ContextOnly) => Some("context_only"),
        _ => None,
    }
}

fn build_causal_training_examples(
    samples: &[DecisionTrainingSample],
) -> (Vec<CausalTrainingExample>, usize, usize, usize) {
    type ReviewKey = (String, String, String);
    let mut latest = BTreeMap::<ReviewKey, (DateTime<Utc>, CausalTrainingExample)>::new();
    let mut excluded_unclassified_links = 0usize;
    let mut excluded_future_evidence = 0usize;
    let mut deduplicated_review_rows = 0usize;

    for sample in samples {
        let Some(model) = &sample.state.first_principles else {
            continue;
        };
        for review in &sample.human_review.causal_link_reviews {
            let Some(reviewed_at) = causal_review_timestamp(sample, review) else {
                continue;
            };
            let Some(target) = causal_dataset_target(review) else {
                excluded_unclassified_links += 1;
                continue;
            };
            let Some(driver) = model
                .demand_drivers
                .iter()
                .chain(model.supply_drivers.iter())
                .chain(model.value_capture_drivers.iter())
                .find(|driver| driver.driver_id == review.driver_id)
            else {
                continue;
            };
            let Some(observation) = driver
                .observations
                .iter()
                .find(|observation| observation.observation_id == review.observation_id)
            else {
                continue;
            };
            if observation.as_of > sample.state.decision_date_beijing {
                excluded_future_evidence += 1;
                continue;
            }
            let key = (
                sample.state.symbol.clone(),
                driver.driver_id.clone(),
                observation.observation_id.clone(),
            );
            let example_identity = format!(
                "{CAUSAL_TRAINING_DATASET_POLICY_VERSION}:{}:{}:{}",
                key.0, key.1, key.2
            );
            let example = CausalTrainingExample {
                example_id: format!("{:x}", Sha256::digest(example_identity.as_bytes())),
                // Assigned after all company/source links are known.
                split: CausalDatasetSplit::Train,
                symbol: sample.state.symbol.clone(),
                decision_at: sample.state.decision_at,
                model_id: model.model_id.clone(),
                model_version: model.version.clone(),
                driver_id: driver.driver_id.clone(),
                driver_label: driver.label.clone(),
                mechanism: driver.mechanism.clone(),
                observation_id: observation.observation_id.clone(),
                relationship: observation.relationship.clone(),
                observation_label: observation.label.clone(),
                observation_value: observation.value.clone(),
                observation_as_of: observation.as_of,
                source_tier: observation.source_tier.clone(),
                source_identity_keys: causal_dataset_source_identities(observation),
                target: target.to_string(),
            };
            match latest.get(&key) {
                Some((previous_reviewed_at, _)) => {
                    deduplicated_review_rows += 1;
                    if *previous_reviewed_at <= reviewed_at {
                        latest.insert(key, (reviewed_at, example));
                    }
                }
                None => {
                    latest.insert(key, (reviewed_at, example));
                }
            }
        }
    }

    let mut examples = latest
        .into_values()
        .map(|(_, example)| example)
        .collect::<Vec<_>>();
    assign_causal_dataset_component_splits(&mut examples);
    examples.sort_by(|left, right| {
        left.split
            .cmp(&right.split)
            .then_with(|| left.symbol.cmp(&right.symbol))
            .then_with(|| left.driver_id.cmp(&right.driver_id))
            .then_with(|| left.observation_id.cmp(&right.observation_id))
    });
    (
        examples,
        excluded_unclassified_links,
        excluded_future_evidence,
        deduplicated_review_rows,
    )
}

fn causal_training_dataset_report(
    samples: &[DecisionTrainingSample],
) -> CausalTrainingDatasetReport {
    const MIN_EXAMPLES: usize = 200;
    const MIN_SYMBOLS: usize = 20;
    const MIN_DRIVERS: usize = 8;
    const MIN_TRAIN: usize = 100;
    const MIN_VALIDATION: usize = 30;
    const MIN_HOLDOUT: usize = 30;
    const MIN_TARGET_CLASSES: usize = 3;

    let (examples, excluded_unclassified_links, excluded_future_evidence, deduplicated) =
        build_causal_training_examples(samples);
    let mut audit_examples = examples.clone();
    let split_audit = assign_causal_dataset_component_splits(&mut audit_examples);
    let train_example_count = examples
        .iter()
        .filter(|example| example.split == CausalDatasetSplit::Train)
        .count();
    let validation_example_count = examples
        .iter()
        .filter(|example| example.split == CausalDatasetSplit::Validation)
        .count();
    let holdout_test_example_count = examples
        .iter()
        .filter(|example| example.split == CausalDatasetSplit::HoldoutTest)
        .count();
    let distinct_symbols = examples
        .iter()
        .map(|example| example.symbol.clone())
        .collect::<BTreeSet<_>>()
        .len();
    let distinct_drivers = examples
        .iter()
        .map(|example| example.driver_id.clone())
        .collect::<BTreeSet<_>>()
        .len();
    let mut development_target_counts = BTreeMap::new();
    for example in examples
        .iter()
        .filter(|example| example.split != CausalDatasetSplit::HoldoutTest)
    {
        *development_target_counts
            .entry(example.target.clone())
            .or_default() += 1;
    }
    let fingerprint_bytes =
        serde_json::to_vec(&(CAUSAL_TRAINING_DATASET_POLICY_VERSION, &examples))
            .expect("causal training dataset is serializable");
    let dataset_fingerprint_sha256 = format!("{:x}", Sha256::digest(fingerprint_bytes));

    let mut readiness_reasons = Vec::new();
    if examples.len() < MIN_EXAMPLES {
        readiness_reasons.push(format!(
            "已分类人工因果样本不足：{}/{MIN_EXAMPLES}",
            examples.len()
        ));
    }
    if distinct_symbols < MIN_SYMBOLS {
        readiness_reasons.push(format!("公司覆盖不足：{distinct_symbols}/{MIN_SYMBOLS}"));
    }
    if distinct_drivers < MIN_DRIVERS {
        readiness_reasons.push(format!("驱动覆盖不足：{distinct_drivers}/{MIN_DRIVERS}"));
    }
    if train_example_count < MIN_TRAIN {
        readiness_reasons.push(format!("训练分区不足：{train_example_count}/{MIN_TRAIN}"));
    }
    if validation_example_count < MIN_VALIDATION {
        readiness_reasons.push(format!(
            "验证分区不足：{validation_example_count}/{MIN_VALIDATION}"
        ));
    }
    if holdout_test_example_count < MIN_HOLDOUT {
        readiness_reasons.push(format!(
            "封存测试分区不足：{holdout_test_example_count}/{MIN_HOLDOUT}"
        ));
    }
    if development_target_counts.len() < MIN_TARGET_CLASSES {
        readiness_reasons.push(format!(
            "标签类型不足：{}/{MIN_TARGET_CLASSES}",
            development_target_counts.len()
        ));
    }
    if !split_audit.company_split_isolation_verified {
        readiness_reasons.push("同一公司跨越多个数据分区".to_string());
    }
    if !split_audit.source_group_split_isolation_verified {
        readiness_reasons.push("同一原文身份跨越开发与封存数据分区".to_string());
    }

    CausalTrainingDatasetReport {
        policy_version: CAUSAL_TRAINING_DATASET_POLICY_VERSION.to_string(),
        status: if readiness_reasons.is_empty() {
            "eligible_for_dataset_governance_review"
        } else {
            "insufficient_human_labels"
        }
        .to_string(),
        dataset_fingerprint_sha256,
        eligible_example_count: examples.len(),
        train_example_count,
        validation_example_count,
        holdout_test_example_count,
        distinct_symbols,
        distinct_drivers,
        development_target_counts,
        excluded_unclassified_links,
        excluded_future_evidence,
        deduplicated_review_rows: deduplicated,
        company_split_isolation_verified: split_audit.company_split_isolation_verified,
        source_group_split_isolation_verified: split_audit
            .source_group_split_isolation_verified,
        connected_component_count: split_audit.connected_component_count,
        shared_source_group_count: split_audit.shared_source_group_count,
        largest_component_symbol_count: split_audit.largest_component_symbol_count,
        holdout_labels_withheld: true,
        training_authorized: false,
        readiness_reasons,
        feature_scope: "特征只包含决策时已经冻结的第一性原理模型、驱动、证据文本/口径、日期与来源层级；不包含投资动作、研究区间、置信度、人工解释、未来收益、回撤或奖励。".to_string(),
        split_scope: "先用事件 ID、规范化原文 URL、内容 SHA-256 与派生主张引用识别来源别名，再把公司与共享原文身份组成不可拆分连通组；按连通组稳定哈希分为训练 70%、验证 15% 和封存测试 15%，同一公司、同一原文及其传递关联不得跨分区，测试标签不向训练入口暴露。".to_string(),
        authorization_scope: "这些数量门槛是 HONE 工程治理提案，不是老王投资阈值；达到门槛也只允许送审数据集，不自动训练、计算奖励、启动影子组合或交易。".to_string(),
    }
}

fn causal_effect_cohort(
    cohort_id: String,
    label: String,
    counts: CausalEffectCounts,
) -> CausalEffectCohort {
    let classified = counts.classified_accepted();
    CausalEffectCohort {
        cohort_id,
        label,
        available_links: counts.available,
        reviewed_links: counts.reviewed,
        accepted_links: counts.accepted,
        rejected_links: counts.rejected,
        supporting_links: counts.supports,
        falsifying_links: counts.falsifies,
        mixed_links: counts.mixed,
        context_only_links: counts.context_only,
        unclassified_accepted_links: counts.unclassified_accepted,
        review_rate_percent: rate_percent(counts.reviewed, counts.available),
        support_share_percent: (classified > 0).then(|| rate_percent(counts.supports, classified)),
        falsification_share_percent: (classified > 0)
            .then(|| rate_percent(counts.falsifies, classified)),
    }
}

fn causal_effect_evaluation(samples: &[DecisionTrainingSample]) -> CausalEffectEvaluation {
    let mut candidates = BTreeMap::<(String, String, String), CausalEffectCandidate>::new();
    let mut reviews = BTreeMap::<(String, String, String), CausalEffectVerdictAt>::new();
    let mut latest_operating_kpi_location =
        BTreeMap::<(String, String), (DateTime<Utc>, String)>::new();
    for sample in samples {
        if let Some(model) = &sample.state.first_principles {
            for driver in model
                .demand_drivers
                .iter()
                .chain(model.supply_drivers.iter())
                .chain(model.value_capture_drivers.iter())
            {
                for observation in &driver.observations {
                    if observation.relationship == CausalObservationRelationship::OperatingKpiClaim
                    {
                        let location_key = (
                            sample.state.symbol.clone(),
                            observation.observation_id.clone(),
                        );
                        if latest_operating_kpi_location
                            .get(&location_key)
                            .is_none_or(|(previous_at, _)| *previous_at <= sample.observed_at)
                        {
                            latest_operating_kpi_location.insert(
                                location_key,
                                (sample.observed_at, driver.driver_id.clone()),
                            );
                        }
                    }
                    candidates
                        .entry((
                            sample.state.symbol.clone(),
                            driver.driver_id.clone(),
                            observation.observation_id.clone(),
                        ))
                        .or_insert_with(|| CausalEffectCandidate {
                            driver_id: driver.driver_id.clone(),
                            driver_label: driver.label.clone(),
                            metric_id: observation
                                .claim
                                .as_ref()
                                .map(|claim| claim.metric_id.clone())
                                .or_else(|| {
                                    observation
                                        .computed
                                        .as_ref()
                                        .map(|item| item.metric_id.clone())
                                })
                                .or_else(|| {
                                    observation
                                        .ratio
                                        .as_ref()
                                        .map(|item| item.metric_id.clone())
                                })
                                .or_else(|| {
                                    observation
                                        .ratio_trend
                                        .as_ref()
                                        .map(|item| item.metric_id.clone())
                                })
                                .or_else(|| {
                                    observation
                                        .operating_kpi
                                        .as_ref()
                                        .map(|item| item.kpi_id.clone())
                                }),
                            market_regime: (sample.state.market_regime.status
                                == MarketRegimeStatus::Observed)
                                .then(|| sample.state.market_regime.label.clone()),
                        });
                }
            }
        }
        for review in &sample.human_review.causal_link_reviews {
            let Some(reviewed_at) = causal_review_timestamp(sample, review) else {
                continue;
            };
            if causal_source_verification_from_confirmation(&review.speaker_confirmation)
                != CausalSourceVerification::VerifiedAgainstSource
                || !review.old_wang_reviewer_identity_verified
            {
                continue;
            }
            let key = (
                sample.state.symbol.clone(),
                review.driver_id.clone(),
                review.observation_id.clone(),
            );
            if candidates.contains_key(&key)
                && reviews
                    .get(&key)
                    .is_none_or(|previous| previous.reviewed_at <= reviewed_at)
            {
                reviews.insert(
                    key,
                    CausalEffectVerdictAt {
                        verdict: review.verdict.clone(),
                        effect: review.effect.clone(),
                        reviewed_at,
                    },
                );
            }
        }
    }

    candidates.retain(|(symbol, driver_id, observation_id), _| {
        latest_operating_kpi_location
            .get(&(symbol.clone(), observation_id.clone()))
            .is_none_or(|(_, current_driver_id)| current_driver_id == driver_id)
    });

    let mut total = CausalEffectCounts {
        available: candidates.len(),
        ..Default::default()
    };
    let mut by_driver = BTreeMap::<String, (String, CausalEffectCounts)>::new();
    let mut by_metric = BTreeMap::<String, CausalEffectCounts>::new();
    let mut by_market_regime = BTreeMap::<String, CausalEffectCounts>::new();
    for (key, candidate) in &candidates {
        let driver = by_driver
            .entry(candidate.driver_id.clone())
            .or_insert_with(|| {
                (
                    candidate.driver_label.clone(),
                    CausalEffectCounts::default(),
                )
            });
        driver.1.available += 1;
        if let Some(metric_id) = &candidate.metric_id {
            by_metric.entry(metric_id.clone()).or_default().available += 1;
        }
        if let Some(regime) = &candidate.market_regime {
            by_market_regime
                .entry(regime.clone())
                .or_default()
                .available += 1;
        }
        if let Some(review) = reviews.get(key) {
            total.record_review(review);
            driver.1.record_review(review);
            if let Some(metric_id) = &candidate.metric_id {
                by_metric
                    .entry(metric_id.clone())
                    .or_default()
                    .record_review(review);
            }
            if let Some(regime) = &candidate.market_regime {
                by_market_regime
                    .entry(regime.clone())
                    .or_default()
                    .record_review(review);
            }
        }
    }
    let classified = total.classified_accepted();
    CausalEffectEvaluation {
        available_links: total.available,
        reviewed_links: total.reviewed,
        accepted_links: total.accepted,
        rejected_links: total.rejected,
        unclassified_accepted_links: total.unclassified_accepted,
        supporting_links: total.supports,
        falsifying_links: total.falsifies,
        mixed_links: total.mixed,
        context_only_links: total.context_only,
        review_rate_percent: rate_percent(total.reviewed, total.available),
        effect_classification_rate_percent: rate_percent(classified, total.accepted),
        support_share_percent: (classified > 0).then(|| rate_percent(total.supports, classified)),
        falsification_share_percent: (classified > 0)
            .then(|| rate_percent(total.falsifies, classified)),
        by_driver: by_driver
            .into_iter()
            .map(|(id, (label, counts))| causal_effect_cohort(id, label, counts))
            .collect(),
        by_metric: by_metric
            .into_iter()
            .map(|(id, counts)| causal_effect_cohort(id.clone(), id, counts))
            .collect(),
        market_regime_status: if by_market_regime.is_empty() {
            "unavailable"
        } else {
            "point_in_time_v1"
        }
        .to_string(),
        by_market_regime: by_market_regime
            .into_iter()
            .map(|(id, counts)| causal_effect_cohort(id.clone(), id, counts))
            .collect(),
        note: "当前只报告点时冻结的人工标签分布；在对应市场结果成熟前，不得把支持占比解释为预测准确率。".to_string(),
    }
}

#[derive(Debug, Clone)]
struct EvidenceReviewVerdictAt {
    verdict: CausalLinkVerdict,
    effect: CausalEvidenceEffect,
    explanation: String,
    source_verification: CausalSourceVerification,
    training_label_eligible: bool,
    reviewed_at: DateTime<Utc>,
}

#[cfg(test)]
fn build_evidence_review_queue(
    samples: &[DecisionTrainingSample],
    symbol_filter: Option<String>,
    status_filter: &str,
    kind_filter: &str,
    limit: usize,
) -> EvidenceReviewQueueResponse {
    build_evidence_review_queue_with_selection(
        samples,
        symbol_filter,
        status_filter,
        kind_filter,
        limit,
        "full_queue",
    )
}

fn build_evidence_review_queue_with_selection(
    samples: &[DecisionTrainingSample],
    symbol_filter: Option<String>,
    status_filter: &str,
    kind_filter: &str,
    limit: usize,
    selection_mode: &str,
) -> EvidenceReviewQueueResponse {
    let mut candidates = BTreeMap::<(String, String, String), EvidenceReviewQueueItem>::new();
    let mut verdicts = BTreeMap::<(String, String, String), EvidenceReviewVerdictAt>::new();
    let mut latest_operating_kpi_location =
        BTreeMap::<(String, String), (DateTime<Utc>, String)>::new();
    for sample in samples {
        let Some(model) = &sample.state.first_principles else {
            continue;
        };
        for driver in model
            .demand_drivers
            .iter()
            .chain(model.supply_drivers.iter())
            .chain(model.value_capture_drivers.iter())
        {
            for observation in &driver.observations {
                let kind = match observation.relationship {
                    CausalObservationRelationship::StructuredSourceClaim => {
                        EvidenceReviewQueueKind::SourceClaim
                    }
                    CausalObservationRelationship::OperatingKpiClaim => {
                        EvidenceReviewQueueKind::OperatingKpi
                    }
                    CausalObservationRelationship::ComputedComparison => {
                        EvidenceReviewQueueKind::ComputedComparison
                    }
                    CausalObservationRelationship::ComputedRatio => {
                        EvidenceReviewQueueKind::ComputedRatio
                    }
                    CausalObservationRelationship::ComputedRatioTrend => {
                        EvidenceReviewQueueKind::ComputedRatio
                    }
                    _ => continue,
                };
                let key = (
                    sample.state.symbol.clone(),
                    driver.driver_id.clone(),
                    observation.observation_id.clone(),
                );
                let replace = candidates
                    .get(&key)
                    .is_none_or(|previous| previous.decision_at <= sample.state.decision_at);
                if !replace {
                    continue;
                }
                let (mut priority, mut priority_reasons) = evidence_review_priority(observation);
                let evidence_identity_sha256 = causal_evidence_identity(
                    sample,
                    &driver.driver_id,
                    &observation.observation_id,
                )
                .expect("validated causal observation has an evidence identity");
                let (source_review_ready, source_review_contract, source_review_blockers) =
                    evidence_source_review_readiness(
                        observation,
                        sample.state.decision_at,
                        driver,
                        &model.operating_kpi_registry,
                    );
                if !source_review_ready {
                    priority = "blocked".to_string();
                    priority_reasons.extend(source_review_blockers.iter().cloned());
                }
                candidates.insert(
                    key.clone(),
                    EvidenceReviewQueueItem {
                        queue_id: format!(
                            "{}:{}:{}",
                            sample.state.symbol, driver.driver_id, observation.observation_id
                        ),
                        symbol: sample.state.symbol.clone(),
                        company_name: sample.state.company_name.clone(),
                        sample_id: sample.sample_id.clone(),
                        decision_at: sample.state.decision_at,
                        driver_id: driver.driver_id.clone(),
                        driver_label: driver.label.clone(),
                        mechanism: driver.mechanism.clone(),
                        kind: kind.clone(),
                        status: EvidenceReviewQueueStatus::Pending,
                        priority,
                        priority_reasons,
                        source_review_ready,
                        source_review_contract,
                        source_review_blockers,
                        evidence_identity_sha256,
                        observation: observation.clone(),
                        review_explanation: None,
                        review_effect: None,
                        review_source_verification: None,
                        source_review_id: None,
                        source_review_note: None,
                        source_reviewed_at: None,
                        source_review_origin_sample_id: None,
                        source_review_reused_across_snapshots: false,
                        source_review_conflict: false,
                        training_label_eligible: false,
                        reviewed_at: None,
                    },
                );
                if kind == EvidenceReviewQueueKind::OperatingKpi {
                    let location_key = (
                        sample.state.symbol.clone(),
                        observation.observation_id.clone(),
                    );
                    if latest_operating_kpi_location
                        .get(&location_key)
                        .is_none_or(|(previous_at, _)| *previous_at <= sample.state.decision_at)
                    {
                        latest_operating_kpi_location.insert(
                            location_key,
                            (sample.state.decision_at, driver.driver_id.clone()),
                        );
                    }
                }
            }
        }
    }
    candidates.retain(|_, item| {
        item.kind != EvidenceReviewQueueKind::OperatingKpi
            || latest_operating_kpi_location
                .get(&(item.symbol.clone(), item.observation.observation_id.clone()))
                .is_some_and(|(_, driver_id)| driver_id == &item.driver_id)
    });
    let mut source_reviews_by_identity =
        BTreeMap::<(String, String), Vec<(String, CausalSourceReviewProjection)>>::new();
    for sample in samples {
        for review in &sample.human_review.causal_source_reviews {
            let Ok(identity) =
                causal_evidence_identity(sample, &review.driver_id, &review.observation_id)
            else {
                continue;
            };
            source_reviews_by_identity
                .entry((sample.state.symbol.clone(), identity))
                .or_default()
                .push((sample.sample_id.clone(), review.clone()));
        }
    }
    for item in candidates.values_mut() {
        let Some(reviews) = source_reviews_by_identity
            .get(&(item.symbol.clone(), item.evidence_identity_sha256.clone()))
        else {
            continue;
        };
        let first_verdict = reviews[0].1.verdict.clone();
        if reviews
            .iter()
            .any(|(_, review)| review.verdict != first_verdict)
        {
            item.source_review_conflict = true;
            item.source_review_ready = false;
            item.priority = "blocked".to_string();
            item.source_review_blockers
                .push("同一冻结证据在不同决策快照中存在相互冲突的来源核验".to_string());
            item.priority_reasons
                .push("跨快照来源核验冲突，必须先人工纠正审计链".to_string());
            continue;
        }
        if let Some((origin_sample_id, review)) = reviews.iter().max_by(|left, right| {
            left.1
                .reviewed_at
                .cmp(&right.1.reviewed_at)
                .then_with(|| left.1.review_id.cmp(&right.1.review_id))
        }) {
            item.review_source_verification = Some(review.verdict.clone());
            item.source_review_id = Some(review.review_id.clone());
            item.source_review_note = Some(review.note.clone());
            item.source_reviewed_at = Some(review.reviewed_at);
            item.source_review_origin_sample_id = Some(origin_sample_id.clone());
            item.source_review_reused_across_snapshots = origin_sample_id != &item.sample_id;
            if item.source_review_reused_across_snapshots {
                item.priority_reasons
                    .push("相同证据身份已在更早决策快照完成来源核验，无需重复核对".to_string());
            }
        }
    }
    for sample in samples {
        for review in &sample.human_review.causal_link_reviews {
            let Some(reviewed_at) = causal_review_timestamp(sample, review) else {
                continue;
            };
            let key = (
                sample.state.symbol.clone(),
                review.driver_id.clone(),
                review.observation_id.clone(),
            );
            let review_matches_candidate_identity = candidates.get(&key).is_some_and(|item| {
                causal_evidence_identity(sample, &review.driver_id, &review.observation_id)
                    .is_ok_and(|identity| identity == item.evidence_identity_sha256)
            });
            if review_matches_candidate_identity
                && verdicts
                    .get(&key)
                    .is_none_or(|previous| previous.reviewed_at <= reviewed_at)
            {
                verdicts.insert(
                    key,
                    EvidenceReviewVerdictAt {
                        verdict: review.verdict.clone(),
                        effect: review.effect.clone(),
                        explanation: review.explanation.clone(),
                        source_verification: causal_source_verification_from_confirmation(
                            &review.speaker_confirmation,
                        ),
                        training_label_eligible: causal_dataset_target(review).is_some(),
                        reviewed_at,
                    },
                );
            }
        }
    }
    for (key, verdict) in verdicts {
        let Some(item) = candidates.get_mut(&key) else {
            continue;
        };
        item.status = match verdict.verdict {
            CausalLinkVerdict::Accepted => EvidenceReviewQueueStatus::Accepted,
            CausalLinkVerdict::Rejected => EvidenceReviewQueueStatus::Rejected,
        };
        item.review_explanation = Some(verdict.explanation);
        item.review_effect = Some(verdict.effect);
        item.review_source_verification = Some(verdict.source_verification);
        item.training_label_eligible = verdict.training_label_eligible;
        item.reviewed_at = Some(verdict.reviewed_at);
    }
    let mut scoped = candidates
        .into_values()
        .filter(|item| match kind_filter {
            "source_claim" => item.kind == EvidenceReviewQueueKind::SourceClaim,
            "operating_kpi" => item.kind == EvidenceReviewQueueKind::OperatingKpi,
            "computed_comparison" => item.kind == EvidenceReviewQueueKind::ComputedComparison,
            "computed_ratio" => item.kind == EvidenceReviewQueueKind::ComputedRatio,
            _ => true,
        })
        .collect::<Vec<_>>();
    let pending_candidates = scoped
        .iter()
        .filter(|item| item.status == EvidenceReviewQueueStatus::Pending)
        .count();
    let accepted_candidates = scoped
        .iter()
        .filter(|item| item.status == EvidenceReviewQueueStatus::Accepted)
        .count();
    let rejected_candidates = scoped
        .iter()
        .filter(|item| item.status == EvidenceReviewQueueStatus::Rejected)
        .count();
    let total_candidates = scoped.len();
    let source_review_ready_candidates = scoped
        .iter()
        .filter(|item| item.source_review_ready)
        .count();
    let source_blocked_candidates = total_candidates - source_review_ready_candidates;
    let source_unreviewed_candidates = scoped
        .iter()
        .filter(|item| item.status == EvidenceReviewQueueStatus::Pending)
        .filter(|item| !item.source_review_conflict)
        .filter(|item| {
            item.review_source_verification
                .as_ref()
                .is_none_or(|status| *status == CausalSourceVerification::Unchecked)
        })
        .count();
    let source_verified_waiting_causal_candidates = scoped
        .iter()
        .filter(|item| item.status == EvidenceReviewQueueStatus::Pending)
        .filter(|item| {
            item.review_source_verification == Some(CausalSourceVerification::VerifiedAgainstSource)
        })
        .count();
    let source_excluded_candidates = scoped
        .iter()
        .filter(|item| item.status == EvidenceReviewQueueStatus::Pending)
        .filter(|item| {
            matches!(
                item.review_source_verification,
                Some(CausalSourceVerification::EvidenceMismatch)
                    | Some(CausalSourceVerification::InsufficientSourceContext)
            )
        })
        .count();
    let source_review_reused_candidates = scoped
        .iter()
        .filter(|item| item.source_review_reused_across_snapshots)
        .count();
    let source_review_conflicted_candidates = scoped
        .iter()
        .filter(|item| item.source_review_conflict)
        .count();
    let supporting_candidates = scoped
        .iter()
        .filter(|item| item.review_effect.as_ref() == Some(&CausalEvidenceEffect::Supports))
        .count();
    let falsifying_candidates = scoped
        .iter()
        .filter(|item| item.review_effect.as_ref() == Some(&CausalEvidenceEffect::Falsifies))
        .count();
    let mixed_candidates = scoped
        .iter()
        .filter(|item| item.review_effect.as_ref() == Some(&CausalEvidenceEffect::Mixed))
        .count();
    let context_only_candidates = scoped
        .iter()
        .filter(|item| item.review_effect.as_ref() == Some(&CausalEvidenceEffect::ContextOnly))
        .count();
    scoped.retain(|item| match status_filter {
        "pending" => item.status == EvidenceReviewQueueStatus::Pending,
        "accepted" => item.status == EvidenceReviewQueueStatus::Accepted,
        "rejected" => item.status == EvidenceReviewQueueStatus::Rejected,
        _ => true,
    });
    scoped.sort_by(|left, right| {
        evidence_review_priority_rank(&left.priority)
            .cmp(&evidence_review_priority_rank(&right.priority))
            .then_with(|| right.observation.as_of.cmp(&left.observation.as_of))
            .then_with(|| right.decision_at.cmp(&left.decision_at))
            .then_with(|| left.symbol.cmp(&right.symbol))
            .then_with(|| left.driver_id.cmp(&right.driver_id))
            .then_with(|| {
                left.observation
                    .observation_id
                    .cmp(&right.observation.observation_id)
            })
    });
    let (items, selection_policy_version, selection_scope) = match selection_mode {
        "active_batch" => (
            select_active_review_batch(&scoped, limit),
            ACTIVE_REVIEW_BATCH_POLICY_VERSION,
            "兼容批次同时允许来源待核和来源已核材料；新管理端应分别使用维护者来源批次与老王待答批次。所有候选都必须来自冻结时点并具备完整来源合同，不读取未来价格、收益或奖励。",
        ),
        "source_batch" => {
            let source_pending = scoped
                .iter()
                .filter(|item| {
                    !item.source_review_conflict
                        && item
                            .review_source_verification
                            .as_ref()
                            .is_none_or(|status| *status == CausalSourceVerification::Unchecked)
                })
                .cloned()
                .collect::<Vec<_>>();
            (
                select_active_review_batch(&source_pending, limit),
                SOURCE_REVIEW_BATCH_POLICY_VERSION,
                "维护者批次只选择来源合同完整且尚未核验的冻结材料；任务仅为打开原文核对主体、数值、期间、单位、定位和上下文。保存结果永不生成因果或训练标签。",
            )
        }
        "old_wang_batch" => {
            let source_verified = scoped
                .iter()
                .filter(|item| {
                    !item.source_review_conflict
                        && item.review_source_verification
                            == Some(CausalSourceVerification::VerifiedAgainstSource)
                })
                .cloned()
                .collect::<Vec<_>>();
            (
                select_active_review_batch(&source_verified, limit),
                OLD_WANG_CAUSAL_BATCH_POLICY_VERSION,
                "老王批次只选择已绑定当前冻结证据指纹、且来源核验结论为一致的材料；老王只回答它为何改变判断、作用方向、适用边界和可观察反证。未核来源和来源排除项不会出现。",
            )
        }
        _ => {
            scoped.truncate(limit);
            (
                scoped,
                FULL_REVIEW_QUEUE_POLICY_VERSION,
                "完整队列保留来源待补齐材料及具体阻断原因，并按证据阻断级别、因果复核优先级、披露时间和稳定标识排序；不使用未来结果或奖励。",
            )
        }
    };
    let selected_symbols = items
        .iter()
        .map(|item| item.symbol.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect();
    let selected_drivers = items
        .iter()
        .map(|item| item.driver_id.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect();
    EvidenceReviewQueueResponse {
        schema_version: REVIEW_QUEUE_SCHEMA_VERSION.to_string(),
        generated_at: Utc::now(),
        symbol_filter,
        status_filter: status_filter.to_string(),
        kind_filter: kind_filter.to_string(),
        selection_mode: selection_mode.to_string(),
        selection_policy_version: selection_policy_version.to_string(),
        selection_scope: selection_scope.to_string(),
        selected_symbols,
        selected_drivers,
        total_candidates,
        pending_candidates,
        accepted_candidates,
        rejected_candidates,
        source_review_ready_candidates,
        source_blocked_candidates,
        source_unreviewed_candidates,
        source_verified_waiting_causal_candidates,
        source_excluded_candidates,
        source_review_reused_candidates,
        source_review_conflicted_candidates,
        old_wang_reviewer_configured: false,
        old_wang_submission_authorized: false,
        supporting_candidates,
        falsifying_candidates,
        mixed_candidates,
        context_only_candidates,
        items,
    }
}

fn evidence_source_review_readiness(
    observation: &CausalObservation,
    decision_at: DateTime<Utc>,
    driver: &ModelDriver,
    registry: &OperatingKpiRegistry,
) -> (bool, EvidenceSourceReviewContract, Vec<String>) {
    let contract = if observation
        .claim
        .as_ref()
        .is_some_and(|claim| claim.numeric_value.is_none())
        || observation
            .operating_kpi
            .as_ref()
            .is_some_and(|claim| claim.numeric_value.is_none())
    {
        EvidenceSourceReviewContract::Qualitative
    } else {
        EvidenceSourceReviewContract::Numeric
    };
    let mut blockers = Vec::new();
    if observation.as_of > decision_at.with_timezone(&Shanghai).date_naive() {
        blockers.push("证据日期晚于冻结决策时点，不能进入本轮复核".to_string());
    }
    if observation.source.trim().is_empty() || observation.source_tier.trim().is_empty() {
        blockers.push("缺少来源名称或来源层级".to_string());
    }
    if observation
        .source_url
        .as_deref()
        .is_none_or(|url| !url.starts_with("https://"))
    {
        blockers.push("缺少可直接打开的 HTTPS 原始来源".to_string());
    }

    let provenance_valid = match (
        &observation.relationship,
        &observation.claim,
        &observation.computed,
        &observation.ratio,
        &observation.ratio_trend,
        &observation.operating_kpi,
    ) {
        (
            CausalObservationRelationship::StructuredSourceClaim,
            Some(claim),
            None,
            None,
            None,
            None,
        ) => {
            let lifecycle_valid = claim.lifecycle_status == CausalClaimLifecycleStatus::Active
                && claim.disposition != EarningsClaimDisposition::Withdrawn
                && claim.superseded_by.is_none()
                && claim.conflicting_claim_ids.is_empty();
            !claim.metric_id.trim().is_empty()
                && !claim.metric_basis.trim().is_empty()
                && claim.metric_basis != LEGACY_UNSPECIFIED_METRIC_BASIS
                && !claim.period.trim().is_empty()
                && !claim.source_event_id.trim().is_empty()
                && !claim.source_document.trim().is_empty()
                && !claim.source_locator.trim().is_empty()
                && !claim.quote_excerpt.trim().is_empty()
                && matches!(
                    claim.source_document.as_str(),
                    "earnings_call_transcript" | "earnings_release" | "sec_filing"
                )
                && claim.numeric_value.is_none_or(f64::is_finite)
                && claim
                    .numeric_value
                    .is_none_or(|_| !claim.unit.trim().is_empty())
                && (claim.claim_kind == EarningsClaimKind::ReportedFact
                    || claim
                        .speaker
                        .as_deref()
                        .is_some_and(|speaker| !speaker.trim().is_empty()))
                && lifecycle_valid
        }
        (
            CausalObservationRelationship::OperatingKpiClaim,
            None,
            None,
            None,
            None,
            Some(provenance),
        ) => causal_operating_kpi_is_valid(provenance, observation, driver, registry),
        (
            CausalObservationRelationship::ComputedComparison,
            None,
            Some(computed),
            None,
            None,
            None,
        ) => {
            let expected_change = if computed.prior_numeric_value.abs() > f64::EPSILON {
                Some(
                    (computed.current_numeric_value - computed.prior_numeric_value)
                        / computed.prior_numeric_value.abs()
                        * 100.0,
                )
            } else {
                None
            };
            computed.formula_version == COMPUTED_COMPARISON_FORMULA_VERSION
                && !computed.metric_id.trim().is_empty()
                && !computed.metric_basis.trim().is_empty()
                && !computed.current_claim_id.trim().is_empty()
                && !computed.prior_claim_id.trim().is_empty()
                && computed.current_claim_id != computed.prior_claim_id
                && !computed.current_period.trim().is_empty()
                && !computed.prior_period.trim().is_empty()
                && !computed.unit.trim().is_empty()
                && computed.current_numeric_value.is_finite()
                && computed.prior_numeric_value.is_finite()
                && computed.change_percent.is_finite()
                && expected_change
                    .is_some_and(|expected| (computed.change_percent - expected).abs() <= 0.000_001)
                && computed.prior_published_at < computed.current_published_at
                && computed.current_published_at <= decision_at
                && computed.current_source_url.starts_with("https://")
                && computed.prior_source_url.starts_with("https://")
                && observation.source_tier == "deterministic_computation"
                && observation.source_url.as_deref() == Some(computed.current_source_url.as_str())
                && computed_period_pair_is_valid(computed)
        }
        (CausalObservationRelationship::ComputedRatio, None, None, Some(ratio), None, None) => {
            causal_ratio_provenance_is_valid(ratio, decision_at)
                && observation.source_tier == "deterministic_computation"
                && observation.source_url.as_deref() == Some(ratio.source_url.as_str())
        }
        (
            CausalObservationRelationship::ComputedRatioTrend,
            None,
            None,
            None,
            Some(trend),
            None,
        ) => {
            causal_ratio_trend_is_valid(trend, decision_at)
                && observation.source_tier == "deterministic_computation"
                && observation.source_url.as_deref() == Some(trend.current.source_url.as_str())
        }
        _ => false,
    };
    if !provenance_valid {
        blockers.push(match observation.relationship {
            CausalObservationRelationship::StructuredSourceClaim => {
                "一手主张缺少可核验的指标口径、期间、原文位置、原文摘录或有效生命周期"
            }
            CausalObservationRelationship::OperatingKpiClaim => {
                "经营 KPI 缺少公司原始定义、期间范围、原文定位、数值单位、来源归档或有效生命周期"
            }
            CausalObservationRelationship::ComputedComparison => {
                "同比/环比缺少两端可比口径、独立原始来源或可复算公式"
            }
            CausalObservationRelationship::ComputedRatio
            | CausalObservationRelationship::ComputedRatioTrend => {
                "利润率证据缺少同口径分子分母、两期原始来源或可复算公式"
            }
            _ => "证据类型与来源证明结构不匹配",
        }
        .to_string());
    }
    (blockers.is_empty(), contract, blockers)
}

fn select_active_review_batch(
    candidates: &[EvidenceReviewQueueItem],
    limit: usize,
) -> Vec<EvidenceReviewQueueItem> {
    let limit = limit.clamp(1, MAX_ACTIVE_REVIEW_BATCH_SIZE);
    let mut eligible = candidates
        .iter()
        .filter(|item| item.status == EvidenceReviewQueueStatus::Pending)
        .filter(|item| item.source_review_ready && item.priority != "blocked")
        .filter(|item| {
            !matches!(
                item.review_source_verification,
                Some(CausalSourceVerification::EvidenceMismatch)
                    | Some(CausalSourceVerification::InsufficientSourceContext)
            )
        })
        .filter(|item| {
            item.observation.as_of <= item.decision_at.with_timezone(&Shanghai).date_naive()
        })
        .cloned()
        .collect::<Vec<_>>();
    eligible.sort_by(|left, right| {
        active_review_information_rank(left)
            .cmp(&active_review_information_rank(right))
            .then_with(|| right.observation.as_of.cmp(&left.observation.as_of))
            .then_with(|| right.decision_at.cmp(&left.decision_at))
            .then_with(|| left.symbol.cmp(&right.symbol))
            .then_with(|| left.driver_id.cmp(&right.driver_id))
            .then_with(|| left.queue_id.cmp(&right.queue_id))
    });

    let mut selected = Vec::new();
    let mut selected_ids = BTreeSet::new();
    let mut selected_symbol_drivers = BTreeSet::new();
    let mut symbol_counts = BTreeMap::<String, usize>::new();

    // The first pass deliberately covers different evidence contracts. A batch
    // made entirely of operating KPIs is faster to review but teaches only one
    // extraction shape and creates a misleading claim of evidence diversity.
    for kind in [
        EvidenceReviewQueueKind::OperatingKpi,
        EvidenceReviewQueueKind::ComputedComparison,
        EvidenceReviewQueueKind::ComputedRatio,
        EvidenceReviewQueueKind::SourceClaim,
    ] {
        if selected.len() >= limit {
            break;
        }
        let Some(item) = eligible.iter().find(|item| {
            item.kind == kind
                && item.priority != "blocked"
                && symbol_counts.get(&item.symbol).copied().unwrap_or_default() < 2
                && !selected_ids.contains(&item.queue_id)
                && !selected_symbol_drivers.contains(&(item.symbol.clone(), item.driver_id.clone()))
        }) else {
            continue;
        };
        selected_ids.insert(item.queue_id.clone());
        selected_symbol_drivers.insert((item.symbol.clone(), item.driver_id.clone()));
        *symbol_counts.entry(item.symbol.clone()).or_default() += 1;
        selected.push(item.clone());
    }

    // Fill the remaining slots while preserving at most two questions per
    // company and one question per company-driver pair whenever possible.
    for item in &eligible {
        if selected.len() >= limit {
            break;
        }
        if symbol_counts.get(&item.symbol).copied().unwrap_or_default() >= 2
            || selected_ids.contains(&item.queue_id)
            || selected_symbol_drivers.contains(&(item.symbol.clone(), item.driver_id.clone()))
        {
            continue;
        }
        selected_ids.insert(item.queue_id.clone());
        selected_symbol_drivers.insert((item.symbol.clone(), item.driver_id.clone()));
        *symbol_counts.entry(item.symbol.clone()).or_default() += 1;
        selected.push(item.clone());
    }

    // Sparse symbol filters may not offer enough companies. Relax only the
    // per-company cap first, then the per-driver cap as a final fallback.
    for item in &eligible {
        if selected.len() >= limit {
            break;
        }
        if selected_ids.contains(&item.queue_id)
            || selected_symbol_drivers.contains(&(item.symbol.clone(), item.driver_id.clone()))
        {
            continue;
        }
        selected_ids.insert(item.queue_id.clone());
        selected_symbol_drivers.insert((item.symbol.clone(), item.driver_id.clone()));
        selected.push(item.clone());
    }
    for item in &eligible {
        if selected.len() >= limit {
            break;
        }
        if selected_ids.insert(item.queue_id.clone()) {
            selected.push(item.clone());
        }
    }
    selected
}

fn active_review_information_rank(item: &EvidenceReviewQueueItem) -> u8 {
    if item.priority == "blocked" {
        return 5;
    }
    match item.kind {
        EvidenceReviewQueueKind::OperatingKpi => 0,
        EvidenceReviewQueueKind::ComputedComparison => 1,
        EvidenceReviewQueueKind::ComputedRatio
            if item.observation.relationship
                == CausalObservationRelationship::ComputedRatioTrend =>
        {
            2
        }
        EvidenceReviewQueueKind::ComputedRatio => 3,
        EvidenceReviewQueueKind::SourceClaim => 4,
    }
}

fn evidence_review_priority(observation: &CausalObservation) -> (String, Vec<String>) {
    if let Some(claim) = &observation.claim
        && claim.lifecycle_status != CausalClaimLifecycleStatus::Active
    {
        return (
            "blocked".to_string(),
            vec!["主张已更正、冲突、撤回或被替代，只能拒绝或暂缓".to_string()],
        );
    }
    if let Some(claim) = &observation.operating_kpi
        && claim.lifecycle_status != CausalClaimLifecycleStatus::Active
    {
        return (
            "blocked".to_string(),
            vec!["经营指标口径已更正、冲突、撤回或被替代，只能拒绝或暂缓".to_string()],
        );
    }
    if observation.relationship == CausalObservationRelationship::OperatingKpiClaim {
        return (
            "high".to_string(),
            vec!["公司原始经营口径已保留，需要人工确认它对需求、供给或价值捕获的作用".to_string()],
        );
    }
    if observation.relationship == CausalObservationRelationship::ComputedComparison {
        return (
            "high".to_string(),
            vec!["两期一手事实已可比，需要确认它是否支持该驱动因子".to_string()],
        );
    }
    if matches!(
        observation.relationship,
        CausalObservationRelationship::ComputedRatio
            | CausalObservationRelationship::ComputedRatioTrend
    ) {
        return (
            "high".to_string(),
            vec![
                "同一 SEC filing 的分子分母已匹配，需要确认利润率是否支持定价权与价值捕获"
                    .to_string(),
            ],
        );
    }
    if observation
        .claim
        .as_ref()
        .is_some_and(|claim| claim.claim_kind == EarningsClaimKind::ReportedFact)
    {
        return (
            "high".to_string(),
            vec!["SEC 报告事实尚未完成因果归因".to_string()],
        );
    }
    (
        "normal".to_string(),
        vec!["管理层主张需要结合后续事实验证".to_string()],
    )
}

fn evidence_review_priority_rank(priority: &str) -> u8 {
    match priority {
        "blocked" => 0,
        "high" => 1,
        _ => 2,
    }
}

fn computed_review_evaluation(samples: &[DecisionTrainingSample]) -> ComputedReviewEvaluation {
    #[derive(Debug, Clone, Copy)]
    enum DerivedKind {
        Comparison(CausalComparisonKind),
        Ratio(CausalRatioKind),
        RatioTrend(CausalComparisonKind),
    }
    let mut available = BTreeMap::<(String, String, String), DerivedKind>::new();
    let mut reviewed =
        BTreeMap::<(String, String, String), (DateTime<Utc>, CausalLinkVerdict)>::new();
    for sample in samples {
        if let Some(model) = &sample.state.first_principles {
            for driver in model
                .demand_drivers
                .iter()
                .chain(model.supply_drivers.iter())
                .chain(model.value_capture_drivers.iter())
            {
                for observation in &driver.observations {
                    if observation.relationship == CausalObservationRelationship::ComputedComparison
                        && let Some(computed) = &observation.computed
                    {
                        available.insert(
                            (
                                sample.state.symbol.clone(),
                                driver.driver_id.clone(),
                                observation.observation_id.clone(),
                            ),
                            DerivedKind::Comparison(computed.comparison_kind),
                        );
                    }
                    if observation.relationship == CausalObservationRelationship::ComputedRatio
                        && let Some(ratio) = &observation.ratio
                    {
                        available.insert(
                            (
                                sample.state.symbol.clone(),
                                driver.driver_id.clone(),
                                observation.observation_id.clone(),
                            ),
                            DerivedKind::Ratio(ratio.ratio_kind),
                        );
                    }
                    if observation.relationship == CausalObservationRelationship::ComputedRatioTrend
                        && let Some(trend) = &observation.ratio_trend
                    {
                        available.insert(
                            (
                                sample.state.symbol.clone(),
                                driver.driver_id.clone(),
                                observation.observation_id.clone(),
                            ),
                            DerivedKind::RatioTrend(trend.comparison_kind),
                        );
                    }
                }
            }
        }
        for review in &sample.human_review.causal_link_reviews {
            let Some(reviewed_at) = causal_review_timestamp(sample, review) else {
                continue;
            };
            if causal_source_verification_from_confirmation(&review.speaker_confirmation)
                != CausalSourceVerification::VerifiedAgainstSource
                || !review.old_wang_reviewer_identity_verified
            {
                continue;
            }
            let key = (
                sample.state.symbol.clone(),
                review.driver_id.clone(),
                review.observation_id.clone(),
            );
            if available.contains_key(&key)
                && reviewed
                    .get(&key)
                    .is_none_or(|(previous_at, _)| *previous_at <= reviewed_at)
            {
                reviewed.insert(key, (reviewed_at, review.verdict.clone()));
            }
        }
    }
    let is_comparison = |key: &(String, String, String)| {
        available
            .get(key)
            .is_some_and(|kind| matches!(kind, DerivedKind::Comparison(_)))
    };
    let is_ratio = |key: &(String, String, String)| {
        available
            .get(key)
            .is_some_and(|kind| matches!(kind, DerivedKind::Ratio(_)))
    };
    let accepted_comparisons = reviewed
        .iter()
        .filter(|(key, (_, verdict))| is_comparison(key) && *verdict == CausalLinkVerdict::Accepted)
        .count();
    let rejected_comparisons = reviewed
        .iter()
        .filter(|(key, (_, verdict))| is_comparison(key) && *verdict == CausalLinkVerdict::Rejected)
        .count();
    ComputedReviewEvaluation {
        available_comparisons: available.keys().filter(|key| is_comparison(key)).count(),
        reviewed_comparisons: reviewed.keys().filter(|key| is_comparison(key)).count(),
        accepted_comparisons,
        rejected_comparisons,
        year_over_year_comparisons: available
            .values()
            .filter(|kind| {
                matches!(
                    kind,
                    DerivedKind::Comparison(CausalComparisonKind::YearOverYear)
                )
            })
            .count(),
        sequential_comparisons: available
            .values()
            .filter(|kind| {
                matches!(
                    kind,
                    DerivedKind::Comparison(CausalComparisonKind::SequentialQuarter)
                )
            })
            .count(),
        available_ratios: available
            .values()
            .filter(|kind| matches!(kind, DerivedKind::Ratio(_)))
            .count(),
        reviewed_ratios: reviewed.keys().filter(|key| is_ratio(key)).count(),
        accepted_ratios: reviewed
            .iter()
            .filter(|(key, (_, verdict))| is_ratio(key) && *verdict == CausalLinkVerdict::Accepted)
            .count(),
        rejected_ratios: reviewed
            .iter()
            .filter(|(key, (_, verdict))| is_ratio(key) && *verdict == CausalLinkVerdict::Rejected)
            .count(),
        gross_margin_ratios: available
            .values()
            .filter(|kind| matches!(kind, DerivedKind::Ratio(CausalRatioKind::GrossMargin)))
            .count(),
        operating_margin_ratios: available
            .values()
            .filter(|kind| matches!(kind, DerivedKind::Ratio(CausalRatioKind::OperatingMargin)))
            .count(),
        available_ratio_trends: available
            .values()
            .filter(|kind| matches!(kind, DerivedKind::RatioTrend(_)))
            .count(),
        reviewed_ratio_trends: reviewed
            .keys()
            .filter(|key| {
                available
                    .get(*key)
                    .is_some_and(|kind| matches!(kind, DerivedKind::RatioTrend(_)))
            })
            .count(),
        year_over_year_ratio_trends: available
            .values()
            .filter(|kind| {
                matches!(
                    kind,
                    DerivedKind::RatioTrend(CausalComparisonKind::YearOverYear)
                )
            })
            .count(),
        sequential_ratio_trends: available
            .values()
            .filter(|kind| {
                matches!(
                    kind,
                    DerivedKind::RatioTrend(CausalComparisonKind::SequentialQuarter)
                )
            })
            .count(),
        review_rate_percent: rate_percent(reviewed.len(), available.len()),
    }
}

fn claim_corpus_evaluation(
    samples: &[DecisionTrainingSample],
    source_claims: &[EarningsSourceClaim],
) -> ClaimCorpusEvaluation {
    let claim_refs = source_claims.iter().collect::<Vec<_>>();
    let lifecycle = resolve_claim_lifecycles(&claim_refs);
    let derived_comparisons = computed_claim_comparisons(&claim_refs, &lifecycle);
    let derived_ratios = computed_claim_ratios(&claim_refs, &lifecycle);
    let derived_ratio_trends = computed_claim_ratio_trends(&derived_ratios);
    let source_events = source_claims
        .iter()
        .map(|claim| claim.source_event_id.as_str())
        .collect::<BTreeSet<_>>();
    let symbols = source_claims
        .iter()
        .map(|claim| claim.symbol.to_ascii_uppercase())
        .collect::<BTreeSet<_>>();
    let periods = source_claims
        .iter()
        .map(|claim| normalize_claim_key(&claim.period))
        .collect::<BTreeSet<_>>();
    let mut periods_by_symbol: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut metrics: BTreeMap<String, (usize, BTreeSet<String>, BTreeSet<String>)> =
        BTreeMap::new();
    for claim in source_claims {
        periods_by_symbol
            .entry(claim.symbol.to_ascii_uppercase())
            .or_default()
            .insert(normalize_claim_key(&claim.period));
        let entry = metrics
            .entry(claim.metric_id.to_ascii_lowercase())
            .or_default();
        entry.0 += 1;
        entry.1.insert(claim.symbol.to_ascii_uppercase());
        entry.2.insert(normalize_claim_key(&claim.period));
    }
    let accepted_ids = samples
        .iter()
        .flat_map(|sample| sample.human_review.causal_link_reviews.iter())
        .filter(|review| review.verdict == CausalLinkVerdict::Accepted)
        .map(|review| review.observation_id.as_str())
        .collect::<BTreeSet<_>>();
    let rejected_ids = samples
        .iter()
        .flat_map(|sample| sample.human_review.causal_link_reviews.iter())
        .filter(|review| review.verdict == CausalLinkVerdict::Rejected)
        .map(|review| review.observation_id.as_str())
        .collect::<BTreeSet<_>>();
    let lifecycle_count = |status: CausalClaimLifecycleStatus| {
        lifecycle
            .values()
            .filter(|resolution| resolution.status == status)
            .count()
    };
    let symbols_with_repeated_periods = periods_by_symbol
        .values()
        .filter(|periods| periods.len() >= MIN_PROMOTION_PERIODS)
        .count();
    let status = if source_claims.is_empty() {
        "empty"
    } else if symbols_with_repeated_periods == symbols.len()
        && lifecycle_count(CausalClaimLifecycleStatus::Conflicted) == 0
    {
        "ready_for_human_causal_review"
    } else {
        "partial"
    };
    ClaimCorpusEvaluation {
        status: status.into(),
        claim_count: source_claims.len(),
        source_event_count: source_events.len(),
        distinct_symbols: symbols.len(),
        distinct_periods: periods.len(),
        symbols_with_repeated_periods,
        active_claims: lifecycle_count(CausalClaimLifecycleStatus::Active),
        superseded_claims: lifecycle_count(CausalClaimLifecycleStatus::Superseded),
        conflicted_claims: lifecycle_count(CausalClaimLifecycleStatus::Conflicted),
        withdrawn_claims: lifecycle_count(CausalClaimLifecycleStatus::Withdrawn),
        human_accepted_claims: source_claims
            .iter()
            .filter(|claim| accepted_ids.contains(claim.claim_id.as_str()))
            .count(),
        human_rejected_claims: source_claims
            .iter()
            .filter(|claim| rejected_ids.contains(claim.claim_id.as_str()))
            .count(),
        derived_comparison_count: derived_comparisons.len(),
        year_over_year_comparison_count: derived_comparisons
            .iter()
            .filter(|comparison| comparison.kind == CausalComparisonKind::YearOverYear)
            .count(),
        sequential_comparison_count: derived_comparisons
            .iter()
            .filter(|comparison| comparison.kind == CausalComparisonKind::SequentialQuarter)
            .count(),
        derived_ratio_count: derived_ratios.len(),
        gross_margin_ratio_count: derived_ratios
            .iter()
            .filter(|ratio| ratio.kind == CausalRatioKind::GrossMargin)
            .count(),
        operating_margin_ratio_count: derived_ratios
            .iter()
            .filter(|ratio| ratio.kind == CausalRatioKind::OperatingMargin)
            .count(),
        derived_ratio_trend_count: derived_ratio_trends.len(),
        year_over_year_ratio_trend_count: derived_ratio_trends
            .iter()
            .filter(|trend| trend.comparison_kind == CausalComparisonKind::YearOverYear)
            .count(),
        sequential_ratio_trend_count: derived_ratio_trends
            .iter()
            .filter(|trend| trend.comparison_kind == CausalComparisonKind::SequentialQuarter)
            .count(),
        earliest_published_at: source_claims.iter().map(|claim| claim.published_at).min(),
        latest_published_at: source_claims.iter().map(|claim| claim.published_at).max(),
        metric_coverage: metrics
            .into_iter()
            .map(
                |(metric_id, (claim_count, metric_symbols, metric_periods))| ClaimMetricCoverage {
                    metric_id,
                    claim_count,
                    distinct_symbols: metric_symbols.len(),
                    distinct_periods: metric_periods.len(),
                },
            )
            .collect(),
        note: "仅统计带 SEC/公司一手来源、明确期间与口径的结构化事实；同比/环比由两期有效事实计算，利润率只用同一 filing、同一期间的利润分子与收入分母，均保留原始来源，且在人工接受前不会晋级，也不会参与 RL 奖励。".into(),
    }
}

fn horizon_evaluation(samples: &[DecisionTrainingSample], horizon: u16) -> HorizonEvaluation {
    let outcomes = observed_outcomes(samples, horizon, None);
    HorizonEvaluation {
        horizon_market_sessions: horizon,
        observed_count: outcomes.len(),
        average_asset_return_percent: average_metric(&outcomes, |item| {
            item.asset_return_percent.unwrap()
        }),
        median_asset_return_percent: median_metric(&outcomes, |item| {
            item.asset_return_percent.unwrap()
        }),
        average_excess_return_percent: average_metric(&outcomes, |item| {
            item.excess_return_percent.unwrap()
        }),
        median_excess_return_percent: median_metric(&outcomes, |item| {
            item.excess_return_percent.unwrap()
        }),
        positive_excess_rate_percent: positive_rate(&outcomes),
        average_max_drawdown_percent: average_metric(&outcomes, |item| {
            item.max_drawdown_percent.unwrap()
        }),
    }
}

fn action_horizon_evaluation(
    samples: &[DecisionTrainingSample],
    action: ExposureAction,
    horizon: u16,
) -> ActionHorizonEvaluation {
    let outcomes = observed_outcomes(samples, horizon, Some(&action));
    let directional = outcomes
        .iter()
        .filter_map(|outcome| directional_success(&action, outcome.excess_return_percent.unwrap()))
        .collect::<Vec<_>>();
    ActionHorizonEvaluation {
        action,
        horizon_market_sessions: horizon,
        observed_count: outcomes.len(),
        average_excess_return_percent: average_metric(&outcomes, |item| {
            item.excess_return_percent.unwrap()
        }),
        positive_excess_rate_percent: positive_rate(&outcomes),
        average_max_drawdown_percent: average_metric(&outcomes, |item| {
            item.max_drawdown_percent.unwrap()
        }),
        directional_sample_count: directional.len(),
        directional_success_rate_percent: boolean_rate(&directional),
    }
}

fn confidence_horizon_evaluation(
    samples: &[DecisionTrainingSample],
    confidence: &str,
    horizon: u16,
) -> ConfidenceHorizonEvaluation {
    let matching = samples
        .iter()
        .filter(|sample| sample.state.decision.confidence == confidence)
        .filter_map(|sample| {
            sample
                .outcomes
                .iter()
                .find(|outcome| {
                    outcome.horizon_market_sessions == horizon
                        && outcome.status == OutcomeStatus::Observed
                })
                .map(|outcome| (sample, outcome))
        })
        .collect::<Vec<_>>();
    let directional = matching
        .iter()
        .filter_map(|(sample, outcome)| {
            directional_success(
                &sample.selected_action,
                outcome.excess_return_percent.unwrap(),
            )
        })
        .collect::<Vec<_>>();
    ConfidenceHorizonEvaluation {
        confidence: confidence.to_string(),
        horizon_market_sessions: horizon,
        observed_count: matching.len(),
        directional_sample_count: directional.len(),
        directional_success_rate_percent: boolean_rate(&directional),
        average_excess_return_percent: if matching.is_empty() {
            None
        } else {
            Some(round4(
                matching
                    .iter()
                    .map(|(_, outcome)| outcome.excess_return_percent.unwrap())
                    .sum::<f64>()
                    / matching.len() as f64,
            ))
        },
    }
}

fn correction_comparison(samples: &[DecisionTrainingSample], horizon: u16) -> CorrectionComparison {
    let mut comparison = CorrectionComparison {
        horizon_market_sessions: horizon,
        corrected_sample_count: 0,
        comparable_direction_count: 0,
        improved_direction_count: 0,
        worsened_direction_count: 0,
        unchanged_direction_count: 0,
        not_comparable_count: 0,
    };
    for sample in samples.iter().filter(|sample| {
        sample.human_review.status == HumanReviewStatus::Corrected
            && sample.human_review.corrected_action.is_some()
    }) {
        let Some(outcome) = sample.outcomes.iter().find(|outcome| {
            outcome.horizon_market_sessions == horizon && outcome.status == OutcomeStatus::Observed
        }) else {
            continue;
        };
        comparison.corrected_sample_count += 1;
        let excess = outcome.excess_return_percent.unwrap();
        let original = directional_success(&sample.selected_action, excess);
        let corrected = sample
            .human_review
            .corrected_action
            .as_ref()
            .and_then(|action| directional_success(action, excess));
        match (original, corrected) {
            (Some(original), Some(corrected)) => {
                comparison.comparable_direction_count += 1;
                match (original, corrected) {
                    (false, true) => comparison.improved_direction_count += 1,
                    (true, false) => comparison.worsened_direction_count += 1,
                    _ => comparison.unchanged_direction_count += 1,
                }
            }
            _ => comparison.not_comparable_count += 1,
        }
    }
    comparison
}

fn directional_success(action: &ExposureAction, excess_return_percent: f64) -> Option<bool> {
    match action {
        ExposureAction::IncreaseCandidate => Some(excess_return_percent > 0.0),
        ExposureAction::ReduceCandidate => Some(excess_return_percent < 0.0),
        ExposureAction::Maintain | ExposureAction::ResearchOnly => None,
    }
}

fn boolean_rate(values: &[bool]) -> Option<f64> {
    (!values.is_empty())
        .then(|| rate_percent(values.iter().filter(|value| **value).count(), values.len()))
}

fn observed_outcomes<'a>(
    samples: &'a [DecisionTrainingSample],
    horizon: u16,
    action: Option<&ExposureAction>,
) -> Vec<&'a ForwardOutcomeLabel> {
    samples
        .iter()
        .filter(|sample| action.is_none_or(|action| &sample.selected_action == action))
        .filter_map(|sample| {
            sample.outcomes.iter().find(|outcome| {
                outcome.horizon_market_sessions == horizon
                    && outcome.status == OutcomeStatus::Observed
            })
        })
        .collect()
}

fn average_metric(
    outcomes: &[&ForwardOutcomeLabel],
    metric: impl Fn(&ForwardOutcomeLabel) -> f64,
) -> Option<f64> {
    (!outcomes.is_empty()).then(|| {
        round4(outcomes.iter().map(|outcome| metric(outcome)).sum::<f64>() / outcomes.len() as f64)
    })
}

fn median_metric(
    outcomes: &[&ForwardOutcomeLabel],
    metric: impl Fn(&ForwardOutcomeLabel) -> f64,
) -> Option<f64> {
    if outcomes.is_empty() {
        return None;
    }
    let mut values = outcomes
        .iter()
        .map(|outcome| metric(outcome))
        .collect::<Vec<_>>();
    values.sort_by(f64::total_cmp);
    let middle = values.len() / 2;
    let median = if values.len() % 2 == 0 {
        (values[middle - 1] + values[middle]) / 2.0
    } else {
        values[middle]
    };
    Some(round4(median))
}

fn positive_rate(outcomes: &[&ForwardOutcomeLabel]) -> Option<f64> {
    (!outcomes.is_empty()).then(|| {
        rate_percent(
            outcomes
                .iter()
                .filter(|outcome| outcome.excess_return_percent.unwrap() > 0.0)
                .count(),
            outcomes.len(),
        )
    })
}

fn rate_percent(numerator: usize, denominator: usize) -> f64 {
    if denominator == 0 {
        0.0
    } else {
        round4(numerator as f64 / denominator as f64 * 100.0)
    }
}

fn offline_evidence_gate(
    samples: &[DecisionTrainingSample],
    observed_250_session_samples: usize,
) -> OfflineEvidenceGate {
    const MIN_SAMPLES: usize = 100;
    const MIN_NON_OVERLAPPING: usize = 30;
    const MIN_SYMBOLS: usize = 20;
    const MIN_QUARTERS: usize = 8;
    const MIN_REVIEW_RATE: f64 = 80.0;
    let matured = samples
        .iter()
        .filter(|sample| {
            sample.outcomes.iter().any(|outcome| {
                outcome.horizon_market_sessions == 250 && outcome.status == OutcomeStatus::Observed
            })
        })
        .collect::<Vec<_>>();
    let observed_review_rate_percent = rate_percent(
        matured
            .iter()
            .filter(|sample| sample.human_review.status != HumanReviewStatus::Pending)
            .count(),
        matured.len(),
    );
    let observed_non_overlapping_250_session_episodes =
        non_overlapping_250_session_episodes(&matured);
    let observed_distinct_symbols = unique_strings(
        matured
            .iter()
            .map(|sample| sample.state.symbol.clone())
            .collect(),
    )
    .len();
    let observed_decision_quarters = unique_strings(
        matured
            .iter()
            .map(|sample| {
                let date = sample.state.decision_date_beijing;
                format!("{}-Q{}", date.year(), (date.month0() / 3) + 1)
            })
            .collect(),
    )
    .len();
    let mut reasons = Vec::new();
    if observed_250_session_samples < MIN_SAMPLES {
        reasons.push(format!(
            "250交易日完整样本不足：{observed_250_session_samples}/{MIN_SAMPLES}"
        ));
    }
    if observed_non_overlapping_250_session_episodes < MIN_NON_OVERLAPPING {
        reasons.push(format!(
            "非重叠长期样本不足：{observed_non_overlapping_250_session_episodes}/{MIN_NON_OVERLAPPING}"
        ));
    }
    if observed_distinct_symbols < MIN_SYMBOLS {
        reasons.push(format!(
            "公司覆盖不足：{observed_distinct_symbols}/{MIN_SYMBOLS}"
        ));
    }
    if observed_decision_quarters < MIN_QUARTERS {
        reasons.push(format!(
            "市场时间分散不足：{observed_decision_quarters}/{MIN_QUARTERS} 个季度"
        ));
    }
    if observed_review_rate_percent < MIN_REVIEW_RATE {
        reasons.push(format!(
            "人工复核率不足：{observed_review_rate_percent:.1}%/{MIN_REVIEW_RATE:.1}%"
        ));
    }
    OfflineEvidenceGate {
        status: if reasons.is_empty() {
            "eligible_for_reward_design_review"
        } else {
            "insufficient_evidence"
        }
        .to_string(),
        minimum_250_session_samples: MIN_SAMPLES,
        observed_250_session_samples,
        minimum_non_overlapping_250_session_episodes: MIN_NON_OVERLAPPING,
        observed_non_overlapping_250_session_episodes,
        minimum_distinct_symbols: MIN_SYMBOLS,
        observed_distinct_symbols,
        minimum_decision_quarters: MIN_QUARTERS,
        observed_decision_quarters,
        minimum_review_rate_percent: MIN_REVIEW_RATE,
        observed_review_rate_percent,
        reasons,
        scope: "该门槛只允许进入奖励函数设计审查，不允许实盘、影子组合或自主执行。".to_string(),
    }
}

fn shadow_policy_protocol(
    samples: &[DecisionTrainingSample],
    evidence_gate: &OfflineEvidenceGate,
) -> ShadowPolicyProtocol {
    let constraints = ShadowPolicyConstraints {
        virtual_notional_usd: 1_000_000.0,
        long_only: true,
        common_stock_only: true,
        options_allowed: false,
        leverage_allowed: false,
        shorting_allowed: false,
        maximum_single_name_weight_percent: 5.0,
        maximum_theme_weight_percent: 20.0,
        maximum_gross_exposure_percent: 60.0,
        minimum_cash_weight_percent: 40.0,
        maximum_position_count: 10,
        rebalance_frequency: "每周一次；重大证伪只允许提前降低，不允许追涨加仓".to_string(),
        execution_assumption: "信号形成后的下一个完整纽约交易日，以可复现的调整后收盘价模拟"
            .to_string(),
        slippage_bps_per_side: 25.0,
    };
    let review_requirements = vec![
        ShadowProtocolRequirement {
            requirement_id: "point_in_time_immutable_revisions".to_string(),
            label: "点时不可篡改".to_string(),
            definition: "每次决策只使用当时可得证据，并以新修订追加，禁止覆盖历史。".to_string(),
        },
        ShadowProtocolRequirement {
            requirement_id: "long_only_common_stock".to_string(),
            label: "仅多头普通股".to_string(),
            definition: "只允许普通股多头；期权、杠杆和做空全部关闭。".to_string(),
        },
        ShadowProtocolRequirement {
            requirement_id: "single_name_and_theme_caps".to_string(),
            label: "公司与主题限额".to_string(),
            definition: format!(
                "单一公司不超过 {:.1}%，单一主题不超过 {:.1}%。",
                constraints.maximum_single_name_weight_percent,
                constraints.maximum_theme_weight_percent
            ),
        },
        ShadowProtocolRequirement {
            requirement_id: "gross_cash_and_position_caps".to_string(),
            label: "总仓位与现金约束".to_string(),
            definition: format!(
                "总敞口不超过 {:.1}%，现金不低于 {:.1}%，持仓不超过 {} 个。",
                constraints.maximum_gross_exposure_percent,
                constraints.minimum_cash_weight_percent,
                constraints.maximum_position_count
            ),
        },
        ShadowProtocolRequirement {
            requirement_id: "weekly_rebalance_with_falsification_exit".to_string(),
            label: "固定调仓与证伪退出".to_string(),
            definition: constraints.rebalance_frequency.clone(),
        },
        ShadowProtocolRequirement {
            requirement_id: "next_session_execution_and_cost".to_string(),
            label: "下一交易日与成本".to_string(),
            definition: format!(
                "{}；每边计入 {:.1} 个基点摩擦。",
                constraints.execution_assumption, constraints.slippage_bps_per_side
            ),
        },
        ShadowProtocolRequirement {
            requirement_id: "spy_benchmark_and_counterfactuals".to_string(),
            label: "SPY 基准与反事实".to_string(),
            definition: "以 SPY 为基准，并与空仓、等权、规则化持有和旧策略分别比较。".to_string(),
        },
        ShadowProtocolRequirement {
            requirement_id: "no_ledger_orders_or_broker".to_string(),
            label: "无账本、订单或券商".to_string(),
            definition: "本协议审批本身不创建影子账本、不生成订单、不连接券商，也不授权交易。"
                .to_string(),
        },
    ];
    let protocol_ready = evidence_gate.status == "eligible_for_reward_design_review";
    let mut readiness_reasons = evidence_gate.reasons.clone();
    if !protocol_ready {
        readiness_reasons.push(
            "长期样本门槛尚未通过：当前只能检查协议和候选阻断，不能启动影子组合。".to_string(),
        );
    }
    readiness_reasons
        .push("奖励函数仍为关闭状态，协议审查通过后仍需单独设计、回测和批准。".to_string());

    let mut latest_by_symbol: BTreeMap<&str, &DecisionTrainingSample> = BTreeMap::new();
    for sample in samples {
        let replace = latest_by_symbol
            .get(sample.state.symbol.as_str())
            .is_none_or(|current| sample.observed_at > current.observed_at);
        if replace {
            latest_by_symbol.insert(sample.state.symbol.as_str(), sample);
        }
    }
    let candidates = latest_by_symbol
        .into_values()
        .map(|sample| shadow_policy_candidate(sample, protocol_ready))
        .collect::<Vec<_>>();

    ShadowPolicyProtocol {
        policy_version: SHADOW_POLICY_VERSION.to_string(),
        status: if protocol_ready {
            "eligible_for_protocol_review"
        } else {
            "insufficient_evidence"
        }
        .to_string(),
        authorization: "not_authorized".to_string(),
        execution_mode: "read_only_protocol_not_started".to_string(),
        benchmark_symbol: OUTCOME_BENCHMARK_SYMBOL.to_string(),
        constraints,
        review_requirements,
        readiness_reasons: unique_strings(readiness_reasons),
        candidates,
        scope:
            "仅生成点时研究候选和阻断理由；不创建持仓、不生成订单、不连接券商，也不构成投资建议。"
                .to_string(),
    }
}

fn shadow_policy_candidate(
    sample: &DecisionTrainingSample,
    protocol_ready: bool,
) -> ShadowPolicyCandidate {
    let state = &sample.state;
    let mut blocking_reasons = Vec::new();
    if !protocol_ready {
        blocking_reasons.push("全局长期证据门槛未通过".to_string());
    }
    if state.decision.action != ExposureAction::IncreaseCandidate
        || state.decision.zone != ResearchZone::Opportunity
    {
        blocking_reasons.push("当前点时决策不是机会区加仓候选".to_string());
    }
    if !matches!(state.decision.confidence.as_str(), "medium" | "high") {
        blocking_reasons.push("有效置信度低于中等".to_string());
    }
    if state.data_status != "live" {
        blocking_reasons.push("公司数据不是实时核验状态".to_string());
    }
    if state.decision_completeness.policy_version != DECISION_COMPLETENESS_POLICY_VERSION
        || !state.decision_completeness.directional_research_ready
    {
        blocking_reasons.push(
            "第一性原理、公司价值捕获、财务、估值或证伪链尚未达到方向研究完整性门槛".to_string(),
        );
    }
    if state.crowding.status != MeasurementStatus::Measured {
        blocking_reasons.push("拥挤度尚未完成价格、估值、资金、期权与注意力的完整核验".to_string());
    }
    let valuation_current = state.valuation.as_ref().is_some_and(|valuation| {
        NaiveDate::parse_from_str(&valuation.as_of, "%Y-%m-%d")
            .ok()
            .is_some_and(|as_of| {
                as_of <= state.decision_date_beijing
                    && state
                        .decision_date_beijing
                        .signed_duration_since(as_of)
                        .num_days()
                        <= 7
            })
            && valuation.current_price.is_finite()
            && valuation.current_price > 0.0
            && valuation.base_case.is_finite()
            && valuation.bull_case >= valuation.base_case
            && valuation.expected_upside_percent >= 10.0
    });
    if !valuation_current {
        blocking_reasons.push("缺少七日内完成复核且预期空间至少 10% 的三情景估值".to_string());
    }
    if state.market_regime.status != MarketRegimeStatus::Observed {
        blocking_reasons.push("缺少决策前冻结的宏观环境快照".to_string());
    } else if state.market_regime.label == "stress" {
        blocking_reasons.push("点时宏观环境处于压力状态".to_string());
    }
    let causal = &state.decision.causal_confidence;
    if causal.blocked_conflict_count > 0
        || causal.blocked_human_rejection_count > 0
        || causal.blocked_falsification_count > 0
    {
        blocking_reasons.push("存在未解决的因果冲突、人工拒绝或证伪".to_string());
    }
    if sample.human_review.status != HumanReviewStatus::Accepted
        || sample.human_review.thesis_verdict != ThesisReviewVerdict::Supported
    {
        blocking_reasons.push("该点时决策尚未被人工明确接受并确认论点成立".to_string());
    }

    let (target_weight_min_percent, target_weight_max_percent) = if blocking_reasons.is_empty() {
        if state.decision.confidence == "high" {
            (Some(3.0), Some(5.0))
        } else {
            (Some(2.0), Some(3.0))
        }
    } else {
        (None, None)
    };
    ShadowPolicyCandidate {
        symbol: state.symbol.clone(),
        company_name: state.company_name.clone(),
        theme: state.theme.clone(),
        sample_id: sample.sample_id.clone(),
        decision_at: state.decision_at,
        action: state.decision.action.clone(),
        zone: state.decision.zone.clone(),
        confidence: state.decision.confidence.clone(),
        market_regime: state.market_regime.label.clone(),
        status: if blocking_reasons.is_empty() {
            "eligible_for_protocol_review"
        } else {
            "blocked"
        }
        .to_string(),
        target_weight_min_percent,
        target_weight_max_percent,
        blocking_reasons,
    }
}

