#[cfg(test)]
fn assess_causal_component_drift(
    snapshot: &CausalComponentDriftSnapshot,
) -> CausalComponentDriftAssessment {
    let mut warning_reasons = Vec::new();
    let mut disable_reasons = Vec::new();
    if snapshot.schema_change_detected {
        disable_reasons.push("输入或标签契约发生未审核变更".to_string());
    }
    if snapshot.future_leakage_detected {
        disable_reasons.push("检测到未来信息泄漏".to_string());
    }
    let metrics = [
        (
            "来源层级分布漂移",
            snapshot.source_mix_js_divergence,
            0.10,
            0.20,
        ),
        (
            "第一性原理驱动分布漂移",
            snapshot.driver_mix_js_divergence,
            0.10,
            0.20,
        ),
        (
            "拒答率变化",
            snapshot.abstention_rate_change.abs(),
            0.08,
            0.15,
        ),
        (
            "在线校准误差",
            snapshot.expected_calibration_error,
            0.10,
            0.15,
        ),
        (
            "人工复核分歧率",
            snapshot.human_disagreement_rate,
            0.15,
            0.25,
        ),
    ];
    for (label, value, warning, disable) in metrics {
        if !value.is_finite() || value < 0.0 || value > 1.0 {
            disable_reasons.push(format!("{label}缺失或越界"));
        } else if value > disable {
            disable_reasons.push(format!("{label}超过停用阈值 {disable:.2}"));
        } else if value > warning {
            warning_reasons.push(format!("{label}超过警戒阈值 {warning:.2}"));
        }
    }
    let (status, reasons, component_use_allowed, promotion_allowed) = if !disable_reasons.is_empty()
    {
        (
            CausalComponentDriftStatus::DisableComponent,
            disable_reasons,
            false,
            false,
        )
    } else if snapshot.audited_examples < 200 {
        (
            CausalComponentDriftStatus::InsufficientAuditCoverage,
            vec![format!(
                "滚动窗口人工审计样本不足：{}/200",
                snapshot.audited_examples
            )],
            false,
            false,
        )
    } else if !warning_reasons.is_empty() {
        (
            CausalComponentDriftStatus::WarningFreezePromotion,
            warning_reasons,
            true,
            false,
        )
    } else {
        (CausalComponentDriftStatus::Healthy, Vec::new(), true, true)
    };
    CausalComponentDriftAssessment {
        policy_version: CAUSAL_COMPONENT_DRIFT_POLICY_VERSION.to_string(),
        status,
        reasons,
        component_use_allowed,
        promotion_allowed,
        decision_agent_deployment_authorized: false,
        trading_authorized: false,
    }
}

#[cfg(test)]
fn assess_causal_component_promotion(
    dataset: &CausalTrainingDatasetReport,
    result: &CausalBlindEvaluationAggregate,
) -> CausalComponentPromotionAssessment {
    let mut blocking_reasons = Vec::new();
    if result.dataset_fingerprint_sha256 != dataset.dataset_fingerprint_sha256 {
        blocking_reasons.push("盲评结果不属于当前不可变数据集指纹".to_string());
    }
    if result.candidate_experiment_ids.len() < 3 || result.distinct_random_seeds < 3 {
        blocking_reasons.push("候选实验少于三个独立随机种子".to_string());
    }
    if result.frozen_baseline_experiment_id.trim().is_empty() {
        blocking_reasons.push("缺少同数据集冻结基线".to_string());
    }
    if result.independent_evaluator_id.trim().is_empty() {
        blocking_reasons.push("缺少独立封存测试评估器身份".to_string());
    }
    if result.holdout_labels_visible_to_training_worker {
        blocking_reasons.push("训练进程接触了封存测试标签".to_string());
    }
    if result.sandbox_violation_detected {
        blocking_reasons.push("实验发生沙箱越权".to_string());
    }
    if result.future_leakage_detected {
        blocking_reasons.push("实验检测到未来信息泄漏".to_string());
    }
    if !result.company_split_isolation_verified {
        blocking_reasons.push("盲评未验证公司级数据隔离".to_string());
    }
    let finite_metrics = [
        result.validation_macro_f1,
        result.holdout_macro_f1,
        result.holdout_worst_class_recall,
        result.holdout_expected_calibration_error,
        result.frozen_baseline_holdout_macro_f1,
    ];
    if finite_metrics
        .into_iter()
        .any(|value| !value.is_finite() || !(0.0..=1.0).contains(&value))
    {
        blocking_reasons.push("盲评指标缺失或越界".to_string());
    } else {
        if result.validation_macro_f1 < 0.75 {
            blocking_reasons.push("验证集宏平均 F1 低于 0.75".to_string());
        }
        if result.holdout_macro_f1 < 0.72 {
            blocking_reasons.push("封存测试集宏平均 F1 低于 0.72".to_string());
        }
        if result.holdout_worst_class_recall < 0.50 {
            blocking_reasons.push("封存测试集最弱类别召回率低于 0.50".to_string());
        }
        if result.holdout_expected_calibration_error > 0.10 {
            blocking_reasons.push("封存测试集校准误差高于 0.10".to_string());
        }
        if result.holdout_macro_f1 - result.frozen_baseline_holdout_macro_f1 < 0.03 {
            blocking_reasons.push("相对冻结基线的 F1 提升不足 0.03".to_string());
        }
        if (result.validation_macro_f1 - result.holdout_macro_f1).abs() > 0.08 {
            blocking_reasons.push("验证集与封存测试集差距超过 0.08".to_string());
        }
    }
    let eligible_for_component_review = blocking_reasons.is_empty();
    CausalComponentPromotionAssessment {
        policy_version: CAUSAL_BLIND_EVALUATION_POLICY_VERSION.to_string(),
        status: if eligible_for_component_review {
            "eligible_for_human_component_review"
        } else {
            "blocked"
        }
        .to_string(),
        eligible_for_component_review,
        blocking_reasons,
        component_deployment_authorized: false,
        decision_agent_deployment_authorized: false,
        shadow_portfolio_authorized: false,
        trading_authorized: false,
        scope: "这项评估只判断因果证据分类组件是否可以送交人工晋级复核；即使指标通过，也不会自动部署或获得任何投资执行权限。".to_string(),
    }
}

fn non_overlapping_250_session_episodes(samples: &[&DecisionTrainingSample]) -> usize {
    let mut by_symbol: BTreeMap<&str, Vec<(NaiveDate, NaiveDate)>> = BTreeMap::new();
    for sample in samples {
        let Some(outcome) = sample.outcomes.iter().find(|outcome| {
            outcome.horizon_market_sessions == 250 && outcome.status == OutcomeStatus::Observed
        }) else {
            continue;
        };
        if let (Some(start), Some(end)) = (outcome.period_start, outcome.period_end) {
            by_symbol
                .entry(&sample.state.symbol)
                .or_default()
                .push((start, end));
        }
    }
    by_symbol
        .values_mut()
        .map(|episodes| {
            episodes.sort_unstable();
            let mut selected = 0usize;
            let mut last_end = None;
            for (start, end) in episodes.iter() {
                if last_end.is_none_or(|last_end| *start > last_end) {
                    selected += 1;
                    last_end = Some(*end);
                }
            }
            selected
        })
        .sum()
}

async fn read_replay_directory(
    directory: &Path,
    symbol: &str,
    limit: usize,
    skip_invalid: bool,
) -> Result<Vec<DecisionTrainingSample>, String> {
    Ok(
        read_replay_directory_report(directory, symbol, limit, skip_invalid)
            .await?
            .samples,
    )
}

async fn read_replay_directory_report(
    directory: &Path,
    symbol: &str,
    limit: usize,
    skip_invalid: bool,
) -> Result<ReplayDirectoryRead, String> {
    let mut entries = match tokio::fs::read_dir(&directory).await {
        Ok(entries) => entries,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok(ReplayDirectoryRead {
                samples: Vec::new(),
                quarantine_warnings: Vec::new(),
            });
        }
        Err(error) => return Err(error.to_string()),
    };
    let mut source_hydrated_samples = Vec::new();
    let mut quarantine_warnings = Vec::new();
    while let Some(entry) = entries
        .next_entry()
        .await
        .map_err(|error| error.to_string())?
    {
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("json") {
            continue;
        }
        let bytes = match tokio::fs::read(&path).await {
            Ok(bytes) => bytes,
            Err(_) if skip_invalid => {
                quarantine_warnings.push(replay_quarantine_warning(&path, "历史样本文件无法读取"));
                continue;
            }
            Err(error) => return Err(format!("{}: {error}", path.display())),
        };
        let mut sample = match serde_json::from_slice::<DecisionTrainingSample>(&bytes) {
            Ok(sample) => sample,
            Err(error) if skip_invalid => {
                quarantine_warnings.push(replay_quarantine_warning(
                    &path,
                    &format!("历史样本格式无效：{error}"),
                ));
                continue;
            }
            Err(error) => return Err(format!("{}: {error}", path.display())),
        };
        let decision_root = directory
            .parent()
            .and_then(Path::parent)
            .ok_or_else(|| "training directory is outside decision storage".to_string())?;
        let review_directory = decision_root
            .join("reviews")
            .join(symbol)
            .join(&sample.sample_id);
        if let Err(error) =
            hydrate_latest_review_from_directory(&review_directory, &mut sample).await
        {
            if skip_invalid {
                quarantine_warnings.push(replay_quarantine_warning(
                    &path,
                    &format!("人工复核记录无效：{error}"),
                ));
                continue;
            }
            return Err(format!("{}: {error}", path.display()));
        }
        let source_review_directory = decision_root
            .join("source-reviews")
            .join(symbol)
            .join(&sample.sample_id);
        if let Err(error) = hydrate_latest_causal_source_reviews_from_directory(
            &source_review_directory,
            &mut sample,
        )
        .await
        {
            if skip_invalid {
                quarantine_warnings.push(replay_quarantine_warning(
                    &path,
                    &format!("来源核验记录无效：{error}"),
                ));
                continue;
            }
            return Err(format!("{}: {error}", path.display()));
        }
        if let Err(error) = validate_training_sample(&sample) {
            if skip_invalid {
                quarantine_warnings.push(replay_quarantine_warning(&path, &error));
                continue;
            }
            return Err(format!("{}: {error}", path.display()));
        }
        if sample.state.symbol != symbol {
            if skip_invalid {
                quarantine_warnings.push(replay_quarantine_warning(
                    &path,
                    "样本代码与所在公司目录不一致",
                ));
                continue;
            }
            return Err(format!(
                "{}: symbol does not match replay directory",
                path.display()
            ));
        }
        source_hydrated_samples.push((path, sample));
    }
    let source_review_context = causal_source_review_context_from_iter(
        source_hydrated_samples.iter().map(|(_, sample)| sample),
    );
    let decision_root = directory
        .parent()
        .and_then(Path::parent)
        .ok_or_else(|| "training directory is outside decision storage".to_string())?;
    let mut samples = Vec::new();
    for (path, mut sample) in source_hydrated_samples {
        let causal_review_directory = decision_root
            .join("causal-reviews")
            .join(symbol)
            .join(&sample.sample_id);
        if let Err(error) = hydrate_latest_causal_reviews_from_directory_with_context(
            &causal_review_directory,
            &mut sample,
            Some(&source_review_context),
        )
        .await
        {
            if skip_invalid {
                quarantine_warnings.push(replay_quarantine_warning(
                    &path,
                    &format!("因果复核记录无效：{error}"),
                ));
                continue;
            }
            return Err(format!("{}: {error}", path.display()));
        }
        if let Err(error) = validate_training_sample(&sample) {
            if skip_invalid {
                quarantine_warnings.push(replay_quarantine_warning(&path, &error));
                continue;
            }
            return Err(format!("{}: {error}", path.display()));
        }
        samples.push(sample);
    }
    if !quarantine_warnings.is_empty() {
        warn!(
            %symbol,
            quarantined_count = quarantine_warnings.len(),
            "invalid training samples quarantined from replay reads"
        );
    }
    samples.sort_by(|left, right| {
        left.observed_at
            .cmp(&right.observed_at)
            .then_with(|| left.sample_id.cmp(&right.sample_id))
    });
    if samples
        .windows(2)
        .any(|pair| pair[0].sample_id == pair[1].sample_id)
    {
        return Err("replay contains duplicate sample ids".to_string());
    }
    if samples.len() > limit {
        samples.drain(..samples.len() - limit);
    }
    Ok(ReplayDirectoryRead {
        samples,
        quarantine_warnings,
    })
}

fn replay_quarantine_warning(path: &Path, reason: &str) -> ReplayQuarantineWarning {
    let reason = match reason {
        "financial verification provenance is invalid" => {
            "财务验证的来源索引、逐条来源明细、计算口径或决策时点不一致"
        }
        "unsupported training sample schema" => "历史样本版本已不受当前校验器支持",
        other => other,
    };
    ReplayQuarantineWarning {
        file_name: path
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or("unknown.json")
            .to_string(),
        reason: reason.to_string(),
    }
}

#[allow(dead_code)]
async fn legacy_label_mature_training_samples_disabled(
    state: &AppState,
    snapshots: &[InvestmentDecisionSnapshot],
) -> Result<(), String> {
    let keys = state.core.config.fmp.effective_key_pool().keys().to_vec();
    if keys.is_empty() {
        return Ok(());
    }
    let labelled_at = Utc::now();
    let completed_market_date = latest_completed_new_york_market_date(labelled_at);
    let mut candidates = Vec::new();
    for snapshot in snapshots {
        let samples = read_replay_samples(state, &snapshot.symbol, MAX_REPLAY_LIMIT).await?;
        if samples
            .iter()
            .any(|sample| sample_may_have_matured(sample, completed_market_date))
        {
            candidates.push((snapshot.symbol.clone(), samples));
        }
    }
    if candidates.is_empty() {
        return Ok(());
    }
    let earliest = candidates
        .iter()
        .flat_map(|(_, samples)| samples.iter())
        .filter(|sample| sample_may_have_matured(sample, completed_market_date))
        .map(|sample| earliest_outcome_start_date(sample.observed_at))
        .min()
        .ok_or_else(|| "outcome label candidates had no start date".to_string())?;
    let benchmark = fetch_adjusted_bars(
        state,
        &keys,
        OUTCOME_BENCHMARK_SYMBOL,
        earliest,
        completed_market_date,
    )
    .await?;
    if !claim_daily_label_run(state, labelled_at.with_timezone(&Shanghai).date_naive()).await? {
        return Ok(());
    }

    let mut updated = 0usize;
    let fetched = stream::iter(candidates.into_iter().map(|(symbol, samples)| {
        let keys = &keys;
        async move {
            let symbol_earliest = samples
                .iter()
                .filter(|sample| sample_may_have_matured(sample, completed_market_date))
                .map(|sample| earliest_outcome_start_date(sample.observed_at))
                .min()
                .unwrap_or(earliest);
            let result =
                fetch_adjusted_bars(state, keys, &symbol, symbol_earliest, completed_market_date)
                    .await;
            (symbol, samples, result)
        }
    }))
    .buffer_unordered(4)
    .collect::<Vec<_>>()
    .await;
    for (symbol, mut samples, asset) in fetched {
        let asset = match asset {
            Ok(bars) => bars,
            Err(error) => {
                warn!(%symbol, %error, "outcome label price history unavailable");
                continue;
            }
        };
        for sample in &mut samples {
            if !sample_may_have_matured(sample, completed_market_date)
                || !label_sample_from_bars(
                    sample,
                    &asset,
                    &benchmark,
                    labelled_at,
                    completed_market_date,
                )
            {
                continue;
            }
            validate_training_sample(sample)?;
            let path = training_path(state, sample);
            atomic_write_json(&path, sample).await?;
            updated += 1;
        }
    }
    info!(updated, "investment decision outcome labels updated");
    Ok(())
}

fn sample_may_have_matured(
    sample: &DecisionTrainingSample,
    completed_market_date: NaiveDate,
) -> bool {
    sample.outcomes.iter().any(|outcome| {
        outcome.status == OutcomeStatus::PendingMarketSessions
            && completed_market_date
                .signed_duration_since(sample.state.decision_date_beijing)
                .num_days()
                >= i64::from(outcome.horizon_market_sessions)
    })
}

async fn claim_daily_label_run(state: &AppState, date: NaiveDate) -> Result<bool, String> {
    let directory = decision_root(state).join("label-runs");
    tokio::fs::create_dir_all(&directory)
        .await
        .map_err(|error| error.to_string())?;
    let path = directory.join(format!("{date}.lock"));
    match tokio::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(path)
        .await
    {
        Ok(_) => Ok(true),
        Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => Ok(false),
        Err(error) => Err(error.to_string()),
    }
}

fn latest_completed_new_york_market_date(now: DateTime<Utc>) -> NaiveDate {
    let local = now.with_timezone(&New_York);
    if local.hour() >= 16 {
        local.date_naive()
    } else {
        local.date_naive() - Duration::days(1)
    }
}

fn earliest_outcome_start_date(decision_at: DateTime<Utc>) -> NaiveDate {
    let local = decision_at.with_timezone(&New_York);
    if local.hour() < 16 {
        local.date_naive()
    } else {
        local.date_naive() + Duration::days(1)
    }
}

fn label_sample_from_bars(
    sample: &mut DecisionTrainingSample,
    asset: &[AdjustedMarketBar],
    benchmark: &[AdjustedMarketBar],
    labelled_at: DateTime<Utc>,
    completed_market_date: NaiveDate,
) -> bool {
    let benchmark_by_date = benchmark
        .iter()
        .map(|bar| (bar.date, bar.adjusted_close))
        .collect::<BTreeMap<_, _>>();
    let earliest = earliest_outcome_start_date(sample.observed_at);
    let paired = asset
        .iter()
        .filter(|bar| bar.date >= earliest && bar.date <= completed_market_date)
        .filter_map(|bar| {
            benchmark_by_date
                .get(&bar.date)
                .map(|benchmark_close| (bar.date, bar.adjusted_close, *benchmark_close))
        })
        .collect::<Vec<_>>();
    let mut changed = false;
    for outcome in &mut sample.outcomes {
        if outcome.status != OutcomeStatus::PendingMarketSessions {
            continue;
        }
        let horizon = usize::from(outcome.horizon_market_sessions);
        if paired.len() <= horizon {
            continue;
        }
        let window = &paired[..=horizon];
        let (start_date, asset_start, benchmark_start) = window[0];
        let (end_date, asset_end, benchmark_end) = window[horizon];
        let asset_return = percent_return(asset_start, asset_end);
        let benchmark_return = percent_return(benchmark_start, benchmark_end);
        outcome.status = OutcomeStatus::Observed;
        outcome.period_start = Some(start_date);
        outcome.period_end = Some(end_date);
        outcome.market_sessions_observed = Some(outcome.horizon_market_sessions);
        outcome.labelled_at = Some(labelled_at);
        outcome.asset_start_price = Some(round4(asset_start));
        outcome.asset_end_price = Some(round4(asset_end));
        outcome.asset_return_percent = Some(round4(asset_return));
        outcome.benchmark_symbol = Some(OUTCOME_BENCHMARK_SYMBOL.to_string());
        outcome.benchmark_start_price = Some(round4(benchmark_start));
        outcome.benchmark_end_price = Some(round4(benchmark_end));
        outcome.benchmark_return_percent = Some(round4(benchmark_return));
        outcome.excess_return_percent = Some(round4(asset_return - benchmark_return));
        outcome.max_drawdown_percent = Some(round4(max_drawdown_percent(
            window.iter().map(|(_, price, _)| *price),
        )));
        outcome.market_data_source = Some(format!(
            "{OUTCOME_PRICE_SOURCE}; benchmark_policy={OUTCOME_BENCHMARK_POLICY}"
        ));
        outcome.invalid_reason = None;
        changed = true;
    }
    changed
}

fn percent_return(start: f64, end: f64) -> f64 {
    (end / start - 1.0) * 100.0
}

fn max_drawdown_percent(prices: impl IntoIterator<Item = f64>) -> f64 {
    let mut peak = 0.0_f64;
    let mut max_drawdown = 0.0_f64;
    for price in prices {
        peak = peak.max(price);
        if peak > 0.0 {
            max_drawdown = max_drawdown.min((price / peak - 1.0) * 100.0);
        }
    }
    max_drawdown
}

fn round4(value: f64) -> f64 {
    (value * 10_000.0).round() / 10_000.0
}

async fn fetch_adjusted_bars(
    state: &AppState,
    keys: &[String],
    symbol: &str,
    from: NaiveDate,
    to: NaiveDate,
) -> Result<Vec<AdjustedMarketBar>, String> {
    let base = fmp_legacy_base(&state.core.config.fmp.base_url);
    let encoded_symbol = utf8_percent_encode(symbol, NON_ALPHANUMERIC).to_string();
    let mut last_error = "no FMP key available".to_string();
    for key in keys {
        let encoded_key = utf8_percent_encode(key, NON_ALPHANUMERIC).to_string();
        let url = format!(
            "{base}/v3/historical-price-full/{encoded_symbol}?from={from}&to={to}&apikey={encoded_key}"
        );
        match super::public_finance_calendar::fetch_fmp_json_once(
            &state.http_client,
            &url,
            state.core.config.fmp.timeout,
        )
        .await
        {
            Ok(value) => match adjusted_bars_from_value(&value) {
                Ok(bars) if !bars.is_empty() => return Ok(bars),
                Ok(_) => last_error = "FMP history contained no adjusted closes".to_string(),
                Err(error) => last_error = error,
            },
            Err(error) => last_error = error,
        }
    }
    Err(last_error)
}

fn adjusted_bars_from_value(value: &serde_json::Value) -> Result<Vec<AdjustedMarketBar>, String> {
    let rows = value
        .get("historical")
        .and_then(serde_json::Value::as_array)
        .ok_or_else(|| "FMP history response is missing historical rows".to_string())?;
    let mut by_date = BTreeMap::new();
    for row in rows {
        let Some(date) = row
            .get("date")
            .and_then(serde_json::Value::as_str)
            .and_then(|value| NaiveDate::parse_from_str(value, "%Y-%m-%d").ok())
        else {
            continue;
        };
        let Some(adjusted_close) = row
            .get("adjClose")
            .and_then(serde_json::Value::as_f64)
            .filter(|value| value.is_finite() && *value > 0.0)
        else {
            continue;
        };
        by_date.insert(date, adjusted_close);
    }
    Ok(by_date
        .into_iter()
        .map(|(date, adjusted_close)| AdjustedMarketBar {
            date,
            adjusted_close,
        })
        .collect())
}

fn fmp_legacy_base(raw: &str) -> String {
    raw.trim()
        .trim_end_matches('/')
        .trim_end_matches("/v3")
        .trim_end_matches("/stable")
        .trim_end_matches('/')
        .to_string()
}

async fn write_decision(
    state: &AppState,
    snapshot: &InvestmentDecisionSnapshot,
) -> Result<(), String> {
    validate_point_in_time(snapshot)?;
    let current = current_path(state, &snapshot.symbol);
    let history = history_path(state, snapshot);
    let training = build_training_sample(snapshot);
    validate_training_sample(&training)?;
    let training_path = training_path(state, &training);
    atomic_write_json(&history, snapshot).await?;
    atomic_write_json(&training_path, &training).await?;
    atomic_write_json(&current, snapshot).await?;
    write_decision_chat_context(state, snapshot).await
}

async fn write_decision_chat_context(
    state: &AppState,
    snapshot: &InvestmentDecisionSnapshot,
) -> Result<(), String> {
    validate_point_in_time(snapshot)?;
    let context = build_decision_chat_context(snapshot);
    context.validate_at(snapshot.decision_at)?;
    atomic_write_json(&chat_context_path(state, &snapshot.symbol), &context).await
}

fn build_decision_chat_context(
    snapshot: &InvestmentDecisionSnapshot,
) -> InvestmentDecisionChatContext {
    let financial = &snapshot.financial_verification;
    let crowding = &snapshot.crowding;
    let completeness = &snapshot.decision_completeness;
    let methodology = &snapshot.decision.methodology;
    let first_principles = snapshot.first_principles.as_ref();
    let mut financial_highlights = Vec::new();
    push_percent_highlight(
        &mut financial_highlights,
        "收入同比",
        financial.revenue_growth_percent,
        "%",
    );
    push_percent_highlight(
        &mut financial_highlights,
        "毛利率",
        financial.gross_margin_percent,
        "%",
    );
    push_percent_highlight(
        &mut financial_highlights,
        "毛利率同比变化",
        financial.gross_margin_change_pp,
        "个百分点",
    );
    push_percent_highlight(
        &mut financial_highlights,
        "营业利润率",
        financial.ebit_margin_percent,
        "%",
    );
    push_percent_highlight(
        &mut financial_highlights,
        "经营现金流同比",
        financial.operating_cash_flow_growth_percent,
        "%",
    );
    push_percent_highlight(
        &mut financial_highlights,
        "应收账款同比",
        financial.accounts_receivable_growth_percent,
        "%",
    );
    push_percent_highlight(
        &mut financial_highlights,
        "应付账款同比",
        financial.accounts_payable_growth_percent,
        "%",
    );
    push_percent_highlight(
        &mut financial_highlights,
        "库存同比",
        financial.inventory_growth_percent,
        "%",
    );
    push_percent_highlight(
        &mut financial_highlights,
        "资本开支同比",
        financial.capital_expenditure_growth_percent,
        "%",
    );

    let completeness_gaps = completeness
        .checks
        .iter()
        .filter(|check| check.status != DecisionCompletenessCheckStatus::Pass)
        .map(|check| {
            let gaps = check.gaps.iter().take(2).cloned().collect::<Vec<_>>();
            if gaps.is_empty() {
                check.label.clone()
            } else {
                format!("{}：{}", check.label, gaps.join("；"))
            }
        })
        .take(16)
        .collect::<Vec<_>>();
    let hari_rule_statuses = methodology
        .rules
        .iter()
        .map(|rule| format!("{}:{}", rule.logic_id, rule.status))
        .take(12)
        .collect::<Vec<_>>();
    let valuation =
        snapshot
            .valuation
            .as_ref()
            .map(|valuation| InvestmentDecisionValuationContext {
                as_of: valuation.as_of.clone(),
                currency: valuation.currency.clone(),
                bear_case: valuation.bear_case,
                base_case: valuation.base_case,
                bull_case: valuation.bull_case,
                current_price: valuation.current_price,
                expected_upside_percent: valuation.expected_upside_percent,
                method_count: valuation.method_count,
                confidence: valuation.confidence.clone(),
                current_position: valuation.current_position.clone(),
            });

    InvestmentDecisionChatContext {
        schema_version: INVESTMENT_DECISION_CHAT_CONTEXT_SCHEMA_VERSION.to_string(),
        source_schema_version: snapshot.schema_version.clone(),
        revision_id: snapshot.revision_id.clone(),
        symbol: snapshot.symbol.clone(),
        company_name: snapshot.company_name.clone(),
        theme: snapshot.theme.clone(),
        decision_at: snapshot.decision_at,
        fresh_until: snapshot.decision_at
            + Duration::hours(INVESTMENT_DECISION_CHAT_CONTEXT_FRESH_HOURS),
        source_rating_methodology: snapshot.source_rating_methodology.clone(),
        source_rating_score: snapshot.source_rating_score,
        source_rating_light: snapshot.source_rating_light.clone(),
        data_status: snapshot.data_status.clone(),
        zone: research_zone_id(&snapshot.decision.zone).to_string(),
        action: exposure_action_id(&snapshot.decision.action).to_string(),
        confidence: snapshot.decision.confidence.clone(),
        rationale: snapshot
            .decision
            .rationale
            .iter()
            .take(8)
            .cloned()
            .collect(),
        business_model: snapshot.company_quality.business_model.clone(),
        value_chain: snapshot.company_quality.value_chain.clone(),
        moat_hypothesis: snapshot.company_quality.moat_hypothesis.clone(),
        thesis: snapshot.company_quality.thesis.clone(),
        first_principles_model_id: first_principles.map(|model| model.model_id.clone()),
        first_principles_version: first_principles.map(|model| model.version.clone()),
        first_principles_status: first_principles.map(|model| model.status.clone()),
        financial_policy_version: financial.policy_version.clone(),
        financial_status: measurement_status_id(&financial.status).to_string(),
        financial_as_of: financial.financial_as_of.clone(),
        financial_highlights,
        financial_quality_warnings: financial
            .quality_warnings
            .iter()
            .take(12)
            .cloned()
            .collect(),
        financial_missing_checks: financial.missing_checks.iter().take(16).cloned().collect(),
        valuation,
        valuation_missing_reason: snapshot.valuation_missing_reason.clone(),
        crowding_policy_version: crowding.policy_version.clone(),
        crowding_status: measurement_status_id(&crowding.status).to_string(),
        crowding_score: crowding.score,
        crowding_label: if crowding.label.trim().is_empty() {
            "未形成完整拥挤判断".to_string()
        } else {
            crowding.label.clone()
        },
        crowding_observations: crowding.observations.iter().take(16).cloned().collect(),
        crowding_missing_checks: crowding.missing_checks.iter().take(16).cloned().collect(),
        market_regime_status: market_regime_status_id(&snapshot.market_regime.status).to_string(),
        market_regime_label: if snapshot.market_regime.label.trim().is_empty() {
            "unavailable".to_string()
        } else {
            snapshot.market_regime.label.clone()
        },
        macro_score: snapshot.market_regime.macro_score,
        market_data_cutoff: snapshot.market_regime.data_cutoff.clone(),
        completeness_policy_version: completeness.policy_version.clone(),
        completeness_status: completeness.status.clone(),
        completeness_passed_checks: completeness.passed_checks,
        completeness_total_checks: completeness.total_checks,
        directional_research_ready: completeness.directional_research_ready,
        portfolio_decision_ready: completeness.portfolio_decision_ready,
        completeness_gaps,
        hari_policy_version: methodology.policy_version.clone(),
        confirmed_logic_ids: methodology
            .confirmed_logic_ids
            .iter()
            .take(12)
            .cloned()
            .collect(),
        hari_rule_statuses,
        candidate_logic_used: methodology.candidate_logic_used,
        increase_candidate_authorized: methodology.increase_candidate_authorized,
        portfolio_action_authorized: methodology.portfolio_action_authorized,
        shadow_portfolio_authorized: false,
        trading_authorized: false,
        falsifiers: snapshot
            .decision
            .falsifiers
            .iter()
            .take(12)
            .cloned()
            .collect(),
        next_checks: snapshot
            .decision
            .next_checks
            .iter()
            .take(16)
            .cloned()
            .collect(),
        scope: format!(
            "{} 对话只可把该快照作为同一版本化研究基线；新的一手证据可以使判断加强、削弱或失效，但必须明确说明变化，且不得从评级或模型记忆绕开完整性、Hari、组合、影子和交易门禁。",
            methodology.scope
        ),
    }
}

fn push_percent_highlight(output: &mut Vec<String>, label: &str, value: Option<f64>, unit: &str) {
    if let Some(value) = value.filter(|value| value.is_finite()) {
        output.push(format!("{label} {value:+.1}{unit}"));
    }
}

fn measurement_status_id(status: &MeasurementStatus) -> &'static str {
    match status {
        MeasurementStatus::Unmeasured => "unmeasured",
        MeasurementStatus::PartiallyMeasured => "partially_measured",
        MeasurementStatus::Measured => "measured",
    }
}

fn market_regime_status_id(status: &MarketRegimeStatus) -> &'static str {
    match status {
        MarketRegimeStatus::Unavailable => "unavailable",
        MarketRegimeStatus::Observed => "observed",
    }
}

async fn atomic_write_json<T: Serialize>(path: &Path, value: &T) -> Result<(), String> {
    let parent = path
        .parent()
        .ok_or_else(|| "decision path has no parent".to_string())?;
    tokio::fs::create_dir_all(parent)
        .await
        .map_err(|error| error.to_string())?;
    let bytes = serde_json::to_vec_pretty(value).map_err(|error| error.to_string())?;
    let temp = path.with_extension(format!("{}.tmp", Uuid::new_v4()));
    tokio::fs::write(&temp, bytes)
        .await
        .map_err(|error| error.to_string())?;
    tokio::fs::rename(&temp, path)
        .await
        .map_err(|error| error.to_string())
}

async fn write_immutable_json<T: Serialize>(path: &Path, value: &T) -> Result<(), String> {
    let parent = path
        .parent()
        .ok_or_else(|| "immutable path has no parent".to_string())?;
    tokio::fs::create_dir_all(parent)
        .await
        .map_err(|error| error.to_string())?;
    let bytes = serde_json::to_vec_pretty(value).map_err(|error| error.to_string())?;
    let temp = parent.join(format!(".{}.{}.tmp", Uuid::new_v4(), std::process::id()));
    tokio::fs::write(&temp, bytes)
        .await
        .map_err(|error| error.to_string())?;
    let linked = tokio::fs::hard_link(&temp, path)
        .await
        .map_err(|error| error.to_string());
    let _ = tokio::fs::remove_file(&temp).await;
    linked
}

