    #[test]
    fn chat_projection_preserves_the_validated_decision_and_never_grants_execution() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision_with_context(&ratings, &ratings.items[0], None, &[], None);
        assert!(validate_point_in_time(&decision).is_ok());

        let context = build_decision_chat_context(&decision);
        assert!(context.validate_at(decision.decision_at).is_ok());
        assert_eq!(context.symbol, decision.symbol);
        assert_eq!(context.revision_id, decision.revision_id);
        assert_eq!(
            context.action,
            exposure_action_id(&decision.decision.action)
        );
        assert_eq!(context.zone, research_zone_id(&decision.decision.zone));
        assert_eq!(
            context.completeness_passed_checks,
            decision.decision_completeness.passed_checks
        );
        assert!(context.valuation.is_some());
        assert!(!context.portfolio_action_authorized);
        assert!(!context.shadow_portfolio_authorized);
        assert!(!context.trading_authorized);

        let mut tampered = context;
        tampered.trading_authorized = true;
        assert!(tampered.validate_at(decision.decision_at).is_err());
    }

    #[test]
    fn market_regime_is_frozen_from_only_a_fresh_prior_macro_snapshot() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let report = macro_report("2026-08-12T11:45:00Z", 72.0);
        let decision = build_decision_with_context_and_macro(
            &ratings,
            &ratings.items[0],
            None,
            &[],
            &[],
            None,
            Some(&report),
        );
        assert_eq!(decision.market_regime.status, MarketRegimeStatus::Observed);
        assert_eq!(decision.market_regime.label, "supportive");
        assert_eq!(decision.market_regime.macro_score, Some(72.0));
        assert!(validate_point_in_time(&decision).is_ok());

        let future = macro_report("2026-08-12T12:01:00Z", 72.0);
        let future_state = market_regime_state(Some(&future), ratings.generated_at);
        assert_eq!(future_state.status, MarketRegimeStatus::Unavailable);

        let stale = macro_report("2026-08-10T23:00:00Z", 72.0);
        let stale_state = market_regime_state(Some(&stale), ratings.generated_at);
        assert_eq!(stale_state.status, MarketRegimeStatus::Unavailable);

        let mut tampered = decision;
        tampered.market_regime.label = "stress".to_string();
        assert!(validate_point_in_time(&tampered).is_err());
    }

    #[test]
    fn crowding_v3_is_point_in_time_partial_and_keeps_background_context_non_scored() {
        let item = rating("SNDK", "存储/企业级 SSD");
        let state = crowding_state(
            &item,
            item.valuation.as_ref(),
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
        );

        assert_eq!(state.policy_version, CROWDING_POLICY_VERSION);
        assert_eq!(state.status, MeasurementStatus::PartiallyMeasured);
        assert_eq!(state.components.len(), 8);
        assert!(state.components.iter().any(|component| {
            component.component_id == "volume_direction_confirmation"
                && component.source.starts_with("https://")
        }));
        assert!(state.score.is_some_and(|score| score.is_finite()));
        assert!(state.short_interest.is_some());
        assert!(state.options_positioning.is_some());
        assert!(state.news_attention.is_some());
        assert!(state.institutional_holdings.is_some());
        assert!(state.analyst_consensus.is_some());
        assert!(
            state
                .observations
                .iter()
                .any(|observation| observation.contains("背景证据，不计入拥挤分"))
        );
        assert!(
            state
                .observations
                .iter()
                .any(|observation| observation.contains("仓位背景，不计入拥挤分"))
        );
        assert!(
            state
                .observations
                .iter()
                .any(|observation| observation.contains("注意力背景，不计入拥挤分"))
        );
        assert!(
            state
                .observations
                .iter()
                .any(|observation| observation.contains("13F持有人"))
        );
        assert!(
            state
                .observations
                .iter()
                .any(|observation| observation.contains("分析师建议买入/持有/卖出"))
        );
        assert!(state.scope.contains("不把上涨等同贪婪"));
        assert!(state.missing_checks.iter().any(|gap| gap.contains("期权")));
        assert!(validate_crowding_state(&state).is_ok());

        let measured_score = state.score;
        let mut without_context_item = item.clone();
        without_context_item.short_interest = None;
        without_context_item.options_positioning = None;
        without_context_item.news_attention = None;
        without_context_item.institutional_holdings = None;
        without_context_item.analyst_consensus = None;
        let without_context = crowding_state(
            &without_context_item,
            without_context_item.valuation.as_ref(),
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
        );
        assert_eq!(without_context.score, measured_score);
        assert!(without_context.short_interest.is_none());
        assert!(without_context.options_positioning.is_none());
        assert!(without_context.news_attention.is_none());
        assert!(without_context.institutional_holdings.is_none());
        assert!(without_context.analyst_consensus.is_none());
        assert!(
            without_context
                .missing_checks
                .iter()
                .any(|gap| gap.contains("空头仓位"))
        );

        let mut tampered = state;
        tampered.components[0].pressure_score += 1.0;
        assert!(validate_crowding_state(&tampered).is_err());

        let mut tampered_short = crowding_state(
            &item,
            item.valuation.as_ref(),
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
        );
        tampered_short
            .short_interest
            .as_mut()
            .expect("short context")
            .change_percent += 5.0;
        assert!(validate_crowding_state(&tampered_short).is_err());

        let mut tampered_options = crowding_state(
            &item,
            item.valuation.as_ref(),
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
        );
        tampered_options
            .options_positioning
            .as_mut()
            .expect("options context")
            .put_call_open_interest_ratio = Some(9.0);
        assert!(validate_crowding_state(&tampered_options).is_err());

        let mut tampered_news = crowding_state(
            &item,
            item.valuation.as_ref(),
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
        );
        tampered_news
            .news_attention
            .as_mut()
            .expect("news context")
            .activity_ratio = Some(9.0);
        assert!(validate_crowding_state(&tampered_news).is_err());

        let mut tampered_institutional = crowding_state(
            &item,
            item.valuation.as_ref(),
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
        );
        tampered_institutional
            .institutional_holdings
            .as_mut()
            .expect("institutional context")
            .increased_positions_shares += 1_000.0;
        assert!(validate_crowding_state(&tampered_institutional).is_err());

        let mut tampered_analyst = crowding_state(
            &item,
            item.valuation.as_ref(),
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
        );
        tampered_analyst
            .analyst_consensus
            .as_mut()
            .expect("analyst context")
            .dominant_share_percent += 5.0;
        assert!(validate_crowding_state(&tampered_analyst).is_err());
    }

