    #[test]
    fn legacy_v1_crowding_replays_but_review_required_history_is_policy_inert() {
        let mut item = rating("SNDK", "存储/企业级 SSD");
        let mut legacy = crowding_state(
            &item,
            item.valuation.as_ref(),
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
        );
        legacy.policy_version = LEGACY_CROWDING_POLICY_VERSION.to_string();
        legacy.short_interest = None;
        legacy.options_positioning = None;
        legacy.news_attention = None;
        legacy.institutional_holdings = None;
        legacy.analyst_consensus = None;
        legacy.components.retain(|component| {
            matches!(
                component.component_id.as_str(),
                "price_position_52w"
                    | "price_vs_50d"
                    | "average_50d_vs_200d"
                    | "valuation_scenario_position"
            )
        });
        for component in &mut legacy.components {
            component.weight = match component.component_id.as_str() {
                "price_position_52w" => 0.35,
                "price_vs_50d" => 0.25,
                "average_50d_vs_200d" => 0.15,
                "valuation_scenario_position" => 0.25,
                _ => unreachable!(),
            };
        }
        let weight_sum = legacy
            .components
            .iter()
            .map(|item| item.weight)
            .sum::<f64>();
        let score = legacy
            .components
            .iter()
            .map(|item| item.pressure_score * item.weight)
            .sum::<f64>()
            / weight_sum;
        legacy.score = Some(score);
        legacy.label = crowding_label(score).to_string();
        legacy.observations.truncate(legacy.components.len());
        assert!(validate_crowding_state(&legacy).is_ok());

        let mut legacy_v2 = crowding_state(
            &item,
            item.valuation.as_ref(),
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
        );
        legacy_v2.policy_version = LEGACY_CROWDING_PRICE_PATH_POLICY_VERSION.to_string();
        let analyst = legacy_v2.analyst_consensus.take();
        assert!(validate_crowding_state(&legacy_v2).is_ok());
        legacy_v2.analyst_consensus = analyst;
        assert!(validate_crowding_state(&legacy_v2).is_err());

        let history = item.market_history.as_mut().expect("history fixture");
        history.quality_status = "review_required".to_string();
        history.quality_warnings = vec!["需核对拆股".to_string()];
        let current = crowding_state(
            &item,
            item.valuation.as_ref(),
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
        );
        assert!(current.components.iter().all(|component| {
            !matches!(
                component.component_id.as_str(),
                "return_20_sessions"
                    | "return_60_sessions"
                    | "drawdown_from_60_session_high"
                    | "volume_direction_confirmation"
            )
        }));
        assert!(validate_crowding_state(&current).is_ok());
    }

    #[test]
    fn decision_completeness_exposes_every_missing_layer_without_inventing_readiness() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let completeness = &decision.decision_completeness;
        assert!(decision.decision.rationale.iter().any(|reason| {
            reason.contains(
                "空头仓位、指定月期权仓位、媒体发布活跃度、机构13F聚合已有点时背景但不计分",
            ) && reason.contains(
                "机构报告期一致性、分析师、隐含波动/偏斜、资金、社交情绪与事件去重仍不完整",
            )
        }));
        assert_eq!(
            completeness.policy_version,
            DECISION_COMPLETENESS_POLICY_VERSION
        );
        assert_eq!(completeness.total_checks, 8);
        assert!(!completeness.portfolio_decision_ready);
        assert!(completeness.checks.iter().any(|check| {
            check.check_id == "portfolio_context"
                && check.status == DecisionCompletenessCheckStatus::Missing
        }));
        assert!(completeness.checks.iter().any(|check| {
            check.check_id == "timing_and_crowding"
                && check.status != DecisionCompletenessCheckStatus::Pass
        }));
        assert!(validate_point_in_time(&decision).is_ok());

        let mut legacy = decision.clone();
        legacy.decision_completeness.policy_version =
            LEGACY_DECISION_COMPLETENESS_POLICY_VERSION.to_string();
        legacy.decision_completeness.passed_checks = 1;
        legacy.decision_completeness.completeness_percent = 12.5;
        assert!(validate_point_in_time(&legacy).is_ok());

        let mut tampered = decision;
        tampered.decision_completeness.completeness_percent = 100.0;
        assert!(validate_point_in_time(&tampered).is_err());
    }

