    fn first_principles_hypothesis_map_uses_latest_company_state_and_never_ranks_or_acts() {
        let sndk_ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let sndk_decision = build_decision(&sndk_ratings, &sndk_ratings.items[0]);
        let newest_sndk = build_training_sample(&sndk_decision);
        let mut older_sndk = newest_sndk.clone();
        older_sndk.observed_at -= Duration::days(1);
        older_sndk.sample_id = "SNDK-older-sample".to_string();
        older_sndk
            .state
            .first_principles
            .as_mut()
            .expect("storage model")
            .version = "legacy-should-not-appear".to_string();

        let mu_ratings = snapshot(rating("MU", "存储/HBM"));
        let mu_decision = build_decision(&mu_ratings, &mu_ratings.items[0]);
        let mu_sample = build_training_sample(&mu_decision);

        let map = first_principles_hypothesis_map(&[older_sndk, newest_sndk, mu_sample]);
        assert_eq!(
            map.policy_version,
            FIRST_PRINCIPLES_HYPOTHESIS_MAP_POLICY_VERSION
        );
        assert_eq!(map.company_count, 2);
        assert_eq!(map.model_count, 1);
        assert_eq!(map.models[0].symbols, vec!["MU", "SNDK"]);
        assert_ne!(map.models[0].model_version, "legacy-should-not-appear");
        assert!(!map.opportunity_ranking_enabled);
        assert!(!map.action_authorized);
        assert_eq!(map.map_fingerprint_sha256.len(), 64);
        assert!(validate_first_principles_hypothesis_map(&map).is_ok());

        let empty = first_principles_hypothesis_map(&[]);
        assert_eq!(empty.status, "empty");
        assert_eq!(empty.company_count, 0);
        assert!(validate_first_principles_hypothesis_map(&empty).is_ok());

        let mut tampered = map;
        tampered.action_authorized = true;
        assert!(validate_first_principles_hypothesis_map(&tampered).is_err());
    }

    #[test]
    fn first_principles_hypothesis_map_separates_traceable_from_measured_evidence() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let mut sample = build_training_sample(&decision);
        let model = sample
            .state
            .first_principles
            .as_mut()
            .expect("storage model");
        for driver in model
            .demand_drivers
            .iter_mut()
            .chain(model.supply_drivers.iter_mut())
            .chain(model.value_capture_drivers.iter_mut())
        {
            driver.observations.clear();
            driver.measurement_status = MeasurementStatus::Unmeasured;
        }
        let shared_context = causal_observation(
            "SNDK:test:shared-context".to_string(),
            CausalObservationRelationship::ConfirmedContext,
            "公司一手上下文",
            "管理层确认企业级需求增长",
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
            "Sandisk IR".to_string(),
            Some("https://example.com/sndk-ir".to_string()),
            "company_primary",
        );
        model.demand_drivers[0]
            .observations
            .push(shared_context.clone());
        model.value_capture_drivers[0]
            .observations
            .push(shared_context);
        model.supply_drivers[0]
            .observations
            .push(causal_observation(
                "SNDK:test:supply-context".to_string(),
                CausalObservationRelationship::ConfirmedContext,
                "供给一手上下文",
                "管理层确认新增产能仍受认证约束",
                NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
                "Sandisk IR".to_string(),
                Some("https://example.com/sndk-supply".to_string()),
                "company_primary",
            ));

        let traceable = first_principles_hypothesis_map(&[sample.clone()]);
        let model = &traceable.models[0];
        assert_eq!(model.demand_traceable_company_count, 1);
        assert_eq!(model.supply_traceable_company_count, 1);
        assert_eq!(model.value_capture_traceable_company_count, 1);
        assert_eq!(model.fully_traceable_company_count, 1);
        assert_eq!(model.demand_measured_company_count, 0);
        assert_eq!(model.fully_measured_company_count, 0);
        assert_eq!(model.state, "traceable_evidence_unmeasured");
        assert_eq!(model.evidence_pathway.unique_observation_count, 2);
        assert_eq!(model.evidence_pathway.confirmed_context_count, 2);
        assert!(model.missing_checks.iter().any(|check| {
            check.contains("需求证据可追溯但尚未进入严格量化层")
        }));

        let model = sample
            .state
            .first_principles
            .as_mut()
            .expect("storage model");
        model.demand_drivers[0].observations[0].relationship =
            CausalObservationRelationship::DirectMetric;
        model.demand_drivers[0].measurement_status = MeasurementStatus::Measured;
        let measured = first_principles_hypothesis_map(&[sample]);
        let model = &measured.models[0];
        assert_eq!(model.demand_traceable_company_count, 1);
        assert_eq!(model.demand_measured_company_count, 1);
        assert_eq!(model.state, "measurement_partial");
        assert_eq!(model.evidence_pathway.unique_observation_count, 2);
        assert_eq!(model.evidence_pathway.direct_metric_count, 1);
        assert_eq!(model.evidence_pathway.confirmed_context_count, 1);
        assert!(validate_first_principles_hypothesis_map(&measured).is_ok());
    }

    #[test]
    fn computed_evidence_requires_explicit_human_measurement_admission() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let mut model = decision.first_principles.expect("storage model");
        let driver = model.demand_drivers.first_mut().expect("demand driver");
        driver.observations.clear();
        driver.measurement_status = MeasurementStatus::Unmeasured;
        let mut observation = causal_observation(
            "SNDK:test:computed-demand".to_string(),
            CausalObservationRelationship::ComputedComparison,
            "收入同比变化",
            "+30.0%",
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap(),
            "HONE 确定性计算（两期 SEC XBRL）".to_string(),
            Some("https://www.sec.gov/example-current".to_string()),
            "deterministic_computation",
        );
        observation.computed = Some(CausalComputedProvenance {
            formula_version: COMPUTED_COMPARISON_FORMULA_VERSION.to_string(),
            comparison_kind: CausalComparisonKind::YearOverYear,
            metric_id: "revenue".to_string(),
            metric_basis: "quarter".to_string(),
            current_claim_id: "current".to_string(),
            prior_claim_id: "prior".to_string(),
            current_period: "FY2026Q2".to_string(),
            prior_period: "FY2025Q2".to_string(),
            current_numeric_value: 130.0,
            prior_numeric_value: 100.0,
            unit: "USD".to_string(),
            change_percent: 30.0,
            current_published_at: "2026-08-12T12:00:00Z".parse().unwrap(),
            prior_published_at: "2025-08-12T12:00:00Z".parse().unwrap(),
            current_source_url: "https://www.sec.gov/example-current".to_string(),
            prior_source_url: "https://www.sec.gov/example-prior".to_string(),
        });
        driver.observations.push(observation.clone());

        apply_measurement_admissions(&mut model, None);
        assert_eq!(
            model.demand_drivers[0].measurement_status,
            MeasurementStatus::Unmeasured
        );

        let mut review_index = CausalPromotionReviewIndex::default();
        review_index.verdicts.insert(
            (
                model.demand_drivers[0].driver_id.clone(),
                observation.observation_id.clone(),
            ),
            CausalReviewVerdictAt {
                verdict: CausalLinkVerdict::Accepted,
                effect: CausalEvidenceEffect::Supports,
                speaker_confirmation: CausalSpeakerConfirmation::SourceCheckedNotSpeakerConfirmed,
                old_wang_reviewer_identity_verified: false,
                reviewed_at: "2026-08-13T12:00:00Z".parse().unwrap(),
            },
        );
        apply_measurement_admissions(&mut model, Some(&review_index));
        assert_eq!(
            model.demand_drivers[0].measurement_status,
            MeasurementStatus::Unmeasured
        );
        review_index
            .verdicts
            .get_mut(&(
                model.demand_drivers[0].driver_id.clone(),
                observation.observation_id.clone(),
            ))
            .expect("review")
            .speaker_confirmation = CausalSpeakerConfirmation::OldWangConfirmedAfterSourceCheck;
        review_index
            .verdicts
            .get_mut(&(
                model.demand_drivers[0].driver_id.clone(),
                observation.observation_id.clone(),
            ))
            .expect("review")
            .old_wang_reviewer_identity_verified = true;
        apply_measurement_admissions(&mut model, Some(&review_index));
        assert_eq!(
            model.demand_drivers[0].measurement_status,
            MeasurementStatus::PartiallyMeasured
        );
    }

