    #[test]
    fn shadow_policy_is_read_only_and_blocks_unreviewed_or_unsafe_candidates() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let report = macro_report("2026-08-12T11:45:00Z", 72.0);
        let decision = build_decision_with_context_and_macro(
            &ratings,
            &ratings.items[0],
            None,
            &[],
            &[],
            None,
            Some(&report),
        );
        let mut sample = build_training_sample(&decision);
        sample.human_review = reviewed_state(
            &sample,
            HumanReviewStatus::Accepted,
            ThesisReviewVerdict::Supported,
        );

        let incomplete = shadow_policy_candidate(&sample, true);
        assert_eq!(incomplete.status, "blocked");
        assert!(
            incomplete
                .blocking_reasons
                .iter()
                .any(|reason| reason.contains("方向研究完整性"))
        );
        assert!(
            incomplete
                .blocking_reasons
                .iter()
                .any(|reason| reason.contains("拥挤度"))
        );

        sample.state.decision_completeness.policy_version =
            DECISION_COMPLETENESS_POLICY_VERSION.to_string();
        sample
            .state
            .decision_completeness
            .directional_research_ready = true;
        // The current price/valuation-only contract intentionally never reaches
        // `Measured`.  Model a future, independently validated full crowding
        // contract here so the remainder of the shadow-policy gates can be
        // exercised without weakening that production invariant.
        sample.state.crowding.status = MeasurementStatus::Measured;
        sample.state.crowding.score = Some(50.0);

        let eligible = shadow_policy_candidate(&sample, true);
        assert_eq!(eligible.status, "eligible_for_protocol_review");
        assert_eq!(eligible.target_weight_min_percent, Some(2.0));
        assert_eq!(eligible.target_weight_max_percent, Some(3.0));

        let mut stress = sample.clone();
        stress.state.market_regime.label = "stress".to_string();
        let stress_candidate = shadow_policy_candidate(&stress, true);
        assert_eq!(stress_candidate.status, "blocked");
        assert!(
            stress_candidate
                .blocking_reasons
                .iter()
                .any(|reason| reason.contains("压力状态"))
        );

        let mut falsified = sample.clone();
        falsified
            .state
            .decision
            .causal_confidence
            .blocked_falsification_count = 1;
        assert_eq!(shadow_policy_candidate(&falsified, true).status, "blocked");

        let mut missing_valuation = sample.clone();
        missing_valuation.state.valuation = None;
        assert_eq!(
            shadow_policy_candidate(&missing_valuation, true).status,
            "blocked"
        );

        let protocol = shadow_policy_protocol(&[sample], &offline_evidence_gate(&[], 0));
        assert_eq!(protocol.authorization, "not_authorized");
        assert_eq!(protocol.execution_mode, "read_only_protocol_not_started");
        assert_eq!(protocol.status, "insufficient_evidence");
        assert!(!protocol.constraints.options_allowed);
        assert!(!protocol.constraints.leverage_allowed);
        assert!(!protocol.constraints.shorting_allowed);
    }

