    #[test]
    fn reward_governance_approval_is_gated_and_never_enables_execution() {
        let mut gate = offline_evidence_gate(&[], 0);
        let proposal = reward_design_proposal(&gate);
        let fingerprint = reward_objective_sha256(&proposal);
        assert_eq!(fingerprint.len(), 64);
        let request = || RewardGovernanceRequest {
            expected_review_id: None,
            design_version: proposal.design_version.clone(),
            proposal_sha256: fingerprint.clone(),
            verdict: RewardGovernanceVerdict::ApprovedForOfflineResearch,
            rationale: "确认目标只用于离线研究，并保留全部一票否决。".to_string(),
            component_weights: proposal
                .proposed_components
                .iter()
                .map(|component| RewardGovernanceComponentWeight {
                    component_id: component.component_id.clone(),
                    weight_percent: component.proposed_weight_percent,
                })
                .collect(),
            confirmed_hard_gate_ids: proposal
                .hard_gates
                .iter()
                .map(|gate| gate.gate_id.clone())
                .collect(),
            counterfactual_protocol_confirmed: true,
        };
        assert!(
            validate_reward_governance_submission(request(), &proposal, &gate)
                .unwrap_err()
                .contains("evidence gate")
        );

        gate.status = "eligible_for_reward_design_review".to_string();
        gate.reasons.clear();
        let normalized =
            validate_reward_governance_submission(request(), &proposal, &gate).unwrap();
        assert_eq!(
            normalized.verdict,
            RewardGovernanceVerdict::ApprovedForOfflineResearch
        );
        assert_eq!(normalized.component_weights.len(), 6);
        assert_eq!(normalized.confirmed_hard_gate_ids.len(), 4);

        let response = reward_governance_response(&gate, &proposal, None);
        assert!(!response.reward_computation_enabled);
        assert!(!response.shadow_portfolio_authorized);
        assert!(!response.trading_authorized);
        assert!(response.scope.contains("不连接券商"));
    }

