    #[test]
    fn shadow_protocol_approval_requires_evidence_reward_and_every_boundary() {
        let mut gate = offline_evidence_gate(&[], 0);
        let mut policy = shadow_policy_protocol(&[], &gate);
        let mut proposal = reward_design_proposal(&gate);
        let request = |gate: &OfflineEvidenceGate,
                       policy: &ShadowPolicyProtocol,
                       _proposal: &RewardDesignProposal,
                       reward_review: Option<&RewardGovernanceRecord>| {
            let _ = gate;
            ShadowProtocolGovernanceRequest {
                expected_review_id: None,
                expected_reward_review_id: reward_review.map(|record| record.review_id.clone()),
                policy_version: policy.policy_version.clone(),
                protocol_sha256: shadow_protocol_sha256(policy),
                verdict: ShadowProtocolGovernanceVerdict::ApprovedForFutureShadowImplementation,
                rationale: "确认冻结协议，仅允许未来另行登记只读影子实现。".to_string(),
                confirmed_requirement_ids: policy
                    .review_requirements
                    .iter()
                    .map(|requirement| requirement.requirement_id.clone())
                    .collect(),
                implementation_boundary_confirmed: true,
            }
        };
        assert!(
            validate_shadow_protocol_governance_submission(
                request(&gate, &policy, &proposal, None),
                &policy,
                &gate,
                &proposal,
                None,
            )
            .unwrap_err()
            .contains("evidence gate")
        );

        gate.status = "eligible_for_reward_design_review".to_string();
        gate.reasons.clear();
        policy = shadow_policy_protocol(&[], &gate);
        proposal = reward_design_proposal(&gate);
        assert!(
            validate_shadow_protocol_governance_submission(
                request(&gate, &policy, &proposal, None),
                &policy,
                &gate,
                &proposal,
                None,
            )
            .unwrap_err()
            .contains("reward objective")
        );

        let reward_review = RewardGovernanceRecord {
            schema_version: REWARD_GOVERNANCE_SCHEMA_VERSION.to_string(),
            review_id: "reward-approved".to_string(),
            previous_review_id: None,
            design_version: proposal.design_version.clone(),
            proposal_sha256: reward_objective_sha256(&proposal),
            submitted_at: Utc::now(),
            reviewer_id: "admin-1".to_string(),
            verdict: RewardGovernanceVerdict::ApprovedForOfflineResearch,
            rationale: "批准离线研究。".to_string(),
            component_weights: proposal
                .proposed_components
                .iter()
                .map(|component| RewardGovernanceComponentWeight {
                    component_id: component.component_id.clone(),
                    weight_percent: component.proposed_weight_percent,
                })
                .collect(),
            confirmed_hard_gate_ids: proposal
                .hard_gates
                .iter()
                .map(|item| item.gate_id.clone())
                .collect(),
            counterfactual_protocol_confirmed: true,
        };
        let normalized = validate_shadow_protocol_governance_submission(
            request(&gate, &policy, &proposal, Some(&reward_review)),
            &policy,
            &gate,
            &proposal,
            Some(&reward_review),
        )
        .unwrap();
        assert_eq!(
            normalized.verdict,
            ShadowProtocolGovernanceVerdict::ApprovedForFutureShadowImplementation
        );
        assert_eq!(
            normalized.confirmed_requirement_ids.len(),
            policy.review_requirements.len()
        );

        let record = ShadowProtocolGovernanceRecord {
            schema_version: SHADOW_PROTOCOL_GOVERNANCE_SCHEMA_VERSION.to_string(),
            review_id: "shadow-approved".to_string(),
            previous_review_id: None,
            policy_version: policy.policy_version.clone(),
            protocol_sha256: shadow_protocol_sha256(&policy),
            reward_design_version: proposal.design_version.clone(),
            reward_proposal_sha256: reward_objective_sha256(&proposal),
            reward_review_id: Some(reward_review.review_id.clone()),
            submitted_at: Utc::now(),
            reviewer_id: "admin-1".to_string(),
            verdict: normalized.verdict,
            rationale: normalized.rationale,
            confirmed_requirement_ids: normalized.confirmed_requirement_ids,
            implementation_boundary_confirmed: normalized.implementation_boundary_confirmed,
        };
        validate_shadow_protocol_governance_record(&record, &policy, &proposal).unwrap();
        let response = shadow_protocol_governance_response(
            &gate,
            &policy,
            &proposal,
            Some(&reward_review),
            Some(record),
        );
        assert!(response.future_shadow_implementation_registration_allowed);
        assert!(!response.shadow_ledger_enabled);
        assert!(!response.shadow_portfolio_authorized);
        assert!(!response.trading_authorized);
        assert!(!response.broker_connected);
        assert!(response.scope.contains("不创建账本"));
    }

