    #[test]
    fn shadow_implementation_registration_only_records_a_disabled_specification() {
        let (gate, policy, proposal, reward, shadow) = approved_shadow_registration_context();
        let normalized = validate_shadow_implementation_registration_request(
            ShadowImplementationRegistrationRequest {
                expected_shadow_review_id: shadow.review_id.clone(),
                expected_reward_review_id: reward.review_id.clone(),
                policy_version: policy.policy_version.clone(),
                protocol_sha256: shadow_protocol_sha256(&policy),
                implementation_name: "确定性影子重放规范".to_string(),
                implementation_kind: ShadowImplementationKind::DeterministicReplaySpecification,
                code_revision: "oldwang@abc123".to_string(),
            },
            &gate,
            &policy,
            &proposal,
            Some(&reward),
            Some(&shadow),
        )
        .unwrap();
        let mut record = ShadowImplementationRecord {
            schema_version: SHADOW_IMPLEMENTATION_REGISTRY_SCHEMA_VERSION.to_string(),
            implementation_id: "shadow-implementation-test".to_string(),
            implementation_spec_sha256: String::new(),
            registered_at: Utc::now(),
            registered_by: "admin-1".to_string(),
            shadow_review_id: normalized.shadow_review_id,
            reward_review_id: normalized.reward_review_id,
            policy_version: policy.policy_version.clone(),
            protocol_sha256: shadow_protocol_sha256(&policy),
            implementation_name: normalized.implementation_name,
            implementation_kind: normalized.implementation_kind,
            code_revision: normalized.code_revision,
            status: "registered_not_started".to_string(),
            input_contract: SHADOW_IMPLEMENTATION_INPUT_CONTRACT.to_string(),
            accounting_contract: SHADOW_IMPLEMENTATION_ACCOUNTING_CONTRACT.to_string(),
            benchmark_symbol: policy.benchmark_symbol.clone(),
            execution_assumption: policy.constraints.execution_assumption.clone(),
            deterministic_replay_required: true,
            outbound_network_allowed: false,
            external_tools_allowed: false,
            production_writes_allowed: false,
            ledger_creation_allowed: false,
            order_generation_allowed: false,
            broker_access_allowed: false,
            run_authorized: false,
            shadow_portfolio_authorized: false,
            trading_authorized: false,
        };
        record.implementation_spec_sha256 = shadow_implementation_spec_sha256(&record);
        validate_shadow_implementation_record(&record, &policy).unwrap();
        let response = shadow_implementation_registry_response(
            &gate,
            &policy,
            &proposal,
            Some(&reward),
            Some(&shadow),
            vec![record.clone()],
        );
        assert!(response.registration_allowed);
        assert_eq!(response.implementations.len(), 1);
        assert!(!response.shadow_ledger_enabled);
        assert!(!response.shadow_run_authorized);
        assert!(!response.shadow_portfolio_authorized);
        assert!(!response.order_generation_authorized);
        assert!(!response.broker_connected);
        assert!(!response.trading_authorized);

        record.ledger_creation_allowed = true;
        record.implementation_spec_sha256 = shadow_implementation_spec_sha256(&record);
        assert!(
            validate_shadow_implementation_record(&record, &policy)
                .unwrap_err()
                .contains("over-authorized")
        );
    }

