    #[test]
    fn blind_evaluation_pass_only_enters_human_component_review() {
        let dataset = eligible_causal_dataset_report();
        let assessment =
            assess_causal_component_promotion(&dataset, &passing_blind_evaluation(&dataset));
        assert!(assessment.eligible_for_component_review);
        assert_eq!(assessment.status, "eligible_for_human_component_review");
        assert!(!assessment.component_deployment_authorized);
        assert!(!assessment.decision_agent_deployment_authorized);
        assert!(!assessment.shadow_portfolio_authorized);
        assert!(!assessment.trading_authorized);
    }

    #[test]
    fn blind_evaluation_fails_closed_on_holdout_leak_or_future_leakage() {
        let dataset = eligible_causal_dataset_report();
        let mut result = passing_blind_evaluation(&dataset);
        result.holdout_labels_visible_to_training_worker = true;
        result.future_leakage_detected = true;
        let assessment = assess_causal_component_promotion(&dataset, &result);
        assert!(!assessment.eligible_for_component_review);
        assert!(
            assessment
                .blocking_reasons
                .iter()
                .any(|reason| reason.contains("封存测试标签"))
        );
        assert!(
            assessment
                .blocking_reasons
                .iter()
                .any(|reason| reason.contains("未来信息泄漏"))
        );
    }

    #[test]
    fn blind_evaluation_rejects_single_seed_overfit_and_weak_baseline_lift() {
        let dataset = eligible_causal_dataset_report();
        let mut result = passing_blind_evaluation(&dataset);
        result.candidate_experiment_ids.truncate(1);
        result.distinct_random_seeds = 1;
        result.validation_macro_f1 = 0.90;
        result.holdout_macro_f1 = 0.75;
        result.frozen_baseline_holdout_macro_f1 = 0.74;
        let assessment = assess_causal_component_promotion(&dataset, &result);
        assert!(!assessment.eligible_for_component_review);
        assert!(
            assessment
                .blocking_reasons
                .iter()
                .any(|reason| reason.contains("随机种子"))
        );
        assert!(
            assessment
                .blocking_reasons
                .iter()
                .any(|reason| reason.contains("提升不足"))
        );
        assert!(
            assessment
                .blocking_reasons
                .iter()
                .any(|reason| reason.contains("差距超过"))
        );
    }

