    #[test]
    fn drift_monitoring_requires_audited_coverage_before_component_use() {
        let mut snapshot = healthy_drift_snapshot();
        snapshot.audited_examples = 40;
        let assessment = assess_causal_component_drift(&snapshot);
        assert_eq!(
            assessment.status,
            CausalComponentDriftStatus::InsufficientAuditCoverage
        );
        assert!(!assessment.component_use_allowed);
        assert!(!assessment.promotion_allowed);
        assert!(!assessment.decision_agent_deployment_authorized);
        assert!(!assessment.trading_authorized);
    }

    #[test]
    fn drift_monitoring_freezes_promotion_before_disabling_component() {
        let mut snapshot = healthy_drift_snapshot();
        snapshot.human_disagreement_rate = 0.18;
        let assessment = assess_causal_component_drift(&snapshot);
        assert_eq!(
            assessment.status,
            CausalComponentDriftStatus::WarningFreezePromotion
        );
        assert!(assessment.component_use_allowed);
        assert!(!assessment.promotion_allowed);
    }

    #[test]
    fn drift_monitoring_hard_stops_schema_or_future_leakage() {
        let mut snapshot = healthy_drift_snapshot();
        snapshot.schema_change_detected = true;
        snapshot.future_leakage_detected = true;
        let assessment = assess_causal_component_drift(&snapshot);
        assert_eq!(
            assessment.status,
            CausalComponentDriftStatus::DisableComponent
        );
        assert!(!assessment.component_use_allowed);
        assert!(
            assessment
                .reasons
                .iter()
                .any(|reason| reason.contains("契约"))
        );
        assert!(
            assessment
                .reasons
                .iter()
                .any(|reason| reason.contains("未来信息泄漏"))
        );
    }

