    #[test]
    fn causal_observations_keep_direct_metrics_proxies_and_context_separate() {
        let mut item = rating("SNDK", "存储/企业级 SSD");
        item.metrics.forward_metric_label = None;
        item.metrics.forward_metric_value = None;
        item.metrics.forward_metric_growth_percent = None;
        item.metrics.forward_metric_as_of = None;
        item.metrics.forward_metric_source_url = None;
        let ratings = snapshot(item);
        let events = confirmed_key_event("hbm", "SNDK", "2026-08-11T12:00:00Z");
        let decision = build_decision_with_events(&ratings, &ratings.items[0], Some(&events));
        let model = decision.first_principles.expect("storage model");

        let pricing = model
            .value_capture_drivers
            .iter()
            .find(|driver| driver.driver_id == "pricing_margin")
            .expect("pricing driver");
        assert!(pricing.observations.iter().any(|observation| {
            observation.relationship == CausalObservationRelationship::DirectMetric
                && observation.policy_status == "training_only_pending_human_review"
        }));

        let inventory = model
            .supply_drivers
            .iter()
            .find(|driver| driver.driver_id == "inventory_price")
            .expect("inventory driver");
        assert_eq!(inventory.measurement_status, MeasurementStatus::Unmeasured);
        assert_eq!(inventory.observations.len(), 1);
        assert_eq!(
            inventory.observations[0].relationship,
            CausalObservationRelationship::ConfirmedContext
        );
        assert_eq!(inventory.observations[0].source_tier, "primary");
    }

    #[test]
    fn future_or_other_company_events_never_enter_the_causal_ledger() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let future = confirmed_key_event("hbm", "SNDK", "2026-08-13T12:00:00Z");
        let other = confirmed_key_event("hbm", "MU", "2026-08-11T12:00:00Z");
        for events in [&future, &other] {
            let decision = build_decision_with_events(&ratings, &ratings.items[0], Some(events));
            let model = decision.first_principles.expect("storage model");
            assert!(
                model
                    .supply_drivers
                    .iter()
                    .find(|driver| driver.driver_id == "inventory_price")
                    .is_some_and(|driver| driver.observations.iter().all(|observation| {
                        observation.relationship != CausalObservationRelationship::ConfirmedContext
                    }))
            );
        }
    }

