    #[test]
    fn reported_sec_facts_create_traceable_yoy_and_sequential_comparisons_only() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let claims = vec![
            reported_sec_claim(
                "revenue-2025-q2",
                "filing-2025-q2",
                "revenue",
                "FY2025 Q2",
                100.0,
                "2025-05-01T13:00:00Z",
            ),
            reported_sec_claim(
                "revenue-2026-q1",
                "filing-2026-q1",
                "revenue",
                "FY2026 Q1",
                110.0,
                "2026-02-01T13:00:00Z",
            ),
            reported_sec_claim(
                "revenue-2026-q2",
                "filing-2026-q2",
                "revenue",
                "FY2026 Q2",
                132.0,
                "2026-05-01T13:00:00Z",
            ),
        ];
        let baseline = build_decision_with_context(&ratings, &ratings.items[0], None, &[], None);
        let report = macro_report("2026-08-12T11:45:00Z", 72.0);
        let decision = build_decision_with_context_and_macro(
            &ratings,
            &ratings.items[0],
            None,
            &claims,
            &[],
            None,
            Some(&report),
        );
        let baseline_driver = baseline
            .first_principles
            .as_ref()
            .unwrap()
            .demand_drivers
            .iter()
            .find(|driver| driver.driver_id == "enterprise_adoption")
            .unwrap();
        let driver = decision
            .first_principles
            .as_ref()
            .unwrap()
            .demand_drivers
            .iter()
            .find(|driver| driver.driver_id == "enterprise_adoption")
            .unwrap();
        let comparisons = driver
            .observations
            .iter()
            .filter(|observation| {
                observation.relationship == CausalObservationRelationship::ComputedComparison
            })
            .collect::<Vec<_>>();
        assert_eq!(comparisons.len(), 2);
        assert_eq!(
            driver.measurement_status,
            baseline_driver.measurement_status
        );
        assert!(comparisons.iter().any(|observation| {
            observation.computed.as_ref().is_some_and(|computed| {
                computed.comparison_kind == CausalComparisonKind::YearOverYear
                    && (computed.change_percent - 32.0).abs() < 0.000_001
                    && computed.prior_claim_id == "revenue-2025-q2"
                    && computed.current_claim_id == "revenue-2026-q2"
            })
        }));
        assert!(comparisons.iter().any(|observation| {
            observation.computed.as_ref().is_some_and(|computed| {
                computed.comparison_kind == CausalComparisonKind::SequentialQuarter
                    && (computed.change_percent - 20.0).abs() < 0.000_001
                    && computed.prior_claim_id == "revenue-2026-q1"
                    && computed.current_claim_id == "revenue-2026-q2"
            })
        }));
        assert_eq!(
            decision.financial_verification.revenue_growth_percent,
            Some(32.0)
        );
        assert_eq!(
            decision.financial_verification.financial_as_of.as_deref(),
            Some("2026-05-01")
        );
        assert!(
            decision
                .financial_verification
                .source_claim_ids
                .contains(&"revenue-2026-q2".to_string())
        );
        assert!(validate_point_in_time(&decision).is_ok());

        let mut transitional = decision.clone();
        transitional.financial_verification.policy_version =
            SOURCE_CLAIM_TRACE_FINANCIAL_VERIFICATION_POLICY_VERSION.to_string();
        assert!(validate_point_in_time(&transitional).is_ok());

        let mut tampered = decision.clone();
        let computed = tampered
            .first_principles
            .as_mut()
            .unwrap()
            .demand_drivers
            .iter_mut()
            .find(|driver| driver.driver_id == "enterprise_adoption")
            .unwrap()
            .observations
            .iter_mut()
            .find_map(|observation| observation.computed.as_mut())
            .unwrap();
        computed.change_percent += 1.0;
        assert!(validate_point_in_time(&tampered).is_err());
    }

    #[test]
    fn same_filing_profit_and_revenue_create_traceable_margin_ratios_only() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let mut claims = vec![
            reported_sec_claim(
                "revenue-q2",
                "base-filing-q2",
                "revenue",
                "FY2026 Q2 2026-04-01 to 2026-06-30",
                200.0,
                "2026-08-01T13:00:00Z",
            ),
            reported_sec_claim(
                "gross-profit-q2",
                "quality-filing-q2",
                "gross_profit",
                "FY2026 Q2 2026-04-01 to 2026-06-30",
                90.0,
                "2026-08-01T13:00:00Z",
            ),
            reported_sec_claim(
                "operating-income-q2",
                "quality-filing-q2",
                "operating_income",
                "FY2026 Q2 2026-04-01 to 2026-06-30",
                30.0,
                "2026-08-01T13:00:00Z",
            ),
        ];
        for claim in &mut claims {
            claim.unit = "USD_millions".to_string();
            claim.source_url = "https://www.sec.gov/Archives/filing-q2.htm".to_string();
        }
        let decision =
            build_decision_with_context(&ratings, &ratings.items[0], None, &claims, None);
        assert_eq!(
            decision.financial_verification.gross_margin_percent,
            Some(45.0)
        );
        assert_eq!(
            decision.financial_verification.ebit_margin_percent,
            Some(15.0)
        );
        assert_eq!(decision.financial_verification.source_urls.len(), 1);
        let ratios = decision
            .first_principles
            .as_ref()
            .unwrap()
            .value_capture_drivers
            .iter()
            .find(|driver| driver.driver_id == "pricing_margin")
            .unwrap()
            .observations
            .iter()
            .filter(|observation| {
                observation.relationship == CausalObservationRelationship::ComputedRatio
            })
            .collect::<Vec<_>>();
        assert_eq!(ratios.len(), 2);
        assert!(ratios.iter().any(|observation| {
            observation.ratio.as_ref().is_some_and(|ratio| {
                ratio.ratio_kind == CausalRatioKind::GrossMargin
                    && (ratio.result_percent - 45.0).abs() < 0.000_001
                    && ratio.numerator_claim_id == "gross-profit-q2"
                    && ratio.denominator_claim_id == "revenue-q2"
            })
        }));
        assert!(ratios.iter().any(|observation| {
            observation.ratio.as_ref().is_some_and(|ratio| {
                ratio.ratio_kind == CausalRatioKind::OperatingMargin
                    && (ratio.result_percent - 15.0).abs() < 0.000_001
            })
        }));
        assert!(validate_point_in_time(&decision).is_ok());

        let sample = build_training_sample(&decision);
        let evaluation = build_evaluation_report(&[sample.clone()], &claims, None);
        assert_eq!(evaluation.claim_corpus.derived_ratio_count, 2);
        assert_eq!(evaluation.claim_corpus.gross_margin_ratio_count, 1);
        assert_eq!(evaluation.claim_corpus.operating_margin_ratio_count, 1);
        assert_eq!(evaluation.computed_review.available_ratios, 2);
        assert_eq!(evaluation.computed_review.reviewed_ratios, 0);
        let queue = build_evidence_review_queue(&[sample], None, "pending", "computed_ratio", 100);
        assert_eq!(queue.total_candidates, 2);
        assert!(
            queue
                .items
                .iter()
                .all(|item| item.kind == EvidenceReviewQueueKind::ComputedRatio)
        );

        let mut tampered = decision;
        tampered
            .first_principles
            .as_mut()
            .unwrap()
            .value_capture_drivers
            .iter_mut()
            .find(|driver| driver.driver_id == "pricing_margin")
            .unwrap()
            .observations
            .iter_mut()
            .find_map(|observation| observation.ratio.as_mut())
            .unwrap()
            .result_percent += 1.0;
        assert!(validate_point_in_time(&tampered).is_err());

        claims[1].source_url = "https://www.sec.gov/Archives/other-filing.htm".to_string();
        assert!(
            computed_claim_ratios(
                &claims.iter().collect::<Vec<_>>(),
                &resolve_claim_lifecycles(&claims.iter().collect::<Vec<_>>())
            )
            .iter()
            .all(|ratio| ratio.kind != CausalRatioKind::GrossMargin)
        );
    }

    #[test]
    fn comparable_margin_rows_create_yoy_and_safe_sequential_inflections() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let mut claims = Vec::new();
        for (period, published_at, url, revenue, gross_profit, operating_income) in [
            (
                "FY2025 Q2 2025-04-01 to 2025-06-30",
                "2025-08-01T13:00:00Z",
                "https://www.sec.gov/Archives/2025-q2.htm",
                100.0,
                40.0,
                10.0,
            ),
            (
                "FY2026 Q1 2026-01-01 to 2026-03-31",
                "2026-05-01T13:00:00Z",
                "https://www.sec.gov/Archives/2026-q1.htm",
                110.0,
                44.0,
                13.2,
            ),
            (
                "FY2026 Q2 2026-04-01 to 2026-06-30",
                "2026-08-01T13:00:00Z",
                "https://www.sec.gov/Archives/2026-q2.htm",
                120.0,
                66.0,
                24.0,
            ),
        ] {
            for (metric, value) in [
                ("revenue", revenue),
                ("gross_profit", gross_profit),
                ("operating_income", operating_income),
            ] {
                let slot = period
                    .split_whitespace()
                    .take(2)
                    .collect::<Vec<_>>()
                    .join("-");
                let source_event = format!("{slot}-{metric}");
                let mut claim = reported_sec_claim(
                    &format!("{metric}-{slot}"),
                    &source_event,
                    metric,
                    period,
                    value,
                    published_at,
                );
                claim.unit = "USD_millions".to_string();
                claim.source_url = url.to_string();
                claims.push(claim);
            }
        }
        let refs = claims.iter().collect::<Vec<_>>();
        let lifecycle = resolve_claim_lifecycles(&refs);
        let ratios = computed_claim_ratios(&refs, &lifecycle);
        let trends = computed_claim_ratio_trends(&ratios);
        assert_eq!(trends.len(), 4);
        assert!(trends.iter().any(|trend| {
            trend.current.kind == CausalRatioKind::GrossMargin
                && trend.comparison_kind == CausalComparisonKind::YearOverYear
                && (trend.change_percentage_points - 15.0).abs() < 0.000_001
        }));
        assert!(trends.iter().any(|trend| {
            trend.current.kind == CausalRatioKind::OperatingMargin
                && trend.comparison_kind == CausalComparisonKind::SequentialQuarter
                && (trend.change_percentage_points - 8.0).abs() < 0.000_001
        }));

        let decision =
            build_decision_with_context(&ratings, &ratings.items[0], None, &claims, None);
        assert!(validate_point_in_time(&decision).is_ok());
        let trend_observations = decision
            .first_principles
            .as_ref()
            .unwrap()
            .value_capture_drivers
            .iter()
            .find(|driver| driver.driver_id == "pricing_margin")
            .unwrap()
            .observations
            .iter()
            .filter(|observation| {
                observation.relationship == CausalObservationRelationship::ComputedRatioTrend
            })
            .count();
        assert_eq!(trend_observations, 4);

        let sample = build_training_sample(&decision);
        let evaluation = build_evaluation_report(&[sample], &claims, None);
        assert_eq!(evaluation.claim_corpus.derived_ratio_trend_count, 4);
        assert_eq!(evaluation.computed_review.available_ratio_trends, 4);

        let mut tampered = decision;
        tampered
            .first_principles
            .as_mut()
            .unwrap()
            .value_capture_drivers
            .iter_mut()
            .find(|driver| driver.driver_id == "pricing_margin")
            .unwrap()
            .observations
            .iter_mut()
            .find_map(|observation| observation.ratio_trend.as_mut())
            .unwrap()
            .change_percentage_points += 0.5;
        assert!(validate_point_in_time(&tampered).is_err());

        claims
            .iter_mut()
            .find(|claim| {
                claim.metric_id == "gross_profit" && claim.period.starts_with("FY2025 Q2")
            })
            .unwrap()
            .metric_basis = "US-GAAP:AlternativeGrossProfit".to_string();
        let refs = claims.iter().collect::<Vec<_>>();
        let trends = computed_claim_ratio_trends(&computed_claim_ratios(
            &refs,
            &resolve_claim_lifecycles(&refs),
        ));
        assert!(trends.iter().all(|trend| {
            !(trend.current.kind == CausalRatioKind::GrossMargin
                && trend.comparison_kind == CausalComparisonKind::YearOverYear)
        }));
    }

    #[test]
    fn duration_metrics_reject_quarter_to_cumulative_period_comparisons() {
        let mut claims = Vec::new();
        for (period, published_at, url, revenue, gross_profit) in [
            (
                "FY2025 Q2 2025-04-01 to 2025-06-30",
                "2025-08-01T13:00:00Z",
                "https://www.sec.gov/Archives/2025-q2.htm",
                100.0,
                40.0,
            ),
            (
                "FY2026 Q2 2025-10-01 to 2026-06-30",
                "2026-08-01T13:00:00Z",
                "https://www.sec.gov/Archives/2026-q2.htm",
                400.0,
                180.0,
            ),
        ] {
            for (metric, value) in [("revenue", revenue), ("gross_profit", gross_profit)] {
                let mut claim = reported_sec_claim(
                    &format!("{metric}-{published_at}"),
                    &format!("filing-{metric}-{published_at}"),
                    metric,
                    period,
                    value,
                    published_at,
                );
                claim.unit = "USD_millions".to_string();
                claim.source_url = url.to_string();
                claims.push(claim);
            }
        }
        let refs = claims.iter().collect::<Vec<_>>();
        let lifecycle = resolve_claim_lifecycles(&refs);
        assert!(computed_claim_comparisons(&refs, &lifecycle).is_empty());
        assert!(computed_claim_ratio_trends(&computed_claim_ratios(&refs, &lifecycle)).is_empty());
    }

    #[test]
    fn extreme_primary_source_changes_remain_visible_but_block_financial_completeness() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let mut claims = Vec::new();
        for (period, published_at, url, revenue, gross_profit) in [
            (
                "FY2025 Q2 2025-04-01 to 2025-06-30",
                "2025-08-01T13:00:00Z",
                "https://www.sec.gov/Archives/2025-q2.htm",
                100.0,
                40.0,
            ),
            (
                "FY2026 Q2 2026-04-01 to 2026-06-30",
                "2026-08-01T13:00:00Z",
                "https://www.sec.gov/Archives/2026-q2.htm",
                400.0,
                340.0,
            ),
        ] {
            for (metric, value) in [("revenue", revenue), ("gross_profit", gross_profit)] {
                let mut claim = reported_sec_claim(
                    &format!("{metric}-{published_at}"),
                    &format!("filing-{metric}-{published_at}"),
                    metric,
                    period,
                    value,
                    published_at,
                );
                claim.unit = "USD_millions".to_string();
                claim.source_url = url.to_string();
                claims.push(claim);
            }
        }
        let decision =
            build_decision_with_context(&ratings, &ratings.items[0], None, &claims, None);
        assert_eq!(
            decision.financial_verification.policy_version,
            FINANCIAL_VERIFICATION_POLICY_VERSION
        );
        assert!(
            decision
                .financial_verification
                .source_calculations
                .iter()
                .any(|value| value.contains("100") && value.contains("400"))
        );
        assert!(
            decision
                .financial_verification
                .quality_warnings
                .iter()
                .any(|value| value.contains("收入同比"))
        );
        let financial_check = decision
            .decision_completeness
            .checks
            .iter()
            .find(|check| check.check_id == "financial_transmission")
            .unwrap();
        assert_ne!(
            financial_check.status,
            DecisionCompletenessCheckStatus::Pass
        );
        assert!(
            financial_check
                .gaps
                .iter()
                .any(|value| value.contains("200%"))
        );
        assert!(validate_point_in_time(&decision).is_ok());

        let mut warning_removed = decision;
        warning_removed
            .financial_verification
            .quality_warnings
            .clear();
        assert!(validate_point_in_time(&warning_removed).is_err());

        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let mut legacy =
            build_decision_with_context(&ratings, &ratings.items[0], None, &claims, None);
        legacy.financial_verification.policy_version =
            SOURCE_CLAIM_TRACE_FINANCIAL_VERIFICATION_POLICY_VERSION.to_string();
        legacy.financial_verification.cash_and_equivalents = None;
        legacy.financial_verification.long_term_debt = None;
        legacy.financial_verification.net_cash = None;
        legacy.financial_verification.current_free_cash_flow = None;
        legacy.financial_verification.prior_free_cash_flow = None;
        legacy.financial_verification.financial_value_unit = None;
        legacy
            .financial_verification
            .quality_warnings
            .retain(|warning| !warning.contains("百分比增长没有经济意义"));
        assert!(validate_point_in_time(&legacy).is_ok());
    }

