    #[test]
    fn major_ai_value_chain_themes_receive_distinct_versioned_models() {
        let cases = [
            ("NVDA", "算力芯片/制造", "ai-compute-effective-capacity"),
            ("ANET", "光通信/网络", "ai-optical-interconnect-bandwidth"),
            ("VRT", "电力/液冷", "ai-data-center-power-delivery"),
            ("MSFT", "AI平台/软件", "ai-platform-token-economics"),
            ("TEM", "AI医疗", "ai-application-workflow-value"),
            ("WDC", "其他", "ai-storage-demand-supply"),
        ];

        for (symbol, theme, expected_model) in cases {
            let ratings = snapshot(rating(symbol, theme));
            let decision = build_decision(&ratings, &ratings.items[0]);
            let model = decision.first_principles.expect("theme model");
            assert_eq!(model.model_id, expected_model, "{symbol}");
            assert_eq!(model.status, "measurement_incomplete");
            assert!(!model.demand_equation.is_empty());
            assert!(!model.effective_supply_equation.is_empty());
            assert!(!model.value_capture_equation.is_empty());
            assert_eq!(model.value_capture_drivers.len(), 3);
            assert!(!model.invalidation_conditions.is_empty());
            assert_eq!(
                model.operating_kpi_registry.version,
                if expected_model == "ai-storage-demand-supply" {
                    STORAGE_OPERATING_KPI_REGISTRY_VERSION
                } else {
                    OPERATING_KPI_REGISTRY_VERSION
                }
            );
            assert_eq!(model.operating_kpi_registry.model_id, model.model_id);
            assert!(model.operating_kpi_registry.entries.len() >= 5);
            assert!(operating_kpi_registry_is_valid(&model));
        }
    }

    #[test]
    fn operating_kpi_registry_preserves_issuer_definitions_and_driver_links() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let mut decision = build_decision(&ratings, &ratings.items[0]);
        let model = decision.first_principles.as_ref().unwrap();
        let ids = model
            .operating_kpi_registry
            .entries
            .iter()
            .map(|entry| entry.kpi_id.as_str())
            .collect::<BTreeSet<_>>();
        assert!(ids.contains("nand_bit_shipments_growth"));
        assert!(ids.contains("nand_asp_change"));
        assert!(ids.contains("enterprise_ssd_mix"));
        assert!(ids.contains("enterprise_ssd_qualification"));
        assert!(ids.contains("nand_capacity_utilization"));
        assert!(ids.contains("data_center_revenue_growth"));
        assert!(ids.contains("signed_storage_supply_agreements"));
        assert!(ids.contains("storage_nbm_remaining_performance_obligations"));
        let shipment = model
            .operating_kpi_registry
            .entries
            .iter()
            .find(|entry| entry.kpi_id == "nand_bit_shipments_growth")
            .unwrap();
        assert_eq!(
            model.operating_kpi_registry.version,
            STORAGE_OPERATING_KPI_REGISTRY_VERSION
        );
        assert_eq!(shipment.driver_id, "realized_bit_demand");
        assert!(shipment.definition.contains("不得解释为晶圆产能增长"));
        let data_center_revenue = model
            .operating_kpi_registry
            .entries
            .iter()
            .find(|entry| entry.kpi_id == "data_center_revenue_growth")
            .unwrap();
        assert_eq!(data_center_revenue.driver_id, "enterprise_adoption");
        assert!(data_center_revenue.definition.contains("不得替代收入占比"));
        assert!(data_center_revenue.definition.contains("RPO"));
        let agreements = model
            .operating_kpi_registry
            .entries
            .iter()
            .find(|entry| entry.kpi_id == "signed_storage_supply_agreements")
            .unwrap();
        assert_eq!(agreements.driver_id, "enterprise_adoption");
        assert_eq!(agreements.unit, "agreements");
        assert!(agreements.definition.contains("既有协议扩展"));
        let rpo = model
            .operating_kpi_registry
            .entries
            .iter()
            .find(|entry| entry.kpi_id == "storage_nbm_remaining_performance_obligations")
            .unwrap();
        assert_eq!(rpo.driver_id, "enterprise_adoption");
        assert!(rpo.definition.contains("不得把 RPO 当作收入"));
        assert!(rpo.definition.contains("纯数据中心订单"));
        assert!(
            model
                .demand_drivers
                .iter()
                .any(|driver| driver.driver_id == "realized_bit_demand")
        );
        assert!(model.operating_kpi_registry.entries.iter().all(|entry| {
            entry.issuer_definition_required
                && !entry.cross_company_comparable
                && entry
                    .acceptance_requirements
                    .iter()
                    .any(|requirement| requirement == "source URL and verbatim issuer definition")
        }));
        assert!(validate_point_in_time(&decision).is_ok());

        decision
            .first_principles
            .as_mut()
            .unwrap()
            .operating_kpi_registry
            .entries[0]
            .driver_id = "invented_driver".to_string();
        assert!(validate_point_in_time(&decision).is_err());
    }

    #[test]
    fn legacy_storage_registry_remains_replayable_but_new_registry_rejects_supply_mapping() {
        let ratings = snapshot(rating("MU", "存储/HBM"));
        let mut legacy = build_decision(&ratings, &ratings.items[0]);
        {
            let legacy_model = legacy.first_principles.as_mut().unwrap();
            legacy_model.operating_kpi_registry.version =
                LEGACY_OPERATING_KPI_REGISTRY_VERSION.to_string();
            legacy_model
                .operating_kpi_registry
                .entries
                .iter_mut()
                .find(|entry| entry.kpi_id == "nand_bit_shipments_growth")
                .unwrap()
                .driver_id = "wafer_bits".to_string();
        }
        assert!(validate_point_in_time(&legacy).is_ok());

        let mut storage_v2 = build_decision(&ratings, &ratings.items[0]);
        let storage_v2_registry = &mut storage_v2
            .first_principles
            .as_mut()
            .unwrap()
            .operating_kpi_registry;
        storage_v2_registry.version = LEGACY_STORAGE_OPERATING_KPI_REGISTRY_VERSION.to_string();
        storage_v2_registry.entries.retain(|entry| {
            !matches!(
                entry.kpi_id.as_str(),
                "data_center_revenue_growth"
                    | "signed_storage_supply_agreements"
                    | "storage_nbm_remaining_performance_obligations"
            )
        });
        assert!(validate_point_in_time(&storage_v2).is_ok());

        let mut storage_v3 = build_decision(&ratings, &ratings.items[0]);
        let storage_v3_registry = &mut storage_v3
            .first_principles
            .as_mut()
            .unwrap()
            .operating_kpi_registry;
        storage_v3_registry.version = LEGACY_STORAGE_OPERATING_KPI_REGISTRY_V3_VERSION.to_string();
        storage_v3_registry
            .entries
            .retain(|entry| entry.kpi_id != "storage_nbm_remaining_performance_obligations");
        assert!(validate_point_in_time(&storage_v3).is_ok());

        legacy
            .first_principles
            .as_mut()
            .unwrap()
            .operating_kpi_registry
            .version = STORAGE_OPERATING_KPI_REGISTRY_VERSION.to_string();
        assert!(validate_point_in_time(&legacy).is_err());
    }

