    #[test]
    fn operating_kpi_definition_change_supersedes_old_semantics_without_comparison() {
        let mut old = operating_kpi_claim(
            "asp-old",
            "sndk-call-q3",
            "FY2026 Q4",
            "2026-05-01T21:00:00Z",
            10.0,
        );
        let mut changed = operating_kpi_claim(
            "asp-new",
            "sndk-call-q4",
            "FY2026 Q4",
            "2026-08-06T21:00:00Z",
            15.0,
        );
        changed.issuer_definition = "blended NAND realized price".to_string();
        changed.definition_key = "blendednandrealizedprice".to_string();
        changed.value_text = "blended NAND realized price increased 15% sequentially".to_string();
        changed.evidence_quote = changed.value_text.clone();
        changed.definition_changed = true;
        old.measurement_scope = changed.measurement_scope.clone();
        let refs = vec![&old, &changed];
        let lifecycle = resolve_operating_kpi_lifecycles(&refs);
        assert_eq!(
            lifecycle["asp-old"].status,
            CausalClaimLifecycleStatus::Superseded
        );
        assert_eq!(
            lifecycle["asp-old"].superseded_by.as_deref(),
            Some("asp-new")
        );
        assert_eq!(
            lifecycle["asp-new"].status,
            CausalClaimLifecycleStatus::Active
        );
    }

