    #[test]
    fn unrelated_theme_does_not_receive_an_ai_causal_model() {
        let ratings = snapshot(rating("RKLB", "航天/能源材料"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        assert!(decision.first_principles.is_none());
        assert_eq!(
            decision.decision.methodology.confirmed_logic_ids,
            HARI_CONFIRMED_LOGIC_IDS
        );
        assert!(!decision.decision.methodology.candidate_logic_used);
        assert_eq!(
            decision.decision.methodology.pre_methodology_action,
            "increase_candidate"
        );
        assert!(!decision.decision.methodology.increase_candidate_authorized);
        assert_eq!(decision.decision.zone, ResearchZone::InsufficientData);
        assert_eq!(decision.decision.action, ExposureAction::ResearchOnly);
        assert!(
            decision
                .decision
                .methodology
                .rules
                .iter()
                .any(|rule| { rule.logic_id == "LOG-V0001" && rule.status == "blocked" })
        );
        assert!(decision.decision.methodology.rules.iter().all(|rule| {
            !matches!(
                rule.logic_id.as_str(),
                "LOG-V0003" | "LOG-V0004" | "LOG-V0005"
            ) || rule.status == "delegated_to_portfolio"
        }));
    }

    #[test]
    fn hari_logic_scenario_benchmark_covers_confirmed_logic_without_creating_authority() {
        let benchmark = hari_logic_scenario_benchmark();

        assert_eq!(
            benchmark.policy_version,
            HARI_SCENARIO_BENCHMARK_POLICY_VERSION
        );
        assert_eq!(benchmark.confirmed_logic_ids, HARI_CONFIRMED_LOGIC_IDS);
        assert_eq!(benchmark.scenario_count, 6);
        assert_eq!(benchmark.passed_scenario_count, 6);
        assert_eq!(benchmark.failed_scenario_count, 0);
        assert!(benchmark.all_passed);
        assert!(benchmark.synthetic_scenarios_only);
        assert!(!benchmark.training_label_created);
        assert!(!benchmark.decision_authorized);
        assert!(!benchmark.portfolio_action_authorized);
        assert!(!benchmark.shadow_portfolio_authorized);
        assert!(!benchmark.trading_authorized);
        assert!(HARI_CONFIRMED_LOGIC_IDS.iter().all(|logic_id| {
            benchmark.cases.iter().any(|case| {
                case.covered_logic_ids
                    .iter()
                    .any(|covered| covered == logic_id)
            })
        }));

        let portfolio_case = benchmark
            .cases
            .iter()
            .find(|case| case.case_id == "portfolio_authority_stays_delegated")
            .expect("portfolio delegation scenario");
        assert!(portfolio_case.passed);
        assert!(portfolio_case.actual_portfolio_delegated);
        assert!(!portfolio_case.actual_company_increase_authorized);
    }

