    #[test]
    fn opportunity_requires_current_evidence_and_verified_valuation_support() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        assert_eq!(decision.decision.zone, ResearchZone::Opportunity);
        assert_eq!(decision.decision.action, ExposureAction::IncreaseCandidate);
        assert_eq!(
            decision.decision.methodology.confirmed_logic_ids,
            HARI_CONFIRMED_LOGIC_IDS
        );
        assert!(!decision.decision.methodology.candidate_logic_used);
        assert!(decision.decision.methodology.increase_candidate_authorized);
        assert!(!decision.decision.methodology.portfolio_action_authorized);
        assert!(decision.decision.methodology.blocking_reasons.is_empty());

        let mut incomplete = rating("SNDK", "存储/企业级 SSD");
        incomplete.factor_coverage = 5;
        let ratings = snapshot(incomplete);
        let decision = build_decision(&ratings, &ratings.items[0]);
        assert_eq!(decision.decision.zone, ResearchZone::InsufficientData);
        assert_eq!(decision.decision.action, ExposureAction::ResearchOnly);
    }

    #[test]
    fn point_in_time_validation_rejects_tampered_hari_methodology_projection() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let mut decision = build_decision(&ratings, &ratings.items[0]);
        decision.decision.methodology.candidate_logic_used = true;

        assert!(validate_point_in_time(&decision).is_err());
    }

    #[test]
    fn working_capital_and_capex_metrics_enter_the_decision_state_without_imputation() {
        let mut item = rating("SNDK", "存储/企业级 SSD");
        item.metrics.accounts_receivable_growth_percent = Some(12.0);
        item.metrics.accounts_payable_growth_percent = Some(18.0);
        item.metrics.inventory_growth_percent = Some(-8.0);
        item.metrics.property_plant_equipment_growth_percent = Some(20.0);
        item.metrics.operating_cash_flow_growth_percent = Some(25.0);
        item.metrics.capital_expenditure_growth_percent = Some(15.0);
        item.metrics.free_cash_flow_growth_percent = Some(30.0);
        let ratings = snapshot(item);
        let decision = build_decision(&ratings, &ratings.items[0]);
        let financial = decision.financial_verification;
        assert_eq!(financial.status, MeasurementStatus::Measured);
        assert_eq!(financial.accounts_receivable_growth_percent, Some(12.0));
        assert_eq!(financial.inventory_growth_percent, Some(-8.0));
        assert_eq!(financial.capital_expenditure_growth_percent, Some(15.0));
        assert!(
            !financial
                .missing_checks
                .iter()
                .any(|item| item.contains("库存"))
        );
        assert!(
            financial
                .missing_checks
                .iter()
                .any(|item| item.contains("真实产能"))
        );
    }

    #[test]
    fn point_in_time_validation_rejects_future_evidence() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let mut decision = build_decision(&ratings, &ratings.items[0]);
        decision.evidence.push(DecisionEvidence {
            evidence_id: "future".to_string(),
            kind: EvidenceKind::Financial,
            status: EvidenceStatus::CurrentVerified,
            label: "future filing".to_string(),
            value: "not available yet".to_string(),
            as_of: NaiveDate::from_ymd_opt(2026, 8, 13).unwrap(),
            source: "future".to_string(),
        });
        assert!(validate_point_in_time(&decision).is_err());
    }

    #[test]
    fn builder_drops_future_dated_inputs_instead_of_leaking_them() {
        let mut item = rating("SNDK", "存储/企业级 SSD");
        item.market_as_of = Some("2026-08-13 09:30".to_string());
        item.financial_as_of = Some("2026-08-14".to_string());
        item.metrics.forward_metric_as_of = Some("2026-08-16".to_string());
        item.valuation.as_mut().unwrap().as_of = "2026-08-15".to_string();
        item.research_updated_at = "2026-08-17".to_string();
        let ratings = snapshot(item);
        let decision = build_decision(&ratings, &ratings.items[0]);
        assert!(
            decision
                .evidence
                .iter()
                .all(|evidence| evidence.as_of <= decision.decision_date_beijing)
        );
        assert!(!decision.evidence.iter().any(|evidence| matches!(
            evidence.kind,
            EvidenceKind::Market | EvidenceKind::Financial | EvidenceKind::Valuation
        )));
        assert!(decision.valuation.is_none());
        assert_eq!(
            decision.financial_verification.status,
            MeasurementStatus::Unmeasured
        );
        assert_eq!(
            decision.company_quality.status,
            MeasurementStatus::Unmeasured
        );
        assert!(validate_point_in_time(&decision).is_ok());
    }

    #[test]
    fn symbols_cannot_escape_the_decision_storage_root() {
        assert!(valid_symbol("BRK.B"));
        assert!(valid_symbol("SNDK"));
        assert!(!valid_symbol("../SNDK"));
        assert!(!valid_symbol("SNDK/../../secret"));
        assert!(!valid_symbol(""));
    }

    #[test]
    fn training_sample_starts_without_future_labels_or_reward() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let sample = build_training_sample(&decision);
        assert_eq!(sample.selected_action, ExposureAction::IncreaseCandidate);
        assert_eq!(sample.human_review.status, HumanReviewStatus::Pending);
        assert_eq!(sample.reward.status, RewardStatus::Unconfigured);
        assert_eq!(sample.reward.value, None);
        assert_eq!(
            sample
                .outcomes
                .iter()
                .map(|outcome| outcome.horizon_market_sessions)
                .collect::<Vec<_>>(),
            vec![20, 60, 250]
        );
        assert!(sample.outcomes.iter().all(|outcome| {
            outcome.status == OutcomeStatus::PendingMarketSessions
                && outcome.asset_return_percent.is_none()
                && outcome.period_end.is_none()
        }));
        assert!(validate_training_sample(&sample).is_ok());
    }

    #[test]
    fn training_validation_rejects_premature_outcome_and_invented_reward() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let mut premature = build_training_sample(&decision);
        premature.outcomes[0].asset_return_percent = Some(12.0);
        assert!(validate_training_sample(&premature).is_err());

        let mut invented_reward = build_training_sample(&decision);
        invented_reward.reward.value = Some(1.0);
        assert!(validate_training_sample(&invented_reward).is_err());
    }

    #[test]
    fn causal_training_dataset_is_company_isolated_deduplicated_and_label_only() {
        let sndk_ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let sndk_decision = build_decision(&sndk_ratings, &sndk_ratings.items[0]);
        let mut sndk = build_training_sample(&sndk_decision);
        let (sndk_driver, sndk_observation) = first_reviewable_link(&sndk);
        sndk.human_review = reviewed_state(
            &sndk,
            HumanReviewStatus::Accepted,
            ThesisReviewVerdict::Supported,
        );
        sndk.human_review.causal_link_reviews = vec![CausalLinkReview {
            driver_id: sndk_driver.clone(),
            observation_id: sndk_observation.clone(),
            verdict: CausalLinkVerdict::Accepted,
            effect: CausalEvidenceEffect::Supports,
            explanation: "该证据支持对应驱动。".to_string(),
            verbatim_judgment: Some("这条证据支持对应驱动。".to_string()),
            applicability_boundary: Some("仅限冻结时点可见的信息。".to_string()),
            falsifier: Some("后续一手证据否定该关系。".to_string()),
            speaker_confirmation: CausalSpeakerConfirmation::OldWangConfirmedAfterSourceCheck,
            review_id: None,
            reviewed_at: None,
            reviewer_id: None,
            old_wang_reviewer_identity_verified: true,
            evidence_identity_sha256: None,
            source_review_id: None,
            source_review_sample_id: None,
        }];

        let mut sndk_later = sndk.clone();
        sndk_later.sample_id = "SNDK-later-review".to_string();
        sndk_later.human_review.reviewed_at = Some(sndk.observed_at + Duration::hours(2));
        sndk_later.human_review.causal_link_reviews[0].effect = CausalEvidenceEffect::Falsifies;

        let mu_ratings = snapshot(rating("MU", "存储/内存"));
        let mu_decision = build_decision(&mu_ratings, &mu_ratings.items[0]);
        let mut mu = build_training_sample(&mu_decision);
        let (mu_driver, mu_observation) = first_reviewable_link(&mu);
        mu.human_review = reviewed_state(
            &mu,
            HumanReviewStatus::Accepted,
            ThesisReviewVerdict::Supported,
        );
        mu.human_review.causal_link_reviews = vec![CausalLinkReview {
            driver_id: mu_driver,
            observation_id: mu_observation,
            verdict: CausalLinkVerdict::Rejected,
            effect: CausalEvidenceEffect::Unclassified,
            explanation: "该证据不能建立对应关系。".to_string(),
            verbatim_judgment: Some("这条证据不能建立对应关系。".to_string()),
            applicability_boundary: Some("当前证据口径下关系不成立。".to_string()),
            falsifier: Some("出现同口径跨期兑现后重新判断。".to_string()),
            speaker_confirmation: CausalSpeakerConfirmation::OldWangConfirmedAfterSourceCheck,
            review_id: None,
            reviewed_at: None,
            reviewer_id: None,
            old_wang_reviewer_identity_verified: true,
            evidence_identity_sha256: None,
            source_review_id: None,
            source_review_sample_id: None,
        }];

        let dataset_samples = vec![sndk.clone(), sndk_later, mu];
        let (examples, unclassified, future, deduplicated) =
            build_causal_training_examples(&dataset_samples);
        assert_eq!(examples.len(), 2);
        assert_eq!(unclassified, 0);
        assert_eq!(future, 0);
        assert_eq!(deduplicated, 1);
        assert_eq!(
            examples
                .iter()
                .find(|example| example.symbol == "SNDK")
                .unwrap()
                .target,
            "falsifies"
        );
        assert_eq!(
            examples
                .iter()
                .find(|example| example.symbol == "MU")
                .unwrap()
                .target,
            "relationship_rejected"
        );
        let symbol_splits = examples.iter().fold(
            BTreeMap::<String, BTreeSet<CausalDatasetSplit>>::new(),
            |mut groups, example| {
                groups
                    .entry(example.symbol.clone())
                    .or_default()
                    .insert(example.split.clone());
                groups
            },
        );
        assert!(symbol_splits.values().all(|splits| splits.len() == 1));
        let report = causal_training_dataset_report(&dataset_samples);
        assert_eq!(report.eligible_example_count, 2);
        assert_eq!(
            report.development_target_counts.values().sum::<usize>(),
            report.train_example_count + report.validation_example_count
        );
        assert!(report.holdout_labels_withheld);
        assert!(!report.training_authorized);

        let baseline = build_causal_training_examples(&[sndk.clone()]).0;
        let mut forbidden_fields_changed = sndk;
        forbidden_fields_changed.selected_action = ExposureAction::ReduceCandidate;
        forbidden_fields_changed.state.decision.action = ExposureAction::ReduceCandidate;
        forbidden_fields_changed.outcomes[0].asset_return_percent = Some(999.0);
        forbidden_fields_changed.reward.value = Some(999.0);
        assert_eq!(
            baseline,
            build_causal_training_examples(&[forbidden_fields_changed]).0
        );
    }

    #[test]
    fn causal_training_dataset_keeps_shared_source_components_in_one_split() {
        let example =
            |symbol: &str, source_identities: &[&str], suffix: &str| CausalTrainingExample {
                example_id: format!("example-{suffix}"),
                split: CausalDatasetSplit::Train,
                symbol: symbol.to_string(),
                decision_at: Utc::now(),
                model_id: "ai-infrastructure".to_string(),
                model_version: "v1".to_string(),
                driver_id: format!("driver-{suffix}"),
                driver_label: "需求兑现".to_string(),
                mechanism: "共享产业证据会同时影响多家公司。".to_string(),
                observation_id: format!("observation-{suffix}"),
                relationship: CausalObservationRelationship::ConfirmedContext,
                observation_label: "共享来源".to_string(),
                observation_value: "已确认".to_string(),
                observation_as_of: NaiveDate::from_ymd_opt(2026, 8, 20).unwrap(),
                source_tier: "primary".to_string(),
                source_identity_keys: source_identities
                    .iter()
                    .map(|identity| (*identity).to_string())
                    .collect(),
                target: "supports".to_string(),
            };
        let mut examples = vec![
            example("SNDK", &["event:storage-demand"], "1"),
            example("MU", &["event:storage-demand"], "2"),
            example("MU", &["event:hbm-supply"], "3"),
            example("NVDA", &["event:hbm-supply"], "4"),
            example("MSFT", &["event:cloud-capex"], "5"),
        ];

        let audit = assign_causal_dataset_component_splits(&mut examples);
        let split = |symbol: &str| {
            examples
                .iter()
                .find(|example| example.symbol == symbol)
                .unwrap()
                .split
                .clone()
        };
        assert_eq!(split("SNDK"), split("MU"));
        assert_eq!(split("MU"), split("NVDA"));
        assert_eq!(audit.connected_component_count, 2);
        assert_eq!(audit.shared_source_group_count, 2);
        assert_eq!(audit.largest_component_symbol_count, 3);
        assert!(audit.company_split_isolation_verified);
        assert!(audit.source_group_split_isolation_verified);
    }

