    #[test]
    fn causal_training_dataset_requires_old_wang_confirmation_and_complete_distillation() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let mut sample = build_training_sample(&decision);
        let (driver_id, observation_id) = first_reviewable_link(&sample);
        sample.human_review = reviewed_state(
            &sample,
            HumanReviewStatus::Accepted,
            ThesisReviewVerdict::Supported,
        );
        sample.human_review.causal_link_reviews = vec![CausalLinkReview {
            driver_id,
            observation_id,
            verdict: CausalLinkVerdict::Accepted,
            effect: CausalEvidenceEffect::Supports,
            explanation: "维护者已经核对来源，但老王尚未确认。".to_string(),
            verbatim_judgment: Some("材料显示需求仍在增长。".to_string()),
            applicability_boundary: Some("仅限当前公司披露口径。".to_string()),
            falsifier: Some("后续订单和收入同时转弱。".to_string()),
            speaker_confirmation: CausalSpeakerConfirmation::SourceCheckedNotSpeakerConfirmed,
            review_id: None,
            reviewed_at: None,
            reviewer_id: None,
            old_wang_reviewer_identity_verified: false,
            evidence_identity_sha256: None,
            source_review_id: None,
            source_review_sample_id: None,
        }];

        assert!(validate_training_sample(&sample).is_ok());
        assert!(
            build_causal_training_examples(&[sample.clone()])
                .0
                .is_empty()
        );

        sample.human_review.causal_link_reviews[0].speaker_confirmation =
            CausalSpeakerConfirmation::OldWangConfirmed;
        assert!(
            build_causal_training_examples(&[sample.clone()])
                .0
                .is_empty()
        );

        sample.human_review.causal_link_reviews[0].speaker_confirmation =
            CausalSpeakerConfirmation::OldWangConfirmedAfterSourceCheck;
        assert!(
            build_causal_training_examples(&[sample.clone()])
                .0
                .is_empty()
        );
        sample.human_review.causal_link_reviews[0].old_wang_reviewer_identity_verified = true;
        assert_eq!(build_causal_training_examples(&[sample.clone()]).0.len(), 1);

        let review = &mut sample.human_review.causal_link_reviews[0];
        review.verdict = CausalLinkVerdict::Rejected;
        review.effect = CausalEvidenceEffect::Unclassified;
        review.explanation = "原文与候选事实不一致，只排除该候选，不形成因果标签。".to_string();
        review.verbatim_judgment = None;
        review.applicability_boundary = None;
        review.falsifier = None;
        review.speaker_confirmation = CausalSpeakerConfirmation::EvidenceMismatch;
        review.old_wang_reviewer_identity_verified = false;
        assert!(validate_training_sample(&sample).is_ok());
        assert!(build_causal_training_examples(&[sample]).0.is_empty());
    }

    #[test]
    fn causal_training_dataset_excludes_future_and_unclassified_evidence() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let mut sample = build_training_sample(&decision);
        let decision_date = sample.state.decision_date_beijing;
        let model = sample.state.first_principles.as_mut().unwrap();
        let driver = model
            .demand_drivers
            .iter_mut()
            .chain(model.supply_drivers.iter_mut())
            .chain(model.value_capture_drivers.iter_mut())
            .find(|driver| !driver.observations.is_empty())
            .unwrap();
        let observation = driver.observations.first_mut().unwrap();
        observation.as_of = decision_date + Duration::days(1);
        sample.human_review.reviewed_at = Some(sample.observed_at + Duration::hours(1));
        sample.human_review.causal_link_reviews = vec![CausalLinkReview {
            driver_id: driver.driver_id.clone(),
            observation_id: observation.observation_id.clone(),
            verdict: CausalLinkVerdict::Accepted,
            effect: CausalEvidenceEffect::Supports,
            explanation: "未来证据必须被拒绝。".to_string(),
            verbatim_judgment: Some("决策后才出现的数据不能用于当时判断。".to_string()),
            applicability_boundary: Some("只允许决策时点或之前公开的证据。".to_string()),
            falsifier: Some("证据发布时间被证明早于决策时点。".to_string()),
            speaker_confirmation: CausalSpeakerConfirmation::OldWangConfirmedAfterSourceCheck,
            review_id: None,
            reviewed_at: None,
            reviewer_id: None,
            old_wang_reviewer_identity_verified: true,
            evidence_identity_sha256: None,
            source_review_id: None,
            source_review_sample_id: None,
        }];
        let (examples, _, future, _) = build_causal_training_examples(&[sample]);
        assert!(examples.is_empty());
        assert_eq!(future, 1);

        let ratings = snapshot(rating("MU", "存储/内存"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let mut unclassified = build_training_sample(&decision);
        let model = unclassified.state.first_principles.as_ref().unwrap();
        let driver = model
            .demand_drivers
            .iter()
            .chain(model.supply_drivers.iter())
            .chain(model.value_capture_drivers.iter())
            .find(|driver| !driver.observations.is_empty())
            .unwrap();
        let driver_id = driver.driver_id.clone();
        let observation_id = driver.observations[0].observation_id.clone();
        unclassified.human_review.reviewed_at = Some(unclassified.observed_at + Duration::hours(1));
        unclassified.human_review.causal_link_reviews = vec![CausalLinkReview {
            driver_id,
            observation_id,
            verdict: CausalLinkVerdict::Accepted,
            effect: CausalEvidenceEffect::Unclassified,
            explanation: "未分类标签不能训练。".to_string(),
            verbatim_judgment: Some("这条关系尚未完成分类。".to_string()),
            applicability_boundary: Some("未分类状态不进入训练。".to_string()),
            falsifier: Some("完成明确分类并再次确认。".to_string()),
            speaker_confirmation: CausalSpeakerConfirmation::OldWangConfirmedAfterSourceCheck,
            review_id: None,
            reviewed_at: None,
            reviewer_id: None,
            old_wang_reviewer_identity_verified: true,
            evidence_identity_sha256: None,
            source_review_id: None,
            source_review_sample_id: None,
        }];
        let (examples, excluded, _, _) = build_causal_training_examples(&[unclassified]);
        assert!(examples.is_empty());
        assert_eq!(excluded, 1);
    }

    #[tokio::test]
    async fn causal_review_audit_hydrates_without_changing_pending_thesis() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let sample = build_training_sample(&decision);
        let (driver_id, observation_id) = first_reviewable_link(&sample);
        let root =
            std::env::temp_dir().join(format!("hone-causal-review-audit-test-{}", Uuid::new_v4()));
        let training_directory = root.join("training").join("SNDK");
        atomic_write_json(
            &training_directory.join(format!("{}.json", sample.sample_id)),
            &sample,
        )
        .await
        .unwrap();
        let first_at = sample.observed_at + Duration::hours(1);
        let evidence_identity_sha256 =
            causal_evidence_identity(&sample, &driver_id, &observation_id).unwrap();
        let first = CausalEvidenceReviewRecord {
            schema_version: CAUSAL_REVIEW_SCHEMA_VERSION.to_string(),
            review_id: "causal-review-1".to_string(),
            previous_review_id: None,
            sample_id: sample.sample_id.clone(),
            symbol: "SNDK".to_string(),
            submitted_at: first_at,
            reviewer_id: "admin-1".to_string(),
            driver_id: driver_id.clone(),
            observation_id: observation_id.clone(),
            verdict: CausalLinkVerdict::Accepted,
            effect: CausalEvidenceEffect::Supports,
            explanation: "这条时间点证据支持对应经营驱动。".to_string(),
            verbatim_judgment: Some("这条时间点证据支持对应经营驱动。".to_string()),
            applicability_boundary: Some("仅适用于该冻结披露口径。".to_string()),
            falsifier: Some("后续同口径事实反向变化。".to_string()),
            speaker_confirmation: CausalSpeakerConfirmation::OldWangConfirmedAfterSourceCheck,
            source_verification: CausalSourceVerification::VerifiedAgainstSource,
            source_verification_note: Some("已核对冻结来源、数值、期间和口径。".to_string()),
            old_wang_confirmation_attested: true,
            old_wang_reviewer_identity_verified: true,
            evidence_identity_sha256: Some(evidence_identity_sha256),
            source_review_id: Some("source-review-origin".to_string()),
            source_review_sample_id: Some(sample.sample_id.clone()),
            thesis_review_unchanged: true,
        };
        let source_record = CausalSourceReviewRecord {
            schema_version: CAUSAL_SOURCE_REVIEW_SCHEMA_VERSION.to_string(),
            review_id: "source-review-origin".to_string(),
            previous_review_id: None,
            sample_id: sample.sample_id.clone(),
            symbol: sample.state.symbol.clone(),
            submitted_at: first_at - Duration::minutes(1),
            reviewer_id: "maintainer-1".to_string(),
            driver_id: driver_id.clone(),
            observation_id: observation_id.clone(),
            evidence_fingerprint_sha256: causal_evidence_fingerprint(
                &sample,
                &driver_id,
                &observation_id,
            )
            .unwrap(),
            verdict: CausalSourceVerification::VerifiedAgainstSource,
            note: first.source_verification_note.clone().unwrap(),
            causal_label_created: false,
            training_label_eligible: false,
            thesis_review_unchanged: true,
        };
        assert!(causal_review_record_source_contract_valid(&first));
        let unverified_old_wang = CausalEvidenceReviewRecord {
            speaker_confirmation: CausalSpeakerConfirmation::OldWangConfirmed,
            ..first.clone()
        };
        assert!(!causal_review_record_source_contract_valid(
            &unverified_old_wang
        ));
        let source_exclusion = CausalEvidenceReviewRecord {
            schema_version: LEGACY_CAUSAL_REVIEW_V3_SCHEMA_VERSION.to_string(),
            verdict: CausalLinkVerdict::Rejected,
            effect: CausalEvidenceEffect::Unclassified,
            explanation: "原文缺少候选所需的期间和口径。".to_string(),
            verbatim_judgment: None,
            applicability_boundary: None,
            falsifier: None,
            speaker_confirmation: CausalSpeakerConfirmation::InsufficientSourceContext,
            source_verification: CausalSourceVerification::InsufficientSourceContext,
            source_verification_note: Some("原文只给方向，没有数值、期间或单位。".to_string()),
            old_wang_confirmation_attested: false,
            old_wang_reviewer_identity_verified: false,
            evidence_identity_sha256: None,
            source_review_id: None,
            source_review_sample_id: None,
            ..first.clone()
        };
        assert!(causal_review_record_source_contract_valid(
            &source_exclusion
        ));
        let second = CausalEvidenceReviewRecord {
            schema_version: CAUSAL_REVIEW_SCHEMA_VERSION.to_string(),
            review_id: "causal-review-2".to_string(),
            previous_review_id: Some(first.review_id.clone()),
            submitted_at: first_at + Duration::minutes(1),
            verdict: CausalLinkVerdict::Accepted,
            effect: CausalEvidenceEffect::Mixed,
            explanation: "新增口径说明后，只能确认正反混合。".to_string(),
            ..first.clone()
        };
        let audit_directory = root
            .join("causal-reviews")
            .join("SNDK")
            .join(&sample.sample_id);
        let source_directory = root
            .join("source-reviews")
            .join("SNDK")
            .join(&sample.sample_id);
        write_immutable_json(
            &source_directory.join("source-review-origin.json"),
            &source_record,
        )
        .await
        .unwrap();
        write_immutable_json(&audit_directory.join("first.json"), &first)
            .await
            .unwrap();
        write_immutable_json(&audit_directory.join("second.json"), &second)
            .await
            .unwrap();

        let hydrated = read_replay_directory(&training_directory, "SNDK", 10, false)
            .await
            .unwrap()
            .pop()
            .unwrap();
        assert_eq!(hydrated.human_review.status, HumanReviewStatus::Pending);
        assert_eq!(
            hydrated.human_review.thesis_verdict,
            ThesisReviewVerdict::Pending
        );
        assert!(hydrated.human_review.review_id.is_none());
        assert_eq!(hydrated.human_review.causal_link_reviews.len(), 1);
        let review = &hydrated.human_review.causal_link_reviews[0];
        assert_eq!(review.review_id.as_deref(), Some("causal-review-2"));
        assert_eq!(review.effect, CausalEvidenceEffect::Mixed);
        assert_eq!(review.reviewed_at, Some(second.submitted_at));
        assert!(validate_training_sample(&hydrated).is_ok());
        assert_eq!(build_causal_training_examples(&[hydrated]).0.len(), 1);

        tokio::fs::remove_file(source_directory.join("source-review-origin.json"))
            .await
            .unwrap();
        assert!(
            read_replay_directory(&training_directory, "SNDK", 10, false)
                .await
                .is_err()
        );

        tokio::fs::remove_dir_all(root).await.unwrap();
    }

    #[test]
    fn current_causal_review_requires_live_verified_source_audit_binding() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let mut source_sample = build_training_sample(&decision);
        let (driver_id, observation_id) = first_reviewable_link(&source_sample);
        let evidence_identity_sha256 =
            causal_evidence_identity(&source_sample, &driver_id, &observation_id).unwrap();
        let source_note = "已核对冻结来源、数值、期间和口径。".to_string();
        source_sample
            .human_review
            .causal_source_reviews
            .push(CausalSourceReviewProjection {
                driver_id: driver_id.clone(),
                observation_id: observation_id.clone(),
                evidence_fingerprint_sha256: causal_evidence_fingerprint(
                    &source_sample,
                    &driver_id,
                    &observation_id,
                )
                .unwrap(),
                verdict: CausalSourceVerification::VerifiedAgainstSource,
                note: source_note.clone(),
                review_id: "source-review-live".to_string(),
                reviewed_at: source_sample.observed_at + Duration::minutes(1),
                reviewer_id: "maintainer-1".to_string(),
            });
        let mut target_sample = source_sample.clone();
        target_sample.sample_id = "SNDK-cross-snapshot-causal-target".to_string();
        target_sample.state.revision_id = target_sample.sample_id.clone();
        target_sample.observed_at += Duration::minutes(20);
        target_sample.state.decision_at = target_sample.observed_at;
        target_sample.human_review.causal_source_reviews.clear();
        let record = CausalEvidenceReviewRecord {
            schema_version: CAUSAL_REVIEW_SCHEMA_VERSION.to_string(),
            review_id: "causal-review-cross-audit".to_string(),
            previous_review_id: None,
            sample_id: target_sample.sample_id.clone(),
            symbol: target_sample.state.symbol.clone(),
            submitted_at: target_sample.observed_at + Duration::minutes(1),
            reviewer_id: "old-wang-web-user".to_string(),
            driver_id: driver_id.clone(),
            observation_id: observation_id.clone(),
            verdict: CausalLinkVerdict::Accepted,
            effect: CausalEvidenceEffect::Supports,
            explanation: "这条证据支持对应经营驱动。".to_string(),
            verbatim_judgment: Some("这条证据支持对应经营驱动。".to_string()),
            applicability_boundary: Some("仅适用于该冻结披露口径。".to_string()),
            falsifier: Some("后续同口径事实反向变化。".to_string()),
            speaker_confirmation: CausalSpeakerConfirmation::OldWangConfirmedAfterSourceCheck,
            source_verification: CausalSourceVerification::VerifiedAgainstSource,
            source_verification_note: Some(source_note),
            old_wang_confirmation_attested: true,
            old_wang_reviewer_identity_verified: true,
            evidence_identity_sha256: Some(evidence_identity_sha256),
            source_review_id: Some("source-review-live".to_string()),
            source_review_sample_id: Some(source_sample.sample_id.clone()),
            thesis_review_unchanged: true,
        };

        let source_context = causal_source_review_context_from_samples(&[source_sample.clone()]);
        assert!(
            validate_current_causal_review_source_binding(
                &record,
                &target_sample,
                &source_context,
            )
            .is_ok()
        );
        assert!(
            validate_current_causal_review_source_binding(&record, &target_sample, &[]).is_err()
        );

        let mut orphan = record.clone();
        orphan.source_review_id = Some("missing-source-review".to_string());
        assert!(
            validate_current_causal_review_source_binding(
                &orphan,
                &target_sample,
                &source_context,
            )
            .is_err()
        );

        let mut wrong_verdict = source_sample.clone();
        wrong_verdict.human_review.causal_source_reviews[0].verdict =
            CausalSourceVerification::EvidenceMismatch;
        let wrong_verdict_context = causal_source_review_context_from_samples(&[wrong_verdict]);
        assert!(
            validate_current_causal_review_source_binding(
                &record,
                &target_sample,
                &wrong_verdict_context,
            )
            .is_err()
        );

        let mut conflicting = target_sample.clone();
        let mut conflicting_review = source_sample.human_review.causal_source_reviews[0].clone();
        conflicting_review.review_id = "source-review-conflict".to_string();
        conflicting_review.verdict = CausalSourceVerification::InsufficientSourceContext;
        conflicting.human_review.causal_source_reviews = vec![conflicting_review];
        let conflicting_context =
            causal_source_review_context_from_samples(&[source_sample.clone(), conflicting]);
        assert!(
            validate_current_causal_review_source_binding(
                &record,
                &target_sample,
                &conflicting_context,
            )
            .is_err()
        );

        let model = target_sample.state.first_principles.as_mut().unwrap();
        let observation = model
            .demand_drivers
            .iter_mut()
            .chain(model.supply_drivers.iter_mut())
            .chain(model.value_capture_drivers.iter_mut())
            .flat_map(|driver| driver.observations.iter_mut())
            .find(|observation| observation.observation_id == observation_id)
            .unwrap();
        observation.value.push_str("（证据被篡改）");
        assert!(
            validate_current_causal_review_source_binding(
                &record,
                &target_sample,
                &source_context,
            )
            .is_err()
        );
    }

    #[tokio::test]
    async fn source_review_is_fingerprint_bound_and_never_creates_a_training_label() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let sample = build_training_sample(&decision);
        let (driver_id, observation_id) = first_reviewable_link(&sample);
        let fingerprint =
            causal_evidence_fingerprint(&sample, &driver_id, &observation_id).unwrap();
        let root =
            std::env::temp_dir().join(format!("hone-source-review-audit-test-{}", Uuid::new_v4()));
        let training_directory = root.join("training").join("SNDK");
        atomic_write_json(
            &training_directory.join(format!("{}.json", sample.sample_id)),
            &sample,
        )
        .await
        .unwrap();
        let record = CausalSourceReviewRecord {
            schema_version: CAUSAL_SOURCE_REVIEW_SCHEMA_VERSION.to_string(),
            review_id: "source-review-1".to_string(),
            previous_review_id: None,
            sample_id: sample.sample_id.clone(),
            symbol: "SNDK".to_string(),
            submitted_at: sample.observed_at + Duration::hours(1),
            reviewer_id: "maintainer-1".to_string(),
            driver_id: driver_id.clone(),
            observation_id: observation_id.clone(),
            evidence_fingerprint_sha256: fingerprint.clone(),
            verdict: CausalSourceVerification::VerifiedAgainstSource,
            note: "维护者逐项核对了原文、期间、口径和数值。".to_string(),
            causal_label_created: false,
            training_label_eligible: false,
            thesis_review_unchanged: true,
        };
        let source_directory = root
            .join("source-reviews")
            .join("SNDK")
            .join(&sample.sample_id);
        write_immutable_json(&source_directory.join("source-review-1.json"), &record)
            .await
            .unwrap();

        let hydrated = read_replay_directory(&training_directory, "SNDK", 10, false)
            .await
            .unwrap()
            .pop()
            .unwrap();
        assert_eq!(hydrated.human_review.status, HumanReviewStatus::Pending);
        assert!(hydrated.human_review.causal_link_reviews.is_empty());
        assert_eq!(hydrated.human_review.causal_source_reviews.len(), 1);
        assert_eq!(
            hydrated.human_review.causal_source_reviews[0].evidence_fingerprint_sha256,
            fingerprint
        );
        assert!(
            build_causal_training_examples(&[hydrated.clone()])
                .0
                .is_empty()
        );

        let mut tampered = hydrated;
        let (_, observation) = find_causal_observation(&tampered, &driver_id, &observation_id)
            .expect("reviewed observation");
        let original_value = observation.value.clone();
        let model = tampered.state.first_principles.as_mut().unwrap();
        let observation = model
            .demand_drivers
            .iter_mut()
            .chain(model.supply_drivers.iter_mut())
            .chain(model.value_capture_drivers.iter_mut())
            .flat_map(|driver| driver.observations.iter_mut())
            .find(|observation| observation.observation_id == observation_id)
            .unwrap();
        observation.value = format!("{original_value}（被篡改）");
        assert!(validate_training_sample(&tampered).is_err());

        tokio::fs::remove_dir_all(root).await.unwrap();
    }

