    #[tokio::test]
    async fn replay_storage_is_chronological_and_returns_latest_limit() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let first_decision = build_decision(&ratings, &ratings.items[0]);
        let first = build_training_sample(&first_decision);
        let mut second = first.clone();
        second.sample_id = "SNDK-second".to_string();
        second.observed_at += chrono::Duration::days(1);
        second.state.revision_id = second.sample_id.clone();
        second.state.decision_at = second.observed_at;
        second.state.decision_date_beijing =
            second.observed_at.with_timezone(&Shanghai).date_naive();

        let directory =
            std::env::temp_dir().join(format!("hone-investment-replay-test-{}", Uuid::new_v4()));
        atomic_write_json(&directory.join("z-first.json"), &first)
            .await
            .unwrap();
        atomic_write_json(&directory.join("a-second.json"), &second)
            .await
            .unwrap();

        let all = read_replay_directory(&directory, "SNDK", 10, false)
            .await
            .unwrap();
        assert_eq!(all.len(), 2);
        assert_eq!(all[0].sample_id, first.sample_id);
        assert_eq!(all[1].sample_id, second.sample_id);
        let latest = read_replay_directory(&directory, "SNDK", 1, false)
            .await
            .unwrap();
        assert_eq!(latest[0].sample_id, second.sample_id);

        tokio::fs::remove_dir_all(&directory).await.unwrap();
    }

    #[tokio::test]
    async fn aggregate_replay_quarantines_invalid_samples_without_hiding_valid_history() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let valid = build_training_sample(&decision);
        let mut invalid = valid.clone();
        invalid.sample_id = "SNDK-invalid-financial-provenance".to_string();
        invalid.state.revision_id = invalid.sample_id.clone();
        invalid.state.financial_verification.net_cash = Some(999.0);

        let directory = std::env::temp_dir().join(format!(
            "hone-investment-replay-quarantine-test-{}",
            Uuid::new_v4()
        ));
        atomic_write_json(&directory.join("valid.json"), &valid)
            .await
            .unwrap();
        atomic_write_json(&directory.join("invalid.json"), &invalid)
            .await
            .unwrap();

        assert!(
            read_replay_directory(&directory, "SNDK", 10, false)
                .await
                .is_err()
        );
        let aggregate = read_replay_directory(&directory, "SNDK", 10, true)
            .await
            .unwrap();
        assert_eq!(aggregate.len(), 1);
        assert_eq!(aggregate[0].sample_id, valid.sample_id);

        let public_replay = read_replay_directory_report(&directory, "SNDK", 10, true)
            .await
            .unwrap();
        assert_eq!(public_replay.samples.len(), 1);
        assert_eq!(public_replay.quarantine_warnings.len(), 1);
        assert_eq!(
            public_replay.quarantine_warnings[0].file_name,
            "invalid.json"
        );
        assert_eq!(
            public_replay.quarantine_warnings[0].reason,
            "财务验证的来源索引、逐条来源明细、计算口径或决策时点不一致"
        );

        tokio::fs::remove_dir_all(&directory).await.unwrap();
    }

    #[test]
    fn outcome_labeler_counts_common_market_rows_not_calendar_days() {
        let ratings = snapshot(rating("SNDK", "存储/企业级 SSD"));
        let decision = build_decision(&ratings, &ratings.items[0]);
        let mut sample = build_training_sample(&decision);
        let start = NaiveDate::from_ymd_opt(2026, 8, 12).unwrap();
        let asset = (0..21)
            .map(|index| AdjustedMarketBar {
                // The fixture intentionally advances calendar days. Each row,
                // rather than the date gap, is one observed market session.
                date: start + Duration::days(index),
                adjusted_close: 100.0 + index as f64,
            })
            .collect::<Vec<_>>();
        let benchmark = (0..21)
            .map(|index| AdjustedMarketBar {
                date: start + Duration::days(index),
                adjusted_close: 200.0 + index as f64,
            })
            .collect::<Vec<_>>();
        let labelled_at = DateTime::parse_from_rfc3339("2026-09-02T22:00:00Z")
            .unwrap()
            .with_timezone(&Utc);
        assert!(label_sample_from_bars(
            &mut sample,
            &asset,
            &benchmark,
            labelled_at,
            start + Duration::days(30),
        ));
        assert_eq!(sample.outcomes[0].status, OutcomeStatus::Observed);
        assert_eq!(sample.outcomes[0].market_sessions_observed, Some(20));
        assert_eq!(
            sample.outcomes[0].period_end,
            Some(start + Duration::days(20))
        );
        assert_eq!(
            sample.outcomes[1].status,
            OutcomeStatus::PendingMarketSessions
        );
        assert_eq!(sample.reward.status, RewardStatus::Unconfigured);
        assert!(validate_training_sample(&sample).is_ok());
    }

