    #[test]
    fn market_cutoffs_respect_new_york_close_time() {
        let before_close = DateTime::parse_from_rfc3339("2026-08-12T19:59:00Z")
            .unwrap()
            .with_timezone(&Utc);
        let at_close = DateTime::parse_from_rfc3339("2026-08-12T20:00:00Z")
            .unwrap()
            .with_timezone(&Utc);
        assert_eq!(
            latest_completed_new_york_market_date(before_close),
            NaiveDate::from_ymd_opt(2026, 8, 11).unwrap()
        );
        assert_eq!(
            latest_completed_new_york_market_date(at_close),
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap()
        );
        assert_eq!(
            earliest_outcome_start_date(before_close),
            NaiveDate::from_ymd_opt(2026, 8, 12).unwrap()
        );
        assert_eq!(
            earliest_outcome_start_date(
                DateTime::parse_from_rfc3339("2026-08-12T21:00:00Z")
                    .unwrap()
                    .with_timezone(&Utc)
            ),
            NaiveDate::from_ymd_opt(2026, 8, 13).unwrap()
        );
    }

